// data estesa in italiano, es. "27 luglio 2026" (usata per raggruppare le
// ultime iscrizioni per giorno di inserimento)
function fmtDataLunga(dataStr) {
  const [anno, mese, giorno] = dataStr.split("-").map(Number);
  return `${giorno} ${MESI[mese - 1].toLowerCase()} ${anno}`;
}

// intervallo di date in italiano esteso, es. "18–19 ottobre 2026" (stesso
// mese) o "28 settembre – 2 ottobre 2026" (mesi diversi) — usato
// nell'intestazione di Contabilità classe
function fmtIntervalloEsteso(inizio, fine) {
  const [annoI, meseI, giornoI] = inizio.split("-").map(Number);
  if (inizio === fine) return `${giornoI} ${MESI[meseI - 1].toLowerCase()} ${annoI}`;
  const [annoF, meseF, giornoF] = fine.split("-").map(Number);
  if (annoI === annoF && meseI === meseF) return `${giornoI}–${giornoF} ${MESI[meseI - 1].toLowerCase()} ${annoI}`;
  if (annoI === annoF) return `${giornoI} ${MESI[meseI - 1].toLowerCase()} – ${giornoF} ${MESI[meseF - 1].toLowerCase()} ${annoI}`;
  return `${giornoI} ${MESI[meseI - 1].toLowerCase()} ${annoI} – ${giornoF} ${MESI[meseF - 1].toLowerCase()} ${annoF}`;
}

// genera la griglia di un mese come array di settimane (7 celle, null=padding)
function generaSettimane(anno, mese) {
  const primoGiorno = new Date(anno, mese, 1);
  const offset = (primoGiorno.getDay() + 6) % 7; // lunedì=0
  const giorniMese = new Date(anno, mese + 1, 0).getDate();
  const celle = [];
  for (let i = 0; i < offset; i++) celle.push(null);
  for (let d = 1; d <= giorniMese; d++) celle.push(d);
  while (celle.length % 7 !== 0) celle.push(null);
  const settimane = [];
  for (let i = 0; i < celle.length; i += 7) settimane.push(celle.slice(i, i + 7));
  return settimane;
}
function dateStrFor(anno, mese, d) {
  return `${anno}-${String(mese + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}
// somma (o sottrae, se n è negativo) n giorni a una data "yyyy-mm-dd"
function addGiorni(dataStr, n) {
  const [y, m, d] = dataStr.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + n);
  return `${dt.getUTCFullYear()}-${String(dt.getUTCMonth() + 1).padStart(2, "0")}-${String(dt.getUTCDate()).padStart(2, "0")}`;
}
// aggiunge n mesi a una data "yyyy-mm-dd" (n negativo per sottrarre,
// n=12 per un anno): se il giorno di partenza non esiste nel mese di
// destinazione (es. 31 gennaio + 1 mese) si ferma all'ultimo giorno
// valido di quel mese, non "trabocca" nel mese successivo
function addMesi(dataStr, n) {
  const [y, m, d] = dataStr.split("-").map(Number);
  const mesiTotali = (m - 1) + n;
  const annoDest = y + Math.floor(mesiTotali / 12);
  const meseDest = ((mesiTotali % 12) + 12) % 12;
  const ultimoGiornoMese = new Date(Date.UTC(annoDest, meseDest + 1, 0)).getUTCDate();
  const giornoDest = Math.min(d, ultimoGiornoMese);
  return `${annoDest}-${String(meseDest + 1).padStart(2, "0")}-${String(giornoDest).padStart(2, "0")}`;
}
// numero di giorni tra due date "yyyy-mm-dd" (dataB - dataA)
function differenzaGiorni(dataA, dataB) {
  const [ya, ma, da] = dataA.split("-").map(Number);
  const [yb, mb, db] = dataB.split("-").map(Number);
  return Math.round((Date.UTC(yb, mb - 1, db) - Date.UTC(ya, ma - 1, da)) / 86400000);
}
// assegna una "corsia" (lane) a ciascun evento di una riga evitando sovrapposizioni
function assegnaLane(eventiRiga) {
  const lanes = [];
  return eventiRiga
    .slice()
    .sort((a, b) => a.data_inizio.localeCompare(b.data_inizio))
    .map((ev) => {
      let lane = 0;
      while (lanes[lane] && lanes[lane] >= ev.data_inizio) lane++;
      lanes[lane] = ev.data_fine;
      return { ...ev, lane };
    });
}

// sigle automobilistiche delle principali città italiane, per le etichette nel calendario
const SIGLE_CITTA = {
  "milano": "MI", "roma": "RM", "napoli": "NA", "torino": "TO", "bologna": "BO",
  "firenze": "FI", "verona": "VR", "venezia": "VE", "palermo": "PA", "genova": "GE",
  "bari": "BA", "catania": "CT", "padova": "PD", "bergamo": "BG", "brescia": "BS",
  "modena": "MO", "parma": "PR", "reggio emilia": "RE", "perugia": "PG", "cagliari": "CA",
  "ancona": "AN", "pescara": "PE", "trento": "TN", "bolzano": "BZ", "trieste": "TS",
  "udine": "UD", "rimini": "RN", "salerno": "SA", "livorno": "LI", "pisa": "PI",
  "siena": "SI", "lucca": "LU", "ravenna": "RA", "ferrara": "FE", "vicenza": "VI",
  "treviso": "TV", "como": "CO", "varese": "VA", "monza": "MB", "brindisi": "BR",
  "lecce": "LE", "taranto": "TA", "foggia": "FG", "messina": "ME", "siracusa": "SR",
  "sassari": "SS", "reggio calabria": "RC", "cosenza": "CS", "latina": "LT", "pavia": "PV",
  "piacenza": "PC", "cremona": "CR", "mantova": "MN", "novara": "NO", "asti": "AT",
  "cuneo": "CN", "aosta": "AO", "la spezia": "SP", "pistoia": "PT", "arezzo": "AR",
  "grosseto": "GR", "terni": "TR", "viterbo": "VT", "rieti": "RI", "frosinone": "FR",
  "campobasso": "CB", "potenza": "PZ", "matera": "MT", "avellino": "AV", "benevento": "BN",
  "caserta": "CE", "nuoro": "NU", "oristano": "OR", "imperia": "IM", "savona": "SV",
  "alessandria": "AL", "biella": "BI", "vercelli": "VC", "lodi": "LO", "sondrio": "SO",
  "belluno": "BL", "rovigo": "RO", "gorizia": "GO", "pordenone": "PN", "chieti": "CH",
  "teramo": "TE", "isernia": "IS", "l'aquila": "AQ", "macerata": "MC", "fermo": "FM",
  "pesaro": "PU", "prato": "PO", "massa": "MS",
};
function siglaCitta(nome) {
  if (!nome) return "";
  const s = SIGLE_CITTA[nome.trim().toLowerCase()];
  return s || nome.trim().slice(0, 2).toUpperCase();
}
// versione molto chiara (circa 28% di intensità) di un colore esadecimale,
// mescolandolo con il bianco: usata per la parte "vuota" dell'indicatore di
// capienza sulle barre del calendario. Restituisce un colore SOLIDO (non
// trasparente) così resta identico su qualunque sfondo ci sia dietro
function coloreTenue(hex, intensita = 0.28) {
  const cifre = (hex || "").replace("#", "").match(/.{1,2}/g);
  if (!cifre || cifre.length < 3) return hex;
  const [r, g, b] = cifre.map((h) => parseInt(h, 16));
  const mescola = (c) => Math.round(c * intensita + 255 * (1 - intensita));
  return `rgb(${mescola(r)}, ${mescola(g)}, ${mescola(b)})`;
}

// etichetta breve per le barre del calendario: nome corso (max maxChar
// caratteri, di default 10) + sigla città; maxChar=null non tronca affatto
// (usato da mobile sui corsi di un solo giorno, dove il nome può andare a
// capo su due righe invece di essere tagliato)
function etichettaBarra(corso, loc, maxChar = 10) {
  const nomeIntero = toTitleCase(corso?.nome || "");
  const nome = maxChar != null ? nomeIntero.slice(0, maxChar) : nomeIntero;
  return `${nome} ${siglaCitta(loc?.nome)}`;
}

// angolo della punta di freccia, misurato dall'orizzontale: più è
// piccolo più la punta appare schiacciata/allungata invece che a 45°
const ANGOLO_PUNTA_FRECCIA_GRADI = 78;
// quanto deve rientrare orizzontalmente il taglio perché, unito a metà
// altezza della barra, la punta risultante formi ANGOLO_PUNTA_FRECCIA_GRADI
function runPuntaFreccia(altezzaPx) {
  return (altezzaPx / 2) / Math.tan((ANGOLO_PUNTA_FRECCIA_GRADI * Math.PI) / 180);
}
// se il corso prosegue nella riga precedente/successiva (spezzato dal
// cambio di settimana), taglia gli angoli della barra dal lato
// interessato: la barra stessa diventa la punta di una freccia che indica
// da/verso dove prosegue, invece di un simbolo scritto dentro
function clipPathBarra(continuaPrima, continuaDopo, altezzaPx) {
  if (!continuaPrima && !continuaDopo) return undefined;
  const h = runPuntaFreccia(altezzaPx);
  const punti = [];
  punti.push(continuaPrima ? `${h}px 0` : "0 0");
  punti.push(continuaDopo ? `calc(100% - ${h}px) 0` : "100% 0");
  if (continuaDopo) punti.push("100% 50%");
  punti.push(continuaDopo ? `calc(100% - ${h}px) 100%` : "100% 100%");
  punti.push(continuaPrima ? `${h}px 100%` : "0 100%");
  if (continuaPrima) punti.push("0 50%");
  return `polygon(${punti.join(", ")})`;
}

// sfondo di una cella della barra calendario. Le celle normali sono a
// tinta piena su tutto lo spazio. La cella dell'ultimo giorno, quando si
// conosce l'occupancy, si spezza in due: l'80% di sinistra resta a tinta
// piena fissa, il 20% di destra è il "misuratore" — ancorato in basso,
// alto quanto l'occupancy (0% = non si vede proprio, il pezzo sopra resta
// scoperto e lascia intravedere la casella del giorno sotto; 100% = si
// fonde con l'80% e la cella torna a sembrare piena). Niente tinte tenui
// né riempimenti orizzontali: sostituisce la vecchia stellina dorata con
// l'ultimo numero di frazione.
function sfondoCella(occupancy, coloreCorso, ultimoGiorno) {
  if (!ultimoGiorno || occupancy == null) {
    return <div style={{ position: "absolute", inset: 0, background: coloreCorso, pointerEvents: "none", zIndex: 0 }} />;
  }
  return (
    <>
      <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: "80%", background: coloreCorso, pointerEvents: "none", zIndex: 0 }} />
      <div
        style={{
          position: "absolute", right: 0, bottom: 0, width: "20%", height: `${occupancy}%`,
          background: coloreCorso, pointerEvents: "none", zIndex: 0, transition: "height 250ms ease",
        }}
      />
    </>
  );
}

// contenuto di una barra evento nel calendario: per un corso di più giorni
// mostra, sopra ogni singolo giorno che attraversa in questa riga, il
// numero di frazione "giorno/totale" (es. 3/6, tranne l'ultimo giorno, dove
// il riempimento sostituisce il numero); il nome del corso resta visibile
// solo all'inizio del segmento
function contenutoBarraCalendario({ etichetta, giorniTotali, indiciGiorno, fontSizeBadge, gap, inset, continuaPrima, continuaDopo, coneRun, isMobile, fontScaleBarre = 1, occupancy, coloreCorso }) {
  if (giorniTotali <= 1) {
    if (isMobile) {
      // da cellulare la colonna del giorno è troppo stretta perché il nome
      // stia su una riga sola anche riducendo il font: meglio andare a capo
      // su due righe (il nome intero, non troncato) che tagliarlo con "..."
      return (
        <div style={{ position: "relative", height: "100%", display: "flex", alignItems: "center", padding: `0 ${inset}px`, boxSizing: "border-box" }}>
          {sfondoCella(occupancy, coloreCorso, true)}
          <span
            style={{
              position: "relative", zIndex: 1,
              ...fontCondensato,
              display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical",
              overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "normal", wordBreak: "break-word",
              fontSize: 10 * fontScaleBarre, lineHeight: 1.05,
            }}
          >
            {etichetta}
          </span>
        </div>
      );
    }
    return (
      <div style={{ position: "relative", height: "100%", padding: `0 ${inset}px`, boxSizing: "border-box" }}>
        {sfondoCella(occupancy, coloreCorso, true)}
        <span style={{ position: "relative", zIndex: 1, ...fontCondensato, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", height: "100%", display: "flex", alignItems: "center" }}>
          {etichetta}
        </span>
      </div>
    );
  }
  const ultimo = indiciGiorno.length - 1;
  // questa riga contiene davvero l'ultimo giorno del corso solo se non
  // prosegue oltre (continuaDopo): se il corso continua nella settimana
  // successiva, questa non è la cella giusta per il riempimento
  const ultimaCellaEUltimoGiorno = !continuaDopo;
  return (
    // stesso numero di colonne E STESSO gap della griglia dei giorni sotto:
    // solo così ogni numero di frazione combacia esattamente con il giorno
    // a cui si riferisce, invece di scivolare via via che il corso è lungo.
    // Il rientro (inset) va messo sulla prima/ultima cella, non su questo
    // contenitore, altrimenti sposterebbe la larghezza delle colonne e
    // farebbe perdere l'allineamento con la griglia dei giorni.
    // Il distacco del numero dal bordo destro è LO STESSO gap usato tra le
    // colonne dei giorni, applicato a ogni cella: così la frazione si trova
    // sempre alla stessa distanza dal proprio giorno, sia che sia una cella
    // centrale sia che sia l'ultima (dove la barra può finire dritta o a
    // punta di freccia). Quando il lato è tagliato a punta (continuaPrima/
    // continuaDopo), si aggiunge il "coneRun" (la stessa distanza usata dal
    // clip-path per tagliare l'angolo): così testo e numero restano nella
    // parte dritta della barra, senza entrare nel cono della freccia.
    <div style={{ display: "grid", gridTemplateColumns: `repeat(${indiciGiorno.length},1fr)`, gap, width: "100%", height: "100%", boxSizing: "border-box" }}>
      {indiciGiorno.map((indice, i) => {
        const ultimoGiorno = i === ultimo && ultimaCellaEUltimoGiorno;
        return (
        <div
          key={i}
          style={{
            position: "relative",
            display: "flex", alignItems: "center", justifyContent: i === 0 ? "space-between" : "center", gap: 3, minWidth: 0, overflow: "hidden",
            // il rientro riservato al cono della freccia è sempre lo stesso,
            // sia che questo segmento prosegua davvero da/verso un'altra
            // riga sia che inizi/finisca dritto: così i numeri di frazione
            // restano allineati alla stessa distanza dal bordo del giorno
            // su tutte le righe, indipendentemente da dove ogni singolo
            // corso comincia
            paddingLeft: i === 0 ? inset + coneRun : 0,
            paddingRight: gap + (i === ultimo ? coneRun : 0),
            boxSizing: "border-box",
          }}
        >
          {sfondoCella(occupancy, coloreCorso, ultimoGiorno)}
          {i === 0 && (
            isMobile ? (
              <span
                style={{
                  position: "relative", zIndex: 1,
                  ...fontCondensato,
                  display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical",
                  overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "normal", wordBreak: "break-word",
                  flex: "1 1 auto", minWidth: 0, fontSize: 10 * fontScaleBarre, lineHeight: 1.05,
                }}
              >
                {etichetta}
              </span>
            ) : (
              <span style={{ position: "relative", zIndex: 1, ...fontCondensato, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{etichetta}</span>
            )
          )}
          {indice != null && !ultimoGiorno && !(isMobile && i === 0) && (
            <span style={{ position: "relative", zIndex: 1, fontFamily: "'Inter',sans-serif", fontWeight: 400, fontStyle: "italic", color: "#F2F2F2", fontSize: fontSizeBadge, flexShrink: 0, display: "inline-flex", alignItems: "center", gap: 2 }}>
              {indice}/{giorniTotali}
            </span>
          )}
        </div>
        );
      })}
    </div>
  );
}

// ---------- Card / pulsanti base ----------
// spunta verde ben visibile accanto ai campi di upload file, per confermare
// a colpo d'occhio che un file (nuovo o già caricato in precedenza) è
// presente, senza dover leggere la scritta piccola del browser sull'input
function BadgeFileCaricato() {
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6, color: "#2E7D32", fontWeight: 700, fontSize: 14, flexShrink: 0 }}>
      <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
        <circle cx="12" cy="12" r="11" fill="#E8F5E9" stroke="#2E7D32" strokeWidth="2" />
        <path d="M7 12.5l3.2 3.2L17 8.5" stroke="#2E7D32" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
      File caricato
    </span>
  );
}

// card grande della home (griglia 4 colonne): icona, titolo, una riga di
// descrizione e una freccia in basso — passando Icona/descrizione. Senza
// (gli hub interni tipo ERP che riusano lo stesso componente) resta la
// versione minimale di sempre, solo titolo, per non alterarne l'aspetto.
// "attivo=false" la mostra spenta con badge "Non attivo", per aree non
// ancora costruite. Su mobile, invece della card col testo dentro, un
// tasto "squircle" stile app iOS: solo l'icona al centro, etichetta sotto
// — niente più descrizione né freccia, che dentro una tile così piccola
// non si leggevano comunque. Vale per tutte le pagine che riusano questo
// componente (Home, Statistiche, Amministrazione, Gestione magazzino e
// shop), non solo la Home.
function TileHome({
  title, descrizione, Icona, attivo = true, onClick, badge,
  // riordino/cartelle (solo programmatore, vedi GrigliaTasti) — tutti
  // opzionali: i 27+ usi esistenti di TileHome non li passano e restano
  // identici a prima
  maniglia, draggableTasto = false, onDragStartTasto, onDragEndTasto, onDragOverTasto, onDropTasto, attenuato = false, evidenziato = false,
  // rinomina del tasto (solo programmatore, solo mobile — vedi
  // GrigliaTasti): toccando il testo sotto l'icona invece di aprire il
  // tasto. Assente per chi non è programmatore o per le cartelle.
  onRinominaEtichetta,
}) {
  const isMobile = useIsMobile();
  const ricca = !!Icona;
  const coloreTesto = attivo ? NAVY : MUTED;
  if (isMobile && ricca) {
    return (
      <button
        onClick={attivo ? onClick : undefined}
        disabled={!attivo}
        draggable={draggableTasto}
        onDragStart={draggableTasto ? onDragStartTasto : undefined}
        onDragEnd={draggableTasto ? onDragEndTasto : undefined}
        onDragOver={onDragOverTasto}
        onDrop={onDropTasto}
        style={{
          ...fontBody, width: "82%", minWidth: 0, margin: "0 auto", boxSizing: "border-box", background: "none", border: "none", padding: 0,
          display: "flex", flexDirection: "column", alignItems: "center", cursor: attivo ? "pointer" : "default",
          opacity: attenuato ? 0.5 : 1,
        }}
      >
        <div style={{
          width: "100%", aspectRatio: "1 / 1", position: "relative", boxSizing: "border-box",
          display: "flex", alignItems: "center", justifyContent: "center",
          background: attivo ? "#FFFFFF" : "#F1EAE0", borderRadius: "22%",
          boxShadow: "0 1px 4px rgba(14,27,51,0.16)",
          outline: evidenziato ? `2px solid ${NAVY}` : "none", outlineOffset: 2,
        }}>
          {maniglia}
          <Icona size={40} color={coloreTesto} />
          {!attivo && (
            <span style={{ position: "absolute", top: 4, right: 4, ...fontBody, fontSize: 6.5, fontWeight: 700, color: MUTED, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 20, padding: "1.5px 5px" }}>Non attivo</span>
          )}
          {/* il pallino di quanti avvisi ci sono: da mobile mancava, ed è
              proprio lì che serve — la home del telefono è quella che si
              guarda di corsa */}
          {attivo && badge > 0 && (
            <>
              <style>{`@keyframes lampeggiaBadgeTasto { 0%, 49.9% { opacity: 1; } 50%, 100% { opacity: 0; } }`}</style>
              <span title={`${badge} avvis${badge === 1 ? "o" : "i"} da gestire`} style={{ position: "absolute", top: -4, right: -4, ...fontBody, fontSize: 11, fontWeight: 700, color: "#fff", background: "#C0392B", borderRadius: 20, minWidth: 20, height: 20, display: "flex", alignItems: "center", justifyContent: "center", padding: "0 5px", animation: "lampeggiaBadgeTasto 1s steps(1, end) infinite", boxShadow: "0 1px 3px rgba(14,27,51,0.3)" }}>{badge}</span>
            </>
          )}
        </div>
        <div
          onClick={onRinominaEtichetta ? (e) => { e.stopPropagation(); onRinominaEtichetta(); } : undefined}
          title={onRinominaEtichetta ? "Tocca per rinominare questo tasto" : undefined}
          style={{
            ...fontBody, fontSize: 11, fontWeight: 600, color: coloreTesto, marginTop: 6, lineHeight: 1.25, textAlign: "center", width: "max-content", maxWidth: "none", whiteSpace: "nowrap",
            ...(onRinominaEtichetta ? { cursor: "pointer", textDecoration: "underline dotted", textUnderlineOffset: 2 } : {}),
          }}
        >
          {title}
        </div>
      </button>
    );
  }
  return (
    <button
      onClick={attivo ? onClick : undefined}
      disabled={!attivo}
      draggable={draggableTasto}
      onDragStart={draggableTasto ? onDragStartTasto : undefined}
      onDragEnd={draggableTasto ? onDragEndTasto : undefined}
      onDragOver={onDragOverTasto}
      onDrop={onDropTasto}
      style={{
        // 90% invece di 100%: il quadrato resta più piccolo della sua
        // cella della griglia, lasciando vedere lo sfondo dell'app anche
        // fra un tasto e l'altro, non solo nel gap
        ...fontBody, textAlign: ricca ? "center" : "left", width: "90%", margin: "0 auto", boxSizing: "border-box",
        aspectRatio: "1 / 1", position: "relative",
        display: "flex", flexDirection: "column", alignItems: ricca ? "center" : "stretch", justifyContent: ricca ? "center" : "flex-end", minWidth: 0,
        background: attivo ? "#FFFFFF" : "#F1EAE0", border: `1px solid ${CREAM_BORDER}`, borderRadius: isMobile ? 12 : 18,
        padding: ricca ? (isMobile ? "16px 10px 12px" : "28px 22px 22px") : (isMobile ? "8px 10px" : 22),
        cursor: attivo ? "pointer" : "default", overflow: "hidden",
        opacity: attenuato ? 0.5 : 1,
        outline: evidenziato ? `2px solid ${NAVY}` : "none", outlineOffset: 2,
      }}
    >
      {maniglia}
      {!attivo && (
        <span style={{ position: "absolute", top: isMobile ? 10 : 16, right: isMobile ? 8 : 18, ...fontBody, fontSize: isMobile ? 8 : 10.5, fontWeight: 600, color: MUTED, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 20, padding: isMobile ? "2px 8px" : "3px 10px" }}>Non attivo</span>
      )}
      {/* il pallino rosso lampeggia: sta su un tasto che si guarda di
          sfuggita passando, e fermo si confonde con il resto della pagina */}
      {attivo && badge > 0 && (
        <>
          <style>{`@keyframes lampeggiaBadgeTasto { 0%, 49.9% { opacity: 1; } 50%, 100% { opacity: 0; } }`}</style>
          <span title={`${badge} avvis${badge === 1 ? "o" : "i"} da gestire`} style={{ position: "absolute", top: isMobile ? 6 : 14, right: isMobile ? 6 : 16, ...fontBody, fontSize: isMobile ? 10 : 12, fontWeight: 700, color: "#fff", background: "#C0392B", borderRadius: 20, minWidth: isMobile ? 18 : 22, height: isMobile ? 18 : 22, display: "flex", alignItems: "center", justifyContent: "center", padding: "0 5px", animation: "lampeggiaBadgeTasto 1s steps(1, end) infinite" }}>{badge}</span>
        </>
      )}
      {ricca ? (
        <>
          <div style={{ color: coloreTesto, marginBottom: isMobile ? 6 : 12 }}><Icona size={isMobile ? 26 : 80} color={coloreTesto} /></div>
          <div style={{ ...fontDisplay, fontSize: isMobile ? 12.5 : 17, fontWeight: 700, color: coloreTesto, marginBottom: isMobile ? 4 : 7, lineHeight: 1.2 }}>{title}</div>
          {descrizione && (
            <div style={{ ...fontBody, fontSize: isMobile ? 10 : 12, color: MUTED, lineHeight: 1.35, display: "-webkit-box", WebkitLineClamp: isMobile ? 2 : 3, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{descrizione}</div>
          )}
          <div style={{ fontSize: isMobile ? 13 : 16, color: coloreTesto, paddingTop: isMobile ? 6 : 12 }}>&rarr;</div>
        </>
      ) : (
        <span style={{ ...fontDisplay, fontSize: isMobile ? 13 : 22, fontWeight: 700, lineHeight: 1.15, color: coloreTesto }}>{title}</span>
      )}
    </button>
  );
}
// stessa casetta usata nel bottone "Home" della barra in alto, riusata
// nel breadcrumb di una cartella di tasti
function IconaCasa({ size = 16, color = "currentColor" }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
      <polyline points="9 22 9 12 15 12 15 22" />
    </svg>
  );
}
// n barre verticali, per il tasto "N tasti per riga" (solo programmatore)
function IconaColonne({ n, size = 16, color = "currentColor" }) {
  const gap = 2.5;
  const w = (24 - gap * (n - 1)) / n;
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
      {Array.from({ length: n }, (_, i) => (
        <rect key={i} x={i * (w + gap)} y="5" width={w} height="14" rx="2" fill={color} />
      ))}
    </svg>
  );
}
// tasto "indietro" delle pagine di contenuto (non le 4 pagine a tasti,
// quelle hanno già la loro barra di navigazione): un piccolo tassello
// quadrato con l'icona cartellina e, piccolo, il nome della pagina a cui
// si torna — stesso comportamento di click di sempre (va dove andava
// già l'onBack di quella pagina), solo l'aspetto cambia. Nessun
// trascinamento qui: queste pagine non contengono tasti/cartelle da
// spostare, a differenza della Home
function TastoLivelloPrecedente({ titolo, onClick }) {
  return (
    <button
      onClick={onClick}
      title={titolo}
      style={{
        display: "flex", alignItems: "center", gap: 6, flexShrink: 0,
        background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 10,
        padding: "6px 10px", cursor: "pointer", maxWidth: 130,
      }}
    >
      <IconaCartellaShop size={14} color={NAVY} />
      <span style={{ ...fontBody, fontSize: 10.5, fontWeight: 700, color: NAVY, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{titolo}</span>
    </button>
  );
}
// griglia di tasti riordinabile e, solo in Home, raggruppabile in
// cartelle stile Windows — un solo componente riusato da Home,
// Amministrazione, Gestione magazzino e shop, Statistiche:
//
// - "definizioni": elenco { chiave, title, descrizione, Icona, attivo, onClick }
//   di TUTTI i tasti possibili di quella pagina (le voci vere e proprie,
//   sempre le stesse: l'ordine/raggruppamento è quello che cambia).
// - "ordine": l'array persistito (impostazioni_layout_tasti.ordine per
//   quella pagina) — stringhe (chiave di un tasto) o cartelle
//   { tipo:"cartella", id, nome, tasti:[chiave,...] }. Se vuoto/assente,
//   parte dall'ordine di default (l'ordine di "definizioni" stesso).
// - maniglia "⠿" (solo ruoloUtente "programmatore"): trascina per
//   riordinare, dentro la lista in cui ci si trova (cima o dentro una
//   cartella aperta) — stesso schema già usato per le sezioni di
//   "Modifica iscritto" (order via array, salvato subito su Supabase).
// - trascinare il TASTO INTERO (non la maniglia) sopra un altro tasto,
//   solo se "consentiCartelle" (oggi solo Home) e solo al livello
//   principale: se il bersaglio è già una cartella, il tasto trascinato
//   ci entra; se è un tasto semplice, i due si fondono in una cartella
//   nuova (nome chiesto con un prompt, come altre finestre semplici
//   dell'app). Un tasto dentro una cartella aperta, trascinato
//   sull'icona Home del breadcrumb, torna in cima — nessuna cartella
//   dentro un'altra cartella, per restare semplice.
function GrigliaTasti({ pagina, definizioni, ordine, colonne, etichette = {}, ruoloUtente, onSalvaOrdine, onSalvaColonne, onSalvaEtichetta, consentiCartelle = false, colonneDesktop = 3 }) {
  const isMobile = useIsMobile();
  const programmatore = ruoloUtente === "programmatore";
  // scelta del programmatore per QUESTA pagina, salvata — se non ha mai
  // scelto nulla resta il default della pagina (colonneDesktop). Il
  // mobile è sempre a 4 per riga (stile griglia icone iOS), questa scelta
  // riguarda solo il desktop
  const colonneEffettive = colonne || colonneDesktop;
  const [cartellaApertaId, setCartellaApertaId] = useState(null);
  const dragRef = React.useRef(null); // { tipo: "grip" | "tasto", chiave }
  const [trascinata, setTrascinata] = useState(null);
  const [suCursore, setSuCursore] = useState(null);

  const defPerChiave = useMemo(() => Object.fromEntries(definizioni.map((d) => [d.chiave, d])), [definizioni]);

  // in coda, i tasti mai visti in nessun ordine salvato (es. appena
  // aggiunti al codice): così non spariscono mai dalla vista
  const ordineEffettivo = useMemo(() => {
    const base = Array.isArray(ordine) && ordine.length > 0 ? ordine : definizioni.map((d) => d.chiave);
    const visti = new Set();
    base.forEach((nodo) => {
      if (typeof nodo === "string") visti.add(nodo);
      else if (nodo?.tipo === "cartella") (nodo.tasti || []).forEach((c) => visti.add(c));
    });
    const mancanti = definizioni.map((d) => d.chiave).filter((c) => !visti.has(c));
    return mancanti.length ? [...base, ...mancanti] : base;
  }, [ordine, definizioni]);

  const cartellaAperta = cartellaApertaId ? ordineEffettivo.find((n) => n?.tipo === "cartella" && n.id === cartellaApertaId) || null : null;
  // la cartella aperta può essere stata svuotata/rinominata da un altro
  // dispositivo nel frattempo: se non esiste più, si torna in cima da soli
  useEffect(() => { if (cartellaApertaId && !cartellaAperta) setCartellaApertaId(null); }, [cartellaApertaId, cartellaAperta]);

  async function salva(nuovoOrdine) {
    if (onSalvaOrdine) await onSalvaOrdine(nuovoOrdine);
  }
  function iniziaGrip(chiave) { dragRef.current = { tipo: "grip", chiave }; setTrascinata(chiave); }
  function iniziaTasto(chiave) { dragRef.current = { tipo: "tasto", chiave }; setTrascinata(chiave); }
  function fineTrascinamento() { dragRef.current = null; setTrascinata(null); setSuCursore(null); }

  async function rilasciaSuChiave(chiaveDestinazione) {
    const origine = dragRef.current;
    fineTrascinamento();
    if (!origine || origine.chiave === chiaveDestinazione) return;
    const clone = JSON.parse(JSON.stringify(ordineEffettivo));
    const listaCorrente = cartellaApertaId ? clone.find((n) => n?.tipo === "cartella" && n.id === cartellaApertaId)?.tasti : clone;
    if (!listaCorrente) return;

    if (origine.tipo === "grip") {
      const idxO = listaCorrente.findIndex((n) => (typeof n === "string" ? n === origine.chiave : n.id === origine.chiave));
      const idxD = listaCorrente.findIndex((n) => (typeof n === "string" ? n === chiaveDestinazione : n.id === chiaveDestinazione));
      if (idxO < 0 || idxD < 0) return;
      const [spostato] = listaCorrente.splice(idxO, 1);
      listaCorrente.splice(idxD, 0, spostato);
      await salva(clone);
      return;
    }

    // trascinamento del tasto intero: solo al livello principale di una
    // pagina con le cartelle abilitate
    if (!consentiCartelle || cartellaApertaId) return;
    const destNodo = clone.find((n) => (typeof n === "string" ? n === chiaveDestinazione : n.id === chiaveDestinazione));
    const idxOrig = clone.findIndex((n) => n === origine.chiave);
    if (!destNodo || idxOrig < 0) return; // il tasto trascinato deve essere sciolto in cima

    if (typeof destNodo === "object" && destNodo.tipo === "cartella") {
      clone.splice(idxOrig, 1);
      destNodo.tasti.push(origine.chiave);
      await salva(clone);
      return;
    }
    const nome = window.prompt("Nome della cartella:", "Nuova cartella");
    if (!nome || !nome.trim()) return;
    const idxDest = clone.findIndex((n) => n === chiaveDestinazione);
    const nuovaCartella = { tipo: "cartella", id: `cartella-${Date.now()}`, nome: nome.trim(), tasti: [chiaveDestinazione, origine.chiave] };
    const daRimuovere = new Set([chiaveDestinazione, origine.chiave]);
    const nuovoTopLevel = clone.filter((n) => !(typeof n === "string" && daRimuovere.has(n)));
    const idxInserimento = Math.min(idxDest, nuovoTopLevel.length);
    nuovoTopLevel.splice(idxInserimento, 0, nuovaCartella);
    await salva(nuovoTopLevel);
  }
  async function rilasciaSuHome() {
    const origine = dragRef.current;
    fineTrascinamento();
    if (!origine || origine.tipo !== "tasto" || !cartellaApertaId) return;
    const clone = JSON.parse(JSON.stringify(ordineEffettivo));
    const cartella = clone.find((n) => n?.tipo === "cartella" && n.id === cartellaApertaId);
    if (!cartella) return;
    const idx = cartella.tasti.indexOf(origine.chiave);
    if (idx < 0) return;
    cartella.tasti.splice(idx, 1);
    clone.push(origine.chiave);
    await salva(clone);
  }

  function maniglia(chiave) {
    if (!programmatore) return null;
    return (
      <span
        draggable
        onDragStart={(e) => { e.stopPropagation(); iniziaGrip(chiave); }}
        onDragEnd={fineTrascinamento}
        onClick={(e) => e.stopPropagation()}
        title="Trascina per riordinare (salvato per tutti)"
        style={{ position: "absolute", top: 6, left: 6, zIndex: 2, cursor: "grab", color: MUTED, fontSize: 15, lineHeight: 1, padding: "3px 5px", userSelect: "none", background: "rgba(255,255,255,0.85)", borderRadius: 6 }}
      >
        ⠿
      </span>
    );
  }

  const listaVisibile = cartellaApertaId ? (cartellaAperta?.tasti || []) : ordineEffettivo;

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginBottom: isMobile ? 12 : 18, flexWrap: "wrap" }}>
        {consentiCartelle && cartellaAperta ? (
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <button
              onClick={() => setCartellaApertaId(null)}
              onDragOver={(e) => { if (programmatore && dragRef.current?.tipo === "tasto") e.preventDefault(); }}
              onDrop={rilasciaSuHome}
              title="Torna alla Home — trascina qui un tasto per tirarlo fuori dalla cartella"
              style={{ display: "flex", alignItems: "center", justifyContent: "center", width: 34, height: 34, borderRadius: 10, border: "none", background: NAVY, cursor: "pointer", flexShrink: 0 }}
            >
              <IconaCasa size={15} color="#fff" />
            </button>
            <span style={{ color: MUTED }}>/</span>
            <span style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY }}>{cartellaAperta.nome}</span>
          </div>
        ) : <div />}
        {programmatore && !isMobile && onSalvaColonne && (
          <div style={{ display: "flex", gap: 6 }}>
            {[4, 3].map((n) => (
              <button
                key={n}
                onClick={() => onSalvaColonne(n)}
                title={`${n} tasti per riga`}
                style={{ display: "flex", alignItems: "center", justifyContent: "center", width: 34, height: 34, borderRadius: 10, border: `1px solid ${CREAM_BORDER}`, background: colonneEffettive === n ? NAVY : "#fff", cursor: "pointer" }}
              >
                <IconaColonne n={n} size={16} color={colonneEffettive === n ? "#fff" : NAVY} />
              </button>
            ))}
          </div>
        )}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "repeat(4, 1fr)" : `repeat(${colonneEffettive}, 1fr)`, gap: isMobile ? 14 : 16, rowGap: isMobile ? 21 : 16 }}>
        {listaVisibile.map((nodo) => {
          const isCartella = typeof nodo === "object" && nodo?.tipo === "cartella";
          const chiave = isCartella ? nodo.id : nodo;
          const def = isCartella ? null : defPerChiave[chiave];
          if (!isCartella && !def) return null;
          const nTasti = isCartella ? (nodo.tasti || []).length : 0;
          return (
            <TileHome
              key={chiave}
              title={isCartella ? nodo.nome : (etichette[chiave] || def.title)}
              descrizione={isCartella ? `${nTasti} tast${nTasti === 1 ? "o" : "i"}` : def.descrizione}
              Icona={isCartella ? IconaCartellaShop : def.Icona}
              attivo={isCartella ? true : def.attivo}
              badge={isCartella ? null : def.badge}
              onClick={isCartella ? () => setCartellaApertaId(nodo.id) : def.onClick}
              maniglia={maniglia(chiave)}
              draggableTasto={programmatore && consentiCartelle && !isCartella}
              onDragStartTasto={() => iniziaTasto(chiave)}
              onDragEndTasto={fineTrascinamento}
              onDragOverTasto={(e) => { if (programmatore && dragRef.current) { e.preventDefault(); setSuCursore(chiave); } }}
              onDropTasto={() => programmatore && rilasciaSuChiave(chiave)}
              attenuato={trascinata === chiave}
              evidenziato={!!dragRef.current && dragRef.current.chiave !== chiave && suCursore === chiave}
              onRinominaEtichetta={programmatore && !isCartella && onSalvaEtichetta ? () => {
                const attuale = etichette[chiave] || def.title;
                const nuovo = window.prompt("Testo per questo tasto (vuoto = nome originale):", attuale);
                if (nuovo !== null) onSalvaEtichetta(chiave, nuovo);
              } : undefined}
            />
          );
        })}
      </div>
    </div>
  );
}

function Button({ children, onClick, variant = "primary", style = {}, disabled }) {
  const base = {
    ...fontBody,
    fontSize: 14,
    padding: "10px 18px",
    borderRadius: 10,
    cursor: disabled ? "default" : "pointer",
    border: "1px solid " + NAVY,
    opacity: disabled ? 0.5 : 1,
  };
  const variants = {
    primary: { background: NAVY, color: "#fff" },
    ghost: { background: "transparent", color: NAVY },
    danger: { background: "#fff", color: "#C0392B", border: "1px solid #C0392B" },
  };
  return (
    <button disabled={disabled} onClick={onClick} style={{ ...base, ...variants[variant], ...style }}>
      {children}
    </button>
  );
}

// minLabelHeight: quando più Field stanno affiancati in una riga e le
// etichette hanno lunghezze diverse (una va a capo su due righe, un'altra
// no), i campi sotto risultano sfalsati; passandola, tutte le etichette
// della riga riservano la stessa altezza e i campi tornano allineati
// "compatto": etichetta e margini ridotti, per le file di filtri che da
// mobile devono stare tutte su una riga
function Field({ label, children, minLabelHeight, compatto = false }) {
  return (
    <div style={{ marginBottom: compatto ? 8 : 14 }}>
      <div style={{ ...fontBody, fontSize: compatto ? 8.5 : 12, color: MUTED, marginBottom: compatto ? 3 : 5, textTransform: "uppercase", letterSpacing: compatto ? 0.2 : 0.5, lineHeight: 1.15, minHeight: minLabelHeight, display: minLabelHeight ? "flex" : undefined, alignItems: minLabelHeight ? "flex-end" : undefined }}>{label}</div>
      {children}
    </div>
  );
}

const inputStyle = {
  ...fontBody,
  width: "100%",
  boxSizing: "border-box",
  padding: "10px 12px",
  borderRadius: 8,
  border: `1px solid ${CREAM_BORDER}`,
  fontSize: 14,
};
// campi piccoli per liste fitte di righe con numeri corti (Riepilogo
// amministrativo → Costi della classe): inputStyle è pensato per form
// con pochi campi, troppo alto per una tabella di più righe
const campoCompattoStyle = { ...inputStyle, padding: "5px 7px", fontSize: 12.5 };
// Le aree della scheda iscritto — totale pattuito, quote, fatturazione e
// qualunque blocco si aggiunga in futuro — hanno tutte lo stesso vestito:
// fondo azzurro tenue e bordo intonato, così ognuna si stacca dal bianco
// della scheda. Le caselle dentro restano bianche con un filo appena
// accennato: sul colore basta il bianco a dire dove si scrive.
const areaSchedaIscritto = {
  background: "#FBF6EA",
  border: `1px solid ${CREAM_BORDER}`,
  borderLeft: `4px solid ${GOLD}`,
  borderRadius: 12,
  padding: 16,
};
const campoAreaScheda = { ...inputStyle, background: "#fff", border: "1px solid #E6DFCE", borderRadius: 8 };
// il titolo in cima a ogni area: icona a sinistra, testo maiuscolo e
// spaziato. Le icone stanno solo qui — accanto ai metodi di pagamento no,
// lì bastano i cerchietti
const titoloAreaScheda = { ...fontBody, fontSize: 12.5, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.8 };
function IntestazioneArea({ Icona, children }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 9, marginBottom: 12, color: GOLD }}>
      {Icona && <Icona size={18} color={GOLD} />}
      <span style={titoloAreaScheda}>{children}</span>
    </div>
  );
}

// tendina con ricerca: una <select> nativa va benissimo per dieci voci,
// ma con 140 fornitori in ordine alfabetico trovare il proprio significa
// scorrere a mano fino alla lettera giusta. Qui la lista si apre con una
// riga di ricerca in testa e si filtra per parola mentre si scrive.
// opzioni = [{ id, nome }]; valore "" significa nessuna scelta
function TendinaRicerca({ valore, opzioni, onCambia, etichettaVuoto = "— nessuno —", placeholderRicerca = "Cerca per parola…" }) {
  const [aperta, setAperta] = useState(false);
  const [filtro, setFiltro] = useState("");
  const contenitore = useRef(null);
  // chiusura al clic fuori: senza, la tendina resterebbe aperta sopra il
  // resto del form e coprirebbe i campi sotto
  useEffect(() => {
    if (!aperta) return;
    function fuori(e) { if (contenitore.current && !contenitore.current.contains(e.target)) setAperta(false); }
    document.addEventListener("mousedown", fuori);
    return () => document.removeEventListener("mousedown", fuori);
  }, [aperta]);

  const scelta = (opzioni || []).find((o) => o.id === valore) || null;
  const q = filtro.trim().toLowerCase();
  const filtrate = q ? (opzioni || []).filter((o) => (o.nome || "").toLowerCase().includes(q)) : (opzioni || []);
  const rigaStile = (attiva) => ({
    ...fontBody, fontSize: 13, color: NAVY, background: attiva ? "#F4F1E8" : "transparent",
    border: "none", width: "100%", textAlign: "left", padding: "7px 10px", cursor: "pointer",
    fontWeight: attiva ? 700 : 400, borderRadius: 6,
  });

  return (
    <div ref={contenitore} style={{ position: "relative" }}>
      <button
        type="button"
        onClick={() => { setAperta((a) => !a); setFiltro(""); }}
        style={{ ...inputStyle, background: "#fff", cursor: "pointer", textAlign: "left", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}
      >
        <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", color: scelta ? NAVY : MUTED }}>
          {scelta ? scelta.nome : etichettaVuoto}
        </span>
        <span style={{ color: MUTED, fontSize: 11 }}>▾</span>
      </button>
      {aperta && (
        <div style={{ position: "absolute", zIndex: 60, top: "calc(100% + 4px)", left: 0, right: 0, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 10, boxShadow: "0 10px 28px rgba(14,27,51,0.16)", padding: 8 }}>
          <input
            autoFocus style={{ ...inputStyle, marginBottom: 6 }} placeholder={placeholderRicerca}
            value={filtro} onChange={(e) => setFiltro(e.target.value)}
          />
          <div style={{ maxHeight: 240, overflowY: "auto" }}>
            <button type="button" onClick={() => { onCambia(""); setAperta(false); }} style={rigaStile(!valore)}>{etichettaVuoto}</button>
            {filtrate.map((o) => (
              <button type="button" key={o.id} onClick={() => { onCambia(o.id); setAperta(false); }} style={rigaStile(o.id === valore)}>
                {o.nome}
              </button>
            ))}
            {filtrate.length === 0 && (
              <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, padding: "8px 10px" }}>Nessun risultato per "{filtro.trim()}".</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// ---------- helper per i calcoli di imponibile/IVA/totale ----------
const PREZZO_MODELLA = 60;

// ===========================================================
// ORDINAMENTO DELLE TABELLE
//
// Ogni elenco a colonne si riordina cliccando l'intestazione: primo clic
// crescente, secondo decrescente, terzo si torna all'ordine naturale
// della pagina (che spesso vuol dire qualcosa — le date in ordine di
// calendario, i prodotti per venduto). Il confronto capisce da solo che
// tipo di dato ha davanti: numeri per grandezza, date in ordine di
// calendario, testo in ordine alfabetico italiano (accenti compresi), e
// i vuoti sempre in fondo, in salita come in discesa.
// ===========================================================
function confrontaPerOrdinamento(a, b) {
  const vuotoA = a == null || a === "";
  const vuotoB = b == null || b === "";
  if (vuotoA && vuotoB) return 0;
  if (vuotoA) return 1;   // i vuoti finiscono in fondo comunque si ordini
  if (vuotoB) return -1;
  if (typeof a === "boolean" || typeof b === "boolean") return (a ? 1 : 0) - (b ? 1 : 0);
  if (a instanceof Date || b instanceof Date) return new Date(a).getTime() - new Date(b).getTime();
  if (typeof a === "number" && typeof b === "number") return a - b;
  return String(a).localeCompare(String(b), "it", { sensitivity: "base", numeric: true });
}
// stato + comandi dell'ordinamento di una tabella. `iniziale` è l'ordine
// di partenza ({ campo, direzione }) oppure null per l'ordine naturale
function useOrdinamentoTabella(iniziale = null) {
  const [ordine, setOrdine] = useState(iniziale);
  function cambiaOrdine(campo) {
    setOrdine((prec) => {
      if (prec?.campo !== campo) return { campo, direzione: "asc" };
      if (prec.direzione === "asc") return { campo, direzione: "desc" };
      return iniziale && iniziale.campo === campo ? null : null;
    });
  }
  // valori = { nomeCampo: (riga, indice) => valore da confrontare }
  function ordina(righe, valori) {
    if (!ordine || !valori?.[ordine.campo]) return righe || [];
    const estrai = valori[ordine.campo];
    const segno = ordine.direzione === "asc" ? 1 : -1;
    return [...(righe || [])]
      .map((r, i) => ({ r, i }))
      .sort((x, y) => {
        const cmp = confrontaPerOrdinamento(estrai(x.r, x.i), estrai(y.r, y.i));
        return cmp !== 0 ? cmp * segno : x.i - y.i;  // parità: resta l'ordine di partenza
      })
      .map((x) => x.r);
  }
  return { ordine, cambiaOrdine, ordina };
}
// intestazione di colonna cliccabile: si comporta come una <th> normale
// (stile e contenuto passati da fuori), in più mostra la freccia
// riquadro di sintesi (i "display" in cima alle pagine): quadrato, con
// etichetta, numero e nota tutti centrati sui due assi. La forma fissa
// serve a renderli confrontabili a colpo d'occhio: un numero grande e
// uno piccolo occupano lo stesso spazio, e la riga resta ordinata anche
// quando una nota è lunga e un'altra manca
function RiquadroKpi({ etichetta, valore, nota, compatto, children, aSinistra, icona }) {
  return (
    <div style={{
      ...cardStyle, marginBottom: 0, aspectRatio: "1 / 1", padding: compatto ? "10px 8px" : 16, position: "relative", overflow: "hidden",
      display: "flex", flexDirection: "column", gap: 5,
      alignItems: aSinistra ? "flex-start" : "center",
      justifyContent: "center",
      textAlign: aSinistra ? "left" : "center",
    }}>
      <div style={{ ...fontBody, fontSize: compatto ? 9 : 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5 }}>{etichetta}</div>
      <div style={{ ...fontDisplay, fontSize: compatto ? 15 : 22, fontWeight: 700, color: NAVY }}>{valore}</div>
      {children}
      {nota && <div style={{ ...fontBody, fontSize: 11, color: MUTED, lineHeight: 1.35, maxWidth: aSinistra ? "100%" : "92%" }}>{nota}</div>}
      {/* l'icona è solo un segno di riconoscimento, in filigrana nell'angolo:
          serve a distinguere i riquadri da lontano, non a essere letta */}
      {icona && <div style={{ position: "absolute", right: 12, bottom: 10, color: CREAM_BORDER, opacity: 0.9, pointerEvents: "none" }}>{icona}</div>}
    </div>
  );
}
function ThOrdina({ campo, ordine, onOrdina, style, children, title }) {
  const attiva = ordine?.campo === campo;
  return (
    <th
      onClick={campo ? () => onOrdina(campo) : undefined}
      title={title || (campo ? "Ordina per questa colonna" : undefined)}
      style={{ ...style, cursor: campo ? "pointer" : (style?.cursor || "default"), userSelect: "none", ...(attiva ? { color: NAVY } : {}) }}
    >
      {children}
      {attiva && <span style={{ marginLeft: 4 }}>{ordine.direzione === "asc" ? "▲" : "▼"}</span>}
    </th>
  );
}
function round2(n) {
  return Math.round((n + Number.EPSILON) * 100) / 100;
}
function parseNum(v) {
  const n = parseFloat(String(v).replace(",", "."));
  return isNaN(n) ? 0 : n;
}

// ---------- IVA prodotti: il netto è sempre il dato canonico, il lordo
// è sempre derivato (mai scritto a mano) — vedi migrazione
// 20260827120000_gestione_iva_prodotti.sql. L'imposta si arrotonda una
// sola volta (netto*aliquota/100): il lordo è sempre netto+imposta
// arrotondata, mai arrotondato per conto suo, così netto+iva=lordo torna
// sempre esatto sui centesimi
const ALIQUOTE_IVA_STANDARD = [0, 4, 5, 10, 22];
// il prezzo al pubblico di un prodotto: nel database prezzo_vendita è il
// NETTO (l'IVA si gestisce in anagrafica), ma in tutti gli elenchi conta
// il numero che paga il cliente — quello sul sito e sullo scontrino.
// Mostrare il netto faceva sembrare sbagliato l'intero listino
function prezzoAlPubblico(p) {
  if (p?.prezzo_vendita == null) return null;
  return round2(p.prezzo_vendita * (1 + (p.aliquota_iva_vendita ?? 22) / 100));
}
function calcolaIvaELordo(netto, aliquotaPct) {
  if (netto == null || aliquotaPct == null) return { iva: null, lordo: null };
  const iva = round2(netto * (aliquotaPct / 100));
  return { iva, lordo: round2(netto + iva) };
}
// unico punto in cui si parte dal lordo (il toggle "netto/lordo" in
// scheda prodotto): il netto si ricava all'indietro e si arrotonda
// subito, diventando da qui in poi l'unico valore salvato — un nuovo
// giro netto->lordo->netto riparte sempre da un netto già arrotondato,
// non da un lordo "vecchio", quindi non si accumula mai una deriva tra
// un salvataggio e l'altro (al più ±1 centesimo di scarto in un singolo
// giro di conversione, inevitabile arrotondando sui centesimi)
function nettoDaLordo(lordo, aliquotaPct) {
  if (lordo == null || aliquotaPct == null) return null;
  return round2(lordo / (1 + aliquotaPct / 100));
}
function fmtEuroIva(n) {
  return n == null ? "—" : n.toLocaleString("it-IT", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " €";
}
// blocco riutilizzabile "prezzo + IVA" (acquisto e vendita nella scheda
// prodotto): un solo campo di testo, il cui significato dipende dal
// toggle "netto/lordo" — passando da un modo all'altro il valore nel
// campo si converte subito, così i tasti non "cambiano significato"
// sotto le dita restando uguali. Il netto è sempre e solo quello
// derivato dal campo+modo attuali: è l'unico valore poi salvato.
function BloccoPrezzoIva({ titolo, inputTesto, onCambiaInputTesto, modo, onCambiaModo, aliquota, onCambiaAliquota, obbligatorio }) {
  const netto = modo === "netto" ? (inputTesto.trim() === "" ? null : parseNum(inputTesto)) : nettoDaLordo(inputTesto.trim() === "" ? null : parseNum(inputTesto), aliquota);
  const { iva, lordo } = calcolaIvaELordo(netto, aliquota);
  const aliquotaÈStandard = ALIQUOTE_IVA_STANDARD.includes(Number(aliquota));

  function cambiaModo(nuovoModo) {
    if (nuovoModo === modo) return;
    // converte il valore digitato nell'equivalente del nuovo modo, invece
    // di lasciarlo lì a significare qualcos'altro
    if (nuovoModo === "lordo") onCambiaInputTesto(lordo != null ? String(lordo) : "");
    else onCambiaInputTesto(netto != null ? String(netto) : "");
    onCambiaModo(nuovoModo);
  }

  // sul telefono i due blocchi (Acquisto e Vendita) stanno affiancati come
  // su desktop: impilati allungavano la scheda al punto che il campo del
  // prezzo finiva fuori schermo. In mezza larghezza ci stanno solo con
  // caratteri e spaziature ridotte, e con il selettore Netto/Lordo su una
  // riga sua invece che accanto al campo
  const stretto = useIsMobile();
  const etichetta = { ...fontBody, fontSize: stretto ? 9.5 : 12, color: MUTED, marginBottom: 4, textTransform: "uppercase", letterSpacing: 0.4, lineHeight: 1.2 };
  const campo = stretto ? { ...inputStyle, padding: "7px 8px", fontSize: 12.5 } : inputStyle;

  return (
    <div style={{ padding: stretto ? 8 : 12, borderRadius: 10, border: `1px solid ${CREAM_BORDER}`, background: "#FAF8F2", minWidth: 0 }}>
      <div style={{ ...fontBody, fontSize: stretto ? 11.5 : 12.5, fontWeight: 700, color: NAVY, marginBottom: stretto ? 6 : 10 }}>{titolo}</div>
      <div style={{ display: "flex", flexDirection: stretto ? "column" : "row", gap: stretto ? 6 : 10, marginBottom: stretto ? 6 : 10 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={etichetta}>{stretto ? (modo === "netto" ? "Prezzo netto" : "Prezzo lordo") : `Prezzo ${modo === "netto" ? "netto (IVA esclusa)" : "lordo (IVA inclusa)"}${obbligatorio ? "" : " — opzionale"}`}</div>
          <input style={campo} inputMode="decimal" value={inputTesto} onChange={(e) => onCambiaInputTesto(e.target.value)} placeholder="0,00" />
        </div>
        <div style={{ display: "flex", alignItems: stretto ? "stretch" : "flex-end", marginBottom: stretto ? 0 : 14 }}>
          <div style={{ display: "flex", flex: stretto ? 1 : undefined, border: `1px solid ${CREAM_BORDER}`, borderRadius: 8, overflow: "hidden" }}>
            <button type="button" onClick={() => cambiaModo("netto")} style={{ ...fontBody, flex: stretto ? 1 : undefined, fontSize: stretto ? 11 : 12, fontWeight: 700, padding: stretto ? "6px 8px" : "10px 12px", border: "none", cursor: "pointer", background: modo === "netto" ? NAVY : "#fff", color: modo === "netto" ? "#fff" : NAVY }}>Netto</button>
            <button type="button" onClick={() => cambiaModo("lordo")} style={{ ...fontBody, flex: stretto ? 1 : undefined, fontSize: stretto ? 11 : 12, fontWeight: 700, padding: stretto ? "6px 8px" : "10px 12px", border: "none", cursor: "pointer", background: modo === "lordo" ? NAVY : "#fff", color: modo === "lordo" ? "#fff" : NAVY }}>Lordo</button>
          </div>
        </div>
      </div>
      <div style={{ display: "flex", gap: stretto ? 6 : 10, alignItems: "flex-end", marginBottom: stretto ? 6 : 10 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={etichetta}>Aliquota IVA</div>
          <select
            style={campo}
            value={aliquotaÈStandard ? String(Number(aliquota)) : "altra"}
            onChange={(e) => onCambiaAliquota(e.target.value === "altra" ? aliquota : Number(e.target.value))}
          >
            {ALIQUOTE_IVA_STANDARD.map((a) => <option key={a} value={a}>{a}%</option>)}
            <option value="altra">Altra…</option>
          </select>
        </div>
        {!aliquotaÈStandard && (
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={etichetta}>{stretto ? "Personalizzata %" : "Aliquota personalizzata (%)"}</div>
            <input style={campo} inputMode="decimal" value={aliquota ?? ""} onChange={(e) => onCambiaAliquota(parseNum(e.target.value))} placeholder="es. 15" />
          </div>
        )}
      </div>
      <div style={{ ...fontBody, fontSize: stretto ? 10.5 : 12.5, color: MUTED, lineHeight: 1.3 }}>
        {netto != null
          ? <>{fmtEuroIva(netto)} netto → <b style={{ color: NAVY }}>{fmtEuroIva(lordo)}</b> lordo, IVA {aliquota}%</>
          : "Nessun prezzo inserito."}
      </div>
    </div>
  );
}
// avanzamento di un target vendite prodotti (Target Master/Venditori):
// somma le vendite POS dello stesso soggetto nel periodo del target — un
// domani, un reso/annullamento (righe negative, vedi §8 della specifica)
// si sottrae da solo qui dentro, senza bisogno di gestirlo a parte,
// perché è una somma semplice dei "totale"/quantità già registrati.
// tipo_target "combinato" richiede AND rigido: nessun premio parziale
function calcolaAvanzamentoTarget(t, venditeShop, prodottiShop) {
  // gli omaggi non contano per un target di vendita: regalare un
  // prodotto non è venderlo, altrimenti basterebbe regalare per
  // "raggiungere" l'obiettivo senza incassare nulla
  const righe = (venditeShop || []).filter((v) =>
    v.origine === "pos" && v.tipo_movimento !== "omaggio" && v.operatore_tipo === t.soggetto_tipo && v.operatore_id === t.soggetto_id &&
    v.data_ordine && v.data_ordine.slice(0, 10) >= t.data_inizio && v.data_ordine.slice(0, 10) <= t.data_fine
  );
  const incassoRaggiunto = round2(righe.reduce((s, v) => s + (v.totale || 0), 0));
  const quantitaPerNome = {};
  righe.forEach((v) => (Array.isArray(v.prodotti) ? v.prodotti : []).forEach((p) => {
    const chiave = (p.nome || "").trim().toLowerCase();
    quantitaPerNome[chiave] = (quantitaPerNome[chiave] || 0) + (Number(p.quantita) || 0);
  }));
  const prodottiConProgresso = (t.prodotti_obiettivo || []).map((po) => {
    const nomeProdotto = (prodottiShop || []).find((p) => p.id === po.prodotto_id)?.nome || "?";
    const raggiunto = quantitaPerNome[nomeProdotto.trim().toLowerCase()] || 0;
    return { nome: nomeProdotto, obiettivo: po.quantita_minima, raggiunto, completato: raggiunto >= po.quantita_minima };
  });
  const incassoCompletato = t.soglia_incasso == null || incassoRaggiunto >= t.soglia_incasso;
  const prodottiCompletati = prodottiConProgresso.every((p) => p.completato);
  const completato = t.tipo_target === "incasso" ? incassoCompletato
    : t.tipo_target === "prodotto" ? prodottiCompletati
    : incassoCompletato && prodottiCompletati;
  const percentualeIncasso = t.soglia_incasso ? Math.min(100, Math.round((incassoRaggiunto / t.soglia_incasso) * 100)) : null;
  return { incassoRaggiunto, prodottiConProgresso, completato, percentualeIncasso };
}
// avanzamento di un target VENDITORE sui corsi venduti (tipo_target
// 'corsi_denaro'/'corsi_punti'): silo separato dalla vendita prodotti,
// stessa definizione di "chiusura" già in uso nella dashboard venditori
// (iscrizione con questo tutor, non una vecchia iscrizione recuperata,
// data di inserimento dentro il periodo del target) — il valore è la
// somma di totale_pattuito, convertito in punti se il tipo lo richiede:
// 1 punto ogni 50€, arrotondato per difetto e senza decimali (550€ e
// 590€ valgono entrambi 11 punti, 600€ ne vale 12)
function calcolaAvanzamentoTargetCorsi(t, iscritti, nomeVenditore) {
  const nomeNorm = (nomeVenditore || "").trim().toUpperCase();
  const righe = (iscritti || []).filter((i) =>
    (i.tutor || "").trim().toUpperCase() === nomeNorm && !i.vecchia_iscrizione &&
    (i.ts || "").slice(0, 10) >= t.data_inizio && (i.ts || "").slice(0, 10) <= t.data_fine
  );
  const valoreVenduto = round2(righe.reduce((s, i) => s + (i.totale_pattuito || 0), 0));
  const raggiunto = t.tipo_target === "corsi_punti" ? Math.floor(valoreVenduto / 50) : valoreVenduto;
  const soglia = t.soglia_incasso || 0;
  const percentuale = soglia > 0 ? Math.min(100, Math.round((raggiunto / soglia) * 100)) : null;
  const completato = t.soglia_incasso == null || raggiunto >= t.soglia_incasso;
  return { raggiunto, soglia, percentuale, completato, numeroChiusure: righe.length };
}
// anello percentuale (SVG), usato nel pannello grande del target
function AnelloPercentuale({ percentuale, size = 92, spessore = 9, colore = GOLD }) {
  const raggio = (size - spessore) / 2;
  const circonferenza = 2 * Math.PI * raggio;
  const clamp = Math.min(100, Math.max(0, percentuale || 0));
  const offset = circonferenza * (1 - clamp / 100);
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ flexShrink: 0 }}>
      <circle cx={size / 2} cy={size / 2} r={raggio} fill="none" stroke="#EFE9DC" strokeWidth={spessore} />
      <circle
        cx={size / 2} cy={size / 2} r={raggio} fill="none" stroke={colore} strokeWidth={spessore} strokeLinecap="round"
        strokeDasharray={circonferenza} strokeDashoffset={offset} transform={`rotate(-90 ${size / 2} ${size / 2})`}
        style={{ transition: "stroke-dashoffset 400ms ease" }}
      />
      <text x="50%" y="46%" textAnchor="middle" dominantBaseline="middle" style={{ ...fontDisplay, fontSize: size * 0.24, fontWeight: 700 }} fill={NAVY}>{Math.round(clamp)}%</text>
      <text x="50%" y="67%" textAnchor="middle" dominantBaseline="middle" style={{ ...fontBody, fontSize: size * 0.1 }} fill={MUTED}>completato</text>
    </svg>
  );
}
// normalizza le due forme diverse di "avanzamento" (quella dei target
// vendita prodotti/incasso di calcolaAvanzamentoTarget, e quella dei
// target corsi venduti di calcolaAvanzamentoTargetCorsi) in un'unica
// struttura {obiettivo, raggiunto, percentuale, unita, completato,
// secondari}, così il pannello grande le mostra tutte allo stesso modo
function datiPrincipaliTarget(t, avanzamento) {
  if (TIPI_TARGET_CORSI.includes(t.tipo_target)) {
    return {
      obiettivo: avanzamento.soglia || null, raggiunto: avanzamento.raggiunto,
      percentuale: avanzamento.percentuale ?? 0, unita: t.tipo_target === "corsi_punti" ? "punti" : "€",
      completato: avanzamento.completato, secondari: [],
    };
  }
  if (t.soglia_incasso != null) {
    return {
      obiettivo: t.soglia_incasso, raggiunto: avanzamento.incassoRaggiunto,
      percentuale: avanzamento.percentualeIncasso ?? 0, unita: "€",
      completato: avanzamento.completato, secondari: avanzamento.prodottiConProgresso || [],
    };
  }
  const prods = avanzamento.prodottiConProgresso || [];
  if (prods.length === 1) {
    const p = prods[0];
    return {
      obiettivo: p.obiettivo, raggiunto: p.raggiunto,
      percentuale: Math.min(100, Math.round((p.raggiunto / p.obiettivo) * 100)), unita: "pz",
      completato: p.completato, secondari: [],
    };
  }
  const percentualeMedia = prods.length > 0
    ? Math.round(prods.reduce((s, p) => s + Math.min(100, (p.raggiunto / p.obiettivo) * 100), 0) / prods.length)
    : 0;
  return { obiettivo: null, raggiunto: null, percentuale: percentualeMedia, unita: null, completato: avanzamento.completato, secondari: prods };
}
const ETICHETTA_TIPO_TARGET = {
  incasso: "Target incasso", prodotto: "Target prodotto", combinato: "Target combinato",
  corsi_denaro: "Target corsi venduti", corsi_punti: "Target corsi venduti",
};
// pannello grande dell'avanzamento di un target — riusato da POS e dalle
// dashboard di master/venditore, sostituisce la vecchia card compatta
function PannelloTarget({ t, avanzamento }) {
  const d = datiPrincipaliTarget(t, avanzamento);
  const formatta = (n) => {
    if (n == null) return "—";
    // importi target sempre a numero intero, senza decimali dopo la virgola
    if (d.unita === "€") return fmtEuroErp(n);
    if (d.unita === "punti") return `${Math.round(n)} pt`;
    if (d.unita === "pz") return `${n} pz`;
    return `${n}`;
  };
  const mancante = d.obiettivo != null && d.raggiunto != null ? Math.max(0, round2(d.obiettivo - d.raggiunto)) : null;
  const coloreAccento = d.completato ? "#2E7D32" : GOLD;
  return (
    <div style={{ ...cardStyle, padding: 22, marginBottom: 14 }}>
      <div style={{ display: "flex", alignItems: "flex-start", gap: 16, flexWrap: "wrap" }}>
        <div style={{ width: 46, height: 46, borderRadius: "50%", background: "#FBF1D9", display: "flex", alignItems: "center", justifyContent: "center", color: GOLD, flexShrink: 0 }}>
          <IconaTargetRiga size={22} />
        </div>
        <div style={{ flex: "1 1 160px", minWidth: 160 }}>
          <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: GOLD, textTransform: "uppercase", letterSpacing: 0.6, marginBottom: 4 }}>
            {d.completato ? "Obiettivo raggiunto" : "Il tuo prossimo target"}
          </div>
          {d.obiettivo != null ? (
            <>
              <div style={{ ...fontDisplay, fontSize: 28, fontWeight: 700, color: NAVY }}>{formatta(d.obiettivo)}</div>
              <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginTop: 2 }}>entro il <span style={{ color: NAVY, fontWeight: 700 }}>{fmtDataLunga(t.data_fine).toUpperCase()}</span></div>
            </>
          ) : (
            <div style={{ ...fontDisplay, fontSize: 19, fontWeight: 700, color: NAVY }}>{ETICHETTA_TIPO_TARGET[t.tipo_target] || "Target"}</div>
          )}
        </div>
        {d.obiettivo != null && <AnelloPercentuale percentuale={d.percentuale} colore={coloreAccento} />}
      </div>

      {d.obiettivo != null && (
        <>
          <div style={{ display: "flex", alignItems: "stretch", gap: 22, margin: "18px 0 12px" }}>
            <div>
              <div style={{ ...fontDisplay, fontSize: 19, fontWeight: 700, color: NAVY }}>{formatta(d.raggiunto)}</div>
              <div style={{ ...fontBody, fontSize: 12, color: MUTED }}>raggiunti</div>
            </div>
            <div style={{ width: 1, background: CREAM_BORDER }} />
            <div>
              <div style={{ ...fontDisplay, fontSize: 19, fontWeight: 700, color: NAVY }}>{formatta(mancante)}</div>
              <div style={{ ...fontBody, fontSize: 12, color: MUTED }}>mancanti</div>
            </div>
          </div>
          <div style={{ position: "relative", height: 22, borderRadius: 11, background: "#EFE9DC", overflow: "hidden", marginBottom: 6 }}>
            <div style={{ height: "100%", width: `${d.percentuale}%`, background: coloreAccento, borderRadius: 11, transition: "width 400ms ease" }} />
            <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", ...fontBody, fontSize: 11, fontWeight: 700, color: NAVY }}>{d.percentuale}%</div>
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 11, color: MUTED, marginBottom: 12 }}>
            <span>{d.unita === "€" ? "0 €" : formatta(0)}</span>
            <span>{formatta(d.obiettivo)}</span>
          </div>
          <div style={{ ...fontBody, fontSize: 12.5, color: NAVY }}>
            {d.completato ? "🎉 Complimenti, obiettivo raggiunto!" : `🎉 Sei sulla strada giusta! Ti manca${d.unita === "punti" ? "no" : ""} ${formatta(mancante)} al target.`}
          </div>
        </>
      )}

      {d.secondari.length > 0 && (
        <div style={{ marginTop: d.obiettivo != null ? 16 : 8, paddingTop: d.obiettivo != null ? 14 : 0, borderTop: d.obiettivo != null ? `1px solid ${CREAM_BORDER}` : "none" }}>
          {d.secondari.map((p) => (
            <div key={p.nome} style={{ marginBottom: 8 }}>
              <div style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 12.5, color: NAVY, marginBottom: 3 }}>
                <span>{p.nome}</span>
                <span style={{ fontWeight: 700, color: p.completato ? "#2E7D32" : NAVY }}>{p.raggiunto} / {p.obiettivo}</span>
              </div>
              <div style={{ height: 6, borderRadius: 3, background: "#EFE9DC", overflow: "hidden" }}>
                <div style={{ height: "100%", width: `${Math.min(100, Math.round((p.raggiunto / p.obiettivo) * 100))}%`, background: p.completato ? "#2E7D32" : GOLD, borderRadius: 3 }} />
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
// data una quota { imponibile, totale, metodo }, aggiorna l'imponibile e ricalcola il totale
// (o viceversa). applicaIva=false = nessun calcolo IVA (es. saldo pagato in contanti)
function conImponibileAggiornato(prev, valore, applicaIva) {
  const num = parseNum(valore);
  const totale = valore === "" ? "" : String(applicaIva ? round2(num * 1.22) : num);
  return { ...prev, imponibile: valore, totale };
}
function conTotaleAggiornato(prev, valore, applicaIva) {
  const num = parseNum(valore);
  const imponibile = valore === "" ? "" : String(applicaIva ? round2(num / 1.22) : num);
  return { ...prev, totale: valore, imponibile };
}
// cambio del metodo di pagamento di una quota (o di una sua riga extra):
// stessa logica già usata per "Quota acconto" (gestisce anche "Cash no
// iva", che azzera l'imponibile mostrato/bloccato), estratta qui perché
// serve identica anche per ogni riga aggiunta con "+"
function conMetodoAggiornato(prev, v) {
  if (v === "Cash no iva") {
    return { ...prev, metodo: v, interessi: v === "Rate" ? prev.interessi : "", imponibile: "" };
  }
  if (prev.metodo === "Cash no iva" && prev.totale !== "") {
    return { ...prev, metodo: v, interessi: v === "Rate" ? prev.interessi : "", imponibile: String(round2(parseNum(prev.totale) / 1.22)) };
  }
  return { ...prev, metodo: v, interessi: v === "Rate" ? prev.interessi : "" };
}
// come conMetodoAggiornato, ma per le quote dove "Cash no iva" non blocca
// la casella imponibile (Quota pre corso, Da avere al corso): resta
// modificabile e viene tenuta uguale al totale, così l'IVA (totale meno
// imponibile) risulta zero invece di apparire vuota
function conMetodoAggiornatoSenzaBlocco(prev, v) {
  if (v === "Cash no iva") {
    if (prev.totale !== "") return { ...prev, metodo: v, interessi: v === "Rate" ? prev.interessi : "", imponibile: prev.totale };
    if (prev.imponibile !== "") return { ...prev, metodo: v, interessi: v === "Rate" ? prev.interessi : "", totale: prev.imponibile };
    return { ...prev, metodo: v, interessi: v === "Rate" ? prev.interessi : "" };
  }
  if (prev.metodo === "Cash no iva" && prev.totale !== "") {
    return { ...prev, metodo: v, interessi: v === "Rate" ? prev.interessi : "", imponibile: String(round2(parseNum(prev.totale) / 1.22)) };
  }
  return { ...prev, metodo: v, interessi: v === "Rate" ? prev.interessi : "" };
}
function ivaDiQuota(q) {
  // imponibile vuoto (es. "Cash no iva": la casella resta bloccata
  // e non si riempie mai da sola) significa "nessuna IVA da mostrare",
  // anche se il totale è già stato inserito
  if (q.imponibile === "") return "";
  return round2(parseNum(q.totale) - parseNum(q.imponibile)).toFixed(2);
}
// quota venditore: 7% del totale pattuito, min 50€, altrimenti arrotondata ai 5€ superiori
function quotaVenditoreDi(totalePattuito) {
  const base = parseNum(totalePattuito) * 0.07;
  if (base <= 50) return 50;
  return Math.ceil(base / 5) * 5;
}

// etichette del modulo di iscrizione PDF (pagina 6, layout fisso a due colonne:
// etichetta a sinistra, valore a destra sulla stessa riga) mappate ai campi del form
const ETICHETTE_MODULO_PDF = {
  tutor: "tutor con cui hai parlato",
  nome: "nome",
  cognome: "cognome",
  telefono: "telefono",
  indirizzoResidenza: "indirizzo di residenza",
  capResidenza: "cap",
  cittaResidenza: "città di residenza",
  email: "email",
  accontoMetodo: "acconto pagato a mezzo",
  accontoImporto: "di euro",
  tagliaDivisa: "taglia divisa",
  scelteModelle: "scelta delle modelle",
  tipoCorso: "tipo di corso scelto",
  tipoPagamentoSaldo: "tipo di pagamento del saldo",
};

// legge il testo di un file PDF (senza OCR: il modulo ha testo selezionabile)
// e ne estrae i campi noti confrontando etichetta/valore riga per riga.
// Restituisce null se non trova nessuna etichetta attesa in nessuna pagina provata.
async function estraiDatiModuloPdf(file) {
  const pdfjsLib = await getPdfjsLib();
  const buffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
  try {
  const paginePossibili = [6, 5, 7].filter((n) => n <= pdf.numPages);

  for (const numPagina of paginePossibili) {
    const page = await pdf.getPage(numPagina);
    const content = await page.getTextContent();

    const items = content.items
      .map((it) => ({ testo: it.str.trim(), x: it.transform[4], y: it.transform[5] }))
      .filter((it) => it.testo);
    if (items.length === 0) continue;

    // le etichette sono ancorate alla colonna più a sinistra; i valori (anche
    // su più righe, es. un testo lungo che va a capo) stanno più a destra,
    // in una fascia verticale delimitata dal punto medio con l'etichetta
    // precedente/successiva — non necessariamente dalla riga esatta
    // dell'etichetta, perché un valore su più righe può iniziare più in alto.
    const xMin = Math.min(...items.map((it) => it.x));
    const etichetteItems = items.filter((it) => Math.abs(it.x - xMin) < 5).sort((a, b) => b.y - a.y);

    const scarti = [];
    for (let i = 1; i < etichetteItems.length; i++) scarti.push(etichetteItems[i - 1].y - etichetteItems[i].y);
    scarti.sort((a, b) => a - b);
    const scartoMediano = scarti.length ? scarti[Math.floor(scarti.length / 2)] : 20;

    const risultato = {};
    for (let i = 0; i < etichetteItems.length; i++) {
      const corrente = etichetteItems[i];
      const precedente = etichetteItems[i - 1];
      const successiva = etichetteItems[i + 1];
      const yMax = precedente ? (precedente.y + corrente.y) / 2 : corrente.y + scartoMediano / 2;
      const yMin = successiva ? (corrente.y + successiva.y) / 2 : -Infinity;

      const valore = items
        .filter((it) => it !== corrente && it.x > xMin + 5 && it.y <= yMax && it.y > yMin)
        .sort((a, b) => b.y - a.y)
        .map((it) => it.testo)
        .join(" ")
        .trim();

      const etichetta = corrente.testo.replace(/:\s*$/, "").trim().toLowerCase();
      if (!etichetta || !valore) continue;
      for (const [chiave, etichettaAttesa] of Object.entries(ETICHETTE_MODULO_PDF)) {
        if (etichetta === etichettaAttesa) risultato[chiave] = valore;
      }
    }
    if (Object.keys(risultato).length > 0) return risultato;
  }
  return null;
  } finally {
    // libera la memoria del documento PDF: senza questo, rileggere molti
    // moduli in sequenza (es. "Recupera residenze dai moduli") satura la RAM
    // e la scheda del browser va in crash a metà
    try { await pdf.destroy(); } catch (e) { /* ignora */ }
  }
}
// data odierna in formato "YYYY-MM-DD", per confrontare con data_inizio/data_fine
// trasforma un testo in una forma leggibile per l'URL: "Microblading Base" → "microblading-base"
function slugify(testo) {
  return (testo || "")
    .toString()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

// "MARIA ROSSI" o "maria rossi" → "Maria Rossi": solo iniziali maiuscole,
// usato in stampa (mai per come il dato resta salvato nel database)
// nei filtri si sceglie una CITTÀ, non una sede: Roma ha due sedi e
// comparirebbe due volte, e sceglierne una nasconderebbe metà dei corsi
// dell'altra. Qui le sedi si riducono a città distinte, e il valore del
// filtro diventa il nome della città invece dell'id della sede
function cittaDistinte(location) {
  const perNome = new Map();
  (location || []).forEach((l) => {
    const nome = (l.nome || "").trim();
    if (nome && !perNome.has(nome.toUpperCase())) perNome.set(nome.toUpperCase(), { id: nome, nome });
  });
  return [...perNome.values()].sort((a, b) => a.nome.localeCompare(b.nome, "it"));
}
function cittaDiSede(location, locationId) {
  return ((location || []).find((l) => l.id === locationId)?.nome || "").trim();
}
function toTitleCase(testo) {
  return (testo || "")
    .toLowerCase()
    .split(/(\s+)/)
    .map((parola) => (parola ? parola.charAt(0).toUpperCase() + parola.slice(1) : parola))
    .join("");
}
// testo da stampare sul segnaposto di ciascun iscritto della classe:
// solo il nome (già maiuscolo, così com'è salvato). Se nella stessa
// classe più iscritti condividono lo stesso nome, si aggiunge
// l'iniziale del cognome per distinguerli (es. "GIULIA G.")
function testiSegnaposto(listaIscritti) {
  const conteggio = new Map();
  listaIscritti.forEach((i) => conteggio.set(i.nome, (conteggio.get(i.nome) || 0) + 1));
  const mappa = new Map();
  listaIscritti.forEach((i) => {
    const testo = conteggio.get(i.nome) > 1 ? `${i.nome} ${i.cognome.charAt(0)}.` : i.nome;
    mappa.set(i.id, testo);
  });
  return mappa;
}
// quando si apre uno dei filtri "Filtra per..." si vuole vedere subito
// l'elenco delle opzioni, non solo il <select> chiuso con la voce
// generica selezionata: appena il select compare nel DOM, gli si dà il
// focus e (dove supportato) si apre subito il suo menu nativo
function useApriSelectAlMontaggio(aperto, ref) {
  useEffect(() => {
    if (!aperto) return;
    const el = ref.current;
    if (!el) return;
    el.focus();
    try { el.showPicker?.(); } catch { /* fuori da un gesto utente diretto in alcuni browser: resta comunque il focus */ }
  }, [aperto]);
}
// "#RRGGBB" → {r,g,b} 0-1, il formato richiesto dalla funzione rgb() di pdf-lib
function hexInRgb01(hex) {
  const cifre = (hex || "#000000").replace("#", "").match(/.{1,2}/g);
  if (!cifre || cifre.length < 3) return { r: 0, g: 0, b: 0 };
  const [r, g, b] = cifre.map((h) => parseInt(h, 16) / 255);
  return { r, g, b };
}
// scarica un file dallo storage Supabase come bytes grezzi, usato sia per
// "Stampa diplomi" che per "Stampa Segnaposto" (template, font)
async function scaricaBytesStorage(bucket, percorso) {
  const { data } = supabase.storage.from(bucket).getPublicUrl(percorso);
  const risposta = await fetch(data.publicUrl);
  if (!risposta.ok) throw new Error(`impossibile scaricare ${percorso}`);
  return new Uint8Array(await risposta.arrayBuffer());
}

// Un file di logo porta quasi sempre un bordo vuoto suo — bianco o
// trasparente — che nell'immagine non si vede ma occupa spazio. Stampato
// com'e', il disegno non parte mai davvero dal margine e resta rientrato
// rispetto al testo che gli sta sotto. Qui il bordo si misura pixel per
// pixel e si taglia via, cosi' "allineato a sinistra" allinea il disegno
// e non la sua cornice invisibile.
async function bytesLogoSenzaBordi(bucket, percorso) {
  const bytes = await scaricaBytesStorage(bucket, percorso);
  const formatoOriginale = /\.jpe?g$/i.test(percorso) ? "jpg" : "png";
  const url = URL.createObjectURL(new Blob([bytes]));
  try {
    const img = new Image();
    await new Promise((risolvi, rifiuta) => {
      img.onload = risolvi;
      img.onerror = () => rifiuta(new Error("immagine logo non valida"));
      img.src = url;
    });
    const tela = document.createElement("canvas");
    tela.width = img.naturalWidth;
    tela.height = img.naturalHeight;
    const ctx = tela.getContext("2d");
    ctx.drawImage(img, 0, 0);
    const dati = ctx.getImageData(0, 0, tela.width, tela.height).data;
    let sx = tela.width, sy = tela.height, dx = -1, dy = -1;
    for (let y = 0; y < tela.height; y++) {
      for (let x = 0; x < tela.width; x++) {
        const i = (y * tela.width + x) * 4;
        // quasi bianco e quasi trasparente contano come vuoto: un JPG non
        // ha trasparenza e il suo sfondo arriva come bianco sporco
        if (dati[i + 3] < 12 || (dati[i] > 244 && dati[i + 1] > 244 && dati[i + 2] > 244)) continue;
        if (x < sx) sx = x;
        if (x > dx) dx = x;
        if (y < sy) sy = y;
        if (y > dy) dy = y;
      }
    }
    const larghezza = dx - sx + 1;
    const altezza = dy - sy + 1;
    // niente da togliere (o immagine tutta vuota): meglio l'originale
    if (dx < 0 || (larghezza === tela.width && altezza === tela.height)) return { bytes, formato: formatoOriginale };
    const ritagliata = document.createElement("canvas");
    ritagliata.width = larghezza;
    ritagliata.height = altezza;
    ritagliata.getContext("2d").drawImage(tela, sx, sy, larghezza, altezza, 0, 0, larghezza, altezza);
    const blob = await new Promise((risolvi) => ritagliata.toBlob(risolvi, "image/png"));
    return { bytes: new Uint8Array(await blob.arrayBuffer()), formato: "png" };
  } catch {
    // se il ritaglio non riesce il logo si stampa com'e': meglio con il
    // bordo che senza logo
    return { bytes, formato: formatoOriginale };
  } finally {
    URL.revokeObjectURL(url);
  }
}

function dataOggiStr() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
// corsi in cima a tutte le liste, in quest'ordine (riconosciuti dalle parole chiave, non dall'ordine esatto delle parole nel nome); gli altri seguono in ordine alfabetico
function prioritaCorso(nome) {
  const n = (nome || "").trim().toUpperCase();
  if (n.includes("PMU") && n.includes("BASE")) return 0;
  if (n.includes("MICRO") && n.includes("BASE")) return 1;
  return -1;
}
function ordinaCorsi(lista) {
  return [...(lista || [])].sort((a, b) => {
    const ia = prioritaCorso(a.nome);
    const ib = prioritaCorso(b.nome);
    if (ia !== -1 || ib !== -1) return (ia === -1 ? 999 : ia) - (ib === -1 ? 999 : ib);
    return (a.nome || "").localeCompare(b.nome || "");
  });
}
// totale effettivo di una quota (acconto/precorso) salvata su un iscritto, interessi compresi
function totQuota(i, prefisso) {
  const interessi = i[`${prefisso}_metodo`] === "Rate" ? (i[`${prefisso}_interessi`] || 0) : 0;
  return round2((i[`${prefisso}_totale`] || 0) + interessi);
}
// totale da pagare per le modelle: usa il prezzo speciale se impostato, altrimenti n. modelle × 60€
function modelleTotaleDi(i) {
  if (i.prezzo_speciale_modelle != null) return i.prezzo_speciale_modelle;
  return round2((i.numero_modelle || 0) * 60);
}
// posti massimi effettivi di un'edizione: il numero scelto per la data (o, in mancanza,
// quello di default del corso) non può mai superare il tetto massimo della sede
function postiMaxEffettivi(cd, corso, loc) {
  const base = cd?.posti_max ?? corso?.posti_max ?? 0;
  if (loc?.posti_max != null) return Math.min(base, loc.posti_max);
  return base;
}

// blocco Imponibile/IVA/Totale + metodo di pagamento per una singola quota
// pillola rosso/verde "Da pagare"/"Pagato": stesso linguaggio visivo del
// semaforo() già in uso altrove nell'app (Sì/NO verde/rosso), qui applicato
// a una singola riga di pagamento (acconto/pre corso, comprese le righe
// aggiunte con "+")
function SemaforoPagamento({ pagato, onClick }) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        ...fontBody, fontSize: 11, fontWeight: 700, whiteSpace: "nowrap", cursor: "pointer",
        border: "none", borderRadius: 8, padding: "6px 14px", flexShrink: 0,
        background: pagato ? "#E8F5E9" : "#FDECEC", color: pagato ? "#2E7D32" : "#C0392B",
      }}
    >
      {pagato ? "Pagato" : "Da pagare"}
    </button>
  );
}
function BloccoQuota({ titolo, Icona, valori, onImponibile, onTotale, onMetodo, onInteressi, onTotaleConInteressi, soloLettura, imponibileBloccato, totaleBloccato, opzioniMetodo, pagato, onPagato, onRimuovi, onBonificoFile, mostraSaltaFile, onBonificoSkip }) {
  const totaleConInteressi = round2(parseNum(valori.totale) + parseNum(valori.interessi || 0));
  return (
    <div style={{ ...areaSchedaIscritto, marginBottom: 10, ...(soloLettura ? { background: BG } : {}) }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, marginBottom: 10 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 9, color: GOLD }}>
          {Icona && <Icona size={18} color={GOLD} />}
          <span style={titoloAreaScheda}>{titolo}</span>
        </div>
        {onRimuovi && (
          <button onClick={onRimuovi} title="Rimuovi questo pagamento" style={{ border: "none", background: "none", cursor: "pointer", color: "#C0392B", padding: 2, display: "flex" }}>
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6" /><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" /></svg>
          </button>
        )}
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <div style={{ flex: "1 1 90px" }}>
          <Field label="Imponibile">
            <input
              style={{ ...campoAreaScheda, background: soloLettura || imponibileBloccato ? "#EDF1F4" : "#fff", color: soloLettura || imponibileBloccato ? MUTED : NAVY }}
              inputMode="decimal"
              value={valori.imponibile}
              disabled={soloLettura || imponibileBloccato}
              onChange={(e) => onImponibile && onImponibile(e.target.value)}
            />
          </Field>
        </div>
        <div style={{ flex: "1 1 90px" }}>
          <Field label="IVA 22%">
            <input style={{ ...campoAreaScheda, background: "#EDF1F4", color: MUTED }} value={ivaDiQuota(valori)} disabled />
          </Field>
        </div>
        <div style={{ flex: "1 1 90px" }}>
          <Field label={titolo === "Quota acconto" && valori.metodo === "Rate" ? "Totale (senza interessi)" : "Totale"}>
            <input
              style={{ ...campoAreaScheda, background: soloLettura || totaleBloccato ? "#EDF1F4" : "#fff", color: soloLettura || totaleBloccato ? MUTED : NAVY }}
              inputMode="decimal"
              value={valori.totale}
              disabled={soloLettura || totaleBloccato}
              onChange={(e) => onTotale && onTotale(e.target.value)}
            />
          </Field>
        </div>
      </div>
      {onMetodo && (
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 14, flexWrap: "wrap" }}>
          <div style={{ display: "flex", gap: 14, flexWrap: "wrap", ...fontBody, fontSize: 13, color: NAVY }}>
            {(opzioniMetodo || ["Sito", "Bonifico", "Pos", "Contanti"]).map((opz) => (
              <label key={opz} style={{ display: "flex", alignItems: "center", gap: 5, cursor: "pointer" }}>
                <input type="radio" name={titolo + "-metodo"} checked={valori.metodo === opz} onChange={() => onMetodo(opz)} />
                {opz}
              </label>
            ))}
          </div>
          {onPagato && <SemaforoPagamento pagato={pagato} onClick={() => onPagato(!pagato)} />}
        </div>
      )}
      {onMetodo && valori.metodo === "Rate" && (
        <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
          <div style={{ flex: 1 }}>
            <Field label="Interessi">
              <input
                style={campoAreaScheda}
                inputMode="decimal"
                value={valori.interessi || ""}
                onChange={(e) => onInteressi && onInteressi(e.target.value)}
              />
            </Field>
          </div>
          <div style={{ flex: 1 }}>
            <Field label="Totale incluso interessi">
              {onTotaleConInteressi ? (
                <input
                  style={campoAreaScheda}
                  inputMode="decimal"
                  value={valori.totale === "" && (valori.interessi || "") === "" ? "" : totaleConInteressi.toFixed(2)}
                  onChange={(e) => onTotaleConInteressi(e.target.value)}
                />
              ) : (
                <input
                  style={{ ...campoAreaScheda, background: "#EDF1F4", color: MUTED }}
                  value={valori.totale === "" && (valori.interessi || "") === "" ? "" : totaleConInteressi.toFixed(2)}
                  disabled
                />
              )}
            </Field>
          </div>
        </div>
      )}
      {onMetodo && valori.metodo === "Bonifico" && onPagato && (
        <div style={{ marginTop: 10 }}>
          <Field label={valori.bonificoSkip ? "File del bonifico (da caricare più tardi)" : pagato ? "File del bonifico (obbligatorio)" : "File del bonifico (facoltativo finché non segni \"Pagato\")"}>
            {valori.bonificoFilePath && !valori.bonificoFileNuovo ? (
              <div style={{ ...fontBody, fontSize: 12.5, color: MUTED }}>
                Caricato: <AllegatoLink percorso={valori.bonificoFilePath} etichetta="apri il file" />
              </div>
            ) : !soloLettura ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                  <CampoFileTrascinabile accept="image/*,application/pdf" style={{ ...inputStyle, flex: 1, minWidth: 200 }} onChange={(e) => onBonificoFile && onBonificoFile(e.target.files?.[0] || null)} />
                  {valori.bonificoFileNuovo && <BadgeFileCaricato />}
                </div>
                {mostraSaltaFile && onBonificoSkip && (
                  <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", ...fontBody, fontSize: 12.5, color: NAVY }}>
                    <input type="checkbox" checked={!!valori.bonificoSkip} onChange={(e) => onBonificoSkip(e.target.checked)} style={{ width: 14, height: 14 }} />
                    Ora non ho il file
                  </label>
                )}
              </div>
            ) : (
              <div style={{ ...fontBody, fontSize: 12.5, color: "#C0392B" }}>Nessun file caricato.</div>
            )}
          </Field>
        </div>
      )}
    </div>
  );
}

function TopBar({ title }) {
  return (
    <div style={{ marginBottom: 22 }}>
      <div style={{ ...fontDisplay, fontSize: 26, color: NAVY }}>{title}</div>
    </div>
  );
}

// ---------- Gate di accesso ----------
function Gate({ onOk }) {
  const [code, setCode] = useState("");
  const [err, setErr] = useState(false);
  const [verificando, setVerificando] = useState(false);
  return (
    <div style={{ ...fontBody, boxSizing: "border-box", maxWidth: 340, margin: "0 auto", minHeight: "100vh", padding: "60px 20px", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center" }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginTop: -60 }}>
        <img src="/logo-elitederma.png" alt="Elitederma" style={{ height: 64, width: "auto", marginBottom: 44 }} />
        <div style={{ ...fontDisplay, fontFamily: '"Zen Dots", cursive', fontSize: 26, fontWeight: 400, color: NAVY, letterSpacing: 0.5, marginBottom: 3 }}>GENYON</div>
        <div style={{ ...fontBody, fontSize: 11, color: MUTED, letterSpacing: 0.4, marginBottom: 24 }}>General Yield Organization Network</div>
        <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginBottom: 60 }}>developed by GianLuca Rocca</div>
        <input
          type="password"
          placeholder="Codice d'accesso"
          value={code}
          onChange={(e) => { setCode(e.target.value); setErr(false); }}
          style={{ ...inputStyle, width: "100%", textAlign: "center", marginBottom: 12 }}
          onKeyDown={(e) => e.key === "Enter" && check()}
        />
        <Button onClick={check} disabled={verificando} style={{ width: "100%" }}>{verificando ? "Verifico…" : "Entra"}</Button>
        {err && <div style={{ color: "#C0392B", fontSize: 13, marginTop: 10 }}>Codice non corretto</div>}
      </div>
    </div>
  );
  // Tutte le identità (Utente generico, Amministratore, Programmatore,
  // più qualunque utente nominale) vivono ora nella stessa tabella
  // utenti_app, gestita dalla rotellina > Gestione utenti — ognuna con la
  // propria password e i propri "permessi" (i tasti della home
  // cliccabili). Le 3 righe di sistema (chiave_sistema valorizzata)
  // esistono sempre anche se non ancora salvate: finché non vengono
  // personalizzate si ricade sui valori di sempre (RIGHE_SISTEMA_DEFAULT)
  async function check() {
    setVerificando(true);
    const [{ data: utenti }, { data: masterRighe }, { data: venditoriRighe }] = await Promise.all([
      supabase.from("utenti_app").select("id, nome, password, permessi, chiave_sistema, venditore_id, solo_calendario, amministratore"),
      supabase.from("master").select("id, nome, password, permessi, venditore_id"),
      supabase.from("venditori").select("id, nome, password, permessi"),
    ]);
    setVerificando(false);
    const righe = utenti || [];
    function rigaSistema(chiave) {
      const trovata = righe.find((u) => u.chiave_sistema === chiave);
      const def = RIGHE_SISTEMA_DEFAULT.find((d) => d.chiave === chiave);
      return {
        id: trovata?.id || null,
        nome: trovata?.nome || def.nome,
        password: trovata?.password || def.passwordDefault,
        permessi: trovata?.permessi || def.permessiDefault,
        chiave_sistema: chiave,
      };
    }
    const sUser = rigaSistema("__user");
    const sAdmin = rigaSistema("__admin");
    const sProgrammatore = rigaSistema("__programmatore");
    const nominale = righe.find((u) => !u.chiave_sistema && code && u.password === code);
    // le master entrano con la propria password (Password menù > Password
    // Master), impostata voce per voce sulla riga "master" già esistente
    // in Setting — a differenza dei venditori, non scelgono il proprio
    // nome da una tendina: la password stessa identifica la master, e
    // l'unico tasto che vedono è "Dashboard master", già sulla propria scheda
    const masterTrovata = (masterRighe || []).find((m) => !!m.password && code && m.password === code);
    // stesso meccanismo delle master: il venditore entra qui direttamente
    // con la propria password (Password menù > Password venditori), senza
    // passare dalla tendina "Utente generico" + selezione nome — atterra
    // subito sulla Dashboard venditori (gestito nel chiamante tramite
    // venditoreId)
    const venditoreTrovato = (venditoriRighe || []).find((v) => !!v.password && code && v.password === code);
    // collegamento esplicito (Password menù > Password Master > "Venditore
    // collegato"), non più affidato alla coincidenza delle due password:
    // funziona in entrambe le direzioni, qualunque delle due password usi
    const venditoreDellaMaster = masterTrovata?.venditore_id ? (venditoriRighe || []).find((v) => v.id === masterTrovata.venditore_id) : null;
    const masterDelVenditore = venditoreTrovato ? (masterRighe || []).find((m) => m.venditore_id === venditoreTrovato.id) : null;
    // stesso collegamento esplicito di master.venditore_id, ma su un
    // account nominale (Gestione utenti > Venditore collegato): per chi fa
    // sia lavoro d'ufficio sia vendita con la stessa identità (es. Raffaele)
    const venditoreDelNominale = nominale?.venditore_id ? (venditoriRighe || []).find((v) => v.id === nominale.venditore_id) : null;

    let ruolo = null, utente = null;
    if (sProgrammatore.password && code === sProgrammatore.password) { ruolo = "programmatore"; utente = sProgrammatore; }
    else if (sAdmin.password && code === sAdmin.password) { ruolo = "amministratore"; utente = sAdmin; }
    else if (masterTrovata) {
      // se questa master ha un venditore collegato, porta con sé pure
      // venditoreId e i suoi permessi: da qui in poi "Dashboard venditori"
      // la riconosce e la blocca sui propri dati invece di aprire il picker
      ruolo = "user";
      utente = {
        id: masterTrovata.id, nome: masterTrovata.nome,
        permessi: [...new Set(["dashboardmaster", ...(masterTrovata.permessi || []), ...(venditoreDellaMaster ? [...(venditoreDellaMaster.permessi || []), "dashboardvenditori"] : [])])],
        chiave_sistema: null, masterId: masterTrovata.id,
        // il nome del venditore va tenuto distinto da quello della master:
        // le vendite/iscritti hanno "tutor" valorizzato col nome venditore
        // (es. "ANDREA"), non con quello anagrafico master ("ANDREA PAURA")
        ...(venditoreDellaMaster ? { venditoreId: venditoreDellaMaster.id, venditoreNome: venditoreDellaMaster.nome } : {}),
      };
    }
    else if (venditoreTrovato) {
      // simmetrico: se questo venditore è collegato a una master, entrando
      // con la propria password ottiene anche "Dashboard master"
      ruolo = "user";
      utente = {
        id: venditoreTrovato.id, nome: venditoreTrovato.nome,
        permessi: [...new Set([...(venditoreTrovato.permessi || []), "dashboardvenditori", ...(masterDelVenditore ? ["dashboardmaster", ...(masterDelVenditore.permessi || [])] : [])])],
        chiave_sistema: null, venditoreId: venditoreTrovato.id, venditoreNome: venditoreTrovato.nome,
        ...(masterDelVenditore ? { masterId: masterDelVenditore.id } : {}),
      };
    }
    else if (nominale) {
      // simmetrico a masterTrovata/venditoreTrovato: se questo account
      // nominale ha un venditore collegato, porta con sé i suoi permessi e
      // "dashboardvenditori" — da qui in poi apriLoginVenditore lo riconosce
      // (utenteLoggato.venditoreId) e va dritto alla sua scheda, mai al
      // selettore con tutti i venditori. A differenza di chi entra con la
      // propria password venditore, però, questo account fa anche altro
      // (es. ufficio/magazzino): al login atterra sempre in Home come
      // qualunque altro utente nominale, mai dritto sulla dashboard
      // venditori (restaSuHomeAlLogin, letto più sotto in onOk del Gate)
      // il grado batte tutto il resto: un account nominale marcato
      // amministratore entra come tale anche se è collegato a un venditore
      // — altrimenti trovava le schede iscritto in sola lettura, come un
      // venditore qualsiasi, pur avendo tutti i permessi
      ruolo = nominale.amministratore ? "amministratore" : "user";
      utente = {
        id: nominale.id, nome: nominale.nome,
        permessi: [...new Set([...(nominale.permessi || []), ...(venditoreDelNominale ? [...(venditoreDelNominale.permessi || []), "dashboardvenditori"] : [])])],
        chiave_sistema: null,
        ...(venditoreDelNominale ? { venditoreId: venditoreDelNominale.id, venditoreNome: venditoreDelNominale.nome, restaSuHomeAlLogin: true } : {}),
        // profilo "kiosk": entra dritto su Gestione corsi (mai Home), sola
        // lettura del calendario, niente Home/Indietro/Avanti nella
        // barra di navigazione (vedi onOk del Gate e l'header/pasticca)
        ...(nominale.solo_calendario ? { soloCalendarioLettura: true } : {}),
      };
    }
    else if (!sUser.password || code === sUser.password) { ruolo = "user"; utente = sUser; }

    if (ruolo) {
      sessionStorage.setItem("edc_ok", "1");
      sessionStorage.setItem("edc_ruolo", ruolo);
      sessionStorage.setItem("edc_utente", JSON.stringify(utente));
      onOk(ruolo, utente);
    } else {
      setErr(true);
    }
  }
}

// scheda "Gestisci" dell'alloggio di una riga (master principale o
// docente extra): hotel, notti prenotate, pattuito a notte (precompilato
// dalla tariffa dell'hotel corrispondente al Tipo di pagamento scelto,
// modificabile), Tipo di pagamento e Scadenza pagamento — quest'ultima
// è il cuore della differenza tra "Quadro impegni" (bonifico prenotato
// ma senza ancora una fattura/scadenza) e "Scadenziario Passivo" (la
// scadenza è nota, il pagamento è schedulabile): se il tipo è Cash resta
// sempre sola lettura = fine corso, perché il cash si chiude comunque in
// "Cash pulito in busta" a fine corso, non passa da qui.
function ModaleGestisciAlloggio({ cd, riga, tabella, hotel, onClose, onSalvato }) {
  const [hotelId, setHotelId] = useState(riga.alloggio_id || "");
  const [notti, setNotti] = useState(riga.notti_prenotate != null ? String(riga.notti_prenotate) : "");
  const [costoNotteCash, setCostoNotteCash] = useState(riga.pattuito_a_notte_cash != null ? String(riga.pattuito_a_notte_cash) : "");
  const [costoNotteBonifico, setCostoNotteBonifico] = useState(riga.pattuito_a_notte_bonifico != null ? String(riga.pattuito_a_notte_bonifico) : "");
  const [tipoPagamento, setTipoPagamento] = useState(riga.tipo_pagamento_alloggio || "bonifico");
  const [scadenza, setScadenza] = useState(riga.scadenza_pagamento_alloggio || "");
  const [salvando, setSalvando] = useState(false);
  const [msg, setMsg] = useState("");

  // precompila i due costi a notte dalla tariffa dell'hotel scelto (cash e
  // fattura), solo se il campo è ancora vuoto — non sovrascrive un valore
  // già inserito a mano
  useEffect(() => {
    const h = (hotel || []).find((x) => x.id === hotelId);
    if (!h) return;
    if (costoNotteCash === "" && h.costo_notte_cash != null) setCostoNotteCash(String(h.costo_notte_cash));
    if (costoNotteBonifico === "" && h.costo_notte_fattura != null) setCostoNotteBonifico(String(h.costo_notte_fattura));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hotelId]);

  async function salva() {
    setSalvando(true);
    const nottiNum = notti === "" ? null : Number(notti);
    const cashNum = costoNotteCash === "" ? null : parseNum(costoNotteCash);
    const bonificoNum = costoNotteBonifico === "" ? null : parseNum(costoNotteBonifico);
    const aNotteNum = tipoPagamento === "cash" ? cashNum : bonificoNum;
    const periodo = nottiNum != null && aNotteNum != null ? round2(nottiNum * aNotteNum) : null;
    const campi = {
      alloggio_id: hotelId || null,
      notti_prenotate: nottiNum,
      pattuito_a_notte_cash: cashNum,
      pattuito_a_notte_bonifico: bonificoNum,
      pattuito_periodo: periodo,
      tipo_pagamento_alloggio: tipoPagamento || null,
      scadenza_pagamento_alloggio: tipoPagamento === "cash" ? null : (scadenza || null),
    };
    const { error } = await supabase.from(tabella).update(campi).eq("id", riga.id);
    setSalvando(false);
    if (error) { setMsg("Errore: " + error.message); return; }
    onSalvato();
  }

  return (
    <Modal title="Gestisci alloggio" onClose={onClose} maxWidth={480}>
      <Field label="Hotel">
        <select style={inputStyle} value={hotelId} onChange={(e) => setHotelId(e.target.value)}>
          <option value="">— nessuno —</option>
          {(hotel || []).map((h) => <option key={h.id} value={h.id}>{h.nome.toUpperCase()}</option>)}
        </select>
      </Field>
      <Field label="Notti prenotate">
        <input type="text" inputMode="numeric" style={inputStyle} value={notti} onChange={(e) => setNotti(e.target.value)} />
      </Field>
      <div style={{ display: "flex", gap: 10 }}>
        <div style={{ flex: 1 }}>
          <Field label="Costo a notte Cash">
            <input type="text" inputMode="decimal" style={inputStyle} value={costoNotteCash} onChange={(e) => setCostoNotteCash(e.target.value)} />
          </Field>
        </div>
        <div style={{ flex: 1 }}>
          <Field label="Costo a notte Bonifico">
            <input type="text" inputMode="decimal" style={inputStyle} value={costoNotteBonifico} onChange={(e) => setCostoNotteBonifico(e.target.value)} />
          </Field>
        </div>
      </div>
      <Field label="Tipo di pagamento">
        <select style={inputStyle} value={tipoPagamento} onChange={(e) => { setTipoPagamento(e.target.value); if (e.target.value === "cash") setScadenza(""); }}>
          <option value="cash">Cash</option>
          <option value="bonifico">Bonifico con fattura</option>
        </select>
      </Field>
      <Field label={tipoPagamento === "cash" ? "Scadenza pagamento (Cash — pagato a fine corso)" : "Scadenza pagamento (vuota finché non arriva la fattura)"}>
        {tipoPagamento === "cash" ? (
          <input type="date" style={{ ...inputStyle, background: "#EFEFEF", color: MUTED }} value={cd.data_fine || ""} disabled />
        ) : (
          <input type="date" style={inputStyle} value={scadenza} onChange={(e) => setScadenza(e.target.value)} />
        )}
      </Field>
      {msg && <div style={{ ...fontBody, fontSize: 12, color: "#C0392B", marginBottom: 10 }}>{msg}</div>}
      <Button onClick={salva} disabled={salvando} style={{ width: "100%" }}>{salvando ? "Salvo…" : "Salva"}</Button>
    </Modal>
  );
}

// scheda "Gestisci sede": stesso meccanismo di "Gestisci alloggio" ma per
// la location dell'edizione. La Città resta quella del calendario (fissa,
// non si cambia qui), ma se in quella città ci sono più sedi (es. Roma)
// si può scegliere quale delle due tra loro — cambia solo il location_id
// e quindi il nome sede, mai la città del corso. Il costo a giorno
// Cash/Bonifico precompila dalle condizioni generali della sede scelta
// (Impostazioni → Location) solo se il campo è ancora vuoto; "Sede
// avvisata" è lo stesso sede_confermata di sempre, ora dentro la scheda
// invece di un semaforo in tabella — il pallino fuori diventa verde/rosso
// di conseguenza
function ModaleGestisciSede({ cd, location, onClose, onSalvato }) {
  const locOriginale = (location || []).find((l) => l.id === cd.location_id);
  const cittaCorrente = locOriginale?.nome || null;
  const sediStessaCitta = (location || []).filter((l) => l.nome === cittaCorrente);
  const [locationIdScelta, setLocationIdScelta] = useState(cd.location_id || "");
  const loc = (location || []).find((l) => l.id === locationIdScelta) || locOriginale;
  const [costoGiornoCash, setCostoGiornoCash] = useState(cd.costo_giorno_sede_cash != null ? String(cd.costo_giorno_sede_cash) : "");
  const [costoGiornoBonifico, setCostoGiornoBonifico] = useState(cd.costo_giorno_sede_bonifico != null ? String(cd.costo_giorno_sede_bonifico) : "");
  const [tipoPagamento, setTipoPagamento] = useState(cd.pagamento_sede === "cash" ? "cash" : "bonifico");
  const [scadenza, setScadenza] = useState(cd.scadenza_pagamento_location || "");
  const [avvisata, setAvvisata] = useState(!!cd.sede_confermata);
  const [salvando, setSalvando] = useState(false);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    if (!loc) return;
    if (costoGiornoCash === "" && loc.costo_giornaliero_cash != null) setCostoGiornoCash(String(loc.costo_giornaliero_cash));
    if (costoGiornoBonifico === "" && loc.costo_giornaliero_bonifico != null) setCostoGiornoBonifico(String(loc.costo_giornaliero_bonifico));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const sedeCentrale = !!loc?.sede_centrale;

  async function salva() {
    setSalvando(true);
    const campi = {
      location_id: locationIdScelta || null,
      costo_giorno_sede_cash: sedeCentrale ? null : (costoGiornoCash === "" ? null : parseNum(costoGiornoCash)),
      costo_giorno_sede_bonifico: sedeCentrale ? null : (costoGiornoBonifico === "" ? null : parseNum(costoGiornoBonifico)),
      // "pagamento_sede" resta valorizzato anche per una sede centrale
      // (ignorato nel calcolo dei costi, vedi calcolaRigheSpeseCorso): è
      // il segnale che la scheda è stata aperta e salvata almeno una
      // volta, usato in Assegnazione Master per decidere se mostrare
      // ancora "Gestisci" o già nome sede + pallino
      pagamento_sede: tipoPagamento || null,
      scadenza_pagamento_location: sedeCentrale ? null : (tipoPagamento === "cash" ? null : (scadenza || null)),
      sede_confermata: avvisata,
    };
    const { error } = await supabase.from("corsi_date").update(campi).eq("id", cd.id);
    setSalvando(false);
    if (error) { setMsg("Errore: " + error.message); return; }
    onSalvato();
  }

  return (
    <Modal title="Gestisci sede" onClose={onClose} maxWidth={480}>
      {sediStessaCitta.length > 1 && (
        <Field label="Sede">
          <select style={inputStyle} value={locationIdScelta} onChange={(e) => setLocationIdScelta(e.target.value)}>
            {sediStessaCitta.map((l) => (
              <option key={l.id} value={l.id}>{l.nome_sede || l.nome.toUpperCase()}</option>
            ))}
          </select>
        </Field>
      )}
      <Field label="Nome sede">
        <div style={{ ...inputStyle, display: "flex", alignItems: "center", background: "#EFEFEF", color: NAVY, fontWeight: 700 }}>
          {loc?.nome_sede ? toTitleCase(loc.nome_sede) : "—"}
        </div>
      </Field>
      <Field label="Città">
        <div style={{ ...inputStyle, display: "flex", alignItems: "center", background: "#EFEFEF", color: NAVY, fontWeight: 700 }}>
          {loc?.nome ? toTitleCase(loc.nome) : "—"}
        </div>
      </Field>
      {sedeCentrale ? (
        <div style={{ display: "inline-flex", alignItems: "center", gap: 8, background: "#E8F5E9", color: "#2E7D32", border: "1px solid #C8E6C9", borderRadius: 20, padding: "8px 16px", marginBottom: 16, ...fontBody, fontSize: 13, fontWeight: 700 }}>
          Sede Centrale
        </div>
      ) : (
        <>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}>
              <Field label="Costo a giorno Cash">
                <input type="text" inputMode="decimal" style={inputStyle} value={costoGiornoCash} onChange={(e) => setCostoGiornoCash(e.target.value)} />
              </Field>
            </div>
            <div style={{ flex: 1 }}>
              <Field label="Costo a giorno Bonifico">
                <input type="text" inputMode="decimal" style={inputStyle} value={costoGiornoBonifico} onChange={(e) => setCostoGiornoBonifico(e.target.value)} />
              </Field>
            </div>
          </div>
          <Field label="Tipo di pagamento">
            <select style={inputStyle} value={tipoPagamento} onChange={(e) => { setTipoPagamento(e.target.value); if (e.target.value === "cash") setScadenza(""); }}>
              <option value="cash">Cash</option>
              <option value="bonifico">Bonifico con fattura</option>
            </select>
          </Field>
          <Field label={tipoPagamento === "cash" ? "Scadenza pagamento (Cash — pagato a fine corso)" : "Scadenza pagamento (vuota finché non arriva la fattura)"}>
            {tipoPagamento === "cash" ? (
              <input type="date" style={{ ...inputStyle, background: "#EFEFEF", color: MUTED }} value={cd.data_fine || ""} disabled />
            ) : (
              <input type="date" style={inputStyle} value={scadenza} onChange={(e) => setScadenza(e.target.value)} />
            )}
          </Field>
        </>
      )}
      <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", marginBottom: 16 }}>
        <input type="checkbox" checked={avvisata} onChange={(e) => setAvvisata(e.target.checked)} style={{ width: 18, height: 18 }} />
        <span style={{ ...fontBody, fontSize: 13, color: NAVY, fontWeight: 600 }}>Sede avvisata</span>
      </label>
      {msg && <div style={{ ...fontBody, fontSize: 12, color: "#C0392B", marginBottom: 10 }}>{msg}</div>}
      <Button onClick={salva} disabled={salvando} style={{ width: "100%" }}>{salvando ? "Salvo…" : "Salva"}</Button>
    </Modal>
  );
}

// ---------- Assegnazione Master ----------
// tabella orizzontale con una riga per ogni data futura: sede confermata,
// note libere, la master principale sui campi diretti di corsi_date
// (master/note/viaggio/alloggio/note viaggio, come sempre), più
// il "+" accanto al nome della master apre la scelta di che tipo di
// docente extra aggiungere (master/assistente/leva): ognuna diventa
// una riga propria in corsi_date_docenti, con i propri biglietti di
// viaggio e il proprio hotel.
function AssegnazioneMaster({ corsi, location, corsiDate, corsiDateDocenti, master, hotel, assistente, leva, spese, ruoloUtente, layoutCondiviso, ricarica, onBack, onApriRegistraSpesaAlloggio, titolo = "Operativo corsi" }) {
  const corsoById = useMemo(() => Object.fromEntries(corsi.map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries(location.map((l) => [l.id, l])), [location]);

  // aggiunta/rimozione ottimistica delle righe "docente extra": "ricarica"
  // rifà l'intero fetchDati, troppo lento per sentirsi immediato — una
  // riga appena inserita (con l'id vero restituito dall'insert, non
  // finto: le interazioni successive su quella riga, es. scegliere la
  // persona, devono poter salvare subito) compare qui finché il
  // refetch completo non la porta in corsiDateDocenti, dopodiché sparisce
  // da sola (dedup per id); una riga appena rimossa si nasconde subito
  const [righeExtraOttimistiche, setRigheExtraOttimistiche] = useState([]);
  const [idsRimosseOttimisticamente, setIdsRimosseOttimisticamente] = useState(() => new Set());

  // "docenti extra" di ciascuna edizione (altre master, assistenti, leve
  // oltre alla master principale sui campi diretti di corsi_date), una
  // riga per persona con i propri biglietti/hotel — vedi il "+" accanto al nome della master
  const docentiPerCorsoData = useMemo(() => {
    const mappa = {};
    const idsReali = new Set((corsiDateDocenti || []).map((d) => d.id));
    const extra = righeExtraOttimistiche.filter((d) => !idsReali.has(d.id));
    const tutte = [...(corsiDateDocenti || []), ...extra].filter((d) => !idsRimosseOttimisticamente.has(d.id));
    tutte.forEach((d) => { (mappa[d.corso_data_id] ||= []).push(d); });
    Object.values(mappa).forEach((lista) => lista.sort((a, b) => (ORDINE_TIPO_DOCENTE[a.tipo] - ORDINE_TIPO_DOCENTE[b.tipo]) || (a.ts || "").localeCompare(b.ts || "")));
    return mappa;
  }, [corsiDateDocenti, righeExtraOttimistiche, idsRimosseOttimisticamente]);
  function nomeDocente(d) {
    const lista = d.tipo === "master" ? master : d.tipo === "assistente" ? assistente : leva;
    return lista.find((p) => p.id === d.persona_id)?.nome || "";
  }

  const [filtroCorso, setFiltroCorso] = useState("");
  const [filtroCitta, setFiltroCitta] = useState("");
  const [filtroMaster, setFiltroMaster] = useState("");
  const [filtroAssistente, setFiltroAssistente] = useState("");
  const [filtroLeva, setFiltroLeva] = useState("");
  const [apriFiltro, setApriFiltro] = useState(""); // quale tendina filtro è aperta, "" = nessuna
  const [ricercaTesto, setRicercaTesto] = useState("");
  // finestra "Aggiungi docente" (sostituisce i tre pulsanti M/A/L): tiene
  // il corso su cui si sta aggiungendo, null quando è chiusa
  const [corsoDataAggiungiDocente, setCorsoDataAggiungiDocente] = useState(null);
  const [tipoDocenteScelto, setTipoDocenteScelto] = useState("master");
  // scheda "Gestisci alloggio": { cd, riga, tabella } della riga aperta,
  // null quando è chiusa — riga === cd per la master principale
  const [gestisciAlloggio, setGestisciAlloggio] = useState(null);
  // scheda "Gestisci sede": { cd } dell'edizione aperta, null quando è
  // chiusa — la location è fissa (quella del corso), non si sceglie qui
  const [gestisciSede, setGestisciSede] = useState(null);
  function hotelNomeDi(id) {
    return (hotel || []).find((h) => h.id === id)?.nome?.toUpperCase() || null;
  }
  // stesso importo suggerito che calcolaRigheSpeseCorso userebbe per
  // questa riga (pattuito per periodo con priorità, altrimenti tariffa a
  // notte della scheda hotel) — solo per precompilare "Registra spesa",
  // il conto amministrativo vero resta quello del Riepilogo
  function totaleAlloggioRiga(r) {
    if (r.pattuito_periodo != null) return r.pattuito_periodo;
    if (r.notti_prenotate == null || !r.alloggio_id) return null;
    const h = (hotel || []).find((x) => x.id === r.alloggio_id);
    const tipoPag = r.tipo_pagamento_alloggio === "cash" ? "cash" : "bonifico";
    const tariffa = tipoPag === "cash" ? (h?.costo_notte_cash ?? h?.costo_notte_fattura) : (h?.costo_notte_fattura ?? h?.costo_notte_cash);
    return tariffa != null ? round2(tariffa * r.notti_prenotate) : null;
  }
  // "Hotel pagato": non è più un semplice flag visivo ma la stessa spesa
  // vera registrata in "Registra spesa", trovata tramite la chiave
  // "alloggio_<rigaId>" (la stessa usata da calcolaVociScadenziario, per
  // restare sempre in sync con Amministrazione) — di default una tendina
  // con solo "Registra", che diventa un tasto colorato con lo stato della
  // spesa una volta registrata
  function cellaHotelPagato(riga, classeId) {
    const chiave = `alloggio_${riga.id}`;
    const spesaReg = (spese || []).find((s) => s.origine_scadenziario_chiave === chiave);
    if (spesaReg) {
      const stile = COLORE_STATO_SPESA[spesaReg.stato] || COLORE_STATO_SPESA.preventivata;
      return (
        <button onClick={() => onApriRegistraSpesaAlloggio?.(chiave, classeId, totaleAlloggioRiga(riga))} style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: stile.colore, background: stile.sfondo, border: "none", borderRadius: 12, padding: "5px 12px", cursor: "pointer", whiteSpace: "nowrap" }}>
          {etichettaOpzione(STATI_SPESA, spesaReg.stato)}
        </button>
      );
    }
    return (
      <select style={campoStyle} value="" onChange={(e) => { if (e.target.value === "registra") onApriRegistraSpesaAlloggio?.(chiave, classeId, totaleAlloggioRiga(riga)); }}>
        <option value="">—</option>
        <option value="registra">Registra</option>
      </select>
    );
  }
  // agosto è tecnicamente l'ultimo mese della stagione PRECEDENTE (la
  // stagione va da settembre ad agosto), ma è anche il mese in cui si
  // organizza la stagione che sta per iniziare: questa spunta mostra anche
  // quell'agosto insieme alla stagione in vista, senza spostare il confine
  // usato ovunque altrove (annoStagioneDaData resta invariato)
  const [includiAgostoPrecedente, setIncludiAgostoPrecedente] = useState(false);
  function inStagioneVista(dataStr) {
    if (annoStagioneDaData(dataStr) === stagioneVista) return true;
    if (!includiAgostoPrecedente) return false;
    const [anno, mese] = dataStr.split("-").map(Number);
    return mese === 8 && anno === stagioneVista;
  }

  // stagione bloccata (persistita): se assente, la stagione mostrata segue
  // sempre la data odierna e passa automaticamente a quella nuova a
  // settembre; "Setta di default" la fissa, "Sblocca" la rimuove
  const [stagioneBloccata, setStagioneBloccata] = useState(() => {
    try {
      const v = localStorage.getItem(CHIAVE_STAGIONE_BLOCCATA);
      return v ? parseInt(v, 10) : null;
    } catch { return null; }
  });
  // stagione al momento mostrata a schermo: parte dalla bloccata (se c'è)
  // o da quella corrente, ma può essere cambiata liberamente dalla tendina
  // per sfogliare le altre stagioni senza per questo bloccarle
  const [stagioneVista, setStagioneVista] = useState(stagioneBloccata ?? stagioneCorrente());

  const stagioniDisponibili = useMemo(() => {
    const set = new Set(corsiDate.map((cd) => annoStagioneDaData(cd.data_inizio)));
    set.add(stagioneCorrente());
    set.add(stagioneVista);
    return Array.from(set).sort((a, b) => a - b);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [corsiDate, stagioneVista]);


  function bloccaStagioneDiDefault() {
    try { localStorage.setItem(CHIAVE_STAGIONE_BLOCCATA, String(stagioneVista)); } catch { /* ignora */ }
    setStagioneBloccata(stagioneVista);
  }
  function sbloccaStagione() {
    try { localStorage.removeItem(CHIAVE_STAGIONE_BLOCCATA); } catch { /* ignora */ }
    setStagioneBloccata(null);
    setStagioneVista(stagioneCorrente());
  }

  // "Periodo personalizzato": in alternativa alla stagione, un intervallo
  // di date libero (anche nel passato) — sostituisce sia il filtro di
  // stagione sia il "solo edizioni non ancora concluse" che vale sempre
  // per la vista a stagione, altrimenti l'archivio non sarebbe mai
  // raggiungibile da qui
  const [periodoPersonalizzatoAttivo, setPeriodoPersonalizzatoAttivo] = useState(false);
  const [periodoDa, setPeriodoDa] = useState("");
  const [periodoA, setPeriodoA] = useState("");
  function inPeriodoVisualizzato(cd) {
    if (periodoPersonalizzatoAttivo) {
      if (periodoDa && cd.data_fine < periodoDa) return false;
      if (periodoA && cd.data_inizio > periodoA) return false;
      return true;
    }
    return cd.data_fine >= dataOggiStr() && inStagioneVista(cd.data_inizio);
  }

  const filtriAttivi = filtroCorso || filtroCitta || filtroMaster || filtroAssistente || filtroLeva;

  const righe = corsiDate
    .filter((cd) => inPeriodoVisualizzato(cd))
    .filter((cd) => !filtroCorso || cd.corso_id === filtroCorso)
    .filter((cd) => !filtroCitta || cittaDiSede(location, cd.location_id) === filtroCitta)
    .filter((cd) => !filtroMaster || cd.master_id === filtroMaster || (docentiPerCorsoData[cd.id] || []).some((d) => d.tipo === "master" && d.persona_id === filtroMaster))
    .filter((cd) => !filtroAssistente || (docentiPerCorsoData[cd.id] || []).some((d) => d.tipo === "assistente" && d.persona_id === filtroAssistente))
    .filter((cd) => !filtroLeva || (docentiPerCorsoData[cd.id] || []).some((d) => d.tipo === "leva" && d.persona_id === filtroLeva))
    .filter((cd) => {
      const q = ricercaTesto.trim().toLowerCase();
      if (!q) return true;
      const nomiDocenti = (docentiPerCorsoData[cd.id] || []).map(nomeDocente);
      const campi = [
        corsoById[cd.corso_id]?.nome, locById[cd.location_id]?.nome,
        master.find((m) => m.id === cd.master_id)?.nome,
        ...nomiDocenti,
      ];
      return campi.some((c) => (c || "").toLowerCase().includes(q));
    })
    .slice()
    .sort((a, b) =>
      a.data_inizio.localeCompare(b.data_inizio)
      || (corsoById[a.corso_id]?.nome || "").localeCompare(corsoById[b.corso_id]?.nome || "")
      || (locById[a.location_id]?.nome || "").localeCompare(locById[b.location_id]?.nome || "")
      || a.id.localeCompare(b.id)
    );

  const gruppiMese = {};
  righe.forEach((cd) => {
    const [anno, mese] = cd.data_inizio.split("-");
    const chiave = `${anno}-${mese}`;
    if (!gruppiMese[chiave]) gruppiMese[chiave] = { etichetta: `${MESI[parseInt(mese, 10) - 1]} ${anno}`, righe: [] };
    gruppiMese[chiave].righe.push(cd);
  });
  const chiaviMese = Object.keys(gruppiMese).sort();

  // "Carico assegnazioni": quante volte ciascuna persona compare come
  // master, assistente o leva (tra le edizioni future della stagione
  // vista, indipendentemente dagli altri filtri attivi) — un'unica
  // classifica del carico di lavoro complessivo, non solo delle master
  const conteggioCarico = {};
  function incrementaCarico(nome, nomeCorso) {
    if (!nome) return;
    if (!conteggioCarico[nome]) conteggioCarico[nome] = { totale: 0, perCorso: {} };
    conteggioCarico[nome].totale += 1;
    if (nomeCorso) conteggioCarico[nome].perCorso[nomeCorso] = (conteggioCarico[nome].perCorso[nomeCorso] || 0) + 1;
  }
  corsiDate
    .filter((cd) => inPeriodoVisualizzato(cd))
    .forEach((cd) => {
      const nomeCorso = corsoById[cd.corso_id]?.nome;
      if (cd.master_id) {
        incrementaCarico(master.find((m) => m.id === cd.master_id)?.nome, nomeCorso);
      }
      (docentiPerCorsoData[cd.id] || []).forEach((d) => {
        incrementaCarico(nomeDocente(d), nomeCorso);
      });
    });
  const caricoAssegnazioni = Object.entries(conteggioCarico)
    .map(([nome, dati]) => ({
      nome, n: dati.totale,
      dettaglio: Object.entries(dati.perCorso).map(([corso, n]) => ({ corso, n })).sort((a, b) => b.n - a.n),
    }))
    .sort((a, b) => b.n - a.n);

  // generiche perché servono sia alla riga principale (tabella
  // "corsi_date": la prima master) sia alle righe "docenti extra"
  // (tabella "corsi_date_docenti": altre master, assistenti, leve) —
  // stesso comportamento, tabella diversa
  async function salvaCampoGenerico(tabella, id, campo, valore) {
    // aggiornamento ottimistico: "ricarica" rifà l'intero fetchDati
    // (tutte le tabelle dell'app), troppo lento per sentirsi immediato
    // su un clic (pallino viaggio, flag Avvisata, tendine…) — il valore
    // cambia subito sullo schermo, il salvataggio vero e il refetch
    // completo restano in corsa dietro le quinte
    const chiave = `${id}:${campo}`;
    setOverrideCampi((m) => ({ ...m, [chiave]: valore }));
    const { error } = await supabase.from(tabella).update({ [campo]: valore }).eq("id", id);
    if (error) {
      window.alert("Errore: " + error.message);
      setOverrideCampi((m) => { const copia = { ...m }; delete copia[chiave]; return copia; });
      return;
    }
    ricarica([tabella]);
  }
  function salvaCampo(id, campo, valore) { return salvaCampoGenerico("corsi_date", id, campo, valore); }
  // variante multi-campo: serve a "Pattuito per periodo" che si
  // ricalcola da notti×a notte e va salvato insieme al campo appena
  // toccato, in un solo giro (non due update separati)
  async function salvaCampiGenerico(tabella, id, campi) {
    setOverrideCampi((m) => {
      const next = { ...m };
      for (const c of Object.keys(campi)) next[`${id}:${c}`] = campi[c];
      return next;
    });
    const { error } = await supabase.from(tabella).update(campi).eq("id", id);
    if (error) {
      window.alert("Errore: " + error.message);
      setOverrideCampi((m) => { const copia = { ...m }; for (const c of Object.keys(campi)) delete copia[`${id}:${c}`]; return copia; });
      return;
    }
    ricarica([tabella]);
  }
  const [overrideCampi, setOverrideCampi] = useState({});
  function valoreCampo(oggetto, campo) {
    const chiave = `${oggetto.id}:${campo}`;
    return chiave in overrideCampi ? overrideCampi[chiave] : oggetto[campo];
  }

  async function aggiungiDocente(cd, tipo) {
    // "select().single()" restituisce subito la riga vera (con id vero,
    // non provvisorio): compare a schermo appena arrivata la risposta
    // dell'insert, senza aspettare l'intero fetchDati
    const { data, error } = await supabase.from("corsi_date_docenti").insert({ corso_data_id: cd.id, tipo, persona_id: null }).select().single();
    if (error) { window.alert("Errore: " + error.message); return; }
    setRigheExtraOttimistiche((prev) => [...prev, data]);
    ricarica(["corsi_date_docenti"]);
  }
  function apriAggiungiDocente(cd) {
    setTipoDocenteScelto("master");
    setCorsoDataAggiungiDocente(cd);
  }
  async function confermaAggiungiDocente() {
    if (!corsoDataAggiungiDocente) return;
    await aggiungiDocente(corsoDataAggiungiDocente, tipoDocenteScelto);
    setCorsoDataAggiungiDocente(null);
  }
  async function impostaPersonaDocente(riga, valore) {
    await salvaCampoGenerico("corsi_date_docenti", riga.id, "persona_id", valore || null);
  }
  // cestino a destra della tendina persona: rimuove la riga extra, con
  // conferma (non basta più selezionare "—")
  async function rimuoviDocente(riga) {
    const nome = riga.persona_id ? nomeDocente(riga) : null;
    if (!window.confirm(`Rimuovere questa riga${nome ? ` (${ETICHETTA_TIPO_DOCENTE[riga.tipo]} — ${toTitleCase(nome)})` : ` (${ETICHETTA_TIPO_DOCENTE[riga.tipo]})`}?`)) return;
    setIdsRimosseOttimisticamente((prev) => new Set(prev).add(riga.id));
    const { error } = await supabase.from("corsi_date_docenti").delete().eq("id", riga.id);
    if (error) {
      window.alert("Errore: " + error.message);
      setIdsRimosseOttimisticamente((prev) => { const copia = new Set(prev); copia.delete(riga.id); return copia; });
      return;
    }
    ricarica(["corsi_date_docenti"]);
  }

  async function caricaBigliettiGenerico(tabella, id, fileAttuali, campo, fileList) {
    const nuovi = [];
    for (const file of Array.from(fileList || [])) {
      const percorso = `${id}/biglietto-${Date.now()}-${sanitizzaNomeFile(file.name)}`;
      const { error } = await supabase.storage.from("allegati-iscritti").upload(percorso, file);
      if (error) { window.alert("Errore caricamento: " + error.message); return; }
      nuovi.push(percorso);
    }
    if (nuovi.length === 0) return;
    await salvaCampoGenerico(tabella, id, campo, [...(fileAttuali || []), ...nuovi]);
  }

  async function cancellaBigliettiGenerico(tabella, id, fileAttuali, campo) {
    const n = (fileAttuali || []).length;
    if (n === 0) return;
    if (!window.confirm(`Vuoi cancellare ${n === 1 ? "il file caricato" : `i ${n} file caricati`}?`)) return;
    await salvaCampoGenerico(tabella, id, campo, []);
    window.alert("Eseguito.");
  }

  const fontScheda = { fontFamily: "'Sofia Sans Condensed',sans-serif" };
  const bordoV = `1px solid ${CREAM_BORDER}`;
  const celStyle = { padding: "10px 8px", borderBottom: bordoV, verticalAlign: "middle" };
  // verticalAlign "bottom" (non "middle" ereditato da celStyle) e overflow
  // "hidden": con intestazioni miste a una riga e a due righe nella stessa
  // tabella, la riga dell'header prende l'altezza della più alta — senza
  // "bottom" quelle a una riga restano centrate a mezz'aria invece di
  // restare vicine alla casella sotto; senza "hidden" un'etichetta troppo
  // lunga per la sua colonna sconfina visivamente in quella accanto
  const thStyle = { ...celStyle, ...fontScheda, fontSize: 10, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, textAlign: "left", whiteSpace: "nowrap", background: "#F7F5EF", borderBottom: `1px solid ${CREAM_BORDER}`, verticalAlign: "bottom", overflow: "hidden" };
  const campoStyle = { ...fontScheda, fontSize: 12, fontWeight: 600, padding: "7px 8px", border: `1px solid ${CREAM_BORDER}`, borderRadius: 8, width: "100%", boxSizing: "border-box", background: "#fff", color: NAVY };
  // "+" grosso a destra del nome della master: apre la finestra per
  // scegliere che tipo di docente extra aggiungere (era prima i tre
  // pulsanti M/A/L, ora un'unica finestra con una tendina)
  const pulsantePiuDocenteStyle = { ...fontScheda, fontSize: 26, fontWeight: 800, color: "#000", background: "none", border: "none", cursor: "pointer", padding: "0 4px", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, lineHeight: 1 };
  // etichetta "Master/Assistente/Leva" sopra la relativa casella persona,
  // non più a fianco
  const etichettaTipoStyle = { ...fontScheda, fontSize: 10, fontWeight: 700, color: MUTED, marginBottom: 4 };
  // flag generico verde/bianco con segno di spunta — usato per Avvisata
  // e Pagato: stesso comportamento, etichetta diversa
  const flagSemplice = (attivo, onClick, titoloAttivo, titoloInattivo) => (
    <button
      onClick={onClick}
      title={attivo ? titoloAttivo : titoloInattivo}
      style={{
        width: 22, height: 22, borderRadius: 6, border: `1px solid ${attivo ? "#2E7D32" : CREAM_BORDER}`,
        background: attivo ? "#2E7D32" : "#fff", color: attivo ? "#fff" : "transparent",
        cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", padding: 0,
      }}
    >
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>
    </button>
  );
  const flagAvvisata = (attivo, onClick) => flagSemplice(attivo, onClick, "Avvisata", "Non ancora avvisata");

  // larghezza delle colonne della tabella: trascinabile con il mouse (come
  // in Excel) afferrando la giunzione tra due colonne nell'intestazione;
  // resta salvata per sempre in questo browser (localStorage). Limitata
  // tra un minimo e un massimo (anche i valori già salvati, al
  // caricamento): senza questo un trascinamento andato oltre gonfiava
  // una colonna a dismisura e non c'era più modo di restringerla
  const LARGHEZZA_COLONNA_MIN = 30;
  const LARGHEZZA_COLONNA_MAX = 260;
  const limitaLarghezza = (v) => Math.min(LARGHEZZA_COLONNA_MAX, Math.max(LARGHEZZA_COLONNA_MIN, v));
  // La distribuzione delle colonne è una sola per tutti: quella che il
  // programmatore lascia trascinando. Prima ogni browser teneva la sua
  // copia e la vista condivisa serviva solo a chi apriva la pagina per la
  // prima volta — così nessuno vedeva davvero le stesse colonne.
  const larghezzeSalvate = (
    layoutCondiviso?.versione_colonne === CHIAVE_LARGHEZZE_COLONNE &&
    Array.isArray(layoutCondiviso?.larghezze_colonne) &&
    layoutCondiviso.larghezze_colonne.length === LARGHEZZE_COLONNE_DEFAULT.length
  ) ? layoutCondiviso.larghezze_colonne.map(limitaLarghezza) : LARGHEZZE_COLONNE_DEFAULT;
  const [larghezze, setLarghezze] = useState(larghezzeSalvate);
  // se la vista condivisa arriva (o cambia) dopo il primo disegno, le
  // colonne si allineano da sole invece di restare al default
  useEffect(() => { setLarghezze(larghezzeSalvate); }, [JSON.stringify(larghezzeSalvate)]);
  const COLONNE = larghezze.map((larghezza) => ({ larghezza }));
  const larghezzaTabella = larghezze.reduce((a, b) => a + b, 0);

  const ridimensionamentoRef = React.useRef(null);
  function iniziaRidimensionamento(e, indice) {
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    ridimensionamentoRef.current = { indice, pointerId: e.pointerId, startX: e.clientX, startWidth: larghezze[indice] };
  }
  function muoviRidimensionamento(e) {
    const r = ridimensionamentoRef.current;
    if (!r || e.pointerId !== r.pointerId) return;
    const nuovaLarghezza = limitaLarghezza(r.startWidth + (e.clientX - r.startX));
    setLarghezze((precedenti) => precedenti.map((l, i) => (i === r.indice ? nuovaLarghezza : l)));
  }
  function fineRidimensionamento() {
    if (!ridimensionamentoRef.current) return;
    ridimensionamentoRef.current = null;
    // lasciata la maniglia, la nuova distribuzione diventa quella di tutti
    // (solo se a trascinare è il programmatore)
    if (ruoloUtente === "programmatore") {
      supabase.from("impostazioni_layout_assegnazione_master")
        .update({ larghezze_colonne: larghezze, versione_colonne: CHIAVE_LARGHEZZE_COLONNE })
        .eq("id", "00000000-0000-0000-0000-000000000002")
        .then(({ error }) => { if (error) console.warn("Larghezze non salvate:", error.message); });
    }
  }

  // opzioni disponibili per la tendina persona di una riga "docente
  // extra": esclude chi è già scelto altrove nello stesso corso per lo
  // stesso tipo (incluso, per le master, la master principale già sui
  // campi diretti di corsi_date)
  function opzioniPersonaDocente(cd, riga) {
    const opzioniComplete = riga.tipo === "master" ? master : riga.tipo === "assistente" ? assistente : leva;
    const usati = new Set(
      (docentiPerCorsoData[cd.id] || [])
        .filter((d) => d.tipo === riga.tipo && d.id !== riga.id)
        .map((d) => d.persona_id)
        .filter(Boolean)
    );
    if (riga.tipo === "master" && cd.master_id) usati.add(cd.master_id);
    return opzioniComplete.filter((o) => o.id === riga.persona_id || !usati.has(o.id));
  }

  function filtroDropdown(chiave, etichetta, valore, setValore, opzioni, Icona) {
    return (
      <div style={{ position: "relative", flex: "1 1 150px", minWidth: 130 }}>
        <button
          onClick={() => setApriFiltro(apriFiltro === chiave ? "" : chiave)}
          style={{
            ...fontScheda, width: "100%", display: "flex", alignItems: "center", gap: 8, fontSize: 13, fontWeight: 600,
            padding: "10px 12px", borderRadius: 10, cursor: "pointer",
            border: `1px solid ${valore ? NAVY : CREAM_BORDER}`, background: "#fff", color: NAVY,
          }}
        >
          {Icona && <Icona size={16} color={valore ? NAVY : MUTED} />}
          <span style={{ flex: 1, textAlign: "left", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {valore ? opzioni.find((o) => o.id === valore)?.nome?.toUpperCase() : etichetta}
          </span>
          <IconaChevronGiuErp size={13} color={MUTED} />
        </button>
        {apriFiltro === chiave && (
          <select
            autoFocus
            style={{ ...inputStyle, ...fontScheda, position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, zIndex: 10, width: "auto" }}
            value={valore}
            onChange={(e) => { setValore(e.target.value); setApriFiltro(""); }}
            onBlur={() => setApriFiltro("")}
          >
            <option value="">Tutti</option>
            {opzioni.map((o) => <option key={o.id} value={o.id}>{o.nome.toUpperCase()}</option>)}
          </select>
        )}
      </div>
    );
  }

  // cella "Viaggio": pallino rosso/verde (prenotato o no), "+" per
  // caricare biglietti, dicitura "N file" per cancellarli — generica,
  // usata sia per la riga principale (tabella "corsi_date") sia per le
  // righe "docenti extra" (tabella "corsi_date_docenti")
  function cellaViaggio(tabella, riga, campoStato, campoFile) {
    const nBiglietti = (valoreCampo(riga, campoFile) || []).length;
    const stato = valoreCampo(riga, campoStato) || "no";
    const stile = VIAGGIO_STATI[stato];
    return (
      <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "nowrap" }}>
        <button
          onClick={() => salvaCampoGenerico(tabella, riga.id, campoStato, prossimoStatoViaggio(stato))}
          title={`${stile.etichetta} (clicca per cambiare)`}
          style={{ width: 18, height: 18, borderRadius: "50%", border: "none", padding: 0, cursor: "pointer", background: stile.colore, flexShrink: 0 }}
        />
        {stato === "non_occorre" ? (
          <span style={{ ...fontScheda, fontSize: 11.5, fontWeight: 700, color: MUTED, whiteSpace: "nowrap" }}>In sede</span>
        ) : (
          <label style={{ ...fontScheda, fontSize: 16, fontWeight: 700, color: NAVY, border: `1px solid ${CREAM_BORDER}`, borderRadius: 8, padding: "3px 10px", cursor: "pointer", whiteSpace: "nowrap", lineHeight: 1 }}>
            +
            <input type="file" multiple accept="application/pdf,image/*" style={{ display: "none" }} onChange={(e) => { caricaBigliettiGenerico(tabella, riga.id, valoreCampo(riga, campoFile), campoFile, e.target.files); e.target.value = ""; }} />
          </label>
        )}
        {nBiglietti > 0 && (
          <span
            onClick={() => cancellaBigliettiGenerico(tabella, riga.id, valoreCampo(riga, campoFile), campoFile)}
            title="Clicca per cancellare i file caricati"
            style={{ ...fontScheda, fontSize: 12, fontWeight: 600, color: NAVY, whiteSpace: "nowrap", cursor: "pointer", textDecoration: "underline" }}
          >
            {nBiglietti} file
          </span>
        )}
      </div>
    );
  }

  function tabellaMese(righeMese) {
    return (
      <div style={{ overflowX: "auto", background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 14, marginBottom: 28, boxShadow: "0 10px 24px -14px rgba(14,27,51,0.2)" }}>
        <table style={{ borderCollapse: "collapse", width: larghezzaTabella, tableLayout: "fixed" }}>
          <colgroup>{COLONNE.map((c, i) => <col key={i} style={{ width: c.larghezza }} />)}</colgroup>
          <thead>
            <tr>
              {ETICHETTE_COLONNE_MASTER.map((etichetta, i) => (
                <th key={i} style={{
                  ...thStyle, position: "relative",
                  textAlign: (etichetta === "Sede" || COLONNE_HEADER_SU_DUE_RIGHE.has(etichetta)) ? "center" : thStyle.textAlign,
                  lineHeight: COLONNE_HEADER_SU_DUE_RIGHE.has(etichetta) ? 1.25 : thStyle.lineHeight,
                  // separatore tra le intestazioni: senza, due etichette
                  // corte in colonne strette (es. "Avvisata"/"Note") sembrano
                  // incollate anche quando ciascuna sta nella sua colonna
                  borderLeft: i > 0 ? `1px solid ${CREAM_BORDER}` : "none",
                }}>
                  {COLONNE_HEADER_SU_DUE_RIGHE.has(etichetta)
                    ? COLONNE_HEADER_SU_DUE_RIGHE.get(etichetta).map((riga, r) => <div key={r}>{riga}</div>)
                    : etichetta}
                  <div
                    onPointerDown={(e) => iniziaRidimensionamento(e, i)}
                    onPointerMove={muoviRidimensionamento}
                    onPointerUp={fineRidimensionamento}
                    onPointerCancel={fineRidimensionamento}
                    style={{ position: "absolute", top: 0, right: -4, bottom: 0, width: 8, cursor: "col-resize", touchAction: "none", zIndex: 3 }}
                  />
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {righeMese.map((cd, indice) => {
              const corso = corsoById[cd.corso_id];
              const loc = locById[cd.location_id];
              const { sopra, sotto } = fmtDataStack(cd.data_inizio, cd.data_fine);
              const docenti = docentiPerCorsoData[cd.id] || [];
              const rowSpanGruppo = 1 + docenti.length;
              // corsi alternati bianco / grigio chiarissimo, per riconoscere
              // a colpo d'occhio dove finisce un corso e inizia il prossimo
              const sfondoGruppo = indice % 2 === 1 ? "#EEEEEE" : "#fff";
              const cellaGruppo = { ...celStyle, background: sfondoGruppo };
              return (
                <React.Fragment key={cd.id}>
                  <tr>
                    <td rowSpan={rowSpanGruppo} style={{ ...cellaGruppo, ...fontScheda, fontSize: 13, color: NAVY, textAlign: "center", verticalAlign: "top", borderLeft: `8px solid ${corso?.colore || NAVY}` }}>
                      <div>{sopra}</div>
                      <div style={{ fontSize: 10, color: MUTED }}>{sotto}</div>
                    </td>
                    <td rowSpan={rowSpanGruppo} style={{ ...cellaGruppo, ...fontScheda, fontSize: 13, color: NAVY, fontWeight: 700, verticalAlign: "top" }}>
                      {corso?.nome?.toUpperCase() || "?"}
                    </td>
                    <td rowSpan={rowSpanGruppo} style={{ ...cellaGruppo, ...fontScheda, fontSize: 12, color: NAVY, verticalAlign: "top" }}>{loc?.nome?.toUpperCase() || "?"}</td>
                    <td rowSpan={rowSpanGruppo} style={{ ...cellaGruppo, verticalAlign: "top" }}>
                      {loc && valoreCampo(cd, "pagamento_sede") ? (
                        <button onClick={() => setGestisciSede({ cd })} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: NAVY, background: "none", border: "none", textDecoration: "underline", cursor: "pointer", padding: 0, textAlign: "left", display: "flex", alignItems: "center", gap: 7 }}>
                          {loc.nome_sede ? toTitleCase(loc.nome_sede) : toTitleCase(loc.nome)}
                          <span title={valoreCampo(cd, "sede_confermata") ? "Sede avvisata" : "Sede non ancora avvisata"} style={{ width: 13, height: 13, borderRadius: "50%", background: valoreCampo(cd, "sede_confermata") ? "#2E7D32" : "#C0392B", flexShrink: 0 }} />
                        </button>
                      ) : (
                        <button onClick={() => setGestisciSede({ cd })} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: "#C0392B", background: "none", border: "none", textDecoration: "underline", cursor: "pointer", padding: 0, textAlign: "left" }}>
                          Gestisci
                        </button>
                      )}
                    </td>
                    <td style={{ ...cellaGruppo, verticalAlign: "top", paddingTop: 3 }}>
                      <div>
                        <span style={etichettaTipoStyle}>Master</span>
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                        <select style={{ ...campoStyle, flex: 1, minWidth: 0 }} value={valoreCampo(cd, "master_id") || ""} onChange={(e) => salvaCampo(cd.id, "master_id", e.target.value || null)}>
                          <option value="">—</option>
                          {master.map((m) => <option key={m.id} value={m.id}>{m.nome.toUpperCase()}</option>)}
                        </select>
                        <div style={{ position: "relative", flexShrink: 0 }}>
                          <button onClick={() => apriAggiungiDocente(cd)} title="Aggiungi un docente (master, assistente o leva)" style={pulsantePiuDocenteStyle}>+</button>
                          {corsoDataAggiungiDocente?.id === cd.id && (
                            <div style={{ position: "absolute", top: "calc(100% + 10px)", left: -8, zIndex: 30, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 12, boxShadow: "0 10px 28px -8px rgba(14,27,51,0.35)", padding: 14, width: 220 }}>
                              <div style={{ position: "absolute", top: -7, left: 14, width: 12, height: 12, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderTop: "none", borderRight: "none", transform: "rotate(135deg)" }} />
                              <Field label="Aggiungi">
                                <select style={inputStyle} value={tipoDocenteScelto} onChange={(e) => setTipoDocenteScelto(e.target.value)}>
                                  <option value="master">Master</option>
                                  <option value="assistente">Assistente</option>
                                  <option value="leva">Leva</option>
                                </select>
                              </Field>
                              <div style={{ display: "flex", gap: 8 }}>
                                <Button onClick={confermaAggiungiDocente}>Aggiungi</Button>
                                <Button variant="ghost" onClick={() => setCorsoDataAggiungiDocente(null)}>Annulla</Button>
                              </div>
                            </div>
                          )}
                        </div>
                      </div>
                    </td>
                    <td style={{ ...cellaGruppo, textAlign: "center" }}>
                      {flagAvvisata(!!valoreCampo(cd, "avvisata"), () => salvaCampo(cd.id, "avvisata", !valoreCampo(cd, "avvisata")))}
                    </td>
                    <td style={cellaGruppo}>
                      <input style={campoStyle} defaultValue={cd.note || ""} onBlur={(e) => { if (e.target.value !== (cd.note || "")) salvaCampo(cd.id, "note", e.target.value || null); }} />
                    </td>
                    <td style={cellaGruppo}>
                      {cellaViaggio("corsi_date", cd, "viaggio_stato", "viaggio_file")}
                    </td>
                    <td style={cellaGruppo}>
                      <button onClick={() => setGestisciAlloggio({ cd, riga: cd, tabella: "corsi_date" })} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: NAVY, background: "none", border: "none", textDecoration: "underline", cursor: "pointer", padding: 0, textAlign: "left" }}>
                        {hotelNomeDi(valoreCampo(cd, "alloggio_id")) || "Gestisci"}
                      </button>
                    </td>
                    <td style={cellaGruppo}>
                      {cellaHotelPagato(cd, cd.id)}
                    </td>
                    <td style={cellaGruppo}>
                      <input style={campoStyle} defaultValue={cd.note_viaggio || ""} onBlur={(e) => { if (e.target.value !== (cd.note_viaggio || "")) salvaCampo(cd.id, "note_viaggio", e.target.value || null); }} />
                    </td>
                  </tr>
                  {docenti.map((riga) => (
                    <tr key={riga.id}>
                      <td style={{ ...cellaGruppo, verticalAlign: "top", paddingTop: 3 }}>
                        <div>
                          <span style={etichettaTipoStyle}>{ETICHETTA_TIPO_DOCENTE[riga.tipo]}</span>
                        </div>
                        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                          <select style={{ ...campoStyle, flex: 1, minWidth: 0 }} value={valoreCampo(riga, "persona_id") || ""} onChange={(e) => impostaPersonaDocente(riga, e.target.value)}>
                            <option value="">—</option>
                            {opzioniPersonaDocente(cd, riga).map((o) => <option key={o.id} value={o.id}>{o.nome.toUpperCase()}</option>)}
                          </select>
                          <button onClick={() => rimuoviDocente(riga)} title="Rimuovi questa riga" style={{ background: "none", border: "none", color: "#C0392B", cursor: "pointer", padding: 2, display: "flex", flexShrink: 0 }}>
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6" /><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" /></svg>
                          </button>
                        </div>
                      </td>
                      <td style={{ ...cellaGruppo, textAlign: "center" }}>
                        {flagAvvisata(!!valoreCampo(riga, "avvisata"), () => salvaCampoGenerico("corsi_date_docenti", riga.id, "avvisata", !valoreCampo(riga, "avvisata")))}
                      </td>
                      <td style={cellaGruppo}>
                        <input style={campoStyle} defaultValue={riga.note || ""} onBlur={(e) => { if (e.target.value !== (riga.note || "")) salvaCampoGenerico("corsi_date_docenti", riga.id, "note", e.target.value || null); }} />
                      </td>
                      <td style={cellaGruppo}>
                        {cellaViaggio("corsi_date_docenti", riga, "viaggio_stato", "viaggio_file")}
                      </td>
                      <td style={cellaGruppo}>
                        <button onClick={() => setGestisciAlloggio({ cd, riga, tabella: "corsi_date_docenti" })} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: NAVY, background: "none", border: "none", textDecoration: "underline", cursor: "pointer", padding: 0, textAlign: "left" }}>
                          {hotelNomeDi(valoreCampo(riga, "alloggio_id")) || "Gestisci"}
                        </button>
                      </td>
                      <td style={cellaGruppo}>
                        {cellaHotelPagato(riga, cd.id)}
                      </td>
                      <td style={cellaGruppo}>
                        {riga.tipo !== "leva" && (
                          <input style={campoStyle} defaultValue={riga.note_viaggio || ""} onBlur={(e) => { if (e.target.value !== (riga.note_viaggio || "")) salvaCampoGenerico("corsi_date_docenti", riga.id, "note_viaggio", e.target.value || null); }} />
                        )}
                      </td>
                    </tr>
                  ))}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    );
  }

  return (
    <div style={{ background: "transparent", minHeight: "100vh", padding: "40px 20px 60px" }}>
      <div style={{ maxWidth: 1300, margin: "0 auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 20, flexWrap: "wrap", marginBottom: 18 }}>
          <div>
            <div style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: GOLD, textTransform: "uppercase", letterSpacing: 1.2, marginBottom: 4 }}>Team</div>
            <div style={{ ...fontDisplay, fontSize: 32, fontWeight: 700, color: NAVY, marginBottom: 6 }}>{titolo}</div>
            <div style={{ ...fontBody, fontSize: 14, color: MUTED }}>Organizza il team, gli assistenti e le trasferte per ogni corso</div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            {!periodoPersonalizzatoAttivo ? (
              <>
                <select
                  value={stagioneVista}
                  onChange={(e) => setStagioneVista(parseInt(e.target.value, 10))}
                  style={{ ...inputStyle, ...fontBody, fontWeight: 600, width: "auto", borderRadius: 10 }}
                >
                  {stagioniDisponibili.map((anno) => (
                    <option key={anno} value={anno}>{etichettaStagione(anno)}</option>
                  ))}
                </select>
                <label style={{ display: "flex", alignItems: "center", gap: 7, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 10, padding: "9px 14px", ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, whiteSpace: "nowrap", cursor: "pointer" }}>
                  <input type="checkbox" checked={includiAgostoPrecedente} onChange={(e) => setIncludiAgostoPrecedente(e.target.checked)} style={{ width: 15, height: 15 }} />
                  Includi agosto precedente
                </label>
                {stagioneBloccata === stagioneVista ? (
                  <div style={{ display: "flex", alignItems: "center", gap: 7, background: "#EEF1FA", border: "1px solid #D9DEF2", borderRadius: 10, padding: "9px 14px", ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, whiteSpace: "nowrap" }}>
                    <IconaSpuntaCerchio size={15} color="#2E7D32" /> Stagione di default
                  </div>
                ) : (
                  <button
                    onClick={bloccaStagioneDiDefault}
                    style={{ ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 10, padding: "9px 14px", cursor: "pointer", whiteSpace: "nowrap" }}
                  >
                    Imposta come default
                  </button>
                )}
                {stagioneBloccata != null && (
                  <button
                    onClick={sbloccaStagione}
                    style={{ display: "flex", alignItems: "center", gap: 7, ...fontBody, fontSize: 13, fontWeight: 700, color: "#fff", background: NAVY, border: "none", borderRadius: 10, padding: "9px 16px", cursor: "pointer", whiteSpace: "nowrap" }}
                  >
                    <IconaLucchetto size={15} color="#fff" /> Sblocca
                  </button>
                )}
              </>
            ) : (
              <>
                <label style={{ display: "flex", alignItems: "center", gap: 7, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 10, padding: "7px 14px", ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, whiteSpace: "nowrap" }}>
                  Da
                  <input type="date" value={periodoDa} onChange={(e) => setPeriodoDa(e.target.value)} style={{ ...inputStyle, ...fontBody, fontSize: 13, width: "auto", padding: "5px 8px" }} />
                </label>
                <label style={{ display: "flex", alignItems: "center", gap: 7, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 10, padding: "7px 14px", ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, whiteSpace: "nowrap" }}>
                  A
                  <input type="date" value={periodoA} onChange={(e) => setPeriodoA(e.target.value)} style={{ ...inputStyle, ...fontBody, fontSize: 13, width: "auto", padding: "5px 8px" }} />
                </label>
              </>
            )}
            <button
              onClick={() => setPeriodoPersonalizzatoAttivo((v) => !v)}
              style={{
                ...fontBody, fontSize: 13, fontWeight: 700, whiteSpace: "nowrap", cursor: "pointer", borderRadius: 10, padding: "9px 14px",
                color: periodoPersonalizzatoAttivo ? "#fff" : NAVY, background: periodoPersonalizzatoAttivo ? NAVY : "#fff", border: periodoPersonalizzatoAttivo ? "none" : `1px solid ${CREAM_BORDER}`,
              }}
            >
              {periodoPersonalizzatoAttivo ? "Torna alla stagione" : "Periodo personalizzato"}
            </button>
          </div>
        </div>

        <div style={{ ...cardStyle, boxShadow: "0 10px 24px -14px rgba(14,27,51,0.15)", marginBottom: 24 }}>
          <div style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 8 }}>Carico assegnazioni master</div>
          {caricoAssegnazioni.length === 0 ? (
            <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessuna assegnazione ancora.</div>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gridTemplateRows: `repeat(${Math.ceil(caricoAssegnazioni.length / 4)}, auto)`, gridAutoFlow: "column", gap: 6 }}>
              {caricoAssegnazioni.map((p) => (
                <div key={p.nome} style={{ border: `1px solid ${CREAM_BORDER}`, borderRadius: 8, padding: "4px 6px", background: "#fff" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <span style={{ ...fontScheda, fontSize: 13.5, fontWeight: 700, color: NAVY, flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.nome.toUpperCase()}</span>
                    <span style={{ ...fontScheda, fontSize: 12.5, fontWeight: 700, color: "#fff", background: NAVY, borderRadius: 5, width: 24, height: 24, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{p.n}</span>
                  </div>
                  {p.dettaglio.length > 0 && (
                    <div style={{ ...fontBody, fontSize: 9.5, color: MUTED, marginTop: 1, lineHeight: 1.15 }}>
                      {p.dettaglio.map((d) => `${d.n} ${d.corso}`).join(", ")}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        <div style={{ display: "flex", gap: 10, marginBottom: 24, flexWrap: "wrap", alignItems: "center" }}>
          <div style={{ position: "relative", flex: "2 1 220px", minWidth: 180 }}>
            <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", display: "flex", pointerEvents: "none" }}>
              <IconaRicercaErp size={16} color={MUTED} />
            </span>
            <input
              value={ricercaTesto}
              onChange={(e) => setRicercaTesto(e.target.value)}
              placeholder="Cerca corso, città o persona"
              style={{ ...inputStyle, ...fontBody, fontSize: 13, paddingLeft: 36, borderRadius: 10, width: "100%", boxSizing: "border-box" }}
            />
          </div>
          {filtroDropdown("corso", "Corso", filtroCorso, setFiltroCorso, corsi, IconaLaureaErp)}
          {filtroDropdown("citta", "Città", filtroCitta, setFiltroCitta, cittaDistinte(location), IconaPin)}
          {filtroDropdown("master", "Master", filtroMaster, setFiltroMaster, master, IconaMasterRiga)}
          {filtroDropdown("assistente", "Assistente", filtroAssistente, setFiltroAssistente, assistente, IconaAssistentiRiga)}
          {filtroDropdown("leva", "Leve", filtroLeva, setFiltroLeva, leva, IconaCalendarioLeve)}
          {(filtriAttivi || ricercaTesto) && (
            <button
              onClick={() => { setFiltroCorso(""); setFiltroCitta(""); setFiltroMaster(""); setFiltroAssistente(""); setFiltroLeva(""); setApriFiltro(""); setRicercaTesto(""); }}
              style={{ ...fontBody, fontSize: 13, fontWeight: 700, color: GOLD, background: "transparent", border: "none", cursor: "pointer", whiteSpace: "nowrap", padding: "10px 4px" }}
            >
              Azzera filtri
            </button>
          )}
        </div>

        {chiaviMese.length === 0 && (
          <div style={{ ...fontBody, fontSize: 13, color: MUTED, textAlign: "center", padding: 20 }}>Nessuna data in programmazione.</div>
        )}
        {chiaviMese.map((chiave) => (
          <div key={chiave}>
            <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 12, flexWrap: "wrap", gap: 8 }}>
              <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
                <div style={{ ...fontDisplay, fontSize: 20, fontWeight: 700, color: NAVY }}>{gruppiMese[chiave].etichetta.toUpperCase()}</div>
                <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>
                  {gruppiMese[chiave].righe.length} cors{gruppiMese[chiave].righe.length === 1 ? "o" : "i"} visibil{gruppiMese[chiave].righe.length === 1 ? "e" : "i"}
                </div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <div
                  title="Al momento è disponibile solo la vista tabella"
                  style={{ display: "flex", alignItems: "center", gap: 6, ...fontBody, fontSize: 13, fontWeight: 600, color: MUTED, border: `1px solid ${CREAM_BORDER}`, borderRadius: 10, padding: "8px 12px", opacity: 0.6, cursor: "default", background: "#fff" }}
                >
                  <IconaGrigliaTabella size={15} color={MUTED} /> Vista tabella <IconaChevronGiuErp size={12} color={MUTED} />
                </div>
              </div>
            </div>
            {tabellaMese(gruppiMese[chiave].righe)}
          </div>
        ))}
      </div>
      {gestisciAlloggio && (
        <ModaleGestisciAlloggio
          cd={gestisciAlloggio.cd}
          riga={gestisciAlloggio.riga}
          tabella={gestisciAlloggio.tabella}
          hotel={hotel}
          onClose={() => setGestisciAlloggio(null)}
          onSalvato={() => { setGestisciAlloggio(null); ricarica([gestisciAlloggio.tabella]); }}
        />
      )}
      {gestisciSede && (
        <ModaleGestisciSede
          cd={gestisciSede.cd}
          location={location}
          onClose={() => setGestisciSede(null)}
          onSalvato={() => { setGestisciSede(null); ricarica(["corsi_date"]); }}
        />
      )}
    </div>
  );
}

// ---------- Statistiche ----------
// hub d'ingresso di "Statistiche": stesso stile a griglia di Contabilità e
// Gestione magazzino e shop, per uniformità — raccoglie qui anche le due
// aree che prima stavano nell'hub ERP (Performance Aziendale, ex
// "Dashboard analisi", e Statistiche Vendite Prodotti), essendo entrambe
// analisi/numeri più che gestione operativa
function Statistiche({ onBack, onApriVenditori, onApriStatisticheMaster, onApriPerformanceAziendale, onApriStatisticheVenditeProdotti, ruoloUtente, ordineTasti, onSalvaOrdineTasti, colonneTasti, onSalvaColonneTasti, etichetteTasti, onSalvaEtichettaTasti, titolo = "Statistiche" }) {
  const isMobile = useIsMobile();
  return (
    <div style={{ background: "transparent", minHeight: "100vh" }}>
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: isMobile ? "24px 20px 60px" : "32px 32px 60px" }}>
        <div style={{ marginBottom: isMobile ? 12 : 18 }}>
          <TastoLivelloPrecedente titolo="Home" onClick={onBack} />
        </div>
        <div style={{ ...fontDisplay, fontSize: isMobile ? 21 : 32, fontWeight: 700, color: NAVY, marginBottom: isMobile ? 2 : 6 }}>{titolo}</div>
        <div style={{ ...fontBody, fontSize: isMobile ? 12 : 14, color: MUTED, marginBottom: isMobile ? 12 : 26 }}>Analisi, report e KPI della tua Academy.</div>
        <GrigliaTasti
          pagina="statistiche" ordine={ordineTasti} colonne={colonneTasti} etichette={etichetteTasti} ruoloUtente={ruoloUtente} onSalvaOrdine={onSalvaOrdineTasti} onSalvaColonne={onSalvaColonneTasti} onSalvaEtichetta={onSalvaEtichettaTasti} colonneDesktop={3}
          definizioni={[
            { chiave: "venditori", title: "Statistiche venditori", descrizione: "Iscrizioni fatte da ciascun venditore, per corso.", Icona: IconaTileVenditori, attivo: true, onClick: onApriVenditori },
            { chiave: "master", title: "Statistiche Master", descrizione: "Vendite prodotti conseguite da ogni master, per mese, trimestre e oltre.", Icona: IconaTileMaster, attivo: true, onClick: onApriStatisticheMaster },
            { chiave: "performance", title: "Performance Aziendale", descrizione: "Analizza performance, trend e KPI dell'Academy.", Icona: IconaTileDashboardAnalisi, attivo: true, onClick: onApriPerformanceAziendale },
            { chiave: "venditeprodotti", title: "Statistiche Totali Vendite Prodotti", descrizione: "Shop online e vendite al banco, per operatore e per prodotto — separate dalle vendite corsi.", Icona: IconaGruppoVenditeProdotti, attivo: true, onClick: onApriStatisticheVenditeProdotti },
          ]}
        />
      </div>
    </div>
  );
}

// elenco delle iscrizioni più recenti, raggruppate per giorno di
// inserimento (campo "ts" dell'iscritto), più recenti in cima
function UltimeIscrizioni({ corsi, location, corsiDate, iscritti, onApriIscritto }) {
  const { ordine, cambiaOrdine, ordina } = useOrdinamentoTabella();
  const corsoById = useMemo(() => Object.fromEntries(corsi.map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries(location.map((l) => [l.id, l])), [location]);
  const cdById = useMemo(() => Object.fromEntries(corsiDate.map((cd) => [cd.id, cd])), [corsiDate]);

  const ordinate = iscritti
    .filter((i) => i.ts)
    .slice()
    .sort((a, b) => b.ts.localeCompare(a.ts));

  // le iscrizioni flaggate "vecchia iscrizione" (inserite ora ma relative a
  // un corso già passato) non entrano nei gruppi per giorno: altrimenti
  // sporcherebbero il giorno di inserimento con dati che non riguardano
  // davvero "oggi". Finiscono tutte in un unico elenco a parte
  const recenti = ordinate.filter((i) => !i.vecchia_iscrizione);
  const mesePrecedenti = ordinate.filter((i) => i.vecchia_iscrizione);

  const gruppi = {};
  recenti.forEach((i) => {
    const chiave = i.ts.slice(0, 10); // "YYYY-MM-DD"
    if (!gruppi[chiave]) gruppi[chiave] = [];
    gruppi[chiave].push(i);
  });
  const chiaviData = Object.keys(gruppi).sort((a, b) => b.localeCompare(a));

  const bordoV = `1px solid ${CREAM_BORDER}`;
  const celStyle = { padding: "8px 12px", borderBottom: bordoV, borderRight: bordoV };
  const thStyle = { ...celStyle, ...fontBody, fontSize: 11, fontWeight: 600, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, textAlign: "left", background: BG };

  const valoriOrdinamento = {
    tutor: (i) => i.tutor || "",
    corso: (i) => { const cd = cdById[i.corso_data_id]; return (cd ? corsoById[cd.corso_id]?.nome : "") || ""; },
    pacchetto: (i) => i.pacchetto_kit || "",
    citta: (i) => { const cd = cdById[i.corso_data_id]; return (cd ? locById[cd.location_id]?.nome : "") || ""; },
    data: (i) => cdById[i.corso_data_id]?.data_inizio || "",
    importo: (i) => (i.totale_pattuito != null ? Number(i.totale_pattuito) : null),
  };

  const tabella = (lista) => (
    <div style={{ overflowX: "auto", background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 12 }}>
      <table style={{ borderCollapse: "collapse", width: "100%" }}>
        <thead>
          <tr>
            <ThOrdina campo="tutor" ordine={ordine} onOrdina={cambiaOrdine} style={thStyle}>Tutor</ThOrdina>
            <ThOrdina campo="corso" ordine={ordine} onOrdina={cambiaOrdine} style={thStyle}>Tipo di corso</ThOrdina>
            <ThOrdina campo="pacchetto" ordine={ordine} onOrdina={cambiaOrdine} style={thStyle}>Pacchetto/Kit</ThOrdina>
            <ThOrdina campo="citta" ordine={ordine} onOrdina={cambiaOrdine} style={thStyle}>Città</ThOrdina>
            <ThOrdina campo="data" ordine={ordine} onOrdina={cambiaOrdine} style={thStyle}>Data del corso</ThOrdina>
            <ThOrdina campo="importo" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, borderRight: "none" }}>Importo pattuito</ThOrdina>
          </tr>
        </thead>
        <tbody>
          {ordina(lista, valoriOrdinamento).map((i) => {
            const cd = cdById[i.corso_data_id];
            const corso = cd ? corsoById[cd.corso_id] : null;
            const loc = cd ? locById[cd.location_id] : null;
            return (
              <tr
                key={i.id}
                onClick={onApriIscritto ? () => onApriIscritto(i) : undefined}
                style={{ cursor: onApriIscritto ? "pointer" : undefined }}
              >
                <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, fontWeight: 600, whiteSpace: "nowrap" }}>{(i.tutor || "—").toUpperCase()}</td>
                <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, whiteSpace: "nowrap" }}>{corso?.nome?.toUpperCase() || "?"}</td>
                <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY }}>{i.pacchetto_kit || "—"}</td>
                <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, whiteSpace: "nowrap" }}>{loc?.nome?.toUpperCase() || "?"}</td>
                <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, whiteSpace: "nowrap" }}>{cd ? fmtDataCompatta(cd.data_inizio, cd.data_fine) : "—"}</td>
                <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, fontWeight: 600, whiteSpace: "nowrap", borderRight: "none" }}>
                  {i.totale_pattuito != null ? `${i.totale_pattuito} €` : "—"}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );

  return (
    <div style={{ maxWidth: 900, margin: "0 auto", padding: "40px 20px" }}>
      <div style={{ ...fontDisplay, fontSize: 26, fontWeight: 800, color: NAVY, textAlign: "center", marginBottom: 30 }}>
        ULTIME ISCRIZIONI
      </div>

      {chiaviData.length === 0 && mesePrecedenti.length === 0 && (
        <div style={{ ...fontBody, fontSize: 13, color: MUTED, textAlign: "center" }}>Nessuna iscrizione ancora.</div>
      )}

      {chiaviData.map((data) => (
        <div key={data} style={{ marginBottom: 28 }}>
          <div style={{ ...fontBody, fontSize: 15, fontWeight: 600, color: NAVY, textAlign: "center", marginBottom: 12 }}>
            {fmtDataLunga(data)}
          </div>
          {tabella(gruppi[data])}
        </div>
      ))}

      {mesePrecedenti.length > 0 && (
        <div style={{ marginBottom: 28 }}>
          <div style={{ ...fontBody, fontSize: 15, fontWeight: 600, color: NAVY, textAlign: "center", marginBottom: 12 }}>
            Mesi precedenti
          </div>
          {tabella(mesePrecedenti)}
        </div>
      )}
    </div>
  );
}

// "Le tue iscrizioni" (Dashboard venditori): solo gli allievi iscritti da
// questo venditore (match sul campo "Tutor", stesso campo che already
// alimenta il resto della dashboard), in ordine cronologico — stesso
// stile a tabella/riga cliccabile di UltimeIscrizioni, ma senza bisogno
// della colonna Tutor (è già filtrato su un solo venditore)
// finestra "Aggiungi pagamento" (aperta da un tasto su una riga di "Le
// tue iscrizioni"): il venditore carica il file del pagamento e scrive
// una nota a mano — nessun campo strutturato, solo questi due più
// l'invio. Non tocca la scheda dell'iscritto: finisce nella coda
// acconti_da_verificare, in attesa che lo staff la verifichi e approvi
// da "Verifica Pagamenti" (Gestione corsi)
const VOCI_PAGAMENTO_VENDITORE = [
  { chiave: "acconto", etichetta: "Acconto" },
  { chiave: "precorso", etichetta: "Quota pre corso" },
  { chiave: "saldo", etichetta: "Saldo" },
];
function ModalePagamentoVenditore({ iscritto, venditoreNome, ricarica, onChiudi, onInviato, accontoEsistente, corsi, corsiDate, location, iscritti }) {
  const [dataPagamento, setDataPagamento] = useState(accontoEsistente?.data_pagamento || dataOggiStr());
  const [vociPagamento, setVociPagamento] = useState(accontoEsistente?.voci_pagamento || []);
  const [valori, setValori] = useState({
    imponibile: accontoEsistente?.imponibile != null ? String(accontoEsistente.imponibile) : "",
    totale: accontoEsistente?.importo != null ? String(accontoEsistente.importo) : "",
    metodo: accontoEsistente?.metodo || "",
    interessi: "",
  });
  const [nota, setNota] = useState(accontoEsistente?.nota || "");
  const [file, setFile] = useState(null);
  const [inviando, setInviando] = useState(false);
  const inModifica = !!accontoEsistente;

  // "Associa altri corsi": la prima riga (il corso a cui l'iscritto
  // appartiene già) è sempre fissa/derivata, non fa parte dello stato — qui
  // si tiene solo l'elenco di corso_data_id aggiunti in più (es. lo stesso
  // pagamento copre anche un altro corso frequentato dalla stessa persona)
  const [corsiExtra, setCorsiExtra] = useState(accontoEsistente?.corsi_extra_ids || []);
  const [ricercaCorsoAperta, setRicercaCorsoAperta] = useState(false);
  const [testoRicercaCorso, setTestoRicercaCorso] = useState("");

  const corsoById = useMemo(() => Object.fromEntries((corsi || []).map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries((location || []).map((l) => [l.id, l])), [location]);
  function etichettaCorsoData(cdId) {
    const cd = (corsiDate || []).find((x) => x.id === cdId);
    if (!cd) return "?";
    const corso = corsoById[cd.corso_id];
    const loc = locById[cd.location_id];
    return `${corso?.nome?.toUpperCase() || "?"} — ${loc?.nome?.toUpperCase() || "?"} — ${fmtDataCompatta(cd.data_inizio, cd.data_fine)}`;
  }
  // la ricerca è per allievo (di solito si cerca "questa stessa persona,
  // che altro corso ha fatto"), ma trova anche per città/corso/data:
  // ogni ISCRITTO (non ogni corso) è un risultato possibile, così iscritti
  // diversi con lo stesso corso restano distinguibili nell'elenco
  const risultatiRicercaCorso = useMemo(() => {
    if (!ricercaCorsoAperta) return [];
    const q = testoRicercaCorso.trim().toLowerCase();
    return (iscritti || [])
      .filter((i) => i.id !== iscritto.id && i.corso_data_id !== iscritto.corso_data_id && !corsiExtra.includes(i.corso_data_id))
      .map((i) => ({ id: i.id, cd: { id: i.corso_data_id }, etichetta: `${i.nome} ${i.cognome} — ${etichettaCorsoData(i.corso_data_id)}` }))
      .filter(({ etichetta }) => !q || etichetta.toLowerCase().includes(q))
      .slice(0, 30);
  }, [ricercaCorsoAperta, testoRicercaCorso, iscritti, corsiExtra, iscritto.id, iscritto.corso_data_id]);

  function aggiungiCorsoExtra(cdId) {
    setCorsiExtra((prev) => [...prev, cdId]);
    setRicercaCorsoAperta(false);
    setTestoRicercaCorso("");
  }
  function rimuoviCorsoExtra(cdId) {
    setCorsiExtra((prev) => prev.filter((id) => id !== cdId));
  }

  function toggleVoce(chiave) {
    setVociPagamento((prev) => (prev.includes(chiave) ? prev.filter((v) => v !== chiave) : [...prev, chiave]));
  }

  async function invia() {
    if (!nota.trim() && !file && valori.totale === "" && !inModifica) return;
    setInviando(true);
    let filePath = accontoEsistente?.file_path || null;
    if (file) {
      const percorso = `acconti/${iscritto.id}-${Date.now()}-${sanitizzaNomeFile(file.name)}`;
      const { error: erroreUpload } = await supabase.storage.from("allegati-iscritti").upload(percorso, file);
      if (erroreUpload) { setInviando(false); window.alert("Errore nel caricamento del file: " + erroreUpload.message); return; }
      filePath = percorso;
    }
    const payload = {
      data_pagamento: dataPagamento || null,
      voci_pagamento: vociPagamento.length > 0 ? vociPagamento : null,
      imponibile: valori.imponibile === "" ? null : parseNum(valori.imponibile),
      importo: valori.totale === "" ? null : parseNum(valori.totale),
      metodo: valori.metodo || null,
      nota: nota.trim() || null,
      file_path: filePath,
      corsi_extra_ids: corsiExtra.length > 0 ? corsiExtra : null,
    };
    const { error } = inModifica
      ? await supabase.from("acconti_da_verificare").update(payload).eq("id", accontoEsistente.id)
      : await supabase.from("acconti_da_verificare").insert({ ...payload, iscritto_id: iscritto.id, venditore_nome: venditoreNome, origine: "manuale" });
    setInviando(false);
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["acconti_da_verificare"]);
    if (onInviato) onInviato(iscritto.id);
    else onChiudi();
  }
  return (
    <Modal title={`${inModifica ? "Modifica" : "Aggiungi"} pagamento — ${iscritto.nome} ${iscritto.cognome}`} onClose={onChiudi} paddingTop={100}>
      <div style={{ height: 18 }} />
      <Field label="Data pagamento">
        <input type="date" style={inputStyle} value={dataPagamento} onChange={(e) => setDataPagamento(e.target.value)} />
      </Field>
      <div style={{ display: "flex", gap: 24, margin: "14px 2px 20px" }}>
        {VOCI_PAGAMENTO_VENDITORE.map((v) => (
          <label key={v.chiave} style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", ...fontBody, fontSize: 14, color: NAVY }}>
            <input type="checkbox" checked={vociPagamento.includes(v.chiave)} onChange={() => toggleVoce(v.chiave)} style={{ width: 16, height: 16 }} />
            {v.etichetta}
          </label>
        ))}
      </div>
      <div style={{ height: 8 }} />
      <BloccoQuota
        titolo="Importo pagamento"
        valori={valori}
        opzioniMetodo={["Sito", "Bonifico", "Pos", "Contanti"]}
        onImponibile={(v) => setValori((prev) => conImponibileAggiornato(prev, v, true))}
        onTotale={(v) => setValori((prev) => conTotaleAggiornato(prev, v, true))}
        onMetodo={(v) => setValori((prev) => conMetodoAggiornato(prev, v))}
        onInteressi={(v) => setValori((prev) => ({ ...prev, interessi: v }))}
      />
      <Field label="File di pagamento">
        {accontoEsistente?.file_path && !file && (
          <div style={{ marginBottom: 6, ...fontBody, fontSize: 12.5, color: MUTED }}>
            Attuale: <AllegatoLink percorso={accontoEsistente.file_path} etichetta="apri il file" /> — scegline uno nuovo per sostituirlo
          </div>
        )}
        <CampoFileTrascinabile accept="application/pdf,image/*" style={inputStyle} onChange={(e) => setFile(e.target.files?.[0] || null)} />
      </Field>
      <Field label="Nota">
        <textarea
          style={{ ...inputStyle, minHeight: 80, resize: "vertical" }}
          value={nota} onChange={(e) => setNota(e.target.value)}
          placeholder="Scrivi qui i dettagli del pagamento…"
        />
      </Field>
      <Field label="Associa altri corsi">
        <div style={{ border: `1px solid ${CREAM_BORDER}`, borderRadius: 10, padding: 10 }}>
          <div style={{ ...fontBody, fontSize: 13.5, fontWeight: 600, color: NAVY, padding: "4px 2px" }}>
            {etichettaCorsoData(iscritto.corso_data_id)}
          </div>
          {corsiExtra.map((cdId) => (
            <div key={cdId} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, padding: "4px 2px" }}>
              <span style={{ ...fontBody, fontSize: 13.5, color: NAVY }}>{etichettaCorsoData(cdId)}</span>
              <button type="button" onClick={() => rimuoviCorsoExtra(cdId)} title="Rimuovi" style={{ border: "none", background: "none", cursor: "pointer", color: "#C0392B", padding: 2, display: "flex" }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6L6 18" /><path d="M6 6l12 12" /></svg>
              </button>
            </div>
          ))}
          <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", ...fontBody, fontSize: 13.5, color: NAVY, padding: "6px 2px 2px" }}>
            <input type="checkbox" checked={ricercaCorsoAperta} onChange={(e) => { setRicercaCorsoAperta(e.target.checked); setTestoRicercaCorso(""); }} style={{ width: 16, height: 16 }} />
            Associa altro corso
          </label>
          {ricercaCorsoAperta && (
            <div style={{ marginTop: 6 }}>
              <CampoRicerca value={testoRicercaCorso} onChange={(e) => setTestoRicercaCorso(e.target.value)} placeholder="Cerca allievo, città, corso, data…" />
              <div style={{ maxHeight: 160, overflowY: "auto", marginTop: 6, border: risultatiRicercaCorso.length > 0 ? `1px solid ${CREAM_BORDER}` : "none", borderRadius: 8 }}>
                {risultatiRicercaCorso.map(({ id, cd, etichetta }) => (
                  <button
                    key={id} type="button" onClick={() => aggiungiCorsoExtra(cd.id)}
                    style={{ display: "block", width: "100%", textAlign: "left", background: "none", border: "none", borderBottom: `1px solid ${CREAM_BORDER}`, cursor: "pointer", padding: "8px 10px", ...fontBody, fontSize: 13, color: NAVY }}
                  >
                    {etichetta}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </Field>
      <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
        <Button onClick={invia} disabled={inviando || (!inModifica && !nota.trim() && !file && valori.totale === "")}>{inviando ? "Salvo…" : inModifica ? "Salva" : "Invia"}</Button>
        <Button variant="ghost" onClick={onChiudi}>Annulla</Button>
      </div>
    </Modal>
  );
}
// card rossa "Integrazione da approvare" dentro la scheda di un iscritto:
// stessa card Imponibile/IVA/Totale/metodo di una quota, ma senza mai
// scrivere direttamente sull'iscritto — è "onContabilizza" (in SchedaData,
// dove vive lo stato di acconto_extra/precorso_extra) a decidere dove far
// finire la riga quando l'amministratore preme "Contabilizza"
// la prima riga (Imponibile/IVA/Totale/metodo) mostra sempre l'importo
// ORIGINALE della segnalazione, mai il residuo: non scende mai con le
// contabilizzazioni parziali, resta un riferimento fisso. Solo "metodo" si
// azzera a ogni contabilizzazione (va scelto di nuovo, può cambiare da un
// giro all'altro)
function rigaOriginale(integrazione, metodo) {
  return {
    imponibile: integrazione.imponibile != null ? String(integrazione.imponibile) : "",
    totale: integrazione.importo != null ? String(integrazione.importo) : "",
    metodo: metodo || "",
    interessi: "",
  };
}
function BloccoIntegrazioneDaApprovare({ integrazione, onContabilizza, ricarica }) {
  const [valori, setValori] = useState(() => rigaOriginale(integrazione, integrazione.metodo));
  const [destinazione, setDestinazione] = useState(() => {
    const voci = integrazione.voci_pagamento || [];
    return voci.length === 1 && VOCI_PAGAMENTO_VENDITORE.some((v) => v.chiave === voci[0]) ? voci[0] : "";
  });
  // quota (in imponibile) di questa riga che si vuole contabilizzare adesso
  // in questa scheda: il resto rimane come residuo condiviso, così una
  // stessa segnalazione può essere spalmata su più corsi associati
  const [quotaDaContabilizzare, setQuotaDaContabilizzare] = useState("");
  const [contabilizzando, setContabilizzando] = useState(false);
  const residuoIniziale = integrazione.importo_residuo != null ? integrazione.importo_residuo : integrazione.importo;
  // dopo una contabilizzazione parziale il residuo scende (da qualunque
  // corso sia stata fatta): quando cambia si azzerano solo destinazione e
  // quota, non il metodo — quello lo ha già dichiarato il venditore
  // segnalando il pagamento (Sito/Bonifico/Pos/...), non è mai una scelta
  // dell'amministratore, resta fisso per tutta la vita di questa
  // segnalazione, così come l'imponibile/totale mostrati in alto
  const residuoRef = useRef(residuoIniziale);
  useEffect(() => {
    const nuovoResiduo = integrazione.importo_residuo != null ? integrazione.importo_residuo : integrazione.importo;
    if (nuovoResiduo !== residuoRef.current) {
      residuoRef.current = nuovoResiduo;
      setDestinazione("");
      setQuotaDaContabilizzare("");
    }
  }, [integrazione.importo_residuo, integrazione.importo]);

  const imponibileIniziale = parseNum(valori.imponibile);
  const residuoAttuale = integrazione.importo_residuo != null ? integrazione.importo_residuo : integrazione.importo;
  const residuoImponibile = round2(parseNum(residuoAttuale) / 1.22);
  const giaContabilizzato = round2(imponibileIniziale - residuoImponibile);

  const quotaNum = quotaDaContabilizzare === "" ? 0 : parseNum(quotaDaContabilizzare);
  const quotaNonValida = quotaDaContabilizzare !== "" && (quotaNum <= 0 || quotaNum > residuoImponibile);
  const restanoDaCont = round2(residuoImponibile - quotaNum);

  // azzera ogni contabilizzazione parziale fatta finora su questa
  // segnalazione, riportando il residuo all'importo pieno originale:
  // serve soprattutto per le righe contabilizzate prima che esistesse il
  // collegamento automatico (eliminandole oggi il credito non torna da
  // solo, perché non hanno il riferimento per sapere da dove ripristinarlo)
  async function resetResiduo() {
    if (!window.confirm("Sei sicuro di voler ricominciare? Tutto quello che risulta già contabilizzato tornerà disponibile.")) return;
    const { error } = await supabase.from("acconti_da_verificare").update({ importo_residuo: integrazione.importo }).eq("id", integrazione.id);
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["acconti_da_verificare"]);
  }

  async function contabilizza() {
    if (!destinazione || quotaNonValida) return;
    // se non si scrive nessuna quota parziale, "Contabilizza" svuota tutto
    // il residuo rimasto — mai l'imponibile originale, che potrebbe essere
    // già stato in parte contabilizzato altrove
    const imponibileDaUsare = quotaDaContabilizzare !== "" ? quotaNum : residuoImponibile;
    if (imponibileDaUsare <= 0) return;
    const valoriEffettivi = { ...valori, imponibile: String(imponibileDaUsare), totale: String(round2(imponibileDaUsare * 1.22)) };
    setContabilizzando(true);
    // se lo staff sta contabilizzando qui è perché ha già verificato che
    // la somma è stata ricevuta: non serve una spunta "Da pagare/Pagato",
    // è sempre pagato
    await onContabilizza({ integrazione, valori: valoriEffettivi, pagato: true, destinazione });
    setContabilizzando(false);
  }

  return (
    <div style={{ border: "1.5px solid #C0392B", borderRadius: 10, padding: 14, marginBottom: 10 }}>
      <div style={{ ...fontDisplay, fontSize: 15, fontWeight: 700, color: "#C0392B", marginBottom: integrazione.file_path ? 4 : 10 }}>Integrazione da approvare</div>
      {integrazione.file_path && (
        <div style={{ marginBottom: 10 }}>
          <AllegatoLink percorso={integrazione.file_path} etichetta="vedi file allegato" />
        </div>
      )}
      <BloccoQuota
        titolo=""
        valori={valori}
        imponibileBloccato
        totaleBloccato
      />
      {valori.metodo && (
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: -4, marginBottom: 10 }}>
          <span style={{ ...fontBody, fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.4 }}>Pagamento segnalato come</span>
          <span style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, background: BG, border: `1px solid ${CREAM_BORDER}`, borderRadius: 20, padding: "2px 10px" }}>{valori.metodo}</span>
        </div>
      )}
      <div style={{ display: "flex", alignItems: "flex-end", gap: 24, flexWrap: "wrap", marginTop: 4 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 24, flexWrap: "wrap" }}>
          {VOCI_PAGAMENTO_VENDITORE.map((v) => (
            <label key={v.chiave} style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", ...fontBody, fontSize: 14, color: NAVY }}>
              <input type="checkbox" checked={destinazione === v.chiave} onChange={() => setDestinazione((prev) => (prev === v.chiave ? "" : v.chiave))} style={{ width: 16, height: 16 }} />
              {v.etichetta}
            </label>
          ))}
        </div>
        <div style={{ marginLeft: "auto", display: "flex", alignItems: "flex-end", gap: 10, flexWrap: "wrap" }}>
          <div style={{ width: 100 }}>
            <Field label="Totale iniziale">
              <input style={{ ...inputStyle, background: "#EFEFEF", color: MUTED }} value={imponibileIniziale.toFixed(2)} disabled />
            </Field>
          </div>
          <div style={{ width: 100 }}>
            <Field label="Totale già cont.">
              <input style={{ ...inputStyle, background: "#EFEFEF", color: MUTED }} value={giaContabilizzato.toFixed(2)} disabled />
            </Field>
          </div>
          <div style={{ width: 100 }}>
            <Field label="Quota da cont.">
              <input
                style={{ ...inputStyle, border: quotaNonValida ? "1px solid #C0392B" : inputStyle.border }}
                inputMode="decimal"
                value={quotaDaContabilizzare}
                onChange={(e) => setQuotaDaContabilizzare(e.target.value)}
              />
            </Field>
          </div>
          <div style={{ width: 100 }}>
            <Field label="Restano da cont.">
              <input style={{ ...inputStyle, background: "#EFEFEF", color: MUTED }} value={(quotaDaContabilizzare === "" ? residuoImponibile : restanoDaCont).toFixed(2)} disabled />
            </Field>
          </div>
          <Button onClick={contabilizza} disabled={!destinazione || quotaNonValida || contabilizzando}>
            {contabilizzando ? "…" : "Contabilizza"}
          </Button>
        </div>
      </div>
      {quotaNonValida && (
        <div style={{ ...fontBody, fontSize: 12, color: "#C0392B", marginTop: 6, textAlign: "right" }}>
          La quota da contabilizzare non può superare quanto resta da contabilizzare ({fmtEuroErp(residuoImponibile)}).
        </div>
      )}
      {!destinazione && (
        <div style={{ ...fontBody, fontSize: 12, color: "#C0392B", marginTop: 6, textAlign: "right" }}>
          Seleziona a cosa si riferisce questo pagamento (Acconto/Quota pre corso/Saldo) — si azzera a ogni contabilizzazione fatta anche da un'altra scheda associata, va scelto di nuovo.
        </div>
      )}
      {giaContabilizzato > 0 && (
        <div style={{ textAlign: "right", marginTop: 8 }}>
          <button
            type="button"
            onClick={resetResiduo}
            title="Annulla ogni contabilizzazione parziale fatta finora su questa segnalazione"
            style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: "#C0392B", background: "none", border: "none", cursor: "pointer", textDecoration: "underline", padding: 0 }}
          >
            Reset — annulla il contabilizzato e riparti da zero
          </button>
        </div>
      )}
    </div>
  );
}
function LeTueIscrizioni({ corsi, location, corsiDate, iscritti, venditoreNome, onApriIscritto, ricarica }) {
  const corsoById = useMemo(() => Object.fromEntries(corsi.map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries(location.map((l) => [l.id, l])), [location]);
  const cdById = useMemo(() => Object.fromEntries(corsiDate.map((cd) => [cd.id, cd])), [corsiDate]);
  const [ricerca, setRicerca] = useState("");
  const [pagamentoPer, setPagamentoPer] = useState(null); // iscritto per cui è aperta "Aggiungi pagamento", o null
  const [inviatoPerId, setInviatoPerId] = useState(null); // id dell'iscritto appena inviato, per la spunta sulla riga
  // colonna: null = ordine di default (dall'iscrizione più recente, in
  // cima, alla più vecchia, in fondo); altrimenti quale colonna e in che
  // verso, alternato a ogni click sulla stessa intestazione
  const [ordinamento, setOrdinamento] = useState({ colonna: null, direzione: "asc" });

  const righe = iscritti
    .filter((i) => i.ts && i.tutor === venditoreNome)
    .map((i) => {
      const cd = cdById[i.corso_data_id];
      const corso = cd ? corsoById[cd.corso_id] : null;
      const loc = cd ? locById[cd.location_id] : null;
      return {
        iscritto: i,
        citta: loc?.nome?.toUpperCase() || "?",
        corsoNome: corso?.nome?.toUpperCase() || "?",
        dataIso: cd?.data_inizio || "",
        dataLabel: cd ? fmtDataCompatta(cd.data_inizio, cd.data_fine) : "—",
        allievo: `${i.nome} ${i.cognome}`,
      };
    });

  const termini = ricerca.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const filtrate = termini.length === 0 ? righe : righe.filter((r) => {
    const testo = [r.citta, r.corsoNome, r.dataLabel, r.allievo].join(" ").toLowerCase();
    return termini.every((t) => testo.includes(t));
  });

  const ordinate = filtrate.slice().sort((a, b) => {
    if (!ordinamento.colonna) return b.iscritto.ts.localeCompare(a.iscritto.ts);
    let cmp = 0;
    if (ordinamento.colonna === "citta") cmp = a.citta.localeCompare(b.citta);
    else if (ordinamento.colonna === "corso") cmp = a.corsoNome.localeCompare(b.corsoNome);
    else if (ordinamento.colonna === "data") cmp = a.dataIso.localeCompare(b.dataIso);
    else if (ordinamento.colonna === "allievo") cmp = a.allievo.localeCompare(b.allievo);
    return ordinamento.direzione === "asc" ? cmp : -cmp;
  });

  function cambiaOrdinamento(colonna) {
    setOrdinamento((prev) => (prev.colonna === colonna ? { colonna, direzione: prev.direzione === "asc" ? "desc" : "asc" } : { colonna, direzione: "asc" }));
  }

  const bordoV = `1px solid ${CREAM_BORDER}`;
  const celStyle = { padding: "8px 12px", borderBottom: bordoV, borderRight: bordoV };
  function stileTh(colonna, ultima) {
    const attiva = ordinamento.colonna === colonna;
    return { ...celStyle, ...fontBody, fontSize: 11, fontWeight: 600, color: attiva ? NAVY : MUTED, textTransform: "uppercase", letterSpacing: 0.5, textAlign: "left", background: BG, borderRight: ultima ? "none" : bordoV, cursor: "pointer", userSelect: "none" };
  }
  function frecciaOrdinamento(colonna) {
    return ordinamento.colonna === colonna ? (ordinamento.direzione === "asc" ? " ▲" : " ▼") : "";
  }

  return (
    <div>
      <CampoRicerca value={ricerca} onChange={(e) => setRicerca(e.target.value)} placeholder="Cerca città, corso, allievo…" style={{ marginBottom: 12 }} />
      {ordinate.length === 0 ? (
        <div style={{ ...cardStyle, textAlign: "center", padding: 40, color: MUTED, ...fontBody, fontSize: 14 }}>
          {righe.length === 0 ? "Nessuna iscrizione ancora." : "Nessun risultato."}
        </div>
      ) : (
        <div style={{ overflowX: "auto", background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 12 }}>
          <table style={{ borderCollapse: "collapse", width: "100%" }}>
            <thead>
              <tr>
                <th onClick={() => cambiaOrdinamento("citta")} style={stileTh("citta")}>Città{frecciaOrdinamento("citta")}</th>
                <th onClick={() => cambiaOrdinamento("corso")} style={stileTh("corso")}>Corso{frecciaOrdinamento("corso")}</th>
                <th onClick={() => cambiaOrdinamento("data")} style={stileTh("data")}>Data del corso{frecciaOrdinamento("data")}</th>
                <th onClick={() => cambiaOrdinamento("allievo")} style={stileTh("allievo")}>Allievo{frecciaOrdinamento("allievo")}</th>
                <th style={{ ...stileTh(null, true), cursor: "default" }}></th>
              </tr>
            </thead>
            <tbody>
              {ordinate.map((r) => (
                <tr key={r.iscritto.id} onClick={onApriIscritto ? () => onApriIscritto(r.iscritto) : undefined} style={{ cursor: onApriIscritto ? "pointer" : undefined }}>
                  <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, whiteSpace: "nowrap" }}>{r.citta}</td>
                  <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, whiteSpace: "nowrap" }}>{r.corsoNome}</td>
                  <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, whiteSpace: "nowrap" }}>{r.dataLabel}</td>
                  <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, fontWeight: 600 }}>{r.allievo}</td>
                  <td style={{ ...celStyle, borderRight: "none", whiteSpace: "nowrap" }}>
                    {inviatoPerId === r.iscritto.id ? (
                      <span style={{ ...fontBody, fontSize: 12.5, color: "#2E7D32", fontWeight: 600 }}>Inviato ✓</span>
                    ) : (
                      <button
                        type="button"
                        onClick={(e) => { e.stopPropagation(); setPagamentoPer(r.iscritto); }}
                        style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: NAVY, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 20, padding: "6px 12px", cursor: "pointer" }}
                      >
                        Aggiungi Pagamento
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {pagamentoPer && (
        <ModalePagamentoVenditore
          iscritto={pagamentoPer} venditoreNome={venditoreNome} ricarica={ricarica}
          corsi={corsi} corsiDate={corsiDate} location={location} iscritti={iscritti}
          onChiudi={() => setPagamentoPer(null)}
          onInviato={(id) => { setInviatoPerId(id); setPagamentoPer(null); }}
        />
      )}
    </div>
  );
}
// titolo del gruppo in "Verifica Pagamenti": "Integrazione" per i pagamenti
// segnalati a mano da "Aggiungi Pagamento" su un allievo già iscritto,
// "Bonifico iscrizione" per quelli creati in automatico dal modulo di
// iscrizione (quando si iscrive un allievo la prima volta)
const TITOLO_GRUPPO_ORIGINE = { manuale: "Integrazione", bonifico_modulo: "Bonifico iscrizione" };
// un pagamento "Integrazione" può essere associato a più corsi (stessa
// persona, iscrizioni diverse): non esiste un id "persona" univoco
// nell'app, quindi la stessa persona in un altro corso si ritrova per
// nome+cognome — approccio semplice ma sufficiente per questo caso d'uso
function trovaIscrittoStessaPersona(iscritti, personaRif, corsoDataId) {
  if (!personaRif) return null;
  return iscritti.find((i) => i.corso_data_id === corsoDataId && i.nome === personaRif.nome && i.cognome === personaRif.cognome) || null;
}
// coda "Verifica Pagamenti" (Gestione corsi): raccoglie sia le
// segnalazioni manuali dei venditori ("Aggiungi Pagamento" su "Le tue
// iscrizioni", origine "manuale") sia — quando esisterà — quelle create
// in automatico dal modulo di iscrizione quando si sceglie Bonifico come
// metodo (origine "bonifico_modulo"). L'approvazione avviene qui stesso,
// riga per riga: non serve più aprire la scheda dell'iscritto
function PaginaVerificaAcconti({ corsi, location, corsiDate, iscritti, accontiDaVerificare, onApriIscritto, onApriSchedeAffiancate, ricarica, onBack }) {
  const isMobile = useIsMobile();
  const { ordine, cambiaOrdine, ordina } = useOrdinamentoTabella();
  const isPortrait = useIsPortrait();
  // telefono in verticale: la tabella (tante colonne) diventa illeggibile,
  // quindi ogni pagamento si mostra come scheda con i campi disposti su due
  // colonne. In orizzontale (o su desktop) resta la tabella su una riga.
  const schedaVerticale = isMobile && isPortrait;
  const [tab, setTab] = useState("attesa"); // attesa | verificati
  const [approvandoId, setApprovandoId] = useState(null);
  const [modificaAcconto, setModificaAcconto] = useState(null); // riga acconti_da_verificare in modifica, o null
  const corsoById = useMemo(() => Object.fromEntries(corsi.map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries(location.map((l) => [l.id, l])), [location]);
  const cdById = useMemo(() => Object.fromEntries(corsiDate.map((cd) => [cd.id, cd])), [corsiDate]);
  const iscrittoById = useMemo(() => Object.fromEntries(iscritti.map((i) => [i.id, i])), [iscritti]);

  const righe = accontiDaVerificare.filter((a) => (tab === "attesa" ? a.stato === "in_attesa" : a.stato === "approvato"));

  async function approva(a) {
    setApprovandoId(a.id);
    const { error } = await supabase.from("acconti_da_verificare").update({ stato: "approvato", approvato_il: new Date().toISOString() }).eq("id", a.id);
    setApprovandoId(null);
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["acconti_da_verificare"]);
  }

  async function eliminaAcconto(a) {
    if (!window.confirm("Eliminare definitivamente questa segnalazione di pagamento?")) return;
    const { error } = await supabase.from("acconti_da_verificare").delete().eq("id", a.id);
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["acconti_da_verificare"]);
  }

  const bordoV = `1px solid ${CREAM_BORDER}`;
  const celStyle = { padding: "5px 6px", borderBottom: bordoV, borderRight: bordoV, verticalAlign: "middle" };
  const thStyle = { ...celStyle, ...fontBody, fontSize: 8.5, fontWeight: 600, color: MUTED, textTransform: "uppercase", letterSpacing: 0.1, textAlign: "left", background: BG };

  return (
    <div style={{ maxWidth: 1320, margin: "0 auto", padding: "40px 20px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 14, flexWrap: "wrap" }}>
        <TastoLivelloPrecedente titolo="Gestione corsi" onClick={onBack} />
        <div style={{ ...fontDisplay, fontSize: 26, color: NAVY, textTransform: "uppercase" }}>Verifica Pagamenti</div>
      </div>
      <div style={{ display: "flex", gap: 6, marginBottom: 18 }}>
        <TabPillola attivo={tab === "attesa"} onClick={() => setTab("attesa")}>Da verificare ({accontiDaVerificare.filter((a) => a.stato === "in_attesa").length})</TabPillola>
        <TabPillola attivo={tab === "verificati"} onClick={() => setTab("verificati")}>Pagamenti verificati</TabPillola>
      </div>

      {righe.length === 0 ? (
        <div style={{ ...cardStyle, textAlign: "center", padding: 40, color: MUTED, ...fontBody, fontSize: 14 }}>
          {tab === "attesa" ? "Niente da verificare." : "Nessun pagamento verificato ancora."}
        </div>
      ) : (() => {
        // le righe si dividono prima per giorno di inserimento (ts), dal
        // più recente al più vecchio, con un'intestazione centrata sopra
        // ciascun gruppo — stesso linguaggio già usato in "Ultime
        // iscrizioni". Dentro ogni giorno, restano raggruppate per origine
        // (Integrazione prima, Bonifico iscrizione poi) e rese contigue,
        // così l'etichetta del gruppo può stare come prima colonna della
        // stessa tabella con un rowSpan invece di essere una tabella
        // separata a fianco
        const chiaviData = Array.from(new Set(righe.map((a) => (a.ts || "").slice(0, 10)).filter(Boolean))).sort((a, b) => b.localeCompare(a));
        const gruppoStyle = { ...fontDisplay, fontSize: 10, fontWeight: 700, color: "#C0392B", textTransform: "uppercase", letterSpacing: 0.2 };

        // la stessa persona può risultare iscritta a più date ("Associa altri
        // corsi"): ogni corso associato si ritrova per nome+cognome
        const calcolaCoinvolti = (a) => {
          const iscrittoPrincipale = iscrittoById[a.iscritto_id];
          return [
            { iscritto: iscrittoPrincipale, corsoDataId: iscrittoPrincipale?.corso_data_id },
            ...((a.corsi_extra_ids || []).map((cdId) => ({ iscritto: trovaIscrittoStessaPersona(iscritti, iscrittoPrincipale, cdId), corsoDataId: cdId }))),
          ].map(({ iscritto, corsoDataId }) => {
            const cd = corsoDataId ? cdById[corsoDataId] : null;
            const corso = cd ? corsoById[cd.corso_id] : null;
            const loc = cd ? locById[cd.location_id] : null;
            return { iscritto, cd, corso, loc };
          });
        };

        // l'ordinamento agisce dentro ciascun gruppo (Acconti, Saldi…):
        // i gruppi restano al loro posto, cambia l'ordine delle loro righe.
        // Il primo dei "coinvolti" è quello mostrato in cima alla cella
        const valoriAcconti = {
          citta: (a) => calcolaCoinvolti(a)[0]?.loc?.nome || "",
          corso: (a) => calcolaCoinvolti(a)[0]?.corso?.nome || "",
          dataCorso: (a) => calcolaCoinvolti(a)[0]?.cd?.data_inizio || "",
          allievo: (a) => { const i = calcolaCoinvolti(a)[0]?.iscritto; return i ? `${i.cognome || ""} ${i.nome || ""}`.trim() : ""; },
          venditore: (a) => a.venditore_nome || "",
          dataPag: (a) => a.data_pagamento || "",
          importo: (a) => a.importo ?? null,
          metodo: (a) => a.metodo || "",
        };

        const azioniRiga = (a) => tab === "attesa" && (
          <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
            <button onClick={() => approva(a)} disabled={approvandoId === a.id} style={{ ...fontBody, fontSize: 15, fontWeight: 700, color: "#fff", background: NAVY, border: "none", borderRadius: 24, padding: "12px 28px", cursor: approvandoId === a.id ? "default" : "pointer" }}>
              {approvandoId === a.id ? "…" : "Approva"}
            </button>
            <button onClick={() => setModificaAcconto(a)} title="Modifica" style={{ border: `1px solid ${CREAM_BORDER}`, background: "#fff", cursor: "pointer", color: NAVY, padding: 10, borderRadius: 12, display: "flex", alignItems: "center" }}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">{ICONA_MATITA_PATH}</svg>
            </button>
            <button onClick={() => eliminaAcconto(a)} title="Elimina" style={{ border: `1px solid ${CREAM_BORDER}`, background: "#fff", cursor: "pointer", color: "#C0392B", padding: 10, borderRadius: 12, display: "flex", alignItems: "center" }}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">{ICONA_CESTINO_PATH}</svg>
            </button>
          </div>
        );

        const tabellaGiorno = (righeGiorno) => {
          const gruppi = Object.keys(TITOLO_GRUPPO_ORIGINE)
            .map((origine) => ({ origine, righe: righeGiorno.filter((a) => (a.origine || "manuale") === origine) }))
            .filter((g) => g.righe.length > 0);

          // telefono in verticale: ogni pagamento diventa una scheda con i
          // campi su due colonne, così niente resta tagliato
          if (schedaVerticale) {
            const campoCard = (label, valore, full) => (
              <div style={{ gridColumn: full ? "1 / -1" : "auto", minWidth: 0 }}>
                <div style={{ ...fontBody, fontSize: 9, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.3, marginBottom: 2 }}>{label}</div>
                <div style={{ ...fontBody, fontSize: 12.5, color: NAVY, wordBreak: "break-word" }}>{valore}</div>
              </div>
            );
            const valoreCoinvolti = (coinvolti, render) => coinvolti.map((co, i) => (
              <div key={i} onClick={() => co.iscritto && onApriIscritto?.(co.iscritto)} style={{ cursor: co.iscritto ? "pointer" : undefined, marginTop: i === 0 ? 0 : 2 }}>{render(co)}</div>
            ));
            return (
              <div>
                {gruppi.map((g) => g.righe.map((a) => {
                  const coinvolti = calcolaCoinvolti(a);
                  return (
                    <div key={a.id} style={{ background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 12, padding: 12, marginBottom: 10 }}>
                      <div style={{ ...gruppoStyle, marginBottom: 8 }}>{TITOLO_GRUPPO_ORIGINE[g.origine]}</div>
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "9px 12px" }}>
                        {campoCard("Allievo", valoreCoinvolti(coinvolti, (co) => (co.iscritto ? <b>{co.iscritto.nome} {co.iscritto.cognome}</b> : "—")))}
                        {campoCard("Venditore", a.venditore_nome || "—")}
                        {campoCard("Città", valoreCoinvolti(coinvolti, (co) => co.loc?.nome?.toUpperCase() || "?"))}
                        {campoCard("Corso", valoreCoinvolti(coinvolti, (co) => co.corso?.nome?.toUpperCase() || "?"))}
                        {campoCard("Data corso", valoreCoinvolti(coinvolti, (co) => (co.cd ? fmtDataCompatta(co.cd.data_inizio, co.cd.data_fine) : "—")))}
                        {campoCard("Data pag.", a.data_pagamento ? fmtData(a.data_pagamento) : "—")}
                        {campoCard("Importo", a.importo != null ? fmtEuroErp(a.importo) : "—")}
                        {campoCard("Metodo", a.metodo || "—")}
                        {campoCard("Nota", a.nota || "—", true)}
                        {campoCard("File", a.file_path ? <AllegatoLink percorso={a.file_path} etichetta="apri il file" style={{ fontSize: 15, fontWeight: 600, display: "inline-block", padding: "4px 0" }} /> : "—", true)}
                      </div>
                      {tab === "attesa" && <div style={{ marginTop: 12 }}>{azioniRiga(a)}</div>}
                    </div>
                  );
                }))}
              </div>
            );
          }

          return (
            <div style={{ background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 12 }}>
              <table style={{ borderCollapse: "collapse", width: "100%", tableLayout: "fixed" }}>
                <thead>
                  <tr>
                    <th style={{ ...thStyle, width: "9%" }}>Tipologia</th>
                    <ThOrdina campo="citta" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, width: "7%" }}>Città</ThOrdina>
                    <ThOrdina campo="corso" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, width: "9%" }}>Corso</ThOrdina>
                    <ThOrdina campo="dataCorso" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, width: "7%" }}>Data corso</ThOrdina>
                    <ThOrdina campo="allievo" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, width: "12%" }}>Allievo</ThOrdina>
                    <ThOrdina campo="venditore" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, width: "7%" }}>Venditore</ThOrdina>
                    <ThOrdina campo="dataPag" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, width: "6%" }}>Data pag.</ThOrdina>
                    <ThOrdina campo="importo" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, width: "6%" }}>Importo</ThOrdina>
                    <ThOrdina campo="metodo" ordine={ordine} onOrdina={cambiaOrdine} style={{ ...thStyle, width: "6%" }}>Metodo</ThOrdina>
                    <th style={{ ...thStyle, width: "8%" }}>Nota</th>
                    <th style={{ ...thStyle, width: "4%" }}>File</th>
                    <th style={{ ...thStyle, width: "19%", borderRight: "none" }}></th>
                  </tr>
                </thead>
                <tbody>
                  {gruppi.map((g) => ordina(g.righe, valoriAcconti).map((a, idx) => {
                  const coinvolti = calcolaCoinvolti(a);
                  const celStackStyle = { ...celStyle, ...fontBody, fontSize: 10, color: NAVY };
                  return (
                    <tr key={a.id}>
                      {idx === 0 && <td rowSpan={g.righe.length} style={{ ...celStyle, ...gruppoStyle }}>{TITOLO_GRUPPO_ORIGINE[g.origine]}</td>}
                      <td style={{ ...celStackStyle, padding: 0 }}>
                        {coinvolti.map((co, i) => (
                          <div key={i} onClick={() => co.iscritto && onApriIscritto?.(co.iscritto)} style={{ padding: "5px 7px", borderTop: i === 0 ? "none" : bordoV, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", cursor: co.iscritto ? "pointer" : undefined }}>
                            {co.loc?.nome?.toUpperCase() || "?"}
                          </div>
                        ))}
                      </td>
                      <td style={{ ...celStackStyle, padding: 0 }}>
                        {coinvolti.map((co, i) => (
                          <div key={i} onClick={() => co.iscritto && onApriIscritto?.(co.iscritto)} style={{ padding: "5px 7px", borderTop: i === 0 ? "none" : bordoV, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", cursor: co.iscritto ? "pointer" : undefined }}>
                            {co.corso?.nome?.toUpperCase() || "?"}
                          </div>
                        ))}
                      </td>
                      <td style={{ ...celStackStyle, padding: 0 }}>
                        {coinvolti.map((co, i) => (
                          <div key={i} onClick={() => co.iscritto && onApriIscritto?.(co.iscritto)} style={{ padding: "5px 7px", borderTop: i === 0 ? "none" : bordoV, whiteSpace: "nowrap", cursor: co.iscritto ? "pointer" : undefined }}>
                            {co.cd ? fmtDataCompatta(co.cd.data_inizio, co.cd.data_fine) : "—"}
                          </div>
                        ))}
                      </td>
                      <td style={{ ...celStackStyle, fontWeight: 600, padding: 0 }}>
                        {coinvolti.map((co, i) => (
                          <div key={i} onClick={() => co.iscritto && onApriIscritto?.(co.iscritto)} style={{ padding: "5px 7px", borderTop: i === 0 ? "none" : bordoV, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", cursor: co.iscritto ? "pointer" : undefined }}>
                            {co.iscritto ? `${co.iscritto.nome} ${co.iscritto.cognome}` : "—"}
                          </div>
                        ))}
                      </td>
                      <td style={{ ...celStyle, ...fontBody, fontSize: 10, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{a.venditore_nome || "—"}</td>
                      <td style={{ ...celStyle, ...fontBody, fontSize: 10, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{a.data_pagamento ? fmtData(a.data_pagamento) : "—"}</td>
                      <td style={{ ...celStyle, ...fontBody, fontSize: 10, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{a.importo != null ? fmtEuroErp(a.importo) : "—"}</td>
                      <td style={{ ...celStyle, ...fontBody, fontSize: 10, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{a.metodo || "—"}</td>
                      <td style={{ ...celStyle, ...fontBody, fontSize: 10, color: NAVY, whiteSpace: "normal", wordBreak: "break-word" }}>{a.nota || "—"}</td>
                      <td style={{ ...celStyle, whiteSpace: "nowrap" }}>
                        {a.file_path ? <AllegatoLink percorso={a.file_path} etichetta="apri" /> : <span style={{ ...fontBody, fontSize: 10, color: MUTED }}>—</span>}
                      </td>
                      <td style={{ ...celStyle, borderRight: "none", whiteSpace: "nowrap" }}>
                        {tab === "attesa" && (
                          <div style={{ display: "flex", alignItems: "center", gap: 4, flexWrap: "wrap" }}>
                            <button onClick={() => setModificaAcconto(a)} title="Modifica" style={{ border: "none", background: "none", cursor: "pointer", color: NAVY, padding: 4, display: "flex", alignItems: "center" }}>
                              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">{ICONA_MATITA_PATH}</svg>
                            </button>
                            <button onClick={() => eliminaAcconto(a)} title="Elimina" style={{ border: "none", background: "none", cursor: "pointer", color: "#C0392B", padding: 4, display: "flex", alignItems: "center" }}>
                              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">{ICONA_CESTINO_PATH}</svg>
                            </button>
                            {!isMobile && onApriSchedeAffiancate && coinvolti.length > 1 && (
                              <button
                                onClick={() => onApriSchedeAffiancate(coinvolti.map((co) => co.iscritto).filter(Boolean))}
                                title="Apri tutte le schede associate, affiancate"
                                style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: NAVY, background: "#F1ECDF", border: "none", borderRadius: 20, padding: "5px 10px", cursor: "pointer" }}
                              >
                                Associa
                              </button>
                            )}
                            <button
                              onClick={() => approva(a)}
                              disabled={approvandoId === a.id}
                              style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: "#fff", background: NAVY, border: "none", borderRadius: 20, padding: "5px 10px", cursor: approvandoId === a.id ? "default" : "pointer" }}
                            >
                              {approvandoId === a.id ? "…" : "Approva"}
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                    );
                  }))}
                </tbody>
              </table>
            </div>
          );
        };

        return chiaviData.map((data) => (
          <div key={data} style={{ marginBottom: 28 }}>
            <div style={{ ...fontBody, fontSize: 15, fontWeight: 600, color: NAVY, textAlign: "center", marginBottom: 12 }}>
              {fmtDataLunga(data)}
            </div>
            {tabellaGiorno(righe.filter((a) => (a.ts || "").slice(0, 10) === data))}
          </div>
        ));
      })()}
      {modificaAcconto && iscrittoById[modificaAcconto.iscritto_id] && (
        <ModalePagamentoVenditore
          iscritto={iscrittoById[modificaAcconto.iscritto_id]}
          venditoreNome={modificaAcconto.venditore_nome}
          accontoEsistente={modificaAcconto}
          ricarica={ricarica}
          corsi={corsi} corsiDate={corsiDate} location={location} iscritti={iscritti}
          onChiudi={() => setModificaAcconto(null)}
        />
      )}
    </div>
  );
}
// quante iscrizioni ha fatto ciascun venditore (campo "Tutor" nella scheda
// iscritto), nel periodo scelto, con il dettaglio corso per corso
// tonalità della cella "chiusure" nella matrice corso × venditore: vuota
// se 0, oro chiaro se 1, oro pieno se 2 o più — una heatmap leggera per
// far risaltare a colpo d'occhio dove si concentrano le vendite
const COLORE_CELLA_UNA = "#F2E2BE";
const COLORE_CELLA_DUE = "#D8AE66";
function coloreCellaChiusure(n) {
  if (!n) return "transparent";
  if (n === 1) return COLORE_CELLA_UNA;
  return COLORE_CELLA_DUE;
}
function esportaCsvStatisticaVenditori(righeCorsi, colonneVenditori) {
  const intestazione = ["Corso", "Totale", ...colonneVenditori.map((v) => v.nome)];
  const righe = righeCorsi.map((r) => [r.nome, r.totale, ...colonneVenditori.map((v) => r.perVenditore[v.id] || 0)]);
  const csv = [intestazione, ...righe].map((r) => r.map((v) => `"${String(v).replace(/"/g, '""')}"`).join(",")).join("\n");
  const blob = new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = `statistica-venditori-${dataOggiStr()}.csv`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function StatisticaVenditori({ corsi, corsiDate, iscritti, venditori, costiCategorie, costiSottocategorie, categorieGruppi, ricarica, onBack, titolo = "Statistiche venditori" }) {
  const { ordine: ordineMatrice, cambiaOrdine: cambiaOrdineMatrice, ordina: ordinaMatrice } = useOrdinamentoTabella();
  // periodo di default: mese corrente (stessa convenzione di "Ultimo
  // mese" nella scheda personale del venditore) — così le classifiche
  // qui sotto mostrano subito dati utili senza dover scegliere un filtro
  const isMobile = useIsMobile();

  // periodo di default: mese corrente (stessa convenzione di "Ultimo
  // mese" nella scheda personale del venditore) — così le classifiche
  // qui sotto mostrano subito dati utili senza dover scegliere un filtro
  const [da, setDa] = useState(() => rangeMese(0).inizio);
  const [a, setA] = useState(() => rangeMese(0).fine);
  const [periodoSel, setPeriodoSel] = useState(() => { const o = new Date(); return `${o.getFullYear()}-${String(o.getMonth() + 1).padStart(2, "0")}`; });

  // primo e ultimo giorno del mese "oggi + offsetMesi" (0 = mese corrente, -1 = mese scorso)
  function rangeMese(offsetMesi) {
    const oggi = new Date();
    const inizio = new Date(oggi.getFullYear(), oggi.getMonth() + offsetMesi, 1);
    const fine = new Date(oggi.getFullYear(), oggi.getMonth() + offsetMesi + 1, 0);
    const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    return { inizio: fmt(inizio), fine: fmt(fine) };
  }
  // ultimi 24 mesi (compreso quello corrente), per la tendina "Periodo rapido"
  const opzioniMese = useMemo(() => {
    const oggi = new Date();
    const opz = [];
    for (let i = 0; i < 24; i++) {
      const d = new Date(oggi.getFullYear(), oggi.getMonth() - i, 1);
      opz.push({ valore: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`, etichetta: `${MESI[d.getMonth()]} ${d.getFullYear()}` });
    }
    return opz;
  }, []);
  function selezionaMese(valore) {
    setPeriodoSel(valore);
    if (!valore) return;
    const [anno, mese] = valore.split("-").map(Number);
    const inizio = new Date(anno, mese - 1, 1);
    const fine = new Date(anno, mese, 0);
    const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    setDa(fmt(inizio)); setA(fmt(fine));
  }

  // larghezza delle colonne trascinabile con il mouse (come in Assegnazione
  // Master), qui però le colonne sono una per venditore e cambiano in base
  // ai filtri: la larghezza è quindi una mappa "chiave colonna" -> px
  // (chiave = "corso"/"totale" o l'id del venditore) invece che un array
  // a indice fisso, e resta salvata per sempre in questo browser
  const [larghezze, setLarghezze] = useLayoutCondiviso(CHIAVE_LARGHEZZE_VENDITORI, {});
  function larghezzaDi(chiave, larghezzaDefault) {
    return larghezze[chiave] ?? larghezzaDefault;
  }
  const ridimensionamentoRef = React.useRef(null);
  function iniziaRidimensionamento(e, chiave, larghezzaAttuale) {
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    ridimensionamentoRef.current = { chiave, pointerId: e.pointerId, startX: e.clientX, startWidth: larghezzaAttuale };
  }
  function muoviRidimensionamento(e) {
    const r = ridimensionamentoRef.current;
    if (!r || e.pointerId !== r.pointerId) return;
    const nuovaLarghezza = Math.max(30, r.startWidth + (e.clientX - r.startX));
    setLarghezze({ ...larghezze, [r.chiave]: nuovaLarghezza });
  }
  function fineRidimensionamento() {
    ridimensionamentoRef.current = null;
  }

  const corsoById = useMemo(() => Object.fromEntries(corsi.map((c) => [c.id, c])), [corsi]);
  const cdById = useMemo(() => Object.fromEntries(corsiDate.map((cd) => [cd.id, cd])), [corsiDate]);

  const filtrati = iscritti.filter((i) => {
    if (!i.ts) return false;
    // le iscrizioni flaggate "vecchia iscrizione" sono relative a un corso
    // già passato inserito ora: non devono contare nelle statistiche per
    // periodo, altrimenti gonfiano il mese in cui vengono solo inserite
    if (i.vecchia_iscrizione) return false;
    if (da && i.ts < da) return false;
    if (a && i.ts > `${a}T23:59:59.999`) return false;
    return true;
  });

  // "Chiusure per corso e venditore": una riga per corso, una colonna per
  // venditore — i venditori sono quelli della rubrica "Gestione venditori"
  // (non più il testo libero del campo Tutor), con una colonna in più
  // "Non mappato" se compare un Tutor che non corrisponde a nessun
  // venditore della rubrica, così il totale non si "perde" mai in silenzio
  const [ricercaCorso, setRicercaCorso] = useState("");
  const [ordinamento, setOrdinamento] = useState("piu"); // piu | meno | alfabetico
  const [nascondiCorsiSenzaVendite, setNascondiCorsiSenzaVendite] = useState(true);
  const [venditoriVisibiliFiltro, setVenditoriVisibiliFiltro] = useState("tutti"); // tutti | conVendite

  const matrice = useMemo(() => {
    const perVenditoreCorso = {};
    const totalePerVenditore = {};
    const totalePerCorso = {};
    const nonMappatoPerCorso = {};
    let nonMappatoTotale = 0;
    filtrati.forEach((i) => {
      const cd = cdById[i.corso_data_id];
      const nomeCorso = cd ? (corsoById[cd.corso_id]?.nome?.toUpperCase() || "?") : "?";
      totalePerCorso[nomeCorso] = (totalePerCorso[nomeCorso] || 0) + 1;
      const nomeNorm = (i.tutor || "").trim().toUpperCase();
      const v = venditori.find((vv) => vv.nome.trim().toUpperCase() === nomeNorm);
      if (v) {
        if (!perVenditoreCorso[v.id]) perVenditoreCorso[v.id] = {};
        perVenditoreCorso[v.id][nomeCorso] = (perVenditoreCorso[v.id][nomeCorso] || 0) + 1;
        totalePerVenditore[v.id] = (totalePerVenditore[v.id] || 0) + 1;
      } else {
        nonMappatoPerCorso[nomeCorso] = (nonMappatoPerCorso[nomeCorso] || 0) + 1;
        nonMappatoTotale += 1;
      }
    });
    return { perVenditoreCorso, totalePerVenditore, totalePerCorso, nonMappatoPerCorso, nonMappatoTotale };
  }, [filtrati, cdById, corsoById, venditori]);

  const colonneVenditori = useMemo(() => {
    const base = venditoriVisibiliFiltro === "conVendite"
      ? venditori.filter((v) => (matrice.totalePerVenditore[v.id] || 0) > 0)
      : venditori;
    const ordinati = base.slice().sort((x, y) => x.nome.localeCompare(y.nome));
    if (matrice.nonMappatoTotale > 0) ordinati.push({ id: "__nonmappato", nome: "Non mappato", nonMappato: true });
    return ordinati;
  }, [venditori, venditoriVisibiliFiltro, matrice]);

  // tutti i corsi noti (anagrafica "Definisci corsi") uniti a quelli che
  // compaiono nel periodo ma non sono più in anagrafica — così spuntando
  // via "Nascondi corsi senza vendite" si vedono anche quelli mai venduti
  const nomiCorsiConosciuti = useMemo(() => {
    const set = new Set(corsi.map((c) => (c.nome || "").toUpperCase()).filter(Boolean));
    Object.keys(matrice.totalePerCorso).forEach((n) => set.add(n));
    return Array.from(set);
  }, [corsi, matrice]);

  const righeCorsi = useMemo(() => {
    let righe = nomiCorsiConosciuti.map((nome) => ({
      nome,
      totale: matrice.totalePerCorso[nome] || 0,
      perVenditore: Object.fromEntries(colonneVenditori.map((v) => [
        v.id,
        v.nonMappato ? (matrice.nonMappatoPerCorso[nome] || 0) : (matrice.perVenditoreCorso[v.id]?.[nome] || 0),
      ])),
    }));
    if (nascondiCorsiSenzaVendite) righe = righe.filter((r) => r.totale > 0);
    if (ricercaCorso.trim()) {
      const q = ricercaCorso.trim().toUpperCase();
      righe = righe.filter((r) => r.nome.includes(q));
    }
    righe.sort((x, y) => {
      if (ordinamento === "alfabetico") return x.nome.localeCompare(y.nome);
      if (ordinamento === "meno") return x.totale - y.totale || x.nome.localeCompare(y.nome);
      return y.totale - x.totale || x.nome.localeCompare(y.nome);
    });
    return righe;
  }, [nomiCorsiConosciuti, matrice, colonneVenditori, nascondiCorsiSenzaVendite, ricercaCorso, ordinamento]);

  const numeroTipologieVendute = Object.keys(matrice.totalePerCorso).length;
  const numeroVenditoriConVendite = venditori.filter((v) => (matrice.totalePerVenditore[v.id] || 0) > 0).length;

  const bordoV = `1px solid ${CREAM_BORDER}`;
  const celStyle = { padding: "8px 12px", borderBottom: bordoV, borderRight: bordoV, whiteSpace: "nowrap" };
  const thStyle = { ...celStyle, ...fontBody, fontSize: 11, fontWeight: 600, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, textAlign: "left", background: BG };

  // "Classifiche venditori" (Corsi venduti / Performance): stesso periodo
  // scelto qui sopra (filtrati), col confronto rispetto al periodo
  // immediatamente precedente di pari durata
  const [mostraCorsiPeriodoCompleto, setMostraCorsiPeriodoCompleto] = useState(false);
  const [mostraPerformancePeriodoCompleto, setMostraPerformancePeriodoCompleto] = useState(false);
  const [mostraCorsiStoricoCompleto, setMostraCorsiStoricoCompleto] = useState(false);
  const [mostraIncassoStoricoCompleto, setMostraIncassoStoricoCompleto] = useState(false);

  const rangePrecedenteClassifiche = useMemo(() => {
    if (!da || !a) return null;
    const [ay, am, ad] = da.split("-").map(Number);
    const [by, bm, bd] = a.split("-").map(Number);
    const inizioCorrente = new Date(ay, am - 1, ad);
    const fineCorrente = new Date(by, bm - 1, bd);
    const giorni = Math.round((fineCorrente - inizioCorrente) / 86400000) + 1;
    const finePrecedente = new Date(inizioCorrente);
    finePrecedente.setDate(finePrecedente.getDate() - 1);
    const inizioPrecedente = new Date(finePrecedente);
    inizioPrecedente.setDate(inizioPrecedente.getDate() - (giorni - 1));
    return { inizio: fmtDataIso(inizioPrecedente), fine: fmtDataIso(finePrecedente) };
  }, [da, a]);

  const classifichePeriodo = useMemo(() => {
    if (!venditori || venditori.length === 0) return null;
    const corrente = statsVenditoriPerPeriodo(filtrati, venditori);
    const filtratiPrecedenti = rangePrecedenteClassifiche
      ? iscritti.filter((i) => !i.vecchia_iscrizione && i.ts && i.ts.slice(0, 10) >= rangePrecedenteClassifiche.inizio && i.ts.slice(0, 10) <= rangePrecedenteClassifiche.fine)
      : [];
    const precedente = statsVenditoriPerPeriodo(filtratiPrecedenti, venditori);
    const corsiRanked = rankCorsiConTrend(corrente, precedente);
    const { righe: performanceRanked, mediaPerformance } = rankPerformanceConTrend(corrente, precedente);
    const mediaCorsi = corrente.length > 0 ? round2(corrente.reduce((s, r) => s + r.corsi, 0) / corrente.length) : 0;
    return { corsi: corsiRanked, performance: performanceRanked, mediaCorsi, mediaPerformance };
  }, [filtrati, iscritti, venditori, rangePrecedenteClassifiche]);

  // dati "da sempre": non risentono del filtro periodo qui sopra — servono
  // per le due classifiche storiche (più venduto/più incassato di sempre)
  // e per la specializzazione per corso di ciascun venditore. Includono
  // anche le "vecchie iscrizioni" perché qui rappresentano vendite
  // realmente avvenute di quel corso (diversamente dalle statistiche per
  // periodo, dove non vanno attribuite al mese in cui sono state inserite)
  const storico = useMemo(() => {
    if (!venditori || venditori.length === 0) return { classificaCorsi: [], classificaIncasso: [], schede: [], mediaCorsi: 0, mediaIncasso: 0 };
    const perVenditore = {};
    venditori.forEach((v) => { perVenditore[v.id] = { venditore: v, corsi: 0, valore: 0, perCorso: {} }; });
    iscritti.forEach((i) => {
      const nomeNorm = (i.tutor || "").trim().toUpperCase();
      const v = venditori.find((vv) => vv.nome.trim().toUpperCase() === nomeNorm);
      if (!v || !perVenditore[v.id]) return;
      const cd = cdById[i.corso_data_id];
      const nomeCorso = cd ? (corsoById[cd.corso_id]?.nome || "—") : "—";
      perVenditore[v.id].corsi += 1;
      perVenditore[v.id].valore += i.totale_pattuito || 0;
      perVenditore[v.id].perCorso[nomeCorso] = (perVenditore[v.id].perCorso[nomeCorso] || 0) + 1;
    });
    const attivi = Object.values(perVenditore).filter((r) => r.corsi > 0);
    const classificaCorsi = attivi.slice().sort((x, y) => y.corsi - x.corsi).map((r, i) => ({ ...r, posizione: i + 1 }));
    const classificaIncasso = attivi.slice().sort((x, y) => y.valore - x.valore).map((r, i) => ({ ...r, posizione: i + 1 }));
    const schede = attivi
      .map((r) => ({
        venditore: r.venditore,
        totale: r.corsi,
        righeCorsi: Object.entries(r.perCorso)
          .map(([nome, n]) => ({ nome, n, pct: r.corsi > 0 ? Math.round((n / r.corsi) * 100) : 0 }))
          .sort((x, y) => y.n - x.n),
      }))
      .sort((x, y) => y.totale - x.totale);
    const mediaCorsi = attivi.length > 0 ? round2(attivi.reduce((s, r) => s + r.corsi, 0) / attivi.length) : 0;
    const mediaIncasso = attivi.length > 0 ? round2(attivi.reduce((s, r) => s + r.valore, 0) / attivi.length) : 0;
    return { classificaCorsi, classificaIncasso, schede, mediaCorsi, mediaIncasso };
  }, [iscritti, venditori, cdById, corsoById]);

  const etichettaPeriodoClassifiche = (() => {
    if (!da && !a) return "Storico completo";
    if (!da || !a) return "Periodo personalizzato";
    const [ay, am, ad] = da.split("-").map(Number);
    const [by, bm, bd] = a.split("-").map(Number);
    if (am === bm && ay === by) return `${String(ad).padStart(2, "0")}–${String(bd).padStart(2, "0")} ${MESI_ABBR[am - 1]} ${ay}`;
    return `${String(ad).padStart(2, "0")} ${MESI_ABBR[am - 1]} ${ay} – ${String(bd).padStart(2, "0")} ${MESI_ABBR[bm - 1]} ${by}`;
  })();

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: "40px 20px" }}>
      <div style={{ marginBottom: 12 }}><TastoLivelloPrecedente titolo="Statistiche" onClick={onBack} /></div>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16, flexWrap: "wrap", marginBottom: 4 }}>
        <div>
          <div style={{ ...fontDisplay, fontSize: 26, color: NAVY }}>{titolo}</div>
          <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginTop: 4 }}>Corsi chiusi da ciascun venditore nel periodo selezionato</div>
        </div>
        <button
          onClick={() => esportaCsvStatisticaVenditori(righeCorsi, colonneVenditori)}
          style={{ ...fontBody, fontSize: 13, fontWeight: 700, color: NAVY, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 20, padding: "10px 18px", display: "flex", alignItems: "center", gap: 8, cursor: "pointer", flexShrink: 0 }}
        >
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 3v12" /><path d="M7 8l5-5 5 5" /><path d="M5 21h14" /></svg>
          Esporta
        </button>
      </div>
      <SelettoreCategoriaGruppo campo="venditori_categoria_spesa_id" categorieGruppi={categorieGruppi} costiCategorie={costiCategorie} costiSottocategorie={costiSottocategorie} ricarica={ricarica} />

      <div style={{ display: "flex", gap: 14, alignItems: "flex-end", marginTop: 20, marginBottom: 16, flexWrap: "wrap" }}>
        <Field label="Periodo rapido">
          <select style={inputStyle} value={periodoSel} onChange={(e) => selezionaMese(e.target.value)}>
            <option value="">Personalizzato</option>
            {opzioniMese.map((o) => <option key={o.valore} value={o.valore}>{o.etichetta}</option>)}
          </select>
        </Field>
        <Field label="Dal">
          <input type="date" style={inputStyle} value={da} onChange={(e) => { setDa(e.target.value); setPeriodoSel(""); }} />
        </Field>
        <Field label="Al">
          <input type="date" style={inputStyle} value={a} onChange={(e) => { setA(e.target.value); setPeriodoSel(""); }} />
        </Field>
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 22, ...fontBody, fontSize: 13.5, color: NAVY }}>
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={GOLD} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 20V10" /><path d="M12 20V4" /><path d="M20 20v-7" /></svg>
        <b>{filtrati.length}</b>&nbsp;chiusure&nbsp;<span style={{ color: MUTED }}>·</span>&nbsp;<b>{numeroTipologieVendute}</b>&nbsp;tipologie&nbsp;<span style={{ color: MUTED }}>·</span>&nbsp;<b>{numeroVenditoriConVendite}</b>&nbsp;venditori
      </div>

      <div style={{ background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 14, padding: 20, marginBottom: 8 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 16, flexWrap: "wrap", marginBottom: 16 }}>
          <div>
            <div style={{ ...fontDisplay, fontSize: 17, fontWeight: 700, color: NAVY }}>Chiusure per corso e venditore</div>
            <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>I corsi sono ordinati per numero totale di chiusure</div>
          </div>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <input value={ricercaCorso} onChange={(e) => setRicercaCorso(e.target.value)} placeholder="Cerca corso" style={{ ...inputStyle, width: 180 }} />
            <select style={inputStyle} value={ordinamento} onChange={(e) => setOrdinamento(e.target.value)}>
              <option value="piu">Ordina: più venduti</option>
              <option value="meno">Ordina: meno venduti</option>
              <option value="alfabetico">Ordina: alfabetico</option>
            </select>
          </div>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: 20, rowGap: 10, flexWrap: "wrap", marginBottom: 14, paddingBottom: 14, borderBottom: bordoV }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            <span style={{ display: "flex", alignItems: "center", gap: 5, ...fontBody, fontSize: 12, color: MUTED }}>
              <span style={{ width: 16, height: 16, borderRadius: 4, border: `1px solid ${CREAM_BORDER}`, background: "#fff", display: "inline-block" }} /> 0
            </span>
            <span style={{ display: "flex", alignItems: "center", gap: 5, ...fontBody, fontSize: 12, color: MUTED }}>
              <span style={{ width: 16, height: 16, borderRadius: 4, background: COLORE_CELLA_UNA, display: "inline-block" }} /> 1
            </span>
            <span style={{ display: "flex", alignItems: "center", gap: 5, ...fontBody, fontSize: 12, color: MUTED }}>
              <span style={{ width: 16, height: 16, borderRadius: 4, background: COLORE_CELLA_DUE, display: "inline-block" }} /> 2+
            </span>
          </div>
          <label style={{ display: "flex", alignItems: "center", gap: 7, ...fontBody, fontSize: 12.5, color: NAVY, cursor: "pointer" }}>
            <input type="checkbox" checked={nascondiCorsiSenzaVendite} onChange={(e) => setNascondiCorsiSenzaVendite(e.target.checked)} />
            Nascondi corsi senza vendite
          </label>
          <div style={{ display: "flex", alignItems: "center", gap: 7, ...fontBody, fontSize: 12.5, color: NAVY }}>
            Venditori visibili:
            <select style={{ ...inputStyle, padding: "5px 8px", fontSize: 12.5 }} value={venditoriVisibiliFiltro} onChange={(e) => setVenditoriVisibiliFiltro(e.target.value)}>
              <option value="tutti">Tutti</option>
              <option value="conVendite">Solo con vendite</option>
            </select>
          </div>
        </div>

        {righeCorsi.length === 0 ? (
          <div style={{ ...fontBody, fontSize: 13, color: MUTED, padding: "16px 0" }}>Nessun corso trovato.</div>
        ) : (() => {
          // colonne effettive di questa tabella, con la loro chiave di
          // ridimensionamento e larghezza (salvata o di default): cambia in
          // base ai venditori visibili, quindi calcolata qui invece di un
          // array fisso come in Assegnazione Master
          const colonne = [
            { chiave: "corso", etichetta: "Corso", larghezzaDefault: 200 },
            { chiave: "totale", etichetta: "Totale", larghezzaDefault: 90 },
            ...colonneVenditori.map((v) => ({ chiave: v.id, larghezzaDefault: 130, venditore: v })),
          ].map((c) => ({ ...c, larghezza: larghezzaDi(c.chiave, c.larghezzaDefault) }));
          const larghezzaTabella = colonne.reduce((tot, c) => tot + c.larghezza, 0);

          return (
            <div style={{ overflowX: "auto" }}>
              <table style={{ borderCollapse: "collapse", width: larghezzaTabella, tableLayout: "fixed" }}>
                <colgroup>{colonne.map((c) => <col key={c.chiave} style={{ width: c.larghezza }} />)}</colgroup>
                <thead>
                  <tr>
                    {colonne.map((c, i) => (
                      <ThOrdina
                        key={c.chiave} campo={c.chiave} ordine={ordineMatrice} onOrdina={cambiaOrdineMatrice}
                        style={{ ...thStyle, position: "relative", borderRight: i === colonne.length - 1 ? "none" : bordoV, textAlign: c.venditore ? "center" : "left" }}
                      >
                        {c.venditore ? (
                          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4, textTransform: "none" }}>
                            <div style={{ width: 26, height: 26, borderRadius: "50%", border: `1.5px solid ${GOLD}`, color: NAVY, ...fontBody, fontSize: 12, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", background: "#fff" }}>
                              {c.venditore.nome.trim().slice(0, 1).toUpperCase()}
                            </div>
                            <div style={{ textTransform: "uppercase", fontSize: 11 }}>{c.venditore.nonMappato ? "NON MAPPATO" : c.venditore.nome.trim().split(/\s+/)[0].toUpperCase()}</div>
                            <div style={{ ...fontDisplay, fontSize: 13, fontWeight: 700, color: NAVY, textTransform: "none" }}>
                              {c.venditore.nonMappato ? matrice.nonMappatoTotale : (matrice.totalePerVenditore[c.venditore.id] || 0)}
                            </div>
                          </div>
                        ) : c.etichetta}
                        <div
                          onPointerDown={(e) => iniziaRidimensionamento(e, c.chiave, c.larghezza)}
                          onPointerMove={muoviRidimensionamento}
                          onPointerUp={fineRidimensionamento}
                          onPointerCancel={fineRidimensionamento}
                          style={{ position: "absolute", top: 0, right: -4, bottom: 0, width: 8, cursor: "col-resize", touchAction: "none", zIndex: 3 }}
                        />
                      </ThOrdina>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {ordinaMatrice(righeCorsi, {
                    corso: (r) => r.nome || "",
                    totale: (r) => r.totale ?? null,
                    // ogni colonna venditore ordina per le sue chiusure
                    ...Object.fromEntries(colonneVenditori.map((v) => [v.id, (r) => r.perVenditore[v.id] || 0])),
                  }).map((r) => (
                    <tr key={r.nome}>
                      <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, fontWeight: 600, overflow: "hidden", textOverflow: "ellipsis" }}>{toTitleCase(r.nome)}</td>
                      <td style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, fontWeight: 700 }}>{r.totale}</td>
                      {colonneVenditori.map((v) => {
                        const n = r.perVenditore[v.id] || 0;
                        return (
                          <td key={v.id} style={{ ...celStyle, ...fontBody, fontSize: 13, color: NAVY, fontWeight: n > 0 ? 700 : 400, textAlign: "center", background: coloreCellaChiusure(n) }}>
                            {n}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  <tr>
                    <td style={{ ...celStyle, ...fontBody, fontSize: 13, fontWeight: 700, color: NAVY, background: BG }}>Totale del periodo</td>
                    <td style={{ ...celStyle, ...fontBody, fontSize: 13, fontWeight: 700, color: NAVY, background: BG }}>{filtrati.length}</td>
                    {colonneVenditori.map((v) => (
                      <td key={v.id} style={{ ...celStyle, ...fontBody, fontSize: 13, fontWeight: 700, color: NAVY, textAlign: "center", background: BG }}>
                        {v.nonMappato ? matrice.nonMappatoTotale : (matrice.totalePerVenditore[v.id] || 0)}
                      </td>
                    ))}
                  </tr>
                </tfoot>
              </table>
            </div>
          );
        })()}
        <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 14 }}>{righeCorsi.length} tipologi{righeCorsi.length === 1 ? "a" : "e"} visualizzat{righeCorsi.length === 1 ? "a" : "e"}</div>
      </div>

      {classifichePeriodo && (classifichePeriodo.corsi.length > 0) && (
        <>
        <div style={{ marginTop: 44, marginBottom: 12 }}>
          <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY }}>Classifiche venditori</div>
          <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>Periodo: {etichettaPeriodoClassifiche}</div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: 14, marginBottom: 20 }}>
          <ColonnaClassifica
            titolo="Corsi venduti" sottotitolo="Numero di chiusure nel periodo"
            righe={classifichePeriodo.corsi} chiaveValore="corsi" tipoTrend="posizioni"
            etichettaMedia={`${classifichePeriodo.mediaCorsi} corsi`}
            formatValore={(v) => String(v)}
            mostraTutti={mostraCorsiPeriodoCompleto} onToggleMostraTutti={() => setMostraCorsiPeriodoCompleto((v) => !v)}
          />
          <ColonnaClassifica
            titolo="Performance" sottotitolo="Ticket medio corretto per il volume di vendite"
            righe={classifichePeriodo.performance} chiaveValore="performance" tipoTrend="posizioni"
            etichettaMedia={`${classifichePeriodo.mediaPerformance} pt`}
            formatValore={(v) => String(Math.round(v))}
            coloreValore={coloreScorePerformance}
            mostraTutti={mostraPerformancePeriodoCompleto} onToggleMostraTutti={() => setMostraPerformancePeriodoCompleto((v) => !v)}
          />
        </div>
        </>
      )}

      {storico.classificaCorsi.length > 0 && (
        <>
        <div style={{ marginTop: 24, marginBottom: 12 }}>
          <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY }}>Classifiche da sempre</div>
          <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>Non risentono del periodo scelto qui sopra — calcolate su tutto lo storico</div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: 14, marginBottom: 20 }}>
          <ColonnaClassifica
            titolo="Più corsi venduti" sottotitolo="Numero di chiusure da sempre"
            righe={storico.classificaCorsi} chiaveValore="corsi"
            etichettaMedia={`${storico.mediaCorsi} corsi`}
            formatValore={(v) => String(v)}
            mostraTutti={mostraCorsiStoricoCompleto} onToggleMostraTutti={() => setMostraCorsiStoricoCompleto((v) => !v)}
          />
          <ColonnaClassifica
            titolo="Incasso generato" sottotitolo="Valore venduto da sempre"
            righe={storico.classificaIncasso} chiaveValore="valore"
            etichettaMedia={fmtEuroErp(storico.mediaIncasso)}
            formatValore={(v) => fmtEuroErp(round2(v))}
            mostraTutti={mostraIncassoStoricoCompleto} onToggleMostraTutti={() => setMostraIncassoStoricoCompleto((v) => !v)}
          />
        </div>
        </>
      )}

      {storico.schede.length > 0 && (
        <>
        <div style={{ marginTop: 24, marginBottom: 12 }}>
          <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY }}>Specializzazione per venditore</div>
          <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>I corsi più venduti da sempre da ciascun venditore, non risentono del periodo scelto qui sopra</div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(auto-fill, minmax(300px, 1fr))", gap: 14, marginBottom: 20 }}>
          {storico.schede.map((s) => (
            <div key={s.venditore.id} style={cardStyle}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
                <div style={{ width: 32, height: 32, borderRadius: "50%", background: coloreAvatarClassifica(s.venditore.nome), color: "#fff", ...fontBody, fontSize: 13, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  {s.venditore.nome.trim().slice(0, 2).toUpperCase()}
                </div>
                <div style={{ minWidth: 0 }}>
                  <div style={{ ...fontDisplay, fontSize: 15, fontWeight: 700, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{toTitleCase(s.venditore.nome)}</div>
                  <div style={{ ...fontBody, fontSize: 11.5, color: MUTED }}>{s.totale} cors{s.totale === 1 ? "o" : "i"} venduti da sempre</div>
                </div>
              </div>
              {s.righeCorsi.slice(0, 5).map((r, i) => (
                <div key={r.nome} style={{ marginBottom: i < Math.min(4, s.righeCorsi.length - 1) ? 10 : 0 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8, marginBottom: 4 }}>
                    <span style={{ ...fontBody, fontSize: 12.5, fontWeight: 600, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{toTitleCase(r.nome)}</span>
                    <span style={{ ...fontBody, fontSize: 11, color: MUTED, flexShrink: 0 }}>{r.n} · {r.pct}%</span>
                  </div>
                  <div style={{ height: 5, background: BG, borderRadius: 3, overflow: "hidden" }}>
                    <div style={{ height: "100%", width: `${(r.n / s.righeCorsi[0].n) * 100}%`, background: i === 0 ? GOLD : NAVY, borderRadius: 3 }} />
                  </div>
                </div>
              ))}
            </div>
          ))}
        </div>
        </>
      )}
    </div>
  );
}

// ---------- Dashboard venditori ----------
// tasto "pillola" per le tab (In programmazione/Archivio, Elenco/Calendario)
// "urgente" (es. "Da pagare" con almeno una spesa scoperta) sovrasta il
// colore normale con un rosso lampeggiante, per farsi notare anche fra
// tante altre pillole — usato solo dove esplicitamente richiesto, il
// resto delle TabPillola dell'app non cambia
function TabPillola({ attivo, onClick, children, compatto, urgente }) {
  return (
    <>
      {urgente && <style>{`@keyframes lampeggiaTabPillola { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }`}</style>}
      <button
        onClick={onClick}
        style={{
          ...fontBody, fontSize: compatto ? 11 : 13, fontWeight: 600, padding: compatto ? "7px 8px" : "9px 14px", borderRadius: 16,
          border: urgente || attivo ? "none" : `1px solid ${CREAM_BORDER}`,
          background: urgente ? "#C0392B" : attivo ? NAVY : "#fff",
          color: urgente || attivo ? "#fff" : NAVY,
          cursor: "pointer", display: "flex", alignItems: "center", gap: compatto ? 3 : 6, whiteSpace: "nowrap", flexShrink: 0,
          animation: urgente ? "lampeggiaTabPillola 1.1s ease-in-out infinite" : "none",
        }}
      >
        {children}
      </button>
    </>
  );
}

// colori pastello per le tipologie di modella nella Dashboard modelle: le
// tipologie sono libere (catalogo "Definisci tipi di modelle", non un enum
// fisso), quindi il colore si sceglie con un hash del testo invece di un
// elenco codificato — stabile per ogni nome, senza doverli conoscere prima
const PALETTE_TIPOLOGIA = [
  { bg: "#FBE5D6", fg: "#8A4B1F" },
  { bg: "#FCE4EC", fg: "#9B3A5B" },
  { bg: "#E3F2FD", fg: "#1F5C8A" },
  { bg: "#EDE7F6", fg: "#5B3B8A" },
  { bg: "#E8F5E9", fg: "#2E7D32" },
  { bg: "#FFF8E1", fg: "#8A6D1F" },
];
function coloreTipologia(testo) {
  let hash = 0;
  for (let i = 0; i < (testo || "").length; i++) hash = (hash * 31 + testo.charCodeAt(i)) | 0;
  return PALETTE_TIPOLOGIA[Math.abs(hash) % PALETTE_TIPOLOGIA.length];
}
function BadgeTipologia({ testo, conteggio }) {
  const c = coloreTipologia(testo);
  return (
    <span style={{ ...fontBody, fontSize: 12, fontWeight: 600, padding: "5px 10px", borderRadius: 20, background: c.bg, color: c.fg, display: "inline-flex", alignItems: "center", gap: 5, whiteSpace: "nowrap" }}>
      {testo}{conteggio != null && <span style={{ fontWeight: 700 }}>{conteggio}</span>}
    </span>
  );
}

// blocco "Date corsi" (tab In programmazione/Archivio, ricerca, filtri,
// Elenco/Calendario): riusato sia da "Dashboard venditori" sia da
// "Gestione modelle" — cambia solo dove porta il click su una data
// (onApriData), passato dal chiamante
function SezioneDateCorsi({
  corsi, location, corsiDate, iscritti, master, ricarica, onApriData,
  filtroCorsoHome, setFiltroCorsoHome, filtroCittaHome, setFiltroCittaHome, filtroMasterHome, setFiltroMasterHome,
  cronologicoHome, setCronologicoHome,
  apriFiltroCorsoHome, setApriFiltroCorsoHome, apriFiltroCittaHome, setApriFiltroCittaHome, apriFiltroMasterHome, setApriFiltroMasterHome,
  selectFiltroCorsoHomeRef, selectFiltroCittaHomeRef, selectFiltroMasterHomeRef,
  // opzionali: solo "Gestione corsi" li passa, per matita/cestino inline
  // sulle righe. Dashboard venditori e Gestione modelle restano di sola
  // consultazione non passandoli (undefined).
  onEdit, onDelete, idInModifica, renderModifica,
  // opzionali: quando il chiamante ha già le proprie tab esterne
  // equivalenti (es. Dashboard modelle: Elenco richieste/Calendario/
  // Archivio), può forzare qui tab/modo e nascondere le pillole interne
  // per non duplicarle
  tabForzata, modoForzato, nascondiControlli,
  // opzionale: nasconde solo il titolo "Corsi in programmazione" (usato da
  // "Gestione corsi", che ha già il proprio titolo di pagina), lasciando
  // intatte le tab e i filtri sottostanti
  nascondiTitolo,
  // opzionale: cambia il testo del titolo (default "Corsi in
  // programmazione"). Usato da Dashboard venditori ("Iscrivi Allievo")
  titolo,
  // opzionale: solo chi mostra le pillole Elenco/Calendario e In
  // programmazione/Archivio (non tabForzata/modoForzato) lo passa, per far
  // sì che l'header "Indietro" disfi prima queste sotto-viste locali
  // invece di uscire subito dalla pagina
  registraInterceptaIndietro,
  // opzionale: tiene fisso in cima tutto il blocco di controlli (titolo
  // extra passato in intestazioneSticky, tab, tasti +/-, ricerca, filtri,
  // conteggio) mentre solo l'elenco/calendario sotto scorre. Solo
  // "Gestione corsi" lo passa: le altre pagine che riusano questo
  // componente restano invariate.
  stickyControlli, intestazioneSticky,
  // opzionali: ricerca, tab e modo tenuti da chi ospita questa sezione, così
  // sopravvivono all'andata e ritorno da una scheda. Se non arrivano, il
  // componente usa i propri, come ha sempre fatto
  ricercaEsterna, setRicercaEsterna, tabEsterna, setTabEsterna, modoEsterno, setModoEsterno,
  // opzionale: apre la scheda di un singolo allievo. Lo passa solo chi può
  // entrarci (Gestione corsi); dove manca, i nomi trovati restano scritti
  // ma non cliccabili
  onApriIscritto,
}) {
  const [vistaDateTabInterna, setVistaDateTabInterna] = useState("programmazione"); // programmazione | archivio
  const [vistaDateModoInterno, setVistaDateModoInterno] = useState("elenco"); // elenco | calendario
  const vistaDateTab = tabForzata || (setTabEsterna ? tabEsterna : vistaDateTabInterna);
  const vistaDateModo = modoForzato || (setModoEsterno ? modoEsterno : vistaDateModoInterno);
  const setVistaDateTab = setTabEsterna || setVistaDateTabInterna;
  const setVistaDateModo = setModoEsterno || setVistaDateModoInterno;
  const isMobile = useIsMobile();
  // riga filtri su mobile: un unico font per tutti i pulsanti, ridotto
  // quel tanto che basta perché stiano tutti su una sola riga senza
  // troncare (vedi useFontRigaAdattato). Il "segnale" fa ricalcolare
  // quando cambiano le etichette (filtro attivo o numero di opzioni).
  const segnaleFiltri = `${isMobile}|${filtroCorsoHome}|${filtroCittaHome}|${filtroMasterHome}|${corsi.length}|${location.length}|${(master || []).length}`;
  const { ref: rigaFiltriRef, fontSize: fontFiltri } = useFontRigaAdattato(isMobile, segnaleFiltri, 13, 7);
  useEffect(() => {
    if (!registraInterceptaIndietro || nascondiControlli) return;
    if (vistaDateModo === "calendario") { registraInterceptaIndietro(() => setVistaDateModo("elenco")); return () => registraInterceptaIndietro(null); }
    if (vistaDateTab === "archivio") { registraInterceptaIndietro(() => setVistaDateTab("programmazione")); return () => registraInterceptaIndietro(null); }
    registraInterceptaIndietro(null);
  }, [vistaDateModo, vistaDateTab, nascondiControlli, registraInterceptaIndietro]);
  const [ricercaDateInterna, setRicercaDateInterna] = useState("");
  const ricercaDate = setRicercaEsterna ? (ricercaEsterna || "") : ricercaDateInterna;
  const setRicercaDate = setRicercaEsterna || setRicercaDateInterna;
  // dimensione del testo SOLO nelle barre-evento del calendario incorporato
  // (nome corso + sigla città), regolabile coi tasti +/- vicino a "Elenco":
  // resta memorizzata in locale, così l'ultima misura scelta vale anche
  // alle aperture successive
  const [fontScale, setFontScale] = useState(() => {
    const salvato = parseFloat(localStorage.getItem("corsiDateFontScale"));
    return Number.isFinite(salvato) ? salvato : 1;
  });
  function cambiaFontScale(delta) {
    setFontScale((prev) => {
      const nuovo = Math.round(Math.min(1.4, Math.max(0.8, prev + delta)) * 100) / 100;
      localStorage.setItem("corsiDateFontScale", String(nuovo));
      return nuovo;
    });
  }
  // quando i controlli sono sticky (solo "Gestione corsi"), il Calendario
  // incorporato deve sapere quanto è alta questa barra fissa per far
  // scorrere il mese corrente esattamente sotto di essa, non dietro
  const controlliStickyRef = React.useRef(null);
  const [altezzaControlliSticky, setAltezzaControlliSticky] = useState(150);
  useLayoutEffect(() => {
    if (stickyControlli && controlliStickyRef.current) setAltezzaControlliSticky(controlliStickyRef.current.offsetHeight);
  }, [stickyControlli, vistaDateModo]);
  const oggiStr = dataOggiStr();
  // solo "Gestione corsi" (stickyControlli) e solo da mobile: la freccetta
  // ripiega tutto il blocco fisso in cima (titolo, tasti, tab, ricerca,
  // filtri), lasciando solo il conteggio — l'elenco sotto non si muove,
  // resta sempre visibile. Da desktop, o nelle altre pagine che riusano
  // questo componente, il blocco resta sempre aperto, nessuna freccetta
  const collassabileSuMobile = isMobile && stickyControlli;
  const [controlliCollassati, setControlliCollassati] = useState(false);

  const corsoById = useMemo(() => Object.fromEntries(corsi.map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries(location.map((l) => [l.id, l])), [location]);
  const masterById = useMemo(() => Object.fromEntries((master || []).map((m) => [m.id, m])), [master]);

  const numeroInProgrammazione = corsiDate.filter((cd) => cd.data_fine >= oggiStr).length;
  const terminiRicerca = ricercaDate.trim().toLowerCase().split(/\s+/).filter(Boolean);
  // quando la ricerca centra il nome di un allievo, la sua riga va segnata:
  // il corso da solo non basta a capire perché è comparso, e soprattutto si
  // vuole entrare nella sua scheda senza aprire la classe e cercarlo a occhio
  const allieviTrovatiPerData = {};
  // corrispondenza al testo cercato, senza guardare né la tab né i filtri:
  // serve anche a capire, quando la ricerca non dà niente, se il corso
  // esiste ma sono i filtri (o la tab sbagliata) a tenerlo nascosto
  function corrispondeRicerca(cd) {
    if (terminiRicerca.length === 0) return true;
    const iscrittiData = iscritti.filter((i) => i.corso_data_id === cd.id);
    const nomiAllievi = iscrittiData.map((i) => `${i.nome || ""} ${i.cognome || ""}`);
    const mesiCd = [cd.data_inizio, cd.data_fine].filter(Boolean).map((d) => MESI[parseInt(d.slice(5, 7), 10) - 1]);
    const anniCd = [cd.data_inizio, cd.data_fine].filter(Boolean).map((d) => d.slice(0, 4));
    const testoCorso = [corsoById[cd.corso_id]?.nome, locById[cd.location_id]?.nome, masterById[cd.master_id]?.nome, ...mesiCd, ...anniCd]
      .filter(Boolean).join(" ").toLowerCase();
    const testo = [testoCorso, ...nomiAllievi].filter(Boolean).join(" ").toLowerCase();
    // ogni termine digitato deve trovarsi da qualche parte nel testo
    // (in qualunque ordine): "mei milano" trova Mei anche se sta in un
    // campo diverso da "milano" (es. nome allievo + città)
    if (!terminiRicerca.every((t) => testo.includes(t))) return false;
    // un allievo è "centrato" se almeno un termine sta nel suo nome e i
    // termini restanti li spiega la riga del corso: così "mei milano"
    // segna Mei, mentre cercare solo "milano" non segna nessuno
    const centrati = iscrittiData.filter((i) => {
      const nomeIntero = `${i.nome || ""} ${i.cognome || ""}`.toLowerCase();
      return terminiRicerca.some((t) => nomeIntero.includes(t)) && terminiRicerca.every((t) => nomeIntero.includes(t) || testoCorso.includes(t));
    });
    if (centrati.length > 0) allieviTrovatiPerData[cd.id] = centrati;
    return true;
  }
  const nellaTabCorrente = (cd) => (vistaDateTab === "programmazione" ? cd.data_fine >= oggiStr : cd.data_fine < oggiStr);
  const passaIFiltri = (cd) => {
    if (filtroCorsoHome && cd.corso_id !== filtroCorsoHome) return false;
    if (filtroCittaHome && cittaDiSede(location, cd.location_id) !== filtroCittaHome) return false;
    if (filtroMasterHome && cd.master_id !== filtroMasterHome) return false;
    return true;
  };
  const corsiDateFiltrate = corsiDate.filter((cd) => nellaTabCorrente(cd) && passaIFiltri(cd) && corrispondeRicerca(cd));
  // la ricerca non ha dato niente: il corso cercato esiste da qualche altra
  // parte? Un filtro dimenticato o la tab sbagliata sono la causa più
  // frequente, e restano invisibili — meglio dirlo che lasciar credere che
  // quella persona non ci sia
  const fuoriDaCiCheSiGuarda = terminiRicerca.length > 0 && corsiDateFiltrate.length === 0
    ? corsiDate.filter((cd) => corrispondeRicerca(cd))
    : [];
  const filtriAttiviDescrizione = [
    filtroCorsoHome && `corso ${toTitleCase(corsi.find((c) => c.id === filtroCorsoHome)?.nome || "?")}`,
    filtroCittaHome && `città ${toTitleCase(filtroCittaHome)}`,
    filtroMasterHome && `master ${toTitleCase(master.find((m) => m.id === filtroMasterHome)?.nome || "?")}`,
  ].filter(Boolean);
  function mostraQuelliFuori() {
    setFiltroCorsoHome("");
    setFiltroCittaHome("");
    setFiltroMasterHome("");
    if (!fuoriDaCiCheSiGuarda.some((cd) => nellaTabCorrente(cd))) {
      setVistaDateTab(vistaDateTab === "programmazione" ? "archivio" : "programmazione");
    }
  }

  return (
    <div>
      <div ref={controlliStickyRef} style={stickyControlli ? { position: "sticky", top: 0, zIndex: 15, background: BG, paddingTop: isMobile ? 68 : 70, marginTop: isMobile ? -70 : 0, marginBottom: -4 } : undefined}>
      {!(collassabileSuMobile && controlliCollassati) && (
      <>
      {intestazioneSticky}
      {!nascondiControlli && (
        <>
          {!nascondiTitolo && (
            <div style={{ ...fontDisplay, fontSize: 20, fontWeight: 700, color: NAVY, marginBottom: 12, textAlign: "center", textTransform: "uppercase" }}>{titolo || "Corsi in programmazione"}</div>
          )}
          <div style={{ display: "flex", alignItems: "center", justifyContent: isMobile ? "center" : "space-between", gap: isMobile ? 6 : 10, flexWrap: "wrap", marginBottom: 12 }}>
            <div style={{ display: "flex", gap: isMobile ? 3 : 6, flexShrink: 0 }}>
              <TabPillola compatto={isMobile} attivo={vistaDateTab === "programmazione"} onClick={() => setVistaDateTab("programmazione")}>Programmati ({numeroInProgrammazione})</TabPillola>
              <TabPillola compatto={isMobile} attivo={vistaDateTab === "archivio"} onClick={() => setVistaDateTab("archivio")}>Passati</TabPillola>
            </div>
            <div style={{ display: "flex", gap: isMobile ? 3 : 6, alignItems: "center", flexShrink: 0 }}>
              {!modoForzato && (
                <>
                  <TabPillola compatto={isMobile} attivo={vistaDateModo === "elenco"} onClick={() => setVistaDateModo("elenco")}>Elenco</TabPillola>
                  <TabPillola compatto={isMobile} attivo={vistaDateModo === "calendario"} onClick={() => setVistaDateModo("calendario")}>Calendario</TabPillola>
                </>
              )}
              <div style={{ display: "flex", alignItems: "center", marginLeft: isMobile ? 2 : 6, border: `1px solid ${CREAM_BORDER}`, borderRadius: 20, overflow: "hidden", background: "#fff", flexShrink: 0 }}>
                <button onClick={() => cambiaFontScale(-0.1)} title="Riduci il testo nelle barre del calendario" disabled={fontScale <= 0.8} style={{ ...fontBody, fontSize: isMobile ? 20 : 15, fontWeight: 700, color: NAVY, background: "none", border: "none", width: isMobile ? 33 : 30, height: isMobile ? 39 : 30, cursor: fontScale <= 0.8 ? "default" : "pointer", opacity: fontScale <= 0.8 ? 0.4 : 1 }}>−</button>
                <div style={{ width: 1, alignSelf: "stretch", background: CREAM_BORDER }} />
                <button onClick={() => cambiaFontScale(0.1)} title="Ingrandisci il testo nelle barre del calendario" disabled={fontScale >= 1.4} style={{ ...fontBody, fontSize: isMobile ? 20 : 15, fontWeight: 700, color: NAVY, background: "none", border: "none", width: isMobile ? 33 : 30, height: isMobile ? 39 : 30, cursor: fontScale >= 1.4 ? "default" : "pointer", opacity: fontScale >= 1.4 ? 0.4 : 1 }}>+</button>
              </div>
            </div>
          </div>
        </>
      )}
      {isMobile && (
        <CampoRicerca value={ricercaDate} onChange={(e) => setRicercaDate(e.target.value)} placeholder="Cerca allievo, corso, sede o master…" style={{ marginBottom: 12 }} />
      )}
      <div ref={rigaFiltriRef} style={{ marginBottom: 16, minWidth: 0, ...(isMobile
        ? { display: "grid", gridTemplateColumns: "repeat(5, minmax(0, 1fr))", alignItems: "start", gap: 5, fontSize: fontFiltri }
        : { display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }) }}>
        {!isMobile && (
          <div style={{ flex: "1 1 200px", minWidth: 160 }}>
            <CampoRicerca value={ricercaDate} onChange={(e) => setRicercaDate(e.target.value)} placeholder="Cerca allievo, corso, sede o master…" />
          </div>
        )}
        <FiltroPill compatto={isMobile} Icona={IconaFiltroImbuto}
          etichetta="Filtra corso" opzioneVuota="Tutti i corsi" opzioni={corsi}
          valore={filtroCorsoHome} etichettaAttiva={corsi.find((c) => c.id === filtroCorsoHome)?.nome.toUpperCase()}
          aperto={apriFiltroCorsoHome} selectRef={selectFiltroCorsoHomeRef}
          onToggle={() => { setApriFiltroCorsoHome((v) => !v); setApriFiltroCittaHome(false); setApriFiltroMasterHome(false); }}
          onChange={(e) => { setFiltroCorsoHome(e.target.value); setApriFiltroCorsoHome(false); }}
          onBlur={() => setApriFiltroCorsoHome(false)}
        />
        <FiltroPill compatto={isMobile} Icona={IconaPin}
          etichetta="Filtra città" opzioneVuota="Tutte le città" opzioni={cittaDistinte(location)}
          valore={filtroCittaHome} etichettaAttiva={filtroCittaHome ? filtroCittaHome.toUpperCase() : undefined}
          aperto={apriFiltroCittaHome} selectRef={selectFiltroCittaHomeRef}
          onToggle={() => { setApriFiltroCittaHome((v) => !v); setApriFiltroCorsoHome(false); setApriFiltroMasterHome(false); }}
          onChange={(e) => { setFiltroCittaHome(e.target.value); setApriFiltroCittaHome(false); }}
          onBlur={() => setApriFiltroCittaHome(false)}
        />
        <FiltroPill compatto={isMobile} Icona={IconaLaureaErp}
          etichetta="Filtra master" opzioneVuota="Tutte le master" opzioni={master}
          valore={filtroMasterHome} etichettaAttiva={master.find((m) => m.id === filtroMasterHome)?.nome.toUpperCase()}
          aperto={apriFiltroMasterHome} selectRef={selectFiltroMasterHomeRef}
          onToggle={() => { setApriFiltroMasterHome((v) => !v); setApriFiltroCorsoHome(false); setApriFiltroCittaHome(false); }}
          onChange={(e) => { setFiltroMasterHome(e.target.value); setApriFiltroMasterHome(false); }}
          onBlur={() => setApriFiltroMasterHome(false)}
        />
        <button
          onClick={() => setCronologicoHome((v) => !v)}
          style={isMobile ? {
            ...fontBody, fontSize: 10.5, fontWeight: 600, padding: "6px 8px 7px", borderRadius: 10,
            border: cronologicoHome ? "none" : `1px solid ${CREAM_BORDER}`, background: cronologicoHome ? NAVY : "#fff", color: cronologicoHome ? "#fff" : NAVY,
            cursor: "pointer", width: "100%", minWidth: 0, aspectRatio: "1 / 1", overflow: "hidden", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 4,
          } : {
            ...fontBody, fontSize: 13, fontWeight: 600, padding: "10px 16px", borderRadius: 10,
            border: cronologicoHome ? "none" : `1px solid ${CREAM_BORDER}`, background: cronologicoHome ? NAVY : "#fff", color: cronologicoHome ? "#fff" : NAVY,
            cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0, display: "flex", alignItems: "center", gap: 8,
          }}
        >
          <IconaCalendarioCard size={isMobile ? 17 : 16} color="currentColor" />
          <span style={isMobile ? { whiteSpace: "normal", lineHeight: 1.15, textAlign: "center", overflowWrap: "anywhere" } : undefined}>Cronologico</span>
        </button>
        <button
          onClick={() => { setFiltroCorsoHome(""); setFiltroCittaHome(""); setFiltroMasterHome(""); setRicercaDate(""); setApriFiltroCorsoHome(false); setApriFiltroCittaHome(false); setApriFiltroMasterHome(false); }}
          style={isMobile ? {
            ...fontBody, fontSize: 10.5, fontWeight: 600, padding: "6px 8px 7px", borderRadius: 10,
            border: `1px solid ${CREAM_BORDER}`, background: "#fff", color: NAVY,
            cursor: "pointer", width: "100%", minWidth: 0, aspectRatio: "1 / 1", overflow: "hidden", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 4,
          } : {
            ...fontBody, fontSize: 13, fontWeight: 600, padding: "10px 16px", borderRadius: 10,
            border: `1px solid ${CREAM_BORDER}`, background: "#fff", color: NAVY,
            cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0, display: "flex", alignItems: "center", gap: 8,
          }}
        >
          <IconaResetCircolare size={isMobile ? 17 : 16} color="currentColor" />
          <span style={isMobile ? { whiteSpace: "normal", lineHeight: 1.15, textAlign: "center", overflowWrap: "anywhere" } : undefined}>Reset filtri</span>
        </button>
      </div>
      </>
      )}
      <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginBottom: collassabileSuMobile ? 4 : 10 }}>{corsiDateFiltrate.length} cors{corsiDateFiltrate.length === 1 ? "o trovato" : "i trovati"}</div>
      {/* una ricerca che non trova niente non dice se la persona non c'è o
          se è un filtro rimasto attivo (o la tab sbagliata) a nasconderla */}
      {terminiRicerca.length > 0 && corsiDateFiltrate.length === 0 && (
        <div style={{ background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 14, padding: 14, marginBottom: 16 }}>
          {fuoriDaCiCheSiGuarda.length === 0 ? (
            <div style={{ ...fontBody, fontSize: 13, color: NAVY }}>
              Nessun corso e nessun allievo corrisponde a «{ricercaDate.trim()}».
            </div>
          ) : (
            <>
              <div style={{ ...fontBody, fontSize: 13, color: NAVY, marginBottom: 10 }}>
                «{ricercaDate.trim()}» c'è, ma fuori da quello che stai guardando
                {filtriAttiviDescrizione.length > 0 ? ` (filtri attivi: ${filtriAttiviDescrizione.join(" · ")})` : ""}
                {!fuoriDaCiCheSiGuarda.some((cd) => nellaTabCorrente(cd)) ? ` — sta fra i corsi ${vistaDateTab === "programmazione" ? "passati" : "programmati"}` : ""}.
              </div>
              {fuoriDaCiCheSiGuarda.slice(0, 6).map((cd) => (
                <div key={cd.id} onClick={() => onApriData?.(cd)} style={{ ...fontBody, fontSize: 13, color: NAVY, padding: "6px 0", borderTop: `1px solid ${CREAM_BORDER}`, cursor: onApriData ? "pointer" : "default", display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                  <b>{toTitleCase(corsoById[cd.corso_id]?.nome || "?")}</b>
                  <span style={{ color: MUTED }}>{toTitleCase(locById[cd.location_id]?.nome || "?")} · {fmtDataCompatta(cd.data_inizio, cd.data_fine)}</span>
                  {(allieviTrovatiPerData[cd.id] || []).map((i) => (
                    <span key={i.id} style={{ color: "#C0392B", fontWeight: 700 }}>{toTitleCase(`${i.nome || ""} ${i.cognome || ""}`.trim())}</span>
                  ))}
                </div>
              ))}
              <button
                onClick={mostraQuelliFuori}
                style={{ ...fontBody, fontSize: 13, fontWeight: 700, color: "#fff", background: NAVY, border: "none", borderRadius: 10, padding: "8px 14px", cursor: "pointer", marginTop: 10 }}
              >
                Mostrali nell'elenco
              </button>
            </>
          )}
        </div>
      )}
      {collassabileSuMobile && (
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 6 }}>
          <button
            onClick={() => setControlliCollassati((v) => !v)}
            title={controlliCollassati ? "Espandi i controlli" : "Comprimi i controlli"}
            style={{ background: "none", border: "none", cursor: "pointer", color: NAVY, padding: 4, display: "flex" }}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <polyline points={controlliCollassati ? "6 9 12 15 18 9" : "18 15 12 9 6 15"} />
            </svg>
          </button>
        </div>
      )}
      </div>

      {/* la chiave lega l'elenco a TUTTO ciò che ne cambia il contenuto —
          testo cercato, tab Programmati/Passati, filtri, vista cronologica —
          così ad ogni cambiamento il sottoalbero viene ricreato da zero. È
          la garanzia contro quello che si vedeva: contatore aggiornato ("3
          corsi trovati") e sotto l'elenco di prima. Su nodi nuovi il browser
          non ha niente di vecchio da lasciare a video */}
      <div key={`elenco:${vistaDateTab}:${cronologicoHome ? "crono" : "citta"}:${filtroCorsoHome}:${filtroCittaHome}:${filtroMasterHome}:${ricercaDate}`}>
      {vistaDateModo === "elenco" ? (
        <DateRaggruppatePerCitta
          corsi={corsi} location={location} cronologico={cronologicoHome}
          corsiDate={corsiDateFiltrate}
          iscritti={iscritti} master={master} onApriData={onApriData}
          allieviTrovati={allieviTrovatiPerData} onApriIscritto={onApriIscritto}
          onEdit={onEdit} onDelete={onDelete} idInModifica={idInModifica} renderModifica={renderModifica}
        />
      ) : (
        // spostabile solo dove è già consentito modificare le date (Gestione
        // corsi passa onEdit/onDelete; Dashboard venditori e Gestione modelle
        // restano di sola consultazione)
        <Calendario corsi={corsi} location={location} corsiDate={corsiDateFiltrate} iscritti={iscritti} master={master} onApriData={onApriData} onBack={() => setVistaDateModo("elenco")} ricarica={ricarica} fontScaleBarre={fontScale} scrollMarginTop={stickyControlli ? altezzaControlliSticky : undefined} spostabile={!!onEdit} />
      )}
      </div>
    </div>
  );
}

// login del venditore per la propria Dashboard: sceglie il proprio nome
// da una tendina (stesso elenco di "Definisci venditori") e scrive la
// password. Se il codice inserito è l'ADMIN_CODE (lo stesso già usato
// per le altre aree protette), entra invece in modalità amministratore:
// la Dashboard resta "sbloccata", con la tendina per scegliere
// qualunque venditore — così l'amministratore non perde la possibilità
// di controllare le performance di tutti.
function ModaleLoginVenditore({ venditori, onClose, onEntra, codiceAdmin }) {
  const [venditoreId, setVenditoreId] = useState("");
  const [password, setPassword] = useState("");
  const [errore, setErrore] = useState("");

  function entra() {
    if (!venditoreId) { setErrore("Scegli il tuo nome."); return; }
    if (!password) { setErrore("Scrivi la password."); return; }
    if (codiceAdmin && password === codiceAdmin) {
      onEntra({ modalitaAdmin: true });
      return;
    }
    // stesso confronto in chiaro già usato per utenti e master: la
    // password del venditore vive nella riga stessa (venditori.password),
    // niente più verifica lato server
    const venditore = venditori.find((v) => v.id === venditoreId);
    if (!venditore || password !== (venditore.password || "0000")) { setErrore("Password errata."); return; }
    onEntra({ modalitaAdmin: false, venditoreId, nome: venditore.nome });
  }

  return (
    <Modal title="Accedi come venditore" onClose={onClose}>
      <div style={{ ...subStyle, marginTop: -4 }}>Scegli il tuo nome e scrivi la tua password per vedere le tue chiusure e commissioni.</div>
      <Field label="Il tuo nome">
        <select style={inputStyle} value={venditoreId} onChange={(e) => setVenditoreId(e.target.value)}>
          <option value="">— scegli —</option>
          {venditori.map((v) => <option key={v.id} value={v.id}>{v.nome.toUpperCase()}</option>)}
        </select>
      </Field>
      <Field label="Password">
        <input
          type="password" style={inputStyle} value={password}
          onChange={(e) => setPassword(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && entra()}
        />
      </Field>
      {errore && <div style={{ ...fontBody, fontSize: 13, color: "#C0392B", marginBottom: 10 }}>{errore}</div>}
      <Button onClick={entra} style={{ width: "100%" }}>Entra</Button>
    </Modal>
  );
}

function PaginaDashboardVenditori({
  corsi, location, corsiDate, iscritti, master, venditori, ricarica, onBack, apriData, onApriIscritto, venditoreBloccato,
  filtroCorsoHome, setFiltroCorsoHome, filtroCittaHome, setFiltroCittaHome, filtroMasterHome, setFiltroMasterHome,
  cronologicoHome, setCronologicoHome,
  apriFiltroCorsoHome, setApriFiltroCorsoHome, apriFiltroCittaHome, setApriFiltroCittaHome, apriFiltroMasterHome, setApriFiltroMasterHome,
  selectFiltroCorsoHomeRef, selectFiltroCittaHomeRef, selectFiltroMasterHomeRef,
  registraInterceptaIndietro,
  venditeShop, prodottiShop, targetVenditeProdotti,
  titolo = "Dashboard venditori",
}) {
  const isMobile = useIsMobile();
  // se un venditore ha fatto login (venditoreBloccato valorizzato), la
  // selezione parte già su di lui e resta fissa — niente tendina, niente
  // modo di guardare i dati di qualcun altro
  const [venditoreSelId, setVenditoreSelId] = useState(venditoreBloccato?.id || "");
  const [periodo, setPeriodo] = useState("mese"); // mese | trimestre | personalizzato
  const [customDa, setCustomDa] = useState("");
  const [customA, setCustomA] = useState("");
  const [espansoChiusurePerCorso, setEspansoChiusurePerCorso] = useState(false);
  // si apre sul calendario dei corsi: chi entra qui nove volte su dieci
  // deve iscrivere qualcuno, non guardare le proprie commissioni
  const [tabDashboardVenditore, setTabDashboardVenditore] = useState("corsi"); // corsi | performance | iscrizioni
  const [meseClassifica, setMeseClassifica] = useState(() => { const o = new Date(); return { anno: o.getFullYear(), mese: o.getMonth() }; });
  const [classificaCorsiCompleta, setClassificaCorsiCompleta] = useState(false);
  const [classificaTicketCompleta, setClassificaTicketCompleta] = useState(false);
  const [mostraRiepilogoPos, setMostraRiepilogoPos] = useState(false);

  const venditoreSel = venditoreBloccato
    ? (venditori.find((v) => v.id === venditoreBloccato.id) || { id: venditoreBloccato.id, nome: venditoreBloccato.nome })
    : (venditori.find((v) => v.id === venditoreSelId) || null);
  const oggiStr = dataOggiStr();
  // target del venditore selezionato, sia quelli vendita PRODOTTI (POS)
  // sia quelli sui CORSI venduti (denaro o punti) — due silo diversi, ma
  // uno stesso venditore può avere target attivi di entrambi i tipi
  // contemporaneamente, mostrati come pannelli separati — vedi Target
  // Venditori in Impostazioni
  const targetAttiviVenditore = venditoreSel
    ? (targetVenditeProdotti || [])
        .filter((t) => t.soggetto_tipo === "venditore" && t.soggetto_id === venditoreSel.id && t.data_inizio <= oggiStr && t.data_fine >= oggiStr)
        .map((t) => ({
          t,
          avanzamento: TIPI_TARGET_CORSI.includes(t.tipo_target)
            ? calcolaAvanzamentoTargetCorsi(t, iscritti, venditoreSel.nome)
            : calcolaAvanzamentoTarget(t, venditeShop, prodottiShop),
        }))
    : [];
  const numeroDateProgrammazione = corsiDate.filter((cd) => cd.data_fine >= oggiStr).length;

  const range = useMemo(() => {
    const oggi = new Date();
    if (periodo === "mese") {
      return { inizio: fmtDataIso(new Date(oggi.getFullYear(), oggi.getMonth(), 1)), fine: fmtDataIso(new Date(oggi.getFullYear(), oggi.getMonth() + 1, 0)) };
    }
    // "Ultimi 3 mesi": finestra mobile che finisce oggi, non il trimestre
    // solare fisso (lug-set, ott-dic...) — stessa convenzione già usata
    // altrove nell'app per "trimestre"/"semestre" (vedi rangeRiepilogoPos)
    if (periodo === "trimestre") {
      return { inizio: fmtDataIso(new Date(oggi.getFullYear(), oggi.getMonth() - 3, oggi.getDate() + 1)), fine: fmtDataIso(oggi) };
    }
    return { inizio: customDa || oggiStr, fine: customA || oggiStr };
  }, [periodo, customDa, customA, oggiStr]);

  const rangeLabel = useMemo(() => {
    const [ay, am, ad] = range.inizio.split("-").map(Number);
    const [by, bm, bd] = range.fine.split("-").map(Number);
    if (am === bm && ay === by) return `${String(ad).padStart(2, "0")}–${String(bd).padStart(2, "0")} ${MESI_ABBR[am - 1]} ${ay}`;
    return `${String(ad).padStart(2, "0")} ${MESI_ABBR[am - 1]} ${ay} – ${String(bd).padStart(2, "0")} ${MESI_ABBR[bm - 1]} ${by}`;
  }, [range]);

  const corsoById = useMemo(() => Object.fromEntries(corsi.map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries(location.map((l) => [l.id, l])), [location]);
  const corsoDataById = useMemo(() => Object.fromEntries(corsiDate.map((cd) => [cd.id, cd])), [corsiDate]);

  // "chiusura" = un'iscrizione venduta da questo venditore, nel periodo
  // scelto (per data di iscrizione, cioè il giorno reale della vendita —
  // non la data del corso, che può essere mesi dopo). Le "vecchie
  // iscrizioni" (inserite oggi per recuperare dati di un'iscrizione
  // avvenuta tempo fa) sono sempre escluse: la loro data di inserimento
  // (oggi) non è la vera data della vendita, quindi non vanno mai
  // conteggiate come chiusura del mese/periodo corrente — stessa
  // esclusione già in uso per "Ultime iscrizioni" nelle Statistiche
  const chiusure = useMemo(() => {
    if (!venditoreSel) return [];
    const nomeNorm = venditoreSel.nome.trim().toUpperCase();
    return iscritti
      .filter((i) => (i.tutor || "").trim().toUpperCase() === nomeNorm)
      .filter((i) => !i.vecchia_iscrizione)
      .filter((i) => {
        const dataIscr = (i.ts || "").slice(0, 10);
        return dataIscr >= range.inizio && dataIscr <= range.fine;
      })
      .map((i) => ({ iscritto: i, corsoData: corsoDataById[i.corso_data_id] || null }));
  }, [iscritti, venditoreSel, range, corsoDataById]);

  const numeroChiusure = chiusure.length;
  const valoreVenduto = round2(chiusure.reduce((s, { iscritto }) => s + (iscritto.totale_pattuito || 0), 0));
  const ticketMedio = numeroChiusure > 0 ? round2(valoreVenduto / numeroChiusure) : 0;
  const commissioniGenerate = round2(chiusure.reduce((s, { iscritto }) => s + (iscritto.quota_venditore || 0), 0));

  // periodo immediatamente precedente a quello scelto, stessa durata:
  // mese prima se "Ultimo mese", altrimenti (trimestre mobile o
  // personalizzato) lo stesso numero di giorni appena prima dell'inizio
  // scelto — dà un confronto, non solo il numero assoluto. "Ultimi 3 mesi"
  // non ha un ramo suo: essendo già una finestra mobile di N giorni
  // (uguale a "personalizzato" nella forma), il calcolo generico qui sotto
  // produce da solo i 3 mesi immediatamente precedenti
  const rangePrecedente = useMemo(() => {
    const oggi = new Date();
    if (periodo === "mese") {
      return { inizio: fmtDataIso(new Date(oggi.getFullYear(), oggi.getMonth() - 1, 1)), fine: fmtDataIso(new Date(oggi.getFullYear(), oggi.getMonth(), 0)) };
    }
    const [ay, am, ad] = range.inizio.split("-").map(Number);
    const [by, bm, bd] = range.fine.split("-").map(Number);
    const inizioCorrente = new Date(ay, am - 1, ad);
    const fineCorrente = new Date(by, bm - 1, bd);
    const giorni = Math.round((fineCorrente - inizioCorrente) / 86400000) + 1;
    const finePrecedente = new Date(inizioCorrente);
    finePrecedente.setDate(finePrecedente.getDate() - 1);
    const inizioPrecedente = new Date(finePrecedente);
    inizioPrecedente.setDate(inizioPrecedente.getDate() - (giorni - 1));
    return { inizio: fmtDataIso(inizioPrecedente), fine: fmtDataIso(finePrecedente) };
  }, [periodo, range]);
  const etichettaPeriodoPrecedente = periodo === "mese" ? "Mese precedente" : periodo === "trimestre" ? "Tre mesi precedenti" : "Periodo precedente";
  const statsPrecedenti = useMemo(() => {
    if (!venditoreSel) return { count: 0, commissioni: 0 };
    const nomeNorm = venditoreSel.nome.trim().toUpperCase();
    const righeNormali = iscritti
      .filter((i) => (i.tutor || "").trim().toUpperCase() === nomeNorm)
      .filter((i) => !i.vecchia_iscrizione)
      .filter((i) => {
        const d = (i.ts || "").slice(0, 10);
        return d >= rangePrecedente.inizio && d <= rangePrecedente.fine;
      });
    // solo guardando "Ultimi 3 mesi": le vecchie iscrizioni (vendite reali
    // recuperate a posteriori, la cui vera data non è databile con certezza)
    // vanno TUTTE nel periodo di confronto, mai in quello corrente — così
    // gli ultimi 3 mesi in corso restano un dato pulito e il recupero
    // storico non sparisce, pesa solo sul raffronto storico. In "Ultimo mese" e
    // "Periodo personalizzato" restano escluse come sempre: una finestra
    // così stretta le farebbe risultare tutte concentrate nello stesso
    // mese di inserimento, un artefatto del recupero dati, non una vendita
    const righeVecchie = periodo === "trimestre"
      ? iscritti.filter((i) => (i.tutor || "").trim().toUpperCase() === nomeNorm && i.vecchia_iscrizione)
      : [];
    const righe = [...righeNormali, ...righeVecchie];
    return { count: righe.length, commissioni: righe.reduce((s, i) => s + (i.quota_venditore || 0), 0) };
  }, [iscritti, venditoreSel, rangePrecedente, periodo]);
  const numeroChiusurePrecedenti = statsPrecedenti.count;

  // "Performance" = commissione media per chiusura (somma commissioni /
  // numero chiusure), col confronto in % rispetto allo stesso valore nel
  // periodo precedente — niente più fasce fisse Alta/Media/Bassa, il
  // numero e la sua variazione parlano da soli
  const commissioneMediaVenditore = numeroChiusure > 0 ? commissioniGenerate / numeroChiusure : 0;
  const commissioneMediaPrecedente = statsPrecedenti.count > 0 ? statsPrecedenti.commissioni / statsPrecedenti.count : 0;
  const variazionePerformance = numeroChiusure > 0 && commissioneMediaPrecedente > 0
    ? Math.round(((commissioneMediaVenditore - commissioneMediaPrecedente) / commissioneMediaPrecedente) * 100)
    : null;
  // "Da incassare"/"Commissioni in arrivo": indipendenti dal "Periodo di
  // analisi" scelto sopra E dal flag "vecchia iscrizione" — una commissione
  // è dovuta appena il corso finisce, non importa quando né in quale
  // finestra di analisi è stata registrata la vendita. Guarda quindi TUTTE
  // le vendite di questo venditore, non solo "chiusure" (che resta filtrata
  // per periodo e vendite reali, per le tile di performance qui sopra)
  const tutteLeVenditeVenditore = useMemo(() => {
    if (!venditoreSel) return [];
    const nomeNorm = venditoreSel.nome.trim().toUpperCase();
    return iscritti
      .filter((i) => (i.tutor || "").trim().toUpperCase() === nomeNorm)
      .map((i) => ({ iscritto: i, corsoData: corsoDataById[i.corso_data_id] || null }));
  }, [iscritti, venditoreSel, corsoDataById]);
  // la commissione diventa incassabile da sola alla fine del corso (stessa
  // logica già usata per "Archivio corsi", nessun interruttore manuale):
  // finché il corso non è concluso resta "in arrivo"
  const chiusureInAttesa = tutteLeVenditeVenditore.filter(({ corsoData }) => corsoData && corsoData.data_fine >= oggiStr);
  const daIncassare = round2(chiusureInAttesa.reduce((s, { iscritto }) => s + (iscritto.quota_venditore || 0), 0));
  const dataUltimaScadenza = chiusureInAttesa.reduce((max, { corsoData }) => (!max || corsoData.data_fine > max ? corsoData.data_fine : max), null);
  const corsiInAttesaCount = new Set(chiusureInAttesa.map(({ corsoData }) => corsoData?.id)).size;

  const perCorso = {};
  chiusure.forEach(({ iscritto, corsoData }) => {
    const nomeCorso = corsoData ? (corsoById[corsoData.corso_id]?.nome || "—") : "—";
    perCorso[nomeCorso] = (perCorso[nomeCorso] || 0) + 1;
  });
  const righeChiusurePerCorso = Object.entries(perCorso).sort((a, b) => b[1] - a[1]);
  const maxChiusurePerCorso = Math.max(1, ...righeChiusurePerCorso.map(([, n]) => n));

  // dettaglio di "Chiusure per corso": per ogni corso-tipo, quante
  // chiusure in ciascuna edizione (città + date) — mostrato solo quando
  // si espande, per non appesantire la vista compatta di default
  const perCorsoEdizioni = {};
  chiusure.forEach(({ corsoData }) => {
    if (!corsoData) return;
    const nomeCorso = corsoById[corsoData.corso_id]?.nome || "—";
    if (!perCorsoEdizioni[nomeCorso]) perCorsoEdizioni[nomeCorso] = {};
    if (!perCorsoEdizioni[nomeCorso][corsoData.id]) perCorsoEdizioni[nomeCorso][corsoData.id] = { corsoData, totale: 0 };
    perCorsoEdizioni[nomeCorso][corsoData.id].totale += 1;
  });
  function edizioniDi(nomeCorso) {
    return Object.values(perCorsoEdizioni[nomeCorso] || {}).sort((a, b) => a.corsoData.data_inizio.localeCompare(b.corsoData.data_inizio));
  }

  const perEdizione = {};
  chiusureInAttesa.forEach(({ iscritto, corsoData }) => {
    if (!corsoData) return;
    if (!perEdizione[corsoData.id]) perEdizione[corsoData.id] = { corsoData, totale: 0 };
    perEdizione[corsoData.id].totale += iscritto.quota_venditore || 0;
  });
  const commissioniInArrivo = Object.values(perEdizione).sort((a, b) => a.corsoData.data_fine.localeCompare(b.corsoData.data_fine));

  // "Specializzazione di vendita": su quali corsi il venditore chiude di
  // più, calcolato su TUTTO lo storico (non sul "Periodo di analisi" qui
  // sopra, che è per definizione una finestra corta) — include anche le
  // "vecchie iscrizioni", perché qui contano come vendita realmente
  // avvenuta di quel corso, a differenza delle statistiche "chiusure del
  // periodo" dove non vanno attribuite al mese di inserimento
  const specializzazione = useMemo(() => {
    if (!venditoreSel) return { righe: [], totale: 0 };
    const nomeNorm = venditoreSel.nome.trim().toUpperCase();
    const tutte = iscritti.filter((i) => (i.tutor || "").trim().toUpperCase() === nomeNorm);
    const perCorsoStorico = {};
    tutte.forEach((i) => {
      const cd = corsoDataById[i.corso_data_id];
      const nomeCorso = cd ? (corsoById[cd.corso_id]?.nome || "—") : "—";
      perCorsoStorico[nomeCorso] = (perCorsoStorico[nomeCorso] || 0) + 1;
    });
    const totale = tutte.length;
    const righe = Object.entries(perCorsoStorico)
      .map(([nome, n]) => ({ nome, n, pct: totale > 0 ? Math.round((n / totale) * 100) : 0 }))
      .sort((a, b) => b.n - a.n);
    return { righe, totale };
  }, [iscritti, venditoreSel, corsoDataById, corsoById]);

  // classifica del team: chiusure e ticket medio di TUTTI i venditori nel
  // mese scelto, indipendente dal "Periodo di analisi" qui sopra (che
  // riguarda solo la scheda personale) — il confronto con il mese
  // precedente è per posizione in classifica (chiusure) o per variazione %
  // del valore (ticket medio, ha senso confrontarlo come importo)
  const classifiche = useMemo(() => {
    function statsMese({ anno, mese }) {
      const inizio = fmtDataIso(new Date(anno, mese, 1));
      const fine = fmtDataIso(new Date(anno, mese + 1, 0));
      const inPeriodo = iscritti.filter((i) => !i.vecchia_iscrizione && (i.ts || "").slice(0, 10) >= inizio && (i.ts || "").slice(0, 10) <= fine);
      return statsVenditoriPerPeriodo(inPeriodo, venditori);
    }
    const corrente = statsMese(meseClassifica);
    const mesePrecObj = meseClassifica.mese === 0 ? { anno: meseClassifica.anno - 1, mese: 11 } : { anno: meseClassifica.anno, mese: meseClassifica.mese - 1 };
    const precedente = statsMese(mesePrecObj);

    const corsiRanked = rankCorsiConTrend(corrente, precedente);
    const { righe: performanceRanked, mediaPerformance } = rankPerformanceConTrend(corrente, precedente);
    const mediaCorsi = corrente.length > 0 ? round2(corrente.reduce((s, r) => s + r.corsi, 0) / corrente.length) : 0;

    return { corsi: corsiRanked, performance: performanceRanked, mediaCorsi, mediaPerformance };
  }, [iscritti, venditori, meseClassifica]);
  const etichettaMeseClassifica = `${MESI[meseClassifica.mese].toUpperCase()} ${meseClassifica.anno}`;
  const meseClassificaFuturo = (() => { const o = new Date(); return meseClassifica.anno > o.getFullYear() || (meseClassifica.anno === o.getFullYear() && meseClassifica.mese >= o.getMonth()); })();

  if (mostraRiepilogoPos && venditoreSel) {
    return <PaginaRiepilogoVenditeProdotti soggettoTipo="venditore" soggettoId={venditoreSel.id} nomeSoggetto={venditoreSel.nome} venditeShop={venditeShop} onBack={() => setMostraRiepilogoPos(false)} />;
  }

  return (
    <div style={{ background: "transparent", minHeight: "100vh", padding: isMobile ? "24px 16px 60px" : "32px 28px 60px" }}>
      <div style={{ maxWidth: 1100, margin: "0 auto" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 4 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
            <TastoLivelloPrecedente titolo="Home" onClick={onBack} />
            <div style={{ ...fontDisplay, fontSize: 28, fontWeight: 700, color: NAVY }}>
              {venditoreSel ? `Dashboard ${toTitleCase(venditoreSel.nome)}` : titolo}
            </div>
          </div>
          {venditoreBloccato ? null : (
            <select style={{ ...inputStyle, width: "auto", minWidth: 220 }} value={venditoreSelId} onChange={(e) => setVenditoreSelId(e.target.value)}>
              <option value="">— scegli venditore —</option>
              {venditori.map((v) => <option key={v.id} value={v.id}>{v.nome.toUpperCase()}</option>)}
            </select>
          )}
        </div>
        {venditoreSel && <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginBottom: 18 }}>Area venditore</div>}

        {!venditoreSel ? (
          <div style={{ ...cardStyle, textAlign: "center", padding: 40, color: MUTED, ...fontBody, fontSize: 14 }}>Scegli un venditore per vedere le sue chiusure e commissioni.</div>
        ) : (
          <>
            <div style={{ display: "flex", flexDirection: "row", background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 16, marginBottom: 20, overflow: "hidden" }}>
              <button
                onClick={() => setTabDashboardVenditore("corsi")}
                style={{ flex: 1, minWidth: 0, textAlign: isMobile ? "center" : "left", background: "none", border: "none", borderRight: `1px solid ${CREAM_BORDER}`, cursor: "pointer", padding: isMobile ? "14px 6px" : "20px 22px", display: "flex", flexDirection: isMobile ? "column" : "row", alignItems: "center", gap: isMobile ? 8 : 16 }}
              >
                <div style={{ width: isMobile ? 44 : 52, height: isMobile ? 44 : 52, borderRadius: "50%", background: "#F1ECDF", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <IconaPersonaAggiungi size={isMobile ? 20 : 24} color={GOLD} />
                </div>
                <div style={{ minWidth: 0 }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: isMobile ? "center" : "flex-start", flexDirection: isMobile ? "column" : "row", gap: isMobile ? 4 : 8 }}>
                    <div style={{ ...fontDisplay, fontSize: isMobile ? 13 : 16, fontWeight: 700, lineHeight: isMobile ? 1.15 : undefined, color: tabDashboardVenditore === "corsi" ? NAVY : MUTED }}>Iscrivi Allievo</div>
                    <span style={{ ...fontBody, fontSize: isMobile ? 11 : 12, fontWeight: 600, color: NAVY, background: BG, borderRadius: 20, padding: "2px 10px", whiteSpace: "nowrap" }}>{numeroDateProgrammazione} date</span>
                  </div>
                  {!isMobile && <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginTop: 2, fontStyle: "italic" }}>Tutti i corsi in programmazione</div>}
                </div>
              </button>
              <button
                onClick={() => setTabDashboardVenditore("performance")}
                style={{ flex: 1, minWidth: 0, textAlign: isMobile ? "center" : "left", background: "none", border: "none", borderRight: `1px solid ${CREAM_BORDER}`, cursor: "pointer", padding: isMobile ? "14px 6px" : "20px 22px", display: "flex", flexDirection: isMobile ? "column" : "row", alignItems: "center", gap: isMobile ? 8 : 16 }}
              >
                <div style={{ width: isMobile ? 44 : 52, height: isMobile ? 44 : 52, borderRadius: "50%", background: "#F1ECDF", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <IconaFrecciaTrend size={isMobile ? 20 : 24} color={GOLD} />
                </div>
                <div style={{ minWidth: 0 }}>
                  <div style={{ ...fontDisplay, fontSize: isMobile ? 13 : 16, fontWeight: 700, lineHeight: isMobile ? 1.15 : undefined, color: tabDashboardVenditore === "performance" ? NAVY : MUTED }}>Performance di vendita</div>
                  {!isMobile && <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginTop: 2 }}>Chiusure e commissioni</div>}
                </div>
              </button>
              <button
                onClick={() => setTabDashboardVenditore("iscrizioni")}
                style={{ flex: 1, minWidth: 0, textAlign: isMobile ? "center" : "left", background: "none", border: "none", cursor: "pointer", padding: isMobile ? "14px 6px" : "20px 22px", display: "flex", flexDirection: isMobile ? "column" : "row", alignItems: "center", gap: isMobile ? 8 : 16 }}
              >
                <div style={{ width: isMobile ? 44 : 52, height: isMobile ? 44 : 52, borderRadius: "50%", background: "#F1ECDF", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <IconaLaureaErp size={isMobile ? 20 : 24} color={GOLD} />
                </div>
                <div style={{ minWidth: 0 }}>
                  <div style={{ ...fontDisplay, fontSize: isMobile ? 13 : 16, fontWeight: 700, lineHeight: isMobile ? 1.15 : undefined, color: tabDashboardVenditore === "iscrizioni" ? NAVY : MUTED }}>Le tue iscrizioni</div>
                  {!isMobile && <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginTop: 2 }}>Gli allievi che hai iscritto</div>}
                </div>
              </button>
            </div>

            {tabDashboardVenditore === "performance" && (
            <>
            {targetAttiviVenditore.length > 0 && (
              <div style={{ marginBottom: 24 }}>
                <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Target vendite prodotti</div>
                <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginBottom: 12 }}>Vendite al POS — dato separato dalle chiusure corsi qui sotto.</div>
                {targetAttiviVenditore.map(({ t, avanzamento }) => <PannelloTarget key={t.id} t={t} avanzamento={avanzamento} />)}
              </div>
            )}
            <div style={{ marginBottom: 20 }}>
              <Button variant="ghost" onClick={() => setMostraRiepilogoPos(true)}>Riepilogo vendita prodotti</Button>
            </div>
            <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.6, marginBottom: 8 }}>Periodo di analisi</div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 16 }}>
              <div style={{ display: "flex", background: BG, borderRadius: 20, padding: 4, gap: 2 }}>
                {[["mese", "Ultimo mese"], ["trimestre", "Ultimi 3 mesi"], ["personalizzato", "Periodo personalizzato"]].map(([v, l]) => (
                  <button key={v} onClick={() => setPeriodo(v)} style={{ ...fontBody, fontSize: 13, fontWeight: 600, padding: "8px 14px", borderRadius: 16, border: "none", background: periodo === v ? NAVY : "transparent", color: periodo === v ? "#fff" : NAVY, cursor: "pointer" }}>{l}</button>
                ))}
              </div>
              {periodo === "personalizzato" ? (
                <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                  <input type="date" style={inputStyle} value={customDa} onChange={(e) => setCustomDa(e.target.value)} />
                  <span style={{ color: MUTED }}>–</span>
                  <input type="date" style={inputStyle} value={customA} onChange={(e) => setCustomA(e.target.value)} />
                </div>
              ) : (
                <div style={{ ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 20, padding: "8px 14px" }}>{rangeLabel}</div>
              )}
            </div>

            <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY, marginBottom: 2 }}>Chiusure e commissioni</div>
            <div style={{ ...fontBody, fontSize: 11.5, color: MUTED, marginBottom: 12 }}>Le "vecchie iscrizioni" (recuperate a posteriori) non contano mai come chiusura del periodo corrente.</div>
            <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr 1fr" : "repeat(5, minmax(0,1fr))", gap: 14, marginBottom: 18 }}>
              <div style={{ ...cardStyle, marginBottom: 0 }}>
                <div style={{ ...fontBody, fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>Chiusure</div>
                <div style={{ ...fontDisplay, fontSize: 26, fontWeight: 700, color: NAVY }}>{numeroChiusure}</div>
                <div style={{ ...fontBody, fontSize: 11, color: MUTED, marginTop: 2 }}>{etichettaPeriodoPrecedente}: {numeroChiusurePrecedenti}</div>
              </div>
              <div style={{ ...cardStyle, marginBottom: 0 }}>
                <div style={{ ...fontBody, fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>Commissione media</div>
                <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                  <div style={{ ...fontDisplay, fontSize: 26, fontWeight: 700, color: NAVY }}>{numeroChiusure > 0 ? fmtEuroErp(round2(commissioneMediaVenditore)) : "—"}</div>
                  {variazionePerformance !== null && (
                    <div style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: variazionePerformance >= 0 ? "#2E7D32" : "#C0392B" }}>
                      {variazionePerformance >= 0 ? `+${variazionePerformance}%` : `${variazionePerformance}%`}
                    </div>
                  )}
                </div>
              </div>
              <div style={{ ...cardStyle, marginBottom: 0 }}>
                <div style={{ ...fontBody, fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>Ticket medio</div>
                <div style={{ ...fontDisplay, fontSize: 26, fontWeight: 700, color: NAVY }}>{fmtEuroErp(ticketMedio)}</div>
                <div style={{ ...fontBody, fontSize: 11, color: MUTED, marginTop: 2 }}>valore venduto / chiusure</div>
              </div>
              <div style={{ ...cardStyle, marginBottom: 0 }}>
                <div style={{ ...fontBody, fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>Commissioni generate</div>
                <div style={{ ...fontDisplay, fontSize: 26, fontWeight: 700, color: NAVY }}>{fmtEuroErp(commissioniGenerate)}</div>
              </div>
              <div style={{ ...cardStyle, marginBottom: 0, background: "#FBF3E4", border: `1px solid ${GOLD}` }}>
                <div style={{ ...fontBody, fontSize: 11, color: "#8A6D1D", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>
                  Da incassare{dataUltimaScadenza ? ` entro il ${fmtData(dataUltimaScadenza)}` : ""}
                </div>
                <div style={{ ...fontDisplay, fontSize: 26, fontWeight: 700, color: "#8A6D1D" }}>{fmtEuroErp(daIncassare)}</div>
                {corsiInAttesaCount > 0 && <div style={{ ...fontBody, fontSize: 11, color: "#8A6D1D" }}>quando terminano {corsiInAttesaCount} cors{corsiInAttesaCount === 1 ? "o" : "i"}</div>}
              </div>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: 14, marginBottom: 4 }}>
              <div style={cardStyle}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 12, gap: 10 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY }}>Chiusure per corso</div>
                    {righeChiusurePerCorso.length > 0 && (
                      <button
                        onClick={() => setEspansoChiusurePerCorso((v) => !v)}
                        title={espansoChiusurePerCorso ? "Comprimi il dettaglio" : "Espandi il dettaglio per edizione"}
                        style={{ width: 22, height: 22, borderRadius: "50%", border: `1px solid ${CREAM_BORDER}`, background: "#fff", color: NAVY, fontSize: 14, fontWeight: 700, lineHeight: 1, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
                      >
                        {espansoChiusurePerCorso ? "−" : "+"}
                      </button>
                    )}
                  </div>
                  <div style={{ ...fontBody, fontSize: 12, color: MUTED }}>{numeroChiusure} chiusure</div>
                </div>
                {righeChiusurePerCorso.length === 0 && <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessuna chiusura nel periodo.</div>}
                {righeChiusurePerCorso.map(([nome, n]) => (
                  <div key={nome} style={{ marginBottom: 10 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 13, color: NAVY, marginBottom: 4 }}>
                      <span>{nome}</span><span>{n}</span>
                    </div>
                    <div style={{ height: 6, background: BG, borderRadius: 3, overflow: "hidden" }}>
                      <div style={{ height: "100%", width: `${(n / maxChiusurePerCorso) * 100}%`, background: NAVY, borderRadius: 3 }} />
                    </div>
                    {espansoChiusurePerCorso && (
                      <div style={{ marginTop: 6, paddingLeft: 4 }}>
                        {edizioniDi(nome).map(({ corsoData, totale }) => (
                          <div key={corsoData.id} style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 12, color: MUTED, padding: "3px 0" }}>
                            <span>{toTitleCase(locById[corsoData.location_id]?.nome || "—")} · {fmtDataCompatta(corsoData.data_inizio, corsoData.data_fine)}</span>
                            <span>n. {totale}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
              <div style={cardStyle}>
                <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY, marginBottom: 12 }}>Commissioni in arrivo</div>
                {commissioniInArrivo.length === 0 && <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessuna commissione ancora in arrivo.</div>}
                {commissioniInArrivo.map(({ corsoData, totale }) => (
                  <div key={corsoData.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderTop: `1px solid ${CREAM_BORDER}` }}>
                    <div style={{ width: 8, height: 8, borderRadius: "50%", background: GOLD, flexShrink: 0 }} />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY }}>{fmtData(corsoData.data_fine)} · {corsoById[corsoData.corso_id]?.nome || "—"}</div>
                      <div style={{ ...fontBody, fontSize: 11.5, color: MUTED }}>{locById[corsoData.location_id]?.nome || "—"} · a fine corso</div>
                    </div>
                    <div style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY, flexShrink: 0 }}>{fmtEuroErp(round2(totale))}</div>
                  </div>
                ))}
                {commissioniInArrivo.length > 0 && (
                  <div style={{ display: "flex", justifyContent: "space-between", marginTop: 10, paddingTop: 10, borderTop: `1px solid ${CREAM_BORDER}`, ...fontBody, fontSize: 13, fontWeight: 700, color: NAVY }}>
                    <span>Totale in arrivo</span><span>{fmtEuroErp(daIncassare)}</span>
                  </div>
                )}
              </div>
            </div>
            <div style={{ ...fontBody, fontSize: 11.5, color: MUTED, marginTop: 8, marginBottom: 24 }}>Le commissioni diventano incassabili alla data di conclusione del corso.</div>

            {specializzazione.totale > 0 && (
              <>
              <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 12 }}>
                <div>
                  <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY }}>Specializzazione di vendita</div>
                  <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>I corsi che {toTitleCase((venditoreSel.nome.trim().split(/\s+/)[0] || ""))} vende di più nel lungo periodo</div>
                </div>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end" }}>
                  <div style={{ ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 20, padding: "8px 14px", display: "flex", alignItems: "center", gap: 6 }}>
                    Storico completo <IconaChevronGiuErp size={12} color={MUTED} />
                  </div>
                  <div style={{ ...fontBody, fontSize: 11, color: MUTED, marginTop: 4 }}>Dall'inizio dell'attività</div>
                </div>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: 14, marginBottom: 24 }}>
                <div style={cardStyle}>
                  <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY, marginBottom: 16 }}>Classifica per corsi venduti</div>
                  {specializzazione.righe.slice(0, 5).map((r, i) => (
                    <div key={r.nome} style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: i < Math.min(4, specializzazione.righe.length - 1) ? 16 : 0 }}>
                      <div style={{ ...fontDisplay, fontSize: 20, fontWeight: 700, color: i === 0 ? GOLD : MUTED, width: 20, textAlign: "center", flexShrink: 0 }}>{i + 1}</div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8, marginBottom: 6 }}>
                          <span style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{toTitleCase(r.nome)}</span>
                          <span style={{ ...fontBody, fontSize: 12, color: MUTED, flexShrink: 0, whiteSpace: "nowrap" }}>{r.n} vendite  <b style={{ color: NAVY }}>{r.pct}%</b></span>
                        </div>
                        <div style={{ height: 6, background: BG, borderRadius: 3, overflow: "hidden" }}>
                          <div style={{ height: "100%", width: `${(r.n / specializzazione.righe[0].n) * 100}%`, background: i === 0 ? GOLD : NAVY, borderRadius: 3 }} />
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                <div style={{ ...cardStyle, background: "#FBF3E4", border: `1px solid ${GOLD}` }}>
                  <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: "#8A6D1D", textTransform: "uppercase", letterSpacing: 0.6, marginBottom: 10 }}>Specializzazione principale</div>
                  <div style={{ ...fontDisplay, fontSize: 22, fontWeight: 700, color: NAVY, marginBottom: 6 }}>{toTitleCase(specializzazione.righe[0].nome)}</div>
                  <div style={{ ...fontBody, fontSize: 12.5, color: "#8A6D1D", marginBottom: 14 }}>1 vendita su {Math.max(1, Math.round(specializzazione.totale / specializzazione.righe[0].n))} riguarda questo corso</div>
                  <div style={{ ...fontDisplay, fontSize: 34, fontWeight: 700, color: GOLD, marginBottom: 2 }}>{specializzazione.righe[0].pct}%</div>
                  <div style={{ ...fontBody, fontSize: 12, color: "#8A6D1D", marginBottom: 16 }}>del totale storico</div>
                  {specializzazione.righe[1] && (
                    <div style={{ borderTop: "1px solid rgba(201,162,109,0.35)", paddingTop: 12, marginBottom: 14 }}>
                      <div style={{ ...fontBody, fontSize: 11, color: "#8A6D1D", marginBottom: 4 }}>Seconda specializzazione</div>
                      <div style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY }}>{toTitleCase(specializzazione.righe[1].nome)} · {specializzazione.righe[1].pct}%</div>
                    </div>
                  )}
                  <div style={{ borderTop: "1px solid rgba(201,162,109,0.35)", paddingTop: 12 }}>
                    <div style={{ ...fontBody, fontSize: 11, color: "#8A6D1D", marginBottom: 4 }}>Totale storico</div>
                    <div style={{ ...fontDisplay, fontSize: 22, fontWeight: 700, color: NAVY }}>{specializzazione.totale} corsi venduti</div>
                    <div style={{ ...fontBody, fontSize: 11, color: "#8A6D1D", marginTop: 4 }}>Calcolato su tutte le chiusure registrate</div>
                  </div>
                </div>
              </div>
              </>
            )}

            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 4 }}>
              <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY }}>Classifiche venditori</div>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <button
                  onClick={() => setMeseClassifica((m) => (m.mese === 0 ? { anno: m.anno - 1, mese: 11 } : { anno: m.anno, mese: m.mese - 1 }))}
                  title="Mese precedente"
                  style={{ background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: NAVY }}
                ><IconaFrecciaSinistra size={14} /></button>
                <div style={{ ...fontBody, fontSize: 13, fontWeight: 700, color: NAVY, minWidth: 120, textAlign: "center" }}>{etichettaMeseClassifica}</div>
                <button
                  onClick={() => setMeseClassifica((m) => (m.mese === 11 ? { anno: m.anno + 1, mese: 0 } : { anno: m.anno, mese: m.mese + 1 }))}
                  title="Mese successivo"
                  disabled={meseClassificaFuturo}
                  style={{ background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center", cursor: meseClassificaFuturo ? "default" : "pointer", color: meseClassificaFuturo ? MUTED : NAVY, opacity: meseClassificaFuturo ? 0.4 : 1, transform: "rotate(180deg)" }}
                ><IconaFrecciaSinistra size={14} /></button>
              </div>
            </div>
            <div style={{ ...fontBody, fontSize: 11.5, color: MUTED, marginBottom: 12 }}>Aggiornate in tempo reale</div>
            <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: 14, marginBottom: 24 }}>
              <ColonnaClassifica
                titolo="Corsi venduti" sottotitolo="Numero di chiusure nel mese"
                righe={classifiche.corsi} chiaveValore="corsi" tipoTrend="posizioni"
                etichettaMedia={`${classifiche.mediaCorsi} corsi`}
                formatValore={(v) => String(v)}
                venditoreSelId={venditoreSel?.id}
                mostraTutti={classificaCorsiCompleta} onToggleMostraTutti={() => setClassificaCorsiCompleta((v) => !v)}
              />
              <ColonnaClassifica
                titolo="Performance" sottotitolo="Ticket medio corretto per il volume di vendite"
                righe={classifiche.performance} chiaveValore="performance" tipoTrend="posizioni"
                etichettaMedia={`${classifiche.mediaPerformance} pt`}
                formatValore={(v) => String(Math.round(v))}
                coloreValore={coloreScorePerformance}
                venditoreSelId={venditoreSel?.id}
                mostraTutti={classificaTicketCompleta} onToggleMostraTutti={() => setClassificaTicketCompleta((v) => !v)}
              />
            </div>
            </>
            )}

            {tabDashboardVenditore === "corsi" && (
              <SezioneDateCorsi
                titolo="Iscrivi Allievo"
                corsi={corsi} location={location} corsiDate={corsiDate} iscritti={iscritti} master={master}
                ricarica={ricarica} onApriData={apriData}
                filtroCorsoHome={filtroCorsoHome} setFiltroCorsoHome={setFiltroCorsoHome}
                filtroCittaHome={filtroCittaHome} setFiltroCittaHome={setFiltroCittaHome}
                filtroMasterHome={filtroMasterHome} setFiltroMasterHome={setFiltroMasterHome}
                cronologicoHome={cronologicoHome} setCronologicoHome={setCronologicoHome}
                apriFiltroCorsoHome={apriFiltroCorsoHome} setApriFiltroCorsoHome={setApriFiltroCorsoHome}
                apriFiltroCittaHome={apriFiltroCittaHome} setApriFiltroCittaHome={setApriFiltroCittaHome}
                apriFiltroMasterHome={apriFiltroMasterHome} setApriFiltroMasterHome={setApriFiltroMasterHome}
                selectFiltroCorsoHomeRef={selectFiltroCorsoHomeRef} selectFiltroCittaHomeRef={selectFiltroCittaHomeRef} selectFiltroMasterHomeRef={selectFiltroMasterHomeRef}
                registraInterceptaIndietro={registraInterceptaIndietro}
              />
            )}
            {tabDashboardVenditore === "iscrizioni" && (
              <LeTueIscrizioni
                corsi={corsi} location={location} corsiDate={corsiDate} iscritti={iscritti}
                venditoreNome={venditoreSel?.nome} onApriIscritto={onApriIscritto} ricarica={ricarica}
              />
            )}
          </>
        )}
      </div>
    </div>
  );
}

// ---------- Dashboard master ----------
// riquadro data compatto per CardDataMaster: un solo giorno "19", un
// intervallo nello stesso mese "17-19", un intervallo a cavallo di due
// mesi "28 ago-2 set" — mai solo il primo giorno, la master deve
// vedere a colpo d'occhio quanto dura il corso
function etichettaIntervalloGiorni(dataInizio, dataFine) {
  const [, meseI, ggI] = dataInizio.split("-").map(Number);
  const [, meseF, ggF] = dataFine.split("-").map(Number);
  if (dataInizio === dataFine) return { numero: String(ggI), sotto: MESI_ABBR[meseI - 1] };
  if (meseI === meseF) return { numero: `${ggI}-${ggF}`, sotto: MESI_ABBR[meseI - 1] };
  return { numero: `${ggI} ${MESI_ABBR[meseI - 1]}-${ggF} ${MESI_ABBR[meseF - 1]}`, sotto: "" };
}
// una data assegnata alla master: stesso stile a card delle schede di
// Logistica prodotti (bordo e riquadro data nel colore del corso), con
// allievi/kit previsti, sede del corso e dati di viaggio (biglietti +
// alloggio, con link ai biglietti già caricati da "Assegnazione
// Master", stesso file, stesso bucket "allegati-iscritti" — qui è solo
// in lettura, il caricamento resta un compito di chi gestisce
// l'assegnazione)
function CardDataMaster({ corsoData, corso, loc, hotelAssociato, iscrittiEdizione, apribile, onApriInventario, onApriClasse, codiceReferral }) {
  const biglietti = corsoData.viaggio_file || [];
  const statoViaggio = VIAGGIO_STATI[corsoData.viaggio_stato || "no"];
  const coloreCorso = corso?.colore || NAVY;
  const { numero, sotto } = etichettaIntervalloGiorni(corsoData.data_inizio, corsoData.data_fine);
  // "IN CORSO" mentre si svolge, "Appena terminato" nei 5 giorni dopo la
  // fine — la master deve accorgersi a colpo d'occhio del corso attivo
  // o appena chiuso, senza dover guardare le date
  const oggiStr = dataOggiStr();
  const inCorso = oggiStr >= corsoData.data_inizio && oggiStr <= corsoData.data_fine;
  const appenaTerminato = !inCorso && oggiStr > corsoData.data_fine && oggiStr <= addGiorni(corsoData.data_fine, 5);
  // click sul corpo della card: apre la "classe" DENTRO l'app (elenco allievi
  // con kit e taglia + gestione modelle), così ha l'header con Indietro/Home.
  return (
    <div
      onClick={onApriClasse ? () => onApriClasse(corsoData.id) : undefined}
      style={{ border: `2px solid ${coloreCorso}`, borderLeftWidth: 6, borderRadius: 16, padding: 16, marginBottom: 14, background: "#fff", cursor: onApriClasse ? "pointer" : "default" }}
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
        <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
          <div style={{ background: coloreCorso, borderRadius: 12, padding: "10px 14px", textAlign: "center", flexShrink: 0 }}>
            <div style={{ ...fontDisplay, fontSize: numero.length > 5 ? 14 : 20, fontWeight: 700, color: "#fff", whiteSpace: "nowrap" }}>{numero}</div>
            {sotto && <div style={{ ...fontBody, fontSize: 10, fontWeight: 700, color: "#fff", textTransform: "uppercase" }}>{sotto}</div>}
          </div>
          <div>
            <div style={{ ...fontDisplay, fontSize: 19, fontWeight: 700, color: NAVY, lineHeight: 1.25 }}>{corso?.nome || "—"}</div>
            <div style={{ ...fontDisplay, fontSize: 17, fontWeight: 700, color: NAVY, lineHeight: 1.25 }}>{toTitleCase(loc?.nome || "—")}</div>
          </div>
        </div>
        {(inCorso || appenaTerminato) && (
          <div style={{ ...fontDisplay, fontSize: inCorso ? 28 : 19, fontWeight: 700, color: "#2E7D32", whiteSpace: "nowrap" }}>
            {inCorso ? "IN CORSO" : "Appena terminato"}
          </div>
        )}
      </div>

      <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${CREAM_BORDER}` }}>
        <div style={{ display: "flex", alignItems: "center", gap: 9, borderLeft: `3px solid ${GOLD}`, paddingLeft: 9, marginBottom: 6 }}>
          <span style={{ ...fontDisplay, fontSize: 22, fontWeight: 700, color: NAVY, lineHeight: 1 }}>{iscrittiEdizione.length}</span>
          <span style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.3 }}>Allievi totali</span>
        </div>
        <RiepilogoKitPacchetti iscrittiEdizione={iscrittiEdizione} mostraTotale={false} />
      </div>

      {loc && (
        <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${CREAM_BORDER}` }}>
          <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 4 }}>Sede del corso</div>
          <div style={{ ...fontBody, fontSize: 13.5, fontWeight: 700, color: NAVY }}>{loc.nome_sede ? toTitleCase(loc.nome_sede) : toTitleCase(loc.nome || "—")}</div>
          {(loc.indirizzo || loc.nome) && (
            <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginTop: 1 }}>
              {[loc.indirizzo, loc.nome_sede ? toTitleCase(loc.nome || "") : null].filter(Boolean).join(" · ")}
            </div>
          )}
          {loc.telefono && (
            <a href={`tel:${loc.telefono}`} onClick={(e) => e.stopPropagation()} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: NAVY, marginTop: 2, display: "inline-block" }}>{loc.telefono}</a>
          )}
        </div>
      )}

      <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${CREAM_BORDER}` }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
          <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.4 }}>Dati di viaggio</div>
          <div style={{ display: "flex", alignItems: "center", gap: 6, ...fontBody, fontSize: 12, fontWeight: 700, color: statoViaggio.colore }}>
            <span style={{ width: 8, height: 8, borderRadius: "50%", background: statoViaggio.colore }} />
            {statoViaggio.etichetta}
          </div>
        </div>

        {(biglietti.length > 0 || hotelAssociato) && (
          <>
          {biglietti.length > 0 && (
            <div style={{ marginBottom: hotelAssociato ? 12 : 0 }}>
              <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: GOLD, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>Biglietti scaricabili</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                {biglietti.map((percorso, i) => (
                  <span key={i} onClick={(e) => e.stopPropagation()} style={{ display: "inline-flex" }}>
                    <AllegatoLink percorso={percorso} etichetta={`Biglietto ${i + 1}`} />
                  </span>
                ))}
              </div>
            </div>
          )}

          {hotelAssociato && (
            <div>
              <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: GOLD, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>Alloggio</div>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
                <div>
                  <div style={{ ...fontBody, fontSize: 13.5, fontWeight: 700, color: NAVY }}>{toTitleCase(hotelAssociato.nome)}</div>
                  {(hotelAssociato.indirizzo || hotelAssociato.citta) && (
                    <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginTop: 1 }}>
                      {[hotelAssociato.indirizzo, hotelAssociato.civico].filter(Boolean).join(" ")}
                      {hotelAssociato.indirizzo && hotelAssociato.citta ? " · " : ""}
                      {hotelAssociato.citta ? toTitleCase(hotelAssociato.citta) : ""}
                    </div>
                  )}
                </div>
                {hotelAssociato.telefono && (
                  <div style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
                    <a href={`tel:${hotelAssociato.telefono}`} onClick={(e) => e.stopPropagation()} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: NAVY }}>{hotelAssociato.telefono}</a>
                    <a href={`https://wa.me/${numeroWhatsapp(hotelAssociato.telefono)}`} target="_blank" rel="noopener noreferrer" onClick={(e) => e.stopPropagation()} title="Contatta su WhatsApp" style={{ display: "flex" }}>
                      <IconaWhatsapp size={18} />
                    </a>
                  </div>
                )}
              </div>
            </div>
          )}
          </>
        )}
      </div>

      {(apribile || codiceReferral) && (
        <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${CREAM_BORDER}`, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
          {apribile ? (
            <div onClick={(e) => { e.stopPropagation(); onApriInventario(corsoData.id); }} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: GOLD, textTransform: "uppercase", letterSpacing: 0.4, cursor: "pointer" }}>
              Chiusura corso →
            </div>
          ) : <span />}
          {codiceReferral && (
            <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: "#EA580C" }} onClick={(e) => e.stopPropagation()}>
              Coupon code: {codiceReferral.toUpperCase()}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
// La classe vista dalla master: stessa card della dashboard — fondo bianco,
// bordo del colore del corso, targhetta della data in alto a sinistra — solo
// che dentro, al posto del riepilogo per kit, c'è l'elenco nome per nome.
// È la lista che la master si porta in aula: chi ha davanti, quale kit gli
// ha comprato e che taglia di divisa gli tocca. Niente cifre, niente
// pagamenti: quelli non la riguardano.
function PaginaClasseMaster({ corsoData, corso, loc, iscrittiEdizione, onApriModelle, onBack }) {
  const coloreCorso = corso?.colore || NAVY;
  // la pastiglia della taglia prende una velatura del colore del corso: due
  // cifre esadecimali di trasparenza in coda, che valgono solo se il colore
  // e' scritto in esadecimale a sei cifre (lo sono tutti in anagrafica)
  const esadecimale = /^#[0-9a-f]{6}$/i.test(coloreCorso);
  const tintaCorso = esadecimale ? `${coloreCorso}12` : "#F6F7F9";
  const bordoTinta = esadecimale ? `${coloreCorso}3A` : CREAM_BORDER;
  const { numero, sotto } = etichettaIntervalloGiorni(corsoData.data_inizio, corsoData.data_fine);
  const oggiStr = dataOggiStr();
  const inCorso = oggiStr >= corsoData.data_inizio && oggiStr <= corsoData.data_fine;
  const appenaTerminato = !inCorso && oggiStr > corsoData.data_fine && oggiStr <= addGiorni(corsoData.data_fine, 5);
  // in ordine alfabetico di cognome: è così che si chiama l'appello, non
  // nell'ordine in cui sono arrivate le iscrizioni
  const allievi = [...(iscrittiEdizione || [])].sort((a, b) =>
    `${a.cognome || ""} ${a.nome || ""}`.localeCompare(`${b.cognome || ""} ${b.nome || ""}`, "it")
  );

  // stessa riga del riepilogo per kit della dashboard, qui per un allievo
  // solo: il dermografo attaccato al kit, con dove lo riceve — chi prepara
  // la scatola e chi lo consegna in aula leggono la stessa frase
  function descrizioneKit(i) {
    if (!i.pacchetto_kit) return null;
    const modello = dermografoAcquistato(i);
    const suffisso = !modello ? ""
      : i.dermografo_consegna === "casa" ? ` + ${etichettaDermografo(modello)} già comprato e ricevuto`
      : i.dermografo_consegna === "corso" ? ` + ${etichettaDermografo(modello)} da ritirare al corso`
      : ` + ${etichettaDermografo(modello)}`;
    return `${i.pacchetto_kit}${suffisso}`;
  }

  return (
    <div style={{ maxWidth: 640, margin: "0 auto", padding: "4px 20px 30px" }}>
      <button onClick={onBack} title="Indietro" style={{ display: "flex", alignItems: "center", gap: 8, background: "transparent", border: "none", cursor: "pointer", color: NAVY, padding: 4, marginLeft: -4, marginBottom: 10 }}>
        <IconaFrecciaSinistra size={20} />
        <span style={{ ...fontBody, fontSize: 13, fontWeight: 700 }}>Torna alla dashboard</span>
      </button>

      <div style={{ border: `2px solid ${coloreCorso}`, borderLeftWidth: 6, borderRadius: 16, padding: 16, background: "#fff" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
          <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
            <div style={{ background: coloreCorso, borderRadius: 12, padding: "10px 14px", textAlign: "center", flexShrink: 0 }}>
              <div style={{ ...fontDisplay, fontSize: numero.length > 5 ? 14 : 20, fontWeight: 700, color: "#fff", whiteSpace: "nowrap" }}>{numero}</div>
              {sotto && <div style={{ ...fontBody, fontSize: 10, fontWeight: 700, color: "#fff", textTransform: "uppercase" }}>{sotto}</div>}
            </div>
            <div>
              <div style={{ ...fontDisplay, fontSize: 19, fontWeight: 700, color: NAVY, lineHeight: 1.25 }}>{corso?.nome || "—"}</div>
              <div style={{ ...fontDisplay, fontSize: 17, fontWeight: 700, color: NAVY, lineHeight: 1.25 }}>{toTitleCase(loc?.nome || "—")}</div>
            </div>
          </div>
          {(inCorso || appenaTerminato) && (
            <div style={{ ...fontDisplay, fontSize: inCorso ? 28 : 19, fontWeight: 700, color: "#2E7D32", whiteSpace: "nowrap" }}>
              {inCorso ? "IN CORSO" : "Appena terminato"}
            </div>
          )}
        </div>

        <div style={{ marginTop: 14, paddingTop: 18, borderTop: `1px solid ${CREAM_BORDER}` }}>
          {allievi.length === 0 ? (
            <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessun allievo iscritto.</div>
          ) : allievi.map((i, idx) => (
            <div key={i.id} style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap", padding: "12px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
              <div style={{ width: 26, height: 26, borderRadius: "50%", background: coloreCorso, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, ...fontBody, fontSize: 13, fontWeight: 700 }}>{idx + 1}</div>

              <div style={{ flex: "1 1 180px", minWidth: 0 }}>
                <div style={{ display: "flex", alignItems: "baseline", flexWrap: "wrap", gap: 8 }}>
                  <span style={{ ...fontBody, fontSize: 16, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.2 }}>
                    {`${i.nome || ""} ${i.cognome || ""}`.trim()}
                  </span>
                  {i.tutor && <span style={{ ...fontBody, fontSize: 13, color: GOLD }}>: tutor {toTitleCase(i.tutor)}</span>}
                </div>
                <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginTop: 1, lineHeight: 1.35 }}>
                  {descrizioneKit(i) || "Nessun kit"}
                </div>
              </div>

              <div style={{ display: "flex", alignItems: "center", gap: 12, flexShrink: 0, marginLeft: "auto" }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 7, width: 108, background: tintaCorso, border: `1px solid ${bordoTinta}`, borderRadius: 12, padding: "5px 8px" }}>
                  <IconaMaglietta size={14} color={coloreCorso} />
                  <span style={{ ...fontBody, fontSize: 12, fontWeight: 600, color: i.taglia_divisa ? NAVY : MUTED, whiteSpace: "nowrap" }}>Taglia {i.taglia_divisa || "—"}</span>
                </div>
                {i.telefono && (
                  <>
                    <span style={{ width: 1, alignSelf: "stretch", background: CREAM_BORDER }} />
                    <a href={`tel:${i.telefono.replace(/\s+/g, "")}`} style={{ ...fontBody, fontSize: 13, color: MUTED, textDecoration: "underline" }}>{i.telefono}</a>
                    <a href={`https://wa.me/${numeroWhatsapp(i.telefono)}`} target="_blank" rel="noopener noreferrer" title="Apri chat WhatsApp" style={{ display: "flex" }}>
                      <IconaWhatsapp size={20} />
                    </a>
                  </>
                )}
              </div>
            </div>
          ))}
        </div>

        {onApriModelle && (
          <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${CREAM_BORDER}` }}>
            <div onClick={onApriModelle} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: GOLD, textTransform: "uppercase", letterSpacing: 0.4, cursor: "pointer" }}>
              Gestione modelle →
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
// range di periodo per "Riepilogo vendita prodotti": stessa idea dei
// periodi già usati altrove nell'ERP, con "Anno accademico" che segue la
// stessa convenzione settembre→agosto di annoStagioneDaData/stagioneCorrente
function rangeRiepilogoPos(periodo, customDa, customA) {
  const oggi = new Date();
  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  if (periodo === "mese") return { inizio: fmt(new Date(oggi.getFullYear(), oggi.getMonth() - 1, oggi.getDate() + 1)), fine: fmt(oggi) };
  if (periodo === "trimestre") return { inizio: fmt(new Date(oggi.getFullYear(), oggi.getMonth() - 3, oggi.getDate() + 1)), fine: fmt(oggi) };
  if (periodo === "seimesi") return { inizio: fmt(new Date(oggi.getFullYear(), oggi.getMonth() - 6, oggi.getDate() + 1)), fine: fmt(oggi) };
  if (periodo === "annoaccademico") { const s = stagioneCorrente(); return { inizio: `${s}-09-01`, fine: `${s + 1}-08-31` }; }
  return { inizio: customDa || fmt(oggi), fine: customA || fmt(oggi) };
}
// "Riepilogo Vendita prodotti": lo storico personale delle vendite POS di
// UNA master o UN venditore (mai aggregato — quello è "Statistiche Vendite
// Prodotti" in ERP, riservata all'admin), con filtro periodo, in ordine
// cronologico di default
function PaginaRiepilogoVenditeProdotti({ soggettoTipo, soggettoId, nomeSoggetto, venditeShop, onBack }) {
  const { ordine, cambiaOrdine, ordina } = useOrdinamentoTabella();
  const isMobile = useIsMobile();
  const [periodo, setPeriodo] = useState("mese");
  const [customDa, setCustomDa] = useState("");
  const [customA, setCustomA] = useState("");
  const [ordineCronologico, setOrdineCronologico] = useState(true); // true = dal più vecchio (default richiesto), false = dal più recente

  const range = rangeRiepilogoPos(periodo, customDa, customA);
  const righe = (venditeShop || [])
    .filter((v) => v.origine === "pos" && v.operatore_tipo === soggettoTipo && v.operatore_id === soggettoId)
    .filter((v) => { const d = v.data_ordine ? v.data_ordine.slice(0, 10) : null; return d && d >= range.inizio && d <= range.fine; })
    .sort((a, b) => ordineCronologico ? (a.data_ordine || "").localeCompare(b.data_ordine || "") : (b.data_ordine || "").localeCompare(a.data_ordine || ""));

  // gli omaggi restano visibili nell'elenco (trasparenza), ma non contano
  // come pezzi venduti nel KPI personale — regalare non è vendere
  const kpi = {
    incasso: round2(righe.reduce((s, v) => s + (v.totale || 0), 0)),
    pezzi: righe.filter((v) => v.tipo_movimento !== "omaggio").reduce((s, v) => s + (Array.isArray(v.prodotti) ? v.prodotti.reduce((ss, p) => ss + (p.quantita || 0), 0) : 0), 0),
  };
  const badgeTipo = { vendita: { l: "Vendita", c: "#2E7D32", s: "#E3F3E5" }, reso: { l: "Reso", c: "#B8860B", s: "#FBF1D9" }, annullamento: { l: "Annullato", c: "#C0392B", s: "#FBE4E1" }, cambio: { l: "Cambio", c: "#3B6FA0", s: "#E7EEF5" }, omaggio: { l: "Omaggio", c: GOLD, s: "#FBF1D9" } };

  return (
    <div style={{ background: "transparent", minHeight: "100vh", padding: isMobile ? "24px 16px 60px" : "32px 28px 60px" }}>
      <div style={{ maxWidth: 900, margin: "0 auto" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 4, flexWrap: "wrap" }}>
          <TastoLivelloPrecedente titolo="Dashboard venditori" onClick={onBack} />
          <div style={{ ...fontDisplay, fontSize: 26, fontWeight: 700, color: NAVY }}>Riepilogo Vendita prodotti</div>
        </div>
        <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginBottom: 18 }}>{nomeSoggetto ? toTitleCase(nomeSoggetto) : "—"} · Solo vendite al POS</div>

        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 16 }}>
          {[{ v: "mese", l: "Ultimo mese" }, { v: "trimestre", l: "Ultimo trimestre" }, { v: "seimesi", l: "Ultimi 6 mesi" }, { v: "annoaccademico", l: "Anno accademico" }, { v: "personalizzato", l: "Personalizzato" }].map((p) => (
            <button key={p.v} onClick={() => setPeriodo(p.v)} style={{ ...fontBody, fontSize: 12.5, fontWeight: 600, padding: "8px 13px", borderRadius: 16, border: "none", background: periodo === p.v ? NAVY : BG, color: periodo === p.v ? "#fff" : NAVY, cursor: "pointer" }}>{p.l}</button>
          ))}
        </div>
        {periodo === "personalizzato" && (
          <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 16 }}>
            <input type="date" style={inputStyle} value={customDa} onChange={(e) => setCustomDa(e.target.value)} />
            <span style={{ color: MUTED }}>–</span>
            <input type="date" style={inputStyle} value={customA} onChange={(e) => setCustomA(e.target.value)} />
          </div>
        )}

        <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr 1fr" : "repeat(2, minmax(0,1fr))", gap: 14, marginBottom: 20 }}>
          <div style={{ ...cardStyle, marginBottom: 0 }}>
            <div style={{ ...fontBody, fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>Incasso netto nel periodo</div>
            <div style={{ ...fontDisplay, fontSize: 22, fontWeight: 700, color: NAVY }}>{fmtEuroErp2(kpi.incasso)}</div>
          </div>
          <div style={{ ...cardStyle, marginBottom: 0 }}>
            <div style={{ ...fontBody, fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>Pezzi netti</div>
            <div style={{ ...fontDisplay, fontSize: 22, fontWeight: 700, color: NAVY }}>{kpi.pezzi}</div>
          </div>
        </div>

        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginBottom: 10 }}>
          <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY }}>Vendite</div>
          <button onClick={() => setOrdineCronologico((v) => !v)} style={{ ...fontBody, fontSize: 12.5, fontWeight: 600, color: NAVY, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 16, padding: "7px 13px", cursor: "pointer" }}>
            {ordineCronologico ? "Dal più vecchio" : "Dal più recente"}
          </button>
        </div>
        <div style={{ ...cardStyle, padding: 0, overflow: "hidden" }}>
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 560 }}>
              <thead>
                <tr>
                  {[{ c: "data", l: "Data" }, { c: "tipo", l: "Tipo" }, { c: "prodotti", l: "Prodotti" }, { c: "totale", l: "Totale" }].map((th) => (
                    <ThOrdina key={th.c} campo={th.c} ordine={ordine} onOrdina={cambiaOrdine} style={{ ...fontBody, fontSize: 10.5, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, textAlign: "left", padding: "10px 14px", borderBottom: `1px solid ${CREAM_BORDER}`, whiteSpace: "nowrap" }}>{th.l}</ThOrdina>
                  ))}
                </tr>
              </thead>
              <tbody>
                {ordina(righe, {
                  data: (v) => v.data_ordine || "",
                  tipo: (v) => v.tipo_movimento || "",
                  prodotti: (v) => (Array.isArray(v.prodotti) ? v.prodotti : []).map((pr) => pr.nome).join(", "),
                  totale: (v) => (v.totale != null ? Number(v.totale) : null),
                }).map((v) => {
                  const b = badgeTipo[v.tipo_movimento] || { l: v.tipo_movimento, c: MUTED, s: "#EFEFEF" };
                  return (
                    <tr key={v.id}>
                      <td style={{ padding: "12px 14px", borderTop: `1px solid ${CREAM_BORDER}`, ...fontBody, fontSize: 13, color: NAVY, whiteSpace: "nowrap" }}>{v.data_ordine ? fmtData(v.data_ordine.slice(0, 10)) : "—"}</td>
                      <td style={{ padding: "12px 14px", borderTop: `1px solid ${CREAM_BORDER}`, whiteSpace: "nowrap" }}><span style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: b.c, background: b.s, borderRadius: 8, padding: "3px 9px" }}>{b.l}</span></td>
                      <td style={{ padding: "12px 14px", borderTop: `1px solid ${CREAM_BORDER}`, ...fontBody, fontSize: 12.5, color: MUTED }}>{(Array.isArray(v.prodotti) ? v.prodotti : []).map((p) => `${p.quantita}× ${p.nome}`).join(", ")}</td>
                      <td style={{ padding: "12px 14px", borderTop: `1px solid ${CREAM_BORDER}`, ...fontBody, fontSize: 13, fontWeight: 700, color: v.totale < 0 ? "#C0392B" : NAVY, whiteSpace: "nowrap" }}>{fmtEuroErp2(v.totale)}</td>
                    </tr>
                  );
                })}
                {righe.length === 0 && (
                  <tr><td colSpan={4} style={{ padding: "20px 14px", ...fontBody, fontSize: 13, color: MUTED, textAlign: "center" }}>Nessuna vendita nel periodo selezionato.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
// Dashboard master: chi entra con la password di una specifica master
// (Password menù > Password Master) trova già selezionata la propria
// scheda, senza tendina — a differenza della Dashboard venditori, non
// c'è nessuna schermata di login secondaria. Chi invece ha solo il
// permesso sul tasto (staff/Amministratore) vede la tendina per
// scegliere quale master guardare
function PaginaDashboardMaster({ master, corsi, location, corsiDate, hotel, iscritti, masterLoggataId, venditeShop, prodottiShop, targetVenditeProdotti, coupon, puntiMasterRegolaBase, puntiMasterPeriodiSpeciali, puntiMasterImpostazioni, onApriInventarioSede, onApriChiusura, onApriClasse, onBack, titolo = "Dashboard master" }) {
  const isMobile = useIsMobile();
  const [masterSelId, setMasterSelId] = useState(masterLoggataId || "");
  const masterSel = master.find((m) => m.id === masterSelId) || null;
  // target vendite prodotti in corso per la master selezionata (mai per
  // il team vendite corsi: i due silos restano separati, vedi Target
  // Master in Impostazioni)
  const oggiStrTarget = dataOggiStr();
  const targetAttiviMaster = masterSelId
    ? (targetVenditeProdotti || [])
        .filter((t) => t.soggetto_tipo === "master" && t.soggetto_id === masterSelId && t.data_inizio <= oggiStrTarget && t.data_fine >= oggiStrTarget)
        .map((t) => ({ t, avanzamento: calcolaAvanzamentoTarget(t, venditeShop, prodottiShop) }))
    : [];
  const corsoById = useMemo(() => Object.fromEntries(corsi.map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries(location.map((l) => [l.id, l])), [location]);
  const oggiStr = dataOggiStr();
  // resta in lista anche fino a 5 giorni dopo la fine ("Appena
  // terminato" in CardDataMaster), così la card resta cliccabile (per
  // aprire la scheda del corso) e ben visibile appena tornati dalla
  // sede, non solo mentre il corso è in corso. L'ordine per data_inizio
  // crescente porta già naturalmente in cima i corsi appena finiti
  // (data nel passato), senza bisogno di un ordinamento a parte
  const prossimeDate = useMemo(
    () => corsiDate.filter((cd) => cd.master_id === masterSelId && oggiStr <= addGiorni(cd.data_fine, 5)).sort((a, b) => a.data_inizio.localeCompare(b.data_inizio)),
    [corsiDate, masterSelId, oggiStr]
  );
  // Inventario Post Corso: eleggibile un corso in corso o finito da al
  // massimo ~1 settimana, per lasciare il tempo di farlo anche a
  // posteriori se non fatto subito tornando dalla sede
  function inFinestraInventario(cd) {
    return oggiStr >= cd.data_inizio && oggiStr <= addGiorni(cd.data_fine, 7);
  }
  const corsiEleggibiliInventario = useMemo(
    () => corsiDate.filter((cd) => cd.master_id === masterSelId && inFinestraInventario(cd)).sort((a, b) => a.data_inizio.localeCompare(b.data_inizio)),
    [corsiDate, masterSelId, oggiStr]
  );
  const [mostraListaInventario, setMostraListaInventario] = useState(false);

  // quale coupon corrisponde a un codice (per distinguere, sulla raccolta
  // punti qui sotto, un referral "dei corsi" — legato a un'edizione, con
  // corsi_date_id — da uno "personale" della master, sempre valido)
  const couponPerCodice = useMemo(() => {
    const mappa = {};
    (coupon || []).forEach((c) => { mappa[(c.codice || "").toLowerCase()] = c; });
    return mappa;
  }, [coupon]);

  // raccolta punti premi: la master vede SOLO quanta gente ha comprato e
  // quanti punti ha maturato, mai quanto hanno speso — l'importo in euro
  // resta un dato per l'amministrazione, non per la master. "Vendite" conta
  // solo le righe con totale positivo (un reso/annullamento non è un
  // "acquisto effettuato"); i punti invece riflettono anche i resi
  // (negativi), perché sono la sostanza vera della raccolta punti
  const raccoltaPuntiMaster = useMemo(() => {
    const vuoto = { venditeTotale: 0, venditeCorsi: 0, venditePersonale: 0, puntiTotale: 0, puntiCorsi: 0, puntiPersonale: 0, gruppi: [] };
    if (!masterSelId || !puntiMasterImpostazioni) return vuoto;
    const righe = (venditeShop || []).filter((v) => venditaContaPerMaster(v, masterSelId, puntiMasterImpostazioni));
    let venditeTotale = 0, venditeCorsi = 0, venditePersonale = 0;
    let puntiTotale = 0, puntiCorsi = 0, puntiPersonale = 0;
    const perGruppo = {};
    righe.forEach((v) => {
      const infoCoupon = v.codice_coupon ? couponPerCodice[v.codice_coupon.toLowerCase()] : null;
      const punti = puntiMasterDiVendita(v, puntiMasterPeriodiSpeciali, puntiMasterRegolaBase, infoCoupon);
      const contaComeVendita = (v.totale || 0) > 0;
      puntiTotale += punti;
      if (contaComeVendita) venditeTotale += 1;
      if (infoCoupon?.corsi_date_id) { if (contaComeVendita) venditeCorsi += 1; puntiCorsi += punti; }
      else if (infoCoupon) { if (contaComeVendita) venditePersonale += 1; puntiPersonale += punti; }
      const chiave = v.codice_coupon ? v.codice_coupon.toUpperCase() : "__pos_senza_referral__";
      if (!perGruppo[chiave]) perGruppo[chiave] = { etichetta: v.codice_coupon ? v.codice_coupon.toUpperCase() : "Vendite POS senza referral", vendite: 0, punti: 0 };
      if (contaComeVendita) perGruppo[chiave].vendite += 1;
      perGruppo[chiave].punti += punti;
    });
    const gruppi = Object.values(perGruppo).sort((a, b) => b.vendite - a.vendite);
    return { venditeTotale, venditeCorsi, venditePersonale, puntiTotale, puntiCorsi, puntiPersonale, gruppi };
  }, [venditeShop, masterSelId, puntiMasterImpostazioni, puntiMasterPeriodiSpeciali, puntiMasterRegolaBase, couponPerCodice]);
  const [mostraDettaglioPunti, setMostraDettaglioPunti] = useState(false);

  if (mostraDettaglioPunti && masterSel) {
    return (
      <div style={{ background: "transparent", minHeight: "100vh", padding: isMobile ? "24px 16px 60px" : "32px 28px 60px" }}>
        <div style={{ maxWidth: 720, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 6, flexWrap: "wrap" }}>
            <TastoLivelloPrecedente titolo="Dashboard master" onClick={() => setMostraDettaglioPunti(false)} />
            <div style={{ ...fontDisplay, fontSize: 22, fontWeight: 700, color: NAVY }}>Raccolta punti — dettaglio</div>
          </div>
          <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginBottom: 18 }}>Per codice referral usato dai tuoi clienti (online e al banco); i resi e gli annullamenti riducono i punti.</div>
          {raccoltaPuntiMaster.gruppi.length === 0 ? (
            <div style={{ ...cardStyle, color: MUTED, ...fontBody, fontSize: 13 }}>Nessuna vendita nella finestra della raccolta punti.</div>
          ) : raccoltaPuntiMaster.gruppi.map((g) => (
            <div key={g.etichetta} style={{ ...cardStyle, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
              <div>
                <div style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY, textTransform: g.etichetta === "Vendite POS senza referral" ? "none" : "uppercase" }}>{g.etichetta}</div>
                <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginTop: 3 }}>{g.vendite} vendit{g.vendite === 1 ? "a" : "e"}</div>
              </div>
              <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: g.punti < 0 ? "#C0392B" : GOLD }}>{g.punti} pt</div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (mostraListaInventario) {
    return (
      <div style={{ background: "transparent", minHeight: "100vh", padding: isMobile ? "24px 16px 60px" : "32px 28px 60px" }}>
        <div style={{ maxWidth: 640, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 6, flexWrap: "wrap" }}>
            <TastoLivelloPrecedente titolo="Dashboard master" onClick={() => setMostraListaInventario(false)} />
            <div style={{ ...fontDisplay, fontSize: 22, fontWeight: 700, color: NAVY }}>Chiusura corso</div>
          </div>
          <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginBottom: 18 }}>Scegli il corso da chiudere — in cima anche quelli finiti da circa una settimana.</div>
          {corsiEleggibiliInventario.map((cd) => {
            const c = corsoById[cd.corso_id]; const l = locById[cd.location_id];
            return (
              <div key={cd.id} onClick={() => onApriChiusura(cd.id)} style={{ ...cardStyle, marginBottom: 10, padding: 16, cursor: "pointer" }}>
                <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY, marginBottom: 2 }}>{c?.nome || "—"}</div>
                <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>{fmtDataCompatta(cd.data_inizio, cd.data_fine)} · {toTitleCase(l?.nome || "—")}</div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div style={{ background: "transparent", minHeight: "100vh", padding: isMobile ? "24px 16px 60px" : "32px 28px 60px" }}>
      <div style={{ maxWidth: 720, margin: "0 auto" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginBottom: 6, flexWrap: "wrap" }}>
          <TastoLivelloPrecedente titolo="Home" onClick={onBack} />
          {masterSel && (
            <button
              onClick={() => corsiEleggibiliInventario.length > 0 && setMostraListaInventario(true)}
              disabled={corsiEleggibiliInventario.length === 0}
              title={corsiEleggibiliInventario.length > 0 ? "" : "Attivo durante il corso e fino a circa una settimana dopo la fine"}
              style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: corsiEleggibiliInventario.length > 0 ? NAVY : "#C9C4B8", background: "#fff", border: `1px solid ${corsiEleggibiliInventario.length > 0 ? CREAM_BORDER : "#EDEAE0"}`, borderRadius: 16, padding: "9px 14px", cursor: corsiEleggibiliInventario.length > 0 ? "pointer" : "default", flexShrink: 0 }}
            >
              Inventario corso corrente
            </button>
          )}
        </div>
        <div style={{ ...fontDisplay, fontSize: 28, fontWeight: 700, color: NAVY, marginBottom: 4 }}>
          {masterSel ? `Dashboard ${toTitleCase(masterSel.nome)}` : titolo}
        </div>
        {masterSel && <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginBottom: 10 }}>Area master</div>}

        {/* Il referral code personale, subito sotto il nome: e' la prima
            cosa che una master cerca quando entra qui, e finora doveva
            chiederlo. E' lo stesso codice creato in "Genera referral
            code" — quello legato a lei e non a una singola edizione */}
        {masterSel && (() => {
          const suo = (coupon || []).find((c) => c.master_id === masterSel.id && !c.corsi_date_id);
          if (!suo) return null;
          return (
            <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", marginBottom: 18, background: BG, border: `1px solid ${CREAM_BORDER}`, borderRadius: 14, padding: "10px 14px", width: "fit-content", maxWidth: "100%" }}>
              <span style={{ ...fontBody, fontSize: 13, color: NAVY }}>Il tuo referral code personale è:</span>
              <span style={{ ...fontDisplay, fontSize: 20, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 1 }}>{suo.codice}</span>
              <button
                onClick={() => { try { navigator.clipboard.writeText(String(suo.codice || "").toUpperCase()); } catch (e) { /* niente appunti: si legge e si copia a mano */ } }}
                title="Copia il codice"
                style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: MUTED, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 14, padding: "5px 10px", cursor: "pointer" }}
              >
                copia
              </button>
            </div>
          );
        })()}

        {masterSel && puntiMasterImpostazioni && (
          <div style={{ marginBottom: 20 }}>
            <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Raccolta punti premi</div>
            <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginBottom: 12 }}>Dal {fmtData(puntiMasterImpostazioni.data_inizio)} al {fmtData(puntiMasterImpostazioni.data_fine)}.</div>
            {(() => {
              // su mobile le 4 card stanno tutte su UNA riga (font e padding
              // ridotti); su desktop restano larghe e possono andare a capo
              const cardPunti = { ...cardStyle, flex: isMobile ? "1 1 0" : "1 1 200px", minWidth: 0, padding: isMobile ? "12px 6px" : 16, marginBottom: 0, ...(isMobile ? { display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center" } : {}) };
              // su mobile l'etichetta occupa un'altezza fissa (fino a 3 righe),
              // così i numeri delle 4 card partono tutti dalla stessa riga
              const lblPunti = { ...fontBody, fontSize: isMobile ? 10.5 : 11, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: isMobile ? 0.2 : 0.5, marginBottom: isMobile ? 8 : 6, lineHeight: 1.2, ...(isMobile ? { textAlign: "center", minHeight: 40, display: "flex", alignItems: "center", justifyContent: "center" } : {}) };
              const numPunti = { ...fontDisplay, fontSize: isMobile ? 24 : 24, fontWeight: 700, color: NAVY, ...(isMobile ? { textAlign: "center" } : {}) };
              const ptPunti = { ...fontBody, fontSize: isMobile ? 11.5 : 12, color: MUTED, marginTop: 2, ...(isMobile ? { textAlign: "center" } : {}) };
              return (
            <div style={{ display: "flex", gap: isMobile ? 6 : 12, marginBottom: 12, flexWrap: isMobile ? "nowrap" : "wrap" }}>
              <div style={cardPunti}>
                <div style={lblPunti}>Vendite effettuate</div>
                <div style={numPunti}>{raccoltaPuntiMaster.venditeTotale}</div>
              </div>
              <div style={cardPunti}>
                <div style={lblPunti}>Vendite con referral dei corsi</div>
                <div style={numPunti}>{raccoltaPuntiMaster.venditeCorsi}</div>
                <div style={ptPunti}>{raccoltaPuntiMaster.puntiCorsi} pt</div>
              </div>
              <div style={cardPunti}>
                <div style={lblPunti}>Vendite con referral personale</div>
                <div style={numPunti}>{raccoltaPuntiMaster.venditePersonale}</div>
                <div style={ptPunti}>{raccoltaPuntiMaster.puntiPersonale} pt</div>
              </div>
              <div style={cardPunti}>
                <div style={lblPunti}>Punti accumulati</div>
                <div style={{ ...numPunti, color: GOLD }}>{raccoltaPuntiMaster.puntiTotale} <span style={{ ...fontBody, fontSize: isMobile ? 10 : 13, fontWeight: 400, color: MUTED }}>pt</span></div>
              </div>
            </div>
              );
            })()}
            <Button variant="ghost" onClick={() => setMostraDettaglioPunti(true)}>Dettaglio per codice</Button>
          </div>
        )}

        {masterSel && targetAttiviMaster.length > 0 && (
          <div style={{ marginBottom: 20 }}>
            <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Target vendite prodotti</div>
            <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginBottom: 12 }}>Vendite al POS, separate dall'incasso corsi qui sopra.</div>
            {targetAttiviMaster.map(({ t, avanzamento }) => <PannelloTarget key={t.id} t={t} avanzamento={avanzamento} />)}
          </div>
        )}

        {!masterLoggataId && (
          <select
            style={{ ...inputStyle, width: "auto", minWidth: 220, marginBottom: 20 }}
            value={masterSelId} onChange={(e) => setMasterSelId(e.target.value)}
          >
            <option value="">— scegli master —</option>
            {master.map((m) => <option key={m.id} value={m.id}>{m.nome.toUpperCase()}</option>)}
          </select>
        )}

        {!masterSel ? (
          <div style={{ ...cardStyle, textAlign: "center", padding: 40, color: MUTED, ...fontBody, fontSize: 14 }}>Scegli una master per vedere i suoi prossimi corsi.</div>
        ) : (
          <>
            <div style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Prossimi corsi</div>
            <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginBottom: 16 }}>Data, località e biglietti di viaggio già caricati.</div>
            {prossimeDate.length === 0 ? (
              <div style={{ ...cardStyle, color: MUTED, ...fontBody, fontSize: 13 }}>Nessun corso in programma al momento.</div>
            ) : prossimeDate.map((cd) => (
              <CardDataMaster
                key={cd.id} corsoData={cd} corso={corsoById[cd.corso_id]} loc={locById[cd.location_id]}
                hotelAssociato={(hotel || []).find((h) => h.id === cd.alloggio_id)}
                iscrittiEdizione={(iscritti || []).filter((i) => i.corso_data_id === cd.id)}
                apribile={inFinestraInventario(cd)} onApriInventario={onApriChiusura} onApriClasse={onApriClasse}
                codiceReferral={(coupon || []).find((c) => c.corsi_date_id === cd.id)?.codice || null}
              />
            ))}
          </>
        )}
      </div>
    </div>
  );
}
// una riga di "Inventario corso corrente": nome del prodotto/attrezzatura
// + quantità, salvata da sola all'uscita dal campo (nessun tasto Salva)
// riga di un'attrezzatura già dichiarata in questa sede: mostra "risultano
// in magazzino N" (l'ultimo valore confermato) e tiene la modifica sempre
// dietro un passaggio esplicito di conferma — mai un numero che si salva
// da solo appena si sfiora il campo, per non correggere per sbaglio un
// dato che magari è ancora giusto
function RigaAttrezzaturaInventario({ riga, voce, onSalva, onRimuovi }) {
  const [inModifica, setInModifica] = useState(false);
  const [valore, setValore] = useState(riga?.quantita ?? 0);
  function apriModifica() { setValore(riga?.quantita ?? 0); setInModifica(true); }
  async function conferma() {
    await onSalva(voce.id, Math.max(0, Number(valore) || 0));
    setInModifica(false);
  }
  return (
    <div style={{ padding: "8px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ flex: 1, ...fontBody, fontSize: 13, color: NAVY }}>{voce.nome}</span>
        {!inModifica && <span style={{ ...fontBody, fontSize: 12, color: MUTED, whiteSpace: "nowrap" }}>Risultano in magazzino: {riga?.quantita ?? 0}</span>}
        {onRimuovi && <button onClick={onRimuovi} title="Rimuovi" style={{ background: "none", border: "none", color: "#C0392B", cursor: "pointer", fontSize: 14, padding: 4 }}>✕</button>}
      </div>
      {!inModifica ? (
        <button onClick={apriModifica} style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: NAVY, background: "none", border: `1px solid ${CREAM_BORDER}`, borderRadius: 8, padding: "4px 10px", cursor: "pointer", marginTop: 4 }}>
          Aggiorna quantità
        </button>
      ) : (
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
          <span style={{ ...fontBody, fontSize: 12, color: MUTED }}>Quantità reale:</span>
          <input type="number" min="0" autoFocus value={valore} onChange={(e) => setValore(e.target.value)} style={{ ...inputStyle, width: 70, padding: "5px 7px" }} />
          <button onClick={conferma} style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: "#fff", background: NAVY, border: "none", borderRadius: 8, padding: "5px 12px", cursor: "pointer" }}>Conferma</button>
          <button onClick={() => setInModifica(false)} style={{ ...fontBody, fontSize: 11.5, color: MUTED, background: "none", border: "none", cursor: "pointer" }}>Annulla</button>
        </div>
      )}
    </div>
  );
}
// "Inventario corso corrente" (Dashboard master): la master dichiara
// quanti prodotti da magazzino e quante attrezzature sono già presenti
// nella sede del corso che sta insegnando ora. Ogni dichiarazione fa
// upsert su (location_id, tipo, riferimento): l'ultima sostituisce la
// precedente, e resta visibile in Logistica prodotti come "già in sede"
// quando si prepara il contenuto dei kit per quella stessa location
// prodotti effettivamente spediti a questa edizione: contenuto del kit
// principale/speciale selezionati + accessori didattica del corso — la
// stessa identica logica di PannelloPreparazioneKit, riusata sia per
// limitare le tendine di "Materiali rispediti" (Inventario di sede) sia
// congruità dell'Inventario Post Corso
function quantitaInviataPerProdotto(corsoData, corso, kitDefinizioni, corsiKitProdotti, logisticaKitEdizioni, iscritti) {
  const mappa = {};
  if (!corsoData) return mappa;
  const stato = (logisticaKitEdizioni || []).find((e) => e.corso_data_id === corsoData.id) || {};
  const richiesti = kitRichiestiEdizione((iscritti || []).filter((i) => i.corso_data_id === corsoData.id), kitDefinizioni || [], corso?.id || null);
  Object.entries(richiesti).forEach(([kitId, qta]) => {
    if (!kitId || qta <= 0) return;
    (corsiKitProdotti || []).filter((r) => r.kit_id === kitId && r.tipo === "kit").forEach((r) => {
      mappa[r.prodotto_id] = (mappa[r.prodotto_id] || 0) + r.quantita * qta;
    });
    (corsiKitProdotti || []).filter((r) => r.kit_id === kitId && r.tipo === "accessorio").forEach((r) => {
      const q = stato.accessori_quantita?.[`${kitId}::${r.prodotto_id}`] ?? 0;
      mappa[r.prodotto_id] = (mappa[r.prodotto_id] || 0) + q;
    });
  });
  (corsiKitProdotti || []).filter((r) => r.tipo === "accessorio" && !r.kit_id && r.corso_id === (corso?.id || null)).forEach((r) => {
    mappa[r.prodotto_id] = (mappa[r.prodotto_id] || 0) + (r.quantita || 0);
  });
  // "Prodotti extra kit": chiave "extra::prodottoId" nella stessa mappa
  Object.entries(stato.accessori_quantita || {}).forEach(([chiave, q]) => {
    if (!chiave.startsWith("extra::")) return;
    const prodottoId = chiave.slice(7);
    mappa[prodottoId] = (mappa[prodottoId] || 0) + (q || 0);
  });
  return mappa;
}
// elenco causali dell'Inventario Post Corso — "Da verificare"/"Non so"
// esistono apposta per non bloccare la master quando non ha la
// risposta: il pezzo resta segnato aperto/da chiarire, non sparisce
// una riga di "Materiali che vengono rispediti": prodotto + quantità +
// rimuovi (a differenza di Prodotti/Attrezzature a sinistra, qui la
// lista è libera: si aggiunge dalla tendina, si può togliere)
function RigaRientroProdotto({ nome, quantita, onQuantita, onRimuovi }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "6px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
      <span style={{ flex: 1, ...fontBody, fontSize: 13, color: NAVY }}>{nome}</span>
      <input
        type="number" min="0" value={quantita ?? ""} placeholder="0"
        onChange={(e) => onQuantita(e.target.value === "" ? 0 : Math.max(0, Number(e.target.value)))}
        style={{ ...inputStyle, width: 70, padding: "6px 8px" }}
      />
      <button onClick={onRimuovi} title="Rimuovi" style={{ background: "none", border: "none", color: "#C0392B", cursor: "pointer", fontSize: 14, padding: 4 }}>✕</button>
    </div>
  );
}
// ---------- Chiusura corso ----------
// Il principio: la master non conta il rientro, dichiara i consumi; il
// rientro lo calcola l'app.
//
//   atteso in rientro = spedito da Raf − consumato dichiarato
//
// Ogni numero che le compare è già calcolato: conferma, oppure dichiara
// uno scostamento scegliendo un motivo da un elenco chiuso. Confermare è
// un secondo, contare sono venti minuti — e a fine corso, fuori sede,
// nessuno conta davvero: qualunque numero scritto a mano sarebbe finto.
// La verifica vera la fa Raf al ricevimento, che è l'unico con il tempo e
// lo scaffale. Per questo il corso non si chiude qui.
const MOTIVI_SCOSTAMENTO = [
  "Consumato durante il corso",
  "Rotto in aula",
  "Perso",
  "Consegnato a un allievo",
  "Rimasto in sede",
  "Mai arrivato nel pacco",
];

function PaginaChiusuraCorso({ corsoData, corso, location, iscritti, kitDefinizioni, corsiKitProdotti, logisticaKitEdizioni, prodottiShop, venditeShop, masterLoggataId, nomeUtente, onBack, onApriInventarioSede }) {
  const isMobile = useIsMobile();
  const [chiusura, setChiusura] = useState(null);
  const [consegne, setConsegne] = useState([]);
  const [dermografiRighe, setDermografiRighe] = useState([]);
  const [prelievi, setPrelievi] = useState([]);
  const [caricando, setCaricando] = useState(true);
  const [salvando, setSalvando] = useState(false);
  // gli scostamenti sulla bolla restano qui finché non si conferma: sono
  // correzioni a un calcolo, non dichiarazioni autonome come le altre
  const [scostamenti, setScostamenti] = useState({});
  const [ricercaPrelievo, setRicercaPrelievo] = useState("");

  const loc = (location || []).find((l) => l.id === corsoData?.location_id) || null;
  const stato = (logisticaKitEdizioni || []).find((e) => e.corso_data_id === corsoData?.id) || null;
  const iscrittiEdizione = (iscritti || []).filter((i) => i.corso_data_id === corsoData?.id);
  const prodottoDi = (id) => (prodottiShop || []).find((p) => p.id === id) || null;
  const nomeProdotto = (id) => prodottoDi(id)?.nome || "—";
  const nomeKit = (id) => (kitDefinizioni || []).find((k) => k.id === id)?.nome || "Kit";

  // cosa è partito: la fotografia scattata alla partenza del pacco. Se
  // manca (edizione partita prima che esistesse) la si ricompone dal vivo,
  // e lo si dice — è una ricostruzione, non un documento
  const fotografata = !!stato?.spedizione_snapshot;
  const spedito = useMemo(
    () => stato?.spedizione_snapshot || componiSpedizione({ stato, iscrittiEdizione, kitDefinizioni, corsoId: corso?.id || null }),
    [stato, iscrittiEdizione, kitDefinizioni, corso]
  );

  useEffect(() => { caricaTutto(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [corsoData?.id]);

  async function caricaTutto() {
    if (!corsoData?.id) return;
    setCaricando(true);
    // upsert e non "cerca, poi crea": due aperture ravvicinate vedrebbero
    // entrambe "nessuna riga" e violerebbero il vincolo su corso_data_id
    const { data: riga } = await supabase
      .from("chiusura_corso")
      .upsert({ corso_data_id: corsoData.id, master_id: masterLoggataId || null }, { onConflict: "corso_data_id" })
      .select().single();
    if (!riga) { setCaricando(false); return; }
    const [c, d, p] = await Promise.all([
      supabase.from("chiusura_corso_consegne").select("*").eq("chiusura_id", riga.id),
      supabase.from("chiusura_corso_dermografi").select("*").eq("chiusura_id", riga.id),
      supabase.from("chiusura_corso_prelievi").select("*").eq("chiusura_id", riga.id),
    ]);
    // le righe nascono già spuntate "consegnato": nel caso normale la
    // master non tocca niente, deflagga solo chi non ha ricevuto il kit
    const consegneEsistenti = c.data || [];
    const daCreare = iscrittiEdizione
      .filter((i) => !consegneEsistenti.some((r) => r.iscritto_id === i.id))
      .map((i) => ({
        chiusura_id: riga.id, iscritto_id: i.id, kit_consegnato: true,
        dermografo_consegnato: dermografoAcquistato(i) && i.dermografo_consegna !== "casa" ? true : null,
      }));
    // un dermografo di riserva per pezzo, mai aggregati: sono gli oggetti
    // più costosi che escono dal magazzino, e vanno guardati uno per uno
    const dermografiEsistenti = d.data || [];
    const dermografiDaCreare = [];
    Object.entries(spedito?.dermografi?.riserva || {}).forEach(([modello, quantita]) => {
      for (let indice = 1; indice <= Number(quantita || 0); indice += 1) {
        if (!dermografiEsistenti.some((r) => r.modello === modello && r.indice === indice)) {
          dermografiDaCreare.push({ chiusura_id: riga.id, modello, indice, esito: null });
        }
      }
    });
    if (daCreare.length > 0) await supabase.from("chiusura_corso_consegne").insert(daCreare);
    if (dermografiDaCreare.length > 0) await supabase.from("chiusura_corso_dermografi").insert(dermografiDaCreare);
    const [c2, d2] = daCreare.length > 0 || dermografiDaCreare.length > 0
      ? await Promise.all([
          supabase.from("chiusura_corso_consegne").select("*").eq("chiusura_id", riga.id),
          supabase.from("chiusura_corso_dermografi").select("*").eq("chiusura_id", riga.id),
        ])
      : [c, d];
    setChiusura(riga);
    setConsegne(c2.data || []);
    setDermografiRighe((d2.data || []).sort((a, b) => a.modello.localeCompare(b.modello) || a.indice - b.indice));
    setPrelievi(p.data || []);
    setCaricando(false);
  }

  const consegnaDi = (iscrittoId) => consegne.find((r) => r.iscritto_id === iscrittoId) || null;
  async function cambiaConsegna(iscrittoId, campi) {
    const riga = consegnaDi(iscrittoId);
    if (!riga) return;
    setConsegne((prev) => prev.map((r) => (r.id === riga.id ? { ...r, ...campi } : r)));
    await supabase.from("chiusura_corso_consegne").update(campi).eq("id", riga.id);
  }
  async function cambiaDermografo(id, campi) {
    setDermografiRighe((prev) => prev.map((r) => (r.id === id ? { ...r, ...campi } : r)));
    await supabase.from("chiusura_corso_dermografi").update(campi).eq("id", id);
  }
  async function aggiungiPrelievo(prodottoId) {
    setRicercaPrelievo("");
    const { data } = await supabase.from("chiusura_corso_prelievi")
      .insert({ chiusura_id: chiusura.id, prodotto_id: prodottoId, quantita: 1, dichiarato_da: nomeUtente || null })
      .select().single();
    if (data) setPrelievi((prev) => [...prev, data]);
  }
  async function cambiaPrelievo(id, campi) {
    setPrelievi((prev) => prev.map((r) => (r.id === id ? { ...r, ...campi } : r)));
    await supabase.from("chiusura_corso_prelievi").update(campi).eq("id", id);
  }
  async function rimuoviPrelievo(id) {
    setPrelievi((prev) => prev.filter((r) => r.id !== id));
    await supabase.from("chiusura_corso_prelievi").delete().eq("id", id);
  }

  // --- i conti ---
  // le vendite fatte a questo corso: quelle consegnate in aula tolgono
  // pezzi da qui, quelle "da spedire" partiranno da Raf e non toccano il
  // materiale presente in sede
  const venditeCorso = (venditeShop || []).filter((v) => v.corso_data_id === corsoData?.id && v.tipo_movimento !== "annullamento");
  const idProdottoRiga = (riga) => riga.prodotto_id || (prodottiShop || []).find((p) => p.nome === riga.nome)?.id || null;
  function sommaVendite(filtro) {
    const mappa = {};
    venditeCorso.filter(filtro).forEach((v) => {
      (Array.isArray(v.prodotti) ? v.prodotti : []).forEach((r) => {
        const id = idProdottoRiga(r);
        if (id) mappa[id] = (mappa[id] || 0) + (r.quantita || 0);
      });
    });
    return mappa;
  }
  const consegnateInAula = (v) => v.consegnato_in_aula !== false;
  const vendutoDaiKit = sommaVendite((v) => v.prelevato_dai_kit && consegnateInAula(v));
  const vendutoDaMerce = sommaVendite((v) => !v.prelevato_dai_kit && consegnateInAula(v));

  // kit: spediti − consegnati agli allievi presenti
  const consegnatiPerKit = {};
  iscrittiEdizione.forEach((i) => {
    const riga = consegnaDi(i.id);
    if (riga && riga.kit_consegnato === false) return;
    const kitId = i.kit_id || (spedito?.iscritti || []).find((x) => x.id === i.id)?.kit_id;
    if (kitId) consegnatiPerKit[kitId] = (consegnatiPerKit[kitId] || 0) + 1;
  });
  const righeKit = Object.entries(spedito?.kit || {}).map(([kitId, dati]) => {
    const spediti = (dati.per_iscritti || 0) + (dati.riserva || 0);
    return { kitId, nome: dati.nome || nomeKit(kitId), spediti, consegnati: consegnatiPerKit[kitId] || 0, atteso: Math.max(0, spediti - (consegnatiPerKit[kitId] || 0)) };
  }).filter((r) => r.spediti > 0);

  // dermografi: quelli degli allievi più quelli di riserva, meno quelli
  // che risultano consegnati (dall'elenco allievi o dalle righe di riserva)
  const righeDermografi = (() => {
    const assegnati = spedito?.dermografi?.assegnati || {};
    const riserva = spedito?.dermografi?.riserva || {};
    return [...new Set([...Object.keys(assegnati), ...Object.keys(riserva)])].map((modello) => {
      const spediti = (assegnati[modello] || 0) + Number(riserva[modello] || 0);
      const consegnatiAllievi = iscrittiEdizione.filter((i) =>
        dermografoAcquistato(i) === modello && i.dermografo_consegna !== "casa" && consegnaDi(i.id)?.dermografo_consegnato !== false
      ).length;
      const consegnatiRiserva = dermografiRighe.filter((r) => r.modello === modello && r.esito === "consegnato").length;
      return { modello, spediti, consegnati: consegnatiAllievi + consegnatiRiserva, atteso: Math.max(0, spediti - consegnatiAllievi - consegnatiRiserva) };
    }).filter((r) => r.spediti > 0);
  })();

  // merce da vendita: spedita − venduta e consegnata in aula
  const righeMerce = Object.entries(spedito?.merce_vendita || {}).map(([prodottoId, quantita]) => ({
    prodottoId, spediti: Number(quantita || 0), venduti: vendutoDaMerce[prodottoId] || 0,
    atteso: Math.max(0, Number(quantita || 0) - (vendutoDaMerce[prodottoId] || 0)),
  })).filter((r) => r.spediti > 0);

  // altro materiale spedito (accessori didattica ed extra non da vendita)
  const righeAltro = Object.entries(spedito?.accessori || {}).map(([prodottoId, quantita]) => ({
    prodottoId, spediti: Number(quantita || 0), atteso: Number(quantita || 0),
  })).filter((r) => r.spediti > 0);

  // pezzi usciti dai kit: le vendite col prelievo dichiarato, più le
  // sostituzioni. Quale sacchetto sia stato aperto è irrilevante: conta
  // che il pezzo è uscito
  const usciteDaiKit = (() => {
    const mappa = {};
    Object.entries(vendutoDaiKit).forEach(([id, q]) => { mappa[id] = (mappa[id] || 0) + q; });
    prelievi.forEach((r) => { mappa[r.prodotto_id] = (mappa[r.prodotto_id] || 0) + (r.quantita || 0); });
    return Object.entries(mappa).map(([prodottoId, quantita]) => ({ prodottoId, quantita }));
  })();
  const righeDifettosi = prelievi.filter((r) => r.guasto_riconsegnato).map((r) => ({ prodottoId: r.prodotto_id, quantita: r.quantita || 0 }));
  const scartiDichiarati = prelievi.filter((r) => !r.guasto_riconsegnato);

  const chiaveRiga = (tipo, riferimento) => `${tipo}:${riferimento}`;
  function scostamentoDi(tipo, riferimento) { return scostamenti[chiaveRiga(tipo, riferimento)] || null; }
  function apriScostamento(tipo, riferimento, atteso) {
    setScostamenti((prev) => ({ ...prev, [chiaveRiga(tipo, riferimento)]: { dichiarato: atteso, motivo: MOTIVI_SCOSTAMENTO[0] } }));
  }
  function cambiaScostamento(tipo, riferimento, campi) {
    setScostamenti((prev) => ({ ...prev, [chiaveRiga(tipo, riferimento)]: { ...prev[chiaveRiga(tipo, riferimento)], ...campi } }));
  }
  function annullaScostamento(tipo, riferimento) {
    setScostamenti((prev) => { const copia = { ...prev }; delete copia[chiaveRiga(tipo, riferimento)]; return copia; });
  }

  async function confermaBolla() {
    if (!chiusura) return;
    if (!window.confirm("Confermi la bolla di rientro? Da qui in poi la vede Raf, che verificherà il pacco al ricevimento.")) return;
    setSalvando(true);
    const righe = [
      ...righeKit.map((r) => ({ tipo: "kit", kit_id: r.kitId, atteso: r.atteso, chiave: chiaveRiga("kit", r.kitId) })),
      ...righeDermografi.map((r) => ({ tipo: "dermografo", modello_dermografo: r.modello, atteso: r.atteso, chiave: chiaveRiga("dermografo", r.modello) })),
      ...righeMerce.map((r) => ({ tipo: "merce_vendita", prodotto_id: r.prodottoId, atteso: r.atteso, chiave: chiaveRiga("merce", r.prodottoId) })),
      ...righeAltro.map((r) => ({ tipo: "accessorio", prodotto_id: r.prodottoId, atteso: r.atteso, chiave: chiaveRiga("altro", r.prodottoId) })),
      ...righeDifettosi.map((r) => ({ tipo: "reso_difettoso", prodotto_id: r.prodottoId, atteso: r.quantita, chiave: chiaveRiga("difettoso", r.prodottoId) })),
    ].map(({ chiave, ...riga }) => {
      const s = scostamenti[chiave];
      return { ...riga, chiusura_id: chiusura.id, dichiarato: s ? Number(s.dichiarato) : null, motivo: s ? s.motivo : null };
    });
    await supabase.from("chiusura_corso_righe").delete().eq("chiusura_id", chiusura.id);
    if (righe.length > 0) await supabase.from("chiusura_corso_righe").insert(righe);
    const { data } = await supabase.from("chiusura_corso").update({
      stato: "confermata_master", confermata_ts: new Date().toISOString(), confermata_da: nomeUtente || null,
    }).eq("id", chiusura.id).select().single();
    setSalvando(false);
    if (data) setChiusura(data);
  }

  const titoloBlocco = { ...fontBody, fontSize: 11, fontWeight: 700, color: GOLD, textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 4 };
  const sottotitoloBlocco = { ...fontBody, fontSize: 12.5, color: MUTED, marginBottom: 14, lineHeight: 1.45 };
  const rigaBase = { display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", padding: "10px 0", borderBottom: `1px solid ${CREAM_BORDER}` };
  const confermata = chiusura?.stato && chiusura.stato !== "aperta";
  const risultatiPrelievo = ricercaPrelievo.trim()
    ? (prodottiShop || []).filter((p) => p.attivo !== false && p.nome.toLowerCase().includes(ricercaPrelievo.trim().toLowerCase())).slice(0, 8)
    : [];

  function RigaAttesa({ etichetta, dettaglio, atteso, tipo, riferimento }) {
    const s = scostamentoDi(tipo, riferimento);
    return (
      <div style={{ padding: "10px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <div style={{ flex: "1 1 180px", minWidth: 0 }}>
            <div style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY }}>{etichetta}</div>
            {dettaglio && <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 1 }}>{dettaglio}</div>}
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
            <span style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: s ? MUTED : NAVY, textDecoration: s ? "line-through" : "none" }}>{atteso}</span>
            {s && <span style={{ ...fontDisplay, fontSize: 18, fontWeight: 700, color: "#C0392B" }}>{s.dichiarato}</span>}
            {!confermata && (s
              ? <button onClick={() => annullaScostamento(tipo, riferimento)} style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: MUTED, background: "none", border: "none", cursor: "pointer" }}>Annulla</button>
              : <button onClick={() => apriScostamento(tipo, riferimento, atteso)} style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: NAVY, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 14, padding: "5px 10px", cursor: "pointer" }}>Non torna</button>
            )}
          </div>
        </div>
        {s && !confermata && (
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginTop: 8 }}>
            <input
              type="number" min="0" style={{ ...inputStyle, width: 80, padding: "6px 8px" }}
              value={s.dichiarato} onChange={(e) => cambiaScostamento(tipo, riferimento, { dichiarato: e.target.value === "" ? 0 : Math.max(0, Number(e.target.value)) })}
            />
            <select style={{ ...inputStyle, width: "auto", flex: "1 1 220px", padding: "6px 8px" }} value={s.motivo} onChange={(e) => cambiaScostamento(tipo, riferimento, { motivo: e.target.value })}>
              {MOTIVI_SCOSTAMENTO.map((m) => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        )}
      </div>
    );
  }

  if (caricando) {
    return (
      <div style={{ maxWidth: 760, margin: "0 auto", padding: "40px 20px", ...fontBody, color: MUTED }}>Carico la chiusura…</div>
    );
  }

  return (
    <div style={{ maxWidth: 760, margin: "0 auto", padding: isMobile ? "20px 16px 60px" : "32px 20px 60px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 6, flexWrap: "wrap" }}>
        <TastoLivelloPrecedente titolo="Indietro" onClick={onBack} />
        <div style={{ ...fontDisplay, fontSize: 26, fontWeight: 700, color: NAVY }}>Chiusura corso</div>
      </div>
      <div style={{ ...fontBody, fontSize: 13.5, color: MUTED, marginBottom: 18 }}>
        {corso?.nome || "—"} · {toTitleCase(loc?.nome || "—")} · {fmtData(corsoData?.data_inizio)}
      </div>

      {!fotografata && (
        <div style={{ ...cardStyle, padding: 14, marginBottom: 16, border: "1px solid #E8D9A0", background: "#FBF3E0" }}>
          <div style={{ ...fontBody, fontSize: 13, color: NAVY, lineHeight: 1.5 }}>
            Di questo corso non esiste la fotografia della spedizione: i numeri qui sotto sono ricostruiti da quello che risulta oggi.
            Dalla prossima edizione la fotografia si scatta da sola quando Raf segna il pacco come ritirato dal corriere.
          </div>
        </div>
      )}

      {confermata && (
        <div style={{ ...cardStyle, padding: 14, marginBottom: 16, border: "1px solid #A8D5AE", background: "#E9F5EA" }}>
          <div style={{ ...fontBody, fontSize: 13, fontWeight: 700, color: "#2E7D32" }}>
            Bolla confermata{chiusura.confermata_da ? ` da ${chiusura.confermata_da}` : ""} il {fmtData((chiusura.confermata_ts || "").slice(0, 10))}.
          </div>
          <div style={{ ...fontBody, fontSize: 12.5, color: "#2E7D32", marginTop: 2 }}>
            Ora tocca a Raf: il corso si chiude quando il pacco rientra e viene verificato.
          </div>
        </div>
      )}

      {/* 1 — Allievi */}
      <div style={{ ...cardStyle, padding: 16, marginBottom: 14 }}>
        <div style={titoloBlocco}>1 · Allievi</div>
        <div style={sottotitoloBlocco}>Sono tutti già spuntati come "kit consegnato": togli la spunta solo a chi non l'ha ricevuto.</div>
        {iscrittiEdizione.length === 0 && <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessun iscritto.</div>}
        {iscrittiEdizione.map((i) => {
          const riga = consegnaDi(i.id);
          const modello = dermografoAcquistato(i);
          const dermografoQui = modello && i.dermografo_consegna !== "casa";
          // se non ne ha comprato uno a parte, può averlo lo stesso: dentro
          // il kit. In quel caso non c'è niente da spuntare — segue il kit
          const nelKit = !modello ? dermografoDelKit(i.kit_id, corsiKitProdotti, prodottiShop) : null;
          return (
            <div key={i.id} style={rigaBase}>
              <label style={{ display: "flex", alignItems: "center", gap: 10, cursor: confermata ? "default" : "pointer", flex: "1 1 220px", minWidth: 0 }}>
                <input type="checkbox" disabled={confermata} checked={riga ? riga.kit_consegnato !== false : true} onChange={(e) => cambiaConsegna(i.id, { kit_consegnato: e.target.checked })} />
                <span style={{ minWidth: 0 }}>
                  <span style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY, textTransform: "uppercase" }}>{`${i.nome || ""} ${i.cognome || ""}`.trim()}</span>
                  <span style={{ display: "block", ...fontBody, fontSize: 12.5, color: MUTED, marginTop: 1 }}>{i.pacchetto_kit || "Nessun kit"}</span>
                </span>
              </label>
              {dermografoQui ? (
                <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: confermata ? "default" : "pointer", flexShrink: 0, ...fontBody, fontSize: 12.5, color: NAVY }}>
                  <input type="checkbox" disabled={confermata} checked={riga ? riga.dermografo_consegnato !== false : true} onChange={(e) => cambiaConsegna(i.id, { dermografo_consegnato: e.target.checked })} />
                  {etichettaDermografo(modello)}
                </label>
              ) : (
                <span style={{ ...fontBody, fontSize: 12, color: nelKit ? NAVY : MUTED, flexShrink: 0 }}>
                  {modello ? "dermografo ricevuto a casa"
                    : nelKit ? `${nelKit.etichetta} — compreso nel kit`
                      : "nessun dermografo"}
                </span>
              )}
            </div>
          );
        })}
      </div>

      {/* 2 — Kit di riserva */}
      <div style={{ ...cardStyle, padding: 16, marginBottom: 14 }}>
        <div style={titoloBlocco}>2 · Kit di riserva</div>
        <div style={sottotitoloBlocco}>Non li conti: è una sottrazione fra quanto ha spedito Raf e quanto è stato consegnato qui sopra.</div>
        {righeKit.length === 0 && <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessun kit spedito per questa edizione.</div>}
        {righeKit.map((r) => (
          <RigaAttesa
            key={r.kitId} tipo="kit" riferimento={r.kitId} atteso={r.atteso}
            etichetta={r.nome}
            dettaglio={`spediti ${r.spediti} · consegnati ${r.consegnati}`}
          />
        ))}
      </div>

      {/* 3 — Dermografi */}
      <div style={{ ...cardStyle, padding: 16, marginBottom: 14 }}>
        <div style={titoloBlocco}>3 · Dermografi</div>
        <div style={sottotitoloBlocco}>Uno per uno, mai a mucchio: sono gli oggetti più costosi del pacco. Per ciascuno di riserva, di' se è stato consegnato o se rientra.</div>
        {dermografiRighe.length === 0 && <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessun dermografo di riserva in questo pacco.</div>}
        {dermografiRighe.map((r) => (
          <div key={r.id} style={rigaBase}>
            <div style={{ flex: "1 1 160px", minWidth: 0, ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY }}>
              {etichettaDermografo(r.modello)} <span style={{ color: MUTED, fontWeight: 400 }}>n. {r.indice}</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", flexShrink: 0 }}>
              <button
                disabled={confermata}
                onClick={() => cambiaDermografo(r.id, { esito: "rientra", iscritto_id: null })}
                style={{ ...fontBody, fontSize: 12, fontWeight: 700, borderRadius: 14, padding: "6px 12px", cursor: confermata ? "default" : "pointer",
                  color: r.esito === "rientra" ? "#fff" : NAVY, background: r.esito === "rientra" ? NAVY : "#fff", border: `1px solid ${r.esito === "rientra" ? NAVY : CREAM_BORDER}` }}
              >
                Rientra
              </button>
              <button
                disabled={confermata}
                onClick={() => cambiaDermografo(r.id, { esito: "consegnato" })}
                style={{ ...fontBody, fontSize: 12, fontWeight: 700, borderRadius: 14, padding: "6px 12px", cursor: confermata ? "default" : "pointer",
                  color: r.esito === "consegnato" ? "#fff" : NAVY, background: r.esito === "consegnato" ? NAVY : "#fff", border: `1px solid ${r.esito === "consegnato" ? NAVY : CREAM_BORDER}` }}
              >
                Consegnato
              </button>
              {r.esito === "consegnato" && (
                <select
                  disabled={confermata} style={{ ...inputStyle, width: "auto", minWidth: 160, padding: "6px 8px" }}
                  value={r.iscritto_id || ""} onChange={(e) => cambiaDermografo(r.id, { iscritto_id: e.target.value || null })}
                >
                  <option value="">— a quale allievo —</option>
                  {iscrittiEdizione.map((i) => <option key={i.id} value={i.id}>{`${i.nome || ""} ${i.cognome || ""}`.trim()}</option>)}
                </select>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* 4 — Materiale prelevato dai kit */}
      <div style={{ ...cardStyle, padding: 16, marginBottom: 14 }}>
        <div style={titoloBlocco}>4 · Materiale prelevato dai kit in loco</div>
        <div style={sottotitoloBlocco}>Da quale kit sia uscito il pezzo non interessa: conta che è uscito.</div>

        <div style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>Venduto prendendolo dai kit</div>
        {Object.keys(vendutoDaiKit).length === 0 ? (
          <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginBottom: 14 }}>Nessuna vendita con prelievo dai kit. Si dichiara al momento dell'incasso, con la spunta sul POS.</div>
        ) : (
          <div style={{ marginBottom: 14 }}>
            {Object.entries(vendutoDaiKit).map(([prodottoId, q]) => (
              <div key={prodottoId} style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 13, color: NAVY, padding: "6px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
                <span>{nomeProdotto(prodottoId)}</span><span style={{ fontWeight: 700 }}>{q}</span>
              </div>
            ))}
          </div>
        )}

        <div style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>Dato in sostituzione di un pezzo difettoso</div>
        {prelievi.map((r) => (
          <div key={r.id} style={rigaBase}>
            <span style={{ flex: "1 1 160px", minWidth: 0, ...fontBody, fontSize: 13.5, fontWeight: 600, color: NAVY }}>{nomeProdotto(r.prodotto_id)}</span>
            <input
              type="number" min="1" disabled={confermata} style={{ ...inputStyle, width: 64, padding: "6px 8px" }}
              value={r.quantita} onChange={(e) => cambiaPrelievo(r.id, { quantita: Math.max(1, Number(e.target.value) || 1) })}
            />
            <label style={{ display: "flex", alignItems: "center", gap: 7, cursor: confermata ? "default" : "pointer", ...fontBody, fontSize: 12.5, color: NAVY }}>
              <input type="checkbox" disabled={confermata} checked={!!r.guasto_riconsegnato} onChange={(e) => cambiaPrelievo(r.id, { guasto_riconsegnato: e.target.checked })} />
              Pezzo guasto riconsegnato
            </label>
            {!confermata && <button onClick={() => rimuoviPrelievo(r.id)} title="Rimuovi" style={{ background: "none", border: "none", color: "#C0392B", cursor: "pointer", fontSize: 15, padding: 4 }}>✕</button>}
          </div>
        ))}
        {!confermata && (
          <div style={{ marginTop: 10 }}>
            <input style={inputStyle} placeholder="Cerca il prodotto dato in sostituzione…" value={ricercaPrelievo} onChange={(e) => setRicercaPrelievo(e.target.value)} />
            {risultatiPrelievo.map((p) => (
              <button key={p.id} onClick={() => aggiungiPrelievo(p.id)} style={{ display: "block", width: "100%", textAlign: "left", background: "none", border: "none", borderBottom: `1px solid ${CREAM_BORDER}`, padding: "8px 10px", cursor: "pointer", ...fontBody, fontSize: 13, color: NAVY }}>
                {p.nome}
              </button>
            ))}
          </div>
        )}
        <div style={{ ...fontBody, fontSize: 11.5, color: MUTED, marginTop: 10, lineHeight: 1.45 }}>
          Con la spunta il pezzo rotto torna indietro e finisce in una giacenza separata, così il conto quadra senza sporcare il magazzino vendibile. Senza la spunta è un pezzo perso, e resta scritto come tale.
        </div>
      </div>

      {/* 5 — Materiale da vendita */}
      <div style={{ ...cardStyle, padding: 16, marginBottom: 14 }}>
        <div style={titoloBlocco}>5 · Materiale da vendita</div>
        <div style={sottotitoloBlocco}>Scende da solo a ogni incasso registrato: non c'è niente da contare, guardalo solo se un numero non torna.</div>
        {righeMerce.length === 0 && <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessuna merce da vendita spedita a questo corso.</div>}
        {righeMerce.map((r) => (
          <RigaAttesa
            key={r.prodottoId} tipo="merce" riferimento={r.prodottoId} atteso={r.atteso}
            etichetta={nomeProdotto(r.prodottoId)}
            dettaglio={`spediti ${r.spediti} · venduti ${r.venduti}`}
          />
        ))}
      </div>

      {/* La bolla */}
      <div style={{ ...cardStyle, padding: 16, marginBottom: 14 }}>
        <div style={titoloBlocco}>Bolla di rientro</div>
        <div style={sottotitoloBlocco}>Già scritta. Confermala, o correggi la riga che non torna dicendo perché.</div>

        {righeKit.filter((r) => r.atteso > 0).map((r) => (
          <div key={r.kitId} style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 14, color: NAVY, padding: "6px 0" }}>
            <span>{r.nome} <span style={{ color: MUTED, fontSize: 12.5 }}>(integri)</span></span>
            <span style={{ fontWeight: 700 }}>{scostamentoDi("kit", r.kitId)?.dichiarato ?? r.atteso}</span>
          </div>
        ))}
        {righeDermografi.filter((r) => r.atteso > 0).map((r) => (
          <div key={r.modello} style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 14, color: NAVY, padding: "6px 0" }}>
            <span>{etichettaDermografo(r.modello)}</span>
            <span style={{ fontWeight: 700 }}>{scostamentoDi("dermografo", r.modello)?.dichiarato ?? r.atteso}</span>
          </div>
        ))}
        {righeMerce.filter((r) => r.atteso > 0).map((r) => (
          <div key={r.prodottoId} style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 14, color: NAVY, padding: "6px 0" }}>
            <span>{nomeProdotto(r.prodottoId)}</span>
            <span style={{ fontWeight: 700 }}>{scostamentoDi("merce", r.prodottoId)?.dichiarato ?? r.atteso}</span>
          </div>
        ))}
        {righeAltro.length > 0 && (
          <>
            <div style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginTop: 12, marginBottom: 2 }}>Altro materiale spedito</div>
            {righeAltro.map((r) => (
              <RigaAttesa key={r.prodottoId} tipo="altro" riferimento={r.prodottoId} atteso={r.atteso} etichetta={nomeProdotto(r.prodottoId)} dettaglio={`spediti ${r.spediti}`} />
            ))}
          </>
        )}
        {righeDifettosi.length > 0 && (
          <>
            <div style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: "#C0392B", textTransform: "uppercase", letterSpacing: 0.5, marginTop: 12, marginBottom: 2 }}>Resi difettosi — giacenza separata</div>
            {righeDifettosi.map((r) => (
              <div key={r.prodottoId} style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 14, color: NAVY, padding: "6px 0" }}>
                <span>{nomeProdotto(r.prodottoId)}</span><span style={{ fontWeight: 700 }}>{r.quantita}</span>
              </div>
            ))}
          </>
        )}
        {usciteDaiKit.length > 0 && (
          <div style={{ marginTop: 12, paddingTop: 10, borderTop: `1px solid ${CREAM_BORDER}` }}>
            <div style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 2 }}>Meno, usciti dai kit</div>
            {usciteDaiKit.map((r) => (
              <div key={r.prodottoId} style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 13, color: MUTED, padding: "4px 0" }}>
                <span>{nomeProdotto(r.prodottoId)}</span><span>− {r.quantita}</span>
              </div>
            ))}
          </div>
        )}
        {scartiDichiarati.length > 0 && (
          <div style={{ ...fontBody, fontSize: 11.5, color: MUTED, marginTop: 10 }}>
            Dichiarati persi e non attesi indietro: {scartiDichiarati.map((r) => `${nomeProdotto(r.prodotto_id)} (${r.quantita})`).join(" · ")}.
          </div>
        )}

        {!confermata && (
          <div style={{ marginTop: 16 }}>
            <Button onClick={confermaBolla} disabled={salvando}>{salvando ? "Salvo…" : "Conferma la bolla di rientro"}</Button>
            <div style={{ ...fontBody, fontSize: 11.5, color: MUTED, marginTop: 8, lineHeight: 1.45 }}>
              Il corso non si chiude qui: si chiude quando Raf riceve il pacco e registra cosa è tornato davvero.
            </div>
          </div>
        )}
      </div>

      {onApriInventarioSede && (
        <button onClick={onApriInventarioSede} style={{ ...fontBody, fontSize: 12.5, fontWeight: 700, color: GOLD, textTransform: "uppercase", letterSpacing: 0.4, background: "none", border: "none", cursor: "pointer", padding: "4px 0" }}>
          Inventario di sede →
        </button>
      )}
    </div>
  );
}

function PaginaInventarioSede({ corsoData, corso, location, prodottiShop, costiSottocategorie, kitDefinizioni, corsiKitProdotti, logisticaKitEdizioni, iscritti, inventarioSede, masterLoggataId, venditeShop, prodottiApertiMagazzino, magazzinoLocaleConsumabili, segnalazioniMagazzino, ricarica, onBack }) {
  const isMobile = useIsMobile();
  const [ricercaConsumabile, setRicercaConsumabile] = useState("");
  const [testoSegnalazione, setTestoSegnalazione] = useState("");
  const [inviandoSegnalazione, setInviandoSegnalazione] = useState(false);
  const loc = location.find((l) => l.id === corsoData?.location_id) || null;
  // catalogo delle attrezzature (gestito dall'admin in Impostazioni): qui
  // è solo il bacino da cui cercare — quali di queste sono davvero
  // presenti in QUESTA sede lo decide la master, aggiungendo/togliendo
  // righe come per Consumabili, non più un elenco fisso sempre uguale
  const attrezzatureCatalogo = costiSottocategorie
    .filter((sc) => sc.categoria_id === "attrezzature_corsi" && sc.attiva && !sc.automatico)
    .sort((a, b) => (a.ordine || 0) - (b.ordine || 0));

  const inventarioQui = inventarioSede.filter((r) => r.location_id === corsoData?.location_id);
  const rigaDi = (tipo, riferimento) => inventarioQui.find((r) => r.tipo === tipo && r.riferimento === riferimento) || null;
  async function salvaVoce(tipo, riferimento, quantita) {
    const { error } = await supabase.from("inventario_sede").upsert(
      { location_id: corsoData.location_id, tipo, riferimento, quantita, corso_data_id: corsoData.id, master_id: masterLoggataId || null },
      { onConflict: "location_id,tipo,riferimento" }
    );
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["inventario_sede"]);
  }
  async function eliminaVoceInventario(id) {
    const { error } = await supabase.from("inventario_sede").delete().eq("id", id);
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["inventario_sede"]);
  }

  const attrezzatureQui = inventarioQui.filter((r) => r.tipo === "attrezzatura");
  const [ricercaAttrezzatura, setRicercaAttrezzatura] = useState("");
  const risultatiAttrezzatura = ricercaAttrezzatura.trim()
    ? attrezzatureCatalogo.filter((sc) => !attrezzatureQui.some((r) => r.riferimento === sc.id) && sc.nome.toLowerCase().includes(ricercaAttrezzatura.trim().toLowerCase()))
    : [];
  function aggiungiAttrezzatura(sc) {
    setRicercaAttrezzatura("");
    salvaVoce("attrezzatura", sc.id, 1);
  }

  // consumabili di servizio del magazzino locale (livello a pallini):
  // stock persistente per città, non solo di questo corso — restano
  // visibili/modificabili anche in inventari futuri della stessa sede
  const consumabiliQui = (magazzinoLocaleConsumabili || []).filter((r) => r.location_id === corsoData?.location_id);
  const risultatiConsumabile = ricercaConsumabile.trim()
    ? prodottiShop.filter((p) => p.attivo !== false && p.nome.toLowerCase().includes(ricercaConsumabile.trim().toLowerCase())).slice(0, 8)
    : [];
  async function aggiungiConsumabile(p) {
    setRicercaConsumabile("");
    const { error } = await supabase.from("magazzino_locale_consumabili").insert({
      location_id: corsoData.location_id, prodotto_id: p.id, quantita: 1, livello: 5,
      corso_data_id: corsoData.id, master_id: masterLoggataId || null,
    });
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["magazzino_locale_consumabili"]);
  }
  async function aggiornaConsumabile(id, campi) {
    const { error } = await supabase.from("magazzino_locale_consumabili").update(campi).eq("id", id);
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["magazzino_locale_consumabili"]);
  }
  async function rimuoviConsumabile(id) {
    const { error } = await supabase.from("magazzino_locale_consumabili").delete().eq("id", id);
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["magazzino_locale_consumabili"]);
  }

  const statoEdizione = (logisticaKitEdizioni || []).find((e) => e.corso_data_id === corsoData?.id) || null;
  const nomeKit = (id) => (kitDefinizioni || []).find((k) => k.id === id)?.nome || "—";
  const consulenzeEdizione = statoEdizione?.consulenze_edizione || [];
  // upsert invece di "trova o inserisci": se due salvataggi partono
  // vicini prima che statoEdizione si aggiorni, entrambi vedrebbero
  // "nessuna riga" e proverebbero un insert, violando il vincolo unique
  // su corso_data_id (visto nei log come "duplicate key value...")
  async function salvaCampiStatoEdizione(campi) {
    const { error } = await supabase
      .from("logistica_kit_edizioni")
      .upsert({ corso_data_id: corsoData.id, ...campi }, { onConflict: "corso_data_id" });
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["logistica_kit_edizioni"]);
  }
  // "Consulenze": una riga per ciascuna spedita da Raf in Logistica
  // prodotti (stesso prodotto spedito due volte = due righe distinte,
  // mai sommate) — qui la master aggiorna solo il livello di
  // riempimento a pallini, non può aggiungerne o rimuoverne
  function aggiornaLivelloConsulenza(id, livello) {
    salvaCampiStatoEdizione({ consulenze_edizione: consulenzeEdizione.map((r) => (r.id === id ? { ...r, livello } : r)) });
  }

  // "Segnalazioni": problemi sulla sede visti durante il corso (uno
  // sgabello senza rotellina, un lettino tagliato…) — appartengono alla
  // sede del corso, non a questa singola edizione: compaiono nella
  // scheda di quella sede in "Magazzini esterni", dove restano finché
  // chi gestisce il magazzino non scrive una nota di risoluzione
  const segnalazioniCorso = (segnalazioniMagazzino || []).filter((s) => s.corso_data_id === corsoData?.id).sort((a, b) => (b.ts || "").localeCompare(a.ts || ""));
  async function inviaSegnalazione() {
    if (!testoSegnalazione.trim()) return;
    setInviandoSegnalazione(true);
    const { error } = await supabase.from("segnalazioni_magazzino").insert({
      corso_data_id: corsoData.id, location_id: corsoData.location_id, master_id: masterLoggataId || null, testo: testoSegnalazione.trim(),
    });
    setInviandoSegnalazione(false);
    if (error) { window.alert("Errore: " + error.message); return; }
    setTestoSegnalazione("");
    ricarica(["segnalazioni_magazzino"]);
  }

  const labelStyleInv = { ...fontBody, fontSize: 11, color: MUTED, marginBottom: 10 };

  return (
    <div style={{ background: "transparent", minHeight: "100vh", padding: isMobile ? "24px 16px 60px" : "32px 28px 60px" }}>
      <div style={{ maxWidth: 980, margin: "0 auto" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 6, flexWrap: "wrap" }}>
          <TastoLivelloPrecedente titolo="Dashboard master" onClick={onBack} />
          <div style={{ ...fontDisplay, fontSize: 24, fontWeight: 700, color: NAVY }}>
            Inventario {corso?.nome || "—"} {toTitleCase(loc?.nome || "—")} ({fmtDataCompatta(corsoData.data_inizio, corsoData.data_fine)})
          </div>
        </div>
        <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginBottom: 20 }}>
          Rendiconta cosa hai venduto, cosa rispedisci e cosa resta in magazzino locale.
        </div>

        <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: 20, alignItems: "flex-start" }}>
          <div>
            <div style={{ ...fontDisplay, fontSize: 17, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Prodotti che restano in magazzino locale</div>
            <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginBottom: 10 }}>Magazzino {toTitleCase(loc?.nome || "—")}</div>

            <div style={{ ...cardStyle, marginBottom: 16, padding: 16 }}>
              <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Consumabili</div>
              <div style={labelStyleInv}>Dischetti, rotoli, guanti… con il livello di utilizzo rimasto.</div>
              <div style={{ position: "relative" }}>
                <CampoRicerca value={ricercaConsumabile} onChange={(e) => setRicercaConsumabile(e.target.value)} placeholder="Cerca prodotto…" />
                {risultatiConsumabile.length > 0 && (
                  <div style={{ position: "absolute", top: "100%", left: 0, right: 0, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 8, boxShadow: "0 4px 16px rgba(0,0,0,0.1)", zIndex: 10, marginTop: 2 }}>
                    {risultatiConsumabile.map((p) => (
                      <div key={p.id} onClick={() => aggiungiConsumabile(p)} style={{ padding: "8px 10px", cursor: "pointer", ...fontBody, fontSize: 13, color: NAVY, borderBottom: `1px solid ${CREAM_BORDER}` }}>{p.nome}</div>
                    ))}
                  </div>
                )}
              </div>
              {consumabiliQui.length === 0 ? (
                <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginTop: 10 }}>Nessun consumabile dichiarato ancora.</div>
              ) : (
                <div style={{ marginTop: 10 }}>
                  {consumabiliQui.map((r) => (
                    <RigaConsumabileLocale
                      key={r.id} riga={r} nome={prodottiShop.find((p) => p.id === r.prodotto_id)?.nome || "—"}
                      onCambiaLivello={(livello) => aggiornaConsumabile(r.id, { livello })}
                      onCambiaQuantita={(quantita) => aggiornaConsumabile(r.id, { quantita })}
                      onRimuovi={() => rimuoviConsumabile(r.id)}
                    />
                  ))}
                </div>
              )}
            </div>

            <div style={{ ...cardStyle, padding: 16 }}>
              <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Attrezzature</div>
              <div style={labelStyleInv}>Aggiungi solo quelle davvero presenti in questa sede.</div>
              <div style={{ position: "relative" }}>
                <input style={inputStyle} value={ricercaAttrezzatura} onChange={(e) => setRicercaAttrezzatura(e.target.value)} placeholder="Cerca attrezzatura…" />
                {risultatiAttrezzatura.length > 0 && (
                  <div style={{ position: "absolute", top: "100%", left: 0, right: 0, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 8, boxShadow: "0 4px 16px rgba(0,0,0,0.1)", zIndex: 10, marginTop: 2, maxHeight: 240, overflowY: "auto" }}>
                    {risultatiAttrezzatura.map((sc) => (
                      <div key={sc.id} onClick={() => aggiungiAttrezzatura(sc)} style={{ padding: "8px 10px", cursor: "pointer", ...fontBody, fontSize: 13, color: NAVY, borderBottom: `1px solid ${CREAM_BORDER}` }}>{sc.nome}</div>
                    ))}
                  </div>
                )}
              </div>
              {attrezzatureQui.length === 0 ? (
                <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginTop: 10 }}>Nessuna attrezzatura dichiarata ancora.</div>
              ) : (
                <div style={{ marginTop: 10 }}>
                  {attrezzatureQui.map((r) => {
                    const sc = attrezzatureCatalogo.find((c) => c.id === r.riferimento);
                    return (
                      <RigaAttrezzaturaInventario
                        key={r.id} riga={r} voce={{ id: r.riferimento, nome: sc?.nome || "—" }}
                        onSalva={(id, q) => salvaVoce("attrezzatura", id, q)}
                        onRimuovi={() => eliminaVoceInventario(r.id)}
                      />
                    );
                  })}
                </div>
              )}
            </div>

            <div style={{ ...cardStyle, marginTop: 16, padding: 16 }}>
              <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Consulenze</div>
              <div style={labelStyleInv}>Quelle spedite da Raf per questo corso: aggiorna solo il livello di riempimento.</div>
              {consulenzeEdizione.length === 0 ? (
                <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginTop: 10 }}>Nessuna consulenza spedita per questo corso.</div>
              ) : (
                <div style={{ marginTop: 10 }}>
                  {consulenzeEdizione.map((r) => (
                    <RigaConsulenza
                      key={r.id} nome={prodottiShop.find((p) => p.id === r.prodotto_id)?.nome || "—"} livello={r.livello}
                      onCambiaLivello={(livello) => aggiornaLivelloConsulenza(r.id, livello)}
                    />
                  ))}
                </div>
              )}
            </div>
          </div>

        </div>

        <div style={{ marginTop: 24, ...cardStyle, padding: 16 }}>
          <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Segnalazioni</div>
          <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginBottom: 10 }}>
            Problemi visti in sede (es. "uno sgabello è senza una rotellina", "un lettino è tagliato") — compaiono nella scheda di {toTitleCase(loc?.nome || "questa sede")} in Magazzini esterni.
          </div>
          <textarea
            value={testoSegnalazione} onChange={(e) => setTestoSegnalazione(e.target.value)} rows={2}
            style={{ ...inputStyle, resize: "vertical", marginBottom: 10 }}
            placeholder="Scrivi la segnalazione…"
          />
          <Button onClick={inviaSegnalazione} disabled={inviandoSegnalazione || !testoSegnalazione.trim()}>{inviandoSegnalazione ? "Invio…" : "Aggiungi segnalazione e invia"}</Button>
          {segnalazioniCorso.length > 0 && (
            <div style={{ marginTop: 14 }}>
              {segnalazioniCorso.map((s) => (
                <div key={s.id} style={{ padding: "8px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
                  <div style={{ ...fontBody, fontSize: 13, color: NAVY }}>{s.testo}</div>
                  <div style={{ ...fontBody, fontSize: 11, color: MUTED, marginTop: 2 }}>{new Date(s.ts).toLocaleString("it-IT", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" })}</div>
                  {s.nota_risoluzione && (
                    <div style={{ ...fontBody, fontSize: 12, color: "#2E7D32", fontStyle: "italic", marginTop: 3 }}>Risolto: {s.nota_risoluzione}</div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

      </div>

    </div>
  );
}
// una riga di consumabile nel magazzino locale: quantità + livello a
// pallini (1-5), modificabile in qualunque momento — la stima è
// sempre manuale, a occhio, di chi fa l'inventario
function RigaConsumabileLocale({ riga, nome, onCambiaLivello, onCambiaQuantita, onRimuovi }) {
  return (
    <div style={{ padding: "8px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ flex: 1, ...fontBody, fontSize: 13, color: NAVY }}>{nome}</span>
        <input type="number" min="1" value={riga.quantita} onChange={(e) => onCambiaQuantita(Math.max(1, Number(e.target.value) || 1))} style={{ ...inputStyle, width: 56, padding: "5px 7px", fontSize: 12.5 }} />
        <button onClick={onRimuovi} title="Rimuovi" style={{ background: "none", border: "none", color: "#C0392B", cursor: "pointer", fontSize: 14, padding: 4 }}>✕</button>
      </div>
      <div style={{ display: "flex", gap: 3, marginTop: 4 }}>
        {[1, 2, 3, 4, 5].map((n) => (
          <button key={n} onClick={() => onCambiaLivello(n)} title={`${n}/5`} style={{ width: 16, height: 16, borderRadius: "50%", border: `1px solid ${GOLD}`, background: n <= riga.livello ? GOLD : "transparent", cursor: "pointer", padding: 0 }} />
        ))}
      </div>
    </div>
  );
}
// una consulenza spedita per l'edizione: riga indipendente (lo stesso
// prodotto spedito due volte fa due righe distinte, mai sommate), con
// livello di riempimento a 5 pallini — cliccare il pallino già acceso
// più basso lo spegne, così si può arrivare anche a 0/5. Quando il
// livello è a zero appare "Rispedito vuoto" sotto ai pallini
function RigaConsulenza({ nome, livello, onCambiaLivello, onRimuovi, disponibilita }) {
  return (
    <div style={{ padding: "8px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ flex: 1, ...fontBody, fontSize: 13, color: NAVY }}>{nome}</span>
        {disponibilita != null && <span style={{ ...fontBody, fontSize: 11.5, color: MUTED, whiteSpace: "nowrap" }}>disp. {disponibilita}</span>}
        {onRimuovi && <button onClick={onRimuovi} title="Rimuovi" style={{ background: "none", border: "none", color: "#C0392B", cursor: "pointer", fontSize: 14, padding: 4 }}>✕</button>}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 3, marginTop: 4 }}>
        {[1, 2, 3, 4, 5].map((n) => (
          <button key={n} onClick={() => onCambiaLivello(n === livello ? n - 1 : n)} title={`${n}/5`} style={{ width: 16, height: 16, borderRadius: "50%", border: `1px solid ${GOLD}`, background: n <= livello ? GOLD : "transparent", cursor: "pointer", padding: 0 }} />
        ))}
        {livello === 0 && <span style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: "#C0392B", marginLeft: 8 }}>Rispedito vuoto</span>}
      </div>
    </div>
  );
}
// tasto "+ Nuova agenda" (solo Programmatore): crea subito una riga col
// nome scelto — appare all'istante come nuova colonna-checkbox in
// Gestione utenti/Password Master (chiave permesso "agenda_<id>")
function BottoneNuovaAgenda({ ricarica }) {
  const [salvando, setSalvando] = useState(false);
  async function crea() {
    const nome = window.prompt("Nome della nuova agenda:");
    if (!nome || !nome.trim()) return;
    setSalvando(true);
    const { error } = await supabase.from("agende").insert({ nome: nome.trim() });
    setSalvando(false);
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["agende"]);
  }
  return (
    <button
      onClick={crea} disabled={salvando}
      style={{ ...fontBody, fontSize: 13, fontWeight: 700, color: "#fff", background: NAVY, border: "none", borderRadius: 20, padding: "10px 16px", cursor: salvando ? "default" : "pointer", flexShrink: 0 }}
    >
      {salvando ? "Creo…" : "+ Nuova agenda"}
    </button>
  );
}
// una voce dell'agenda: data, titolo, nota libera — eliminabile
// popup "Nuovo appuntamento": si apre cliccando un giorno vuoto del
// calendario, con la data già fissata da quel giorno (stesso schema di
// PopupNuovaData nel Calendario corsi)
function PopupNuovaVoceAgenda({ dataClic, orarioIniziale, onSalva, onChiudi }) {
  const [titolo, setTitolo] = useState("");
  const [orario, setOrario] = useState(orarioIniziale || "");
  const [nota, setNota] = useState("");
  return (
    <Modal title={`Nuovo evento — ${fmtData(dataClic)}`} onClose={onChiudi}>
      <div style={{ display: "flex", gap: 10 }}>
        <div style={{ flex: 2 }}>
          <Field label="Nome">
            <input style={inputStyle} value={titolo} onChange={(e) => setTitolo(e.target.value)} autoFocus />
          </Field>
        </div>
        <div style={{ flex: 1 }}>
          <Field label="Orario">
            <input type="time" style={inputStyle} value={orario} onChange={(e) => setOrario(e.target.value)} />
          </Field>
        </div>
      </div>
      <Field label="Nota (facoltativa)">
        <textarea style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} value={nota} onChange={(e) => setNota(e.target.value)} />
      </Field>
      <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
        <Button disabled={!titolo.trim()} onClick={() => onSalva({ titolo: titolo.trim(), orario: orario || null, nota: nota.trim() || null })}>Salva</Button>
        <Button variant="ghost" onClick={onChiudi}>Annulla</Button>
      </div>
    </Modal>
  );
}
// popup di un evento esistente (click sulla sua etichetta nel
// calendario): modificabile o eliminabile
function PopupVoceAgenda({ voce, onSalva, onElimina, onChiudi }) {
  const [titolo, setTitolo] = useState(voce.titolo);
  const [orario, setOrario] = useState(voce.orario ? voce.orario.slice(0, 5) : "");
  const [nota, setNota] = useState(voce.nota || "");
  return (
    <Modal title={fmtData(voce.data)} onClose={onChiudi}>
      <div style={{ display: "flex", gap: 10 }}>
        <div style={{ flex: 2 }}>
          <Field label="Nome">
            <input style={inputStyle} value={titolo} onChange={(e) => setTitolo(e.target.value)} />
          </Field>
        </div>
        <div style={{ flex: 1 }}>
          <Field label="Orario">
            <input type="time" style={inputStyle} value={orario} onChange={(e) => setOrario(e.target.value)} />
          </Field>
        </div>
      </div>
      <Field label="Nota (facoltativa)">
        <textarea style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} value={nota} onChange={(e) => setNota(e.target.value)} />
      </Field>
      <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
        <Button disabled={!titolo.trim()} onClick={() => onSalva({ titolo: titolo.trim(), orario: orario || null, nota: nota.trim() || null })}>Salva</Button>
        <Button variant="danger" onClick={onElimina}>Elimina</Button>
        <Button variant="ghost" onClick={onChiudi}>Annulla</Button>
      </div>
    </Modal>
  );
}
// una singola "pagina" di taccuino: quella di un giorno (con gli
// appuntamenti) o quella note della settimana (ottava carta della riga)
// carattere per le intestazioni delle carte: serif, diverso di proposito
// dal resto dell'app (Prompt/Roboto) per dare l'aria di un vero taccuino
const fontQuaderno = { fontFamily: "Georgia, 'Times New Roman', serif" };
// tavolozza alternata per mese: un mese la carta ha i toni caldi di
// sempre, il successivo un celeste chiaro "carta da zucchero" — così,
// senza più un titolo/divisore di mese, resta comunque visibile a colpo
// d'occhio dove finisce un mese e comincia il prossimo
const PALETTE_MESE_A = { sfondo: "#FFFDF7", sfondoOggi: "#FBF3E4", riga: "#E9E3D4", retro: "#EDE6D6" };
const PALETTE_MESE_B = { sfondo: "#EEF6FB", sfondoOggi: "#FBF3E4", riga: "#D8E8F0", retro: "#DCEAF1" };
function paletteMese(anno, mese) { return (anno * 12 + mese) % 2 === 0 ? PALETTE_MESE_A : PALETTE_MESE_B; }
// colore dell'ottava carta (le note): quello della domenica, l'ultimo
// giorno della settimana — è la carta a cui sta visivamente accanto nella
// griglia, quindi deve combaciare con quella, non con un calcolo astratto
// di "mese prevalente" che in una settimana a cavallo di due mesi può
// finire scollegato dal colore del giorno appena precedente
function paletteSettimanaNota(giorni) {
  const domenica = giorni[giorni.length - 1];
  return paletteMese(domenica.getFullYear(), domenica.getMonth());
}
// una "pagina" del taccuino (un giorno con i suoi appuntamenti, o l'ottava
// carta delle note): rilegatura a spirale sul bordo sinistro, margine
// rosso, righe orizzontali, e una seconda pagina leggermente sfalsata
// dietro per dare l'effetto di un blocco di fogli impilati. Cliccare la
// data (non il resto della carta) apre la vista dettagliata del giorno.
// Un "+" leggerissimo nell'angolo in basso a destra (solo sui giorni, non
// sulla carta Note) apre subito l'inserimento di un nuovo appuntamento,
// senza dover prima passare dalla vista dettagliata del giorno
function CartaAgendaQuaderno({ intestazione, evidenziata, palette, onClick, onNuovo, children }) {
  const isMobile = useIsMobile();
  const p = palette || PALETTE_MESE_A;
  return (
    <div style={{ position: "relative" }}>
      <div style={{ position: "absolute", top: 5, left: 5, right: -5, bottom: -5, background: p.retro, borderRadius: 9, border: `1px solid ${CREAM_BORDER}` }} />
      <div
        onClick={onClick}
        style={{
          position: "relative", cursor: onClick ? "pointer" : "default",
          background: evidenziata ? p.sfondoOggi : p.sfondo,
          backgroundImage: `repeating-linear-gradient(to bottom, transparent, transparent 22px, ${p.riga} 23px)`,
          backgroundPosition: "0 40px",
          border: `1px solid ${CREAM_BORDER}`, borderRadius: 9,
          boxShadow: "0 10px 18px -12px rgba(14,27,51,0.4)",
          minHeight: isMobile ? 190 : 330, overflow: "hidden", paddingLeft: isMobile ? 11 : 16,
        }}
      >
        {/* rilegatura a spirale: striscia di anelli lungo il bordo sinistro */}
        <div style={{
          position: "absolute", top: 0, bottom: 0, left: 0, width: isMobile ? 11 : 16,
          backgroundImage: "radial-gradient(circle, #fff 2px, #C9C2AE 2.5px)",
          backgroundSize: "100% 14px", backgroundPosition: "center 6px", backgroundRepeat: "repeat-y",
        }} />
        <div style={{ position: "absolute", top: 0, bottom: 0, left: isMobile ? 18 : 26, width: 1, background: "#E4A79B" }} />
        <div style={{ ...fontQuaderno, fontSize: isMobile ? 10.5 : 13.5, fontWeight: 700, color: NAVY, textAlign: "center", padding: isMobile ? "8px 4px 6px" : "12px 8px 10px", position: "relative", zIndex: 1 }}>
          {intestazione}
        </div>
        <div style={{ padding: isMobile ? "0 5px 6px 7px" : "0 10px 10px 12px", position: "relative", zIndex: 1 }}>
          {children}
        </div>
        {onNuovo && (
          <button
            onClick={(e) => { e.stopPropagation(); onNuovo(); }}
            title="Nuovo evento"
            style={{
              position: "absolute", bottom: 6, right: 6, width: isMobile ? 26 : 30, height: isMobile ? 26 : 30,
              display: "flex", alignItems: "center", justifyContent: "center",
              background: "rgba(14,27,51,0.09)", border: "none", borderRadius: "50%", cursor: "pointer",
              color: NAVY, fontSize: isMobile ? 17 : 19, fontWeight: 700, lineHeight: 1, zIndex: 2,
            }}
          >+</button>
        )}
      </div>
    </div>
  );
}
// una settimana (sempre da lunedì, mai spezzata a un confine di mese):
// griglia fissa a 4 colonne, anche da cellulare — 7 carte-giorno + l'ottava
// carta delle note, sempre disposte su 2 righe da 4. Ogni carta calcola da
// sé mese/colore/intestazione dalla propria data, quindi una settimana a
// cavallo di due mesi mostra correttamente carte di entrambi i colori
function SettimanaAgendaQuaderno({ giorni, voci, corsiGiorno, onClickGiorno, onClickVoce, onNuovoEvento, nota, onSalvaNota }) {
  const isMobile = useIsMobile();
  const oggiStr = dataOggiStr();
  const [testoNota, setTestoNota] = useState(nota?.testo || "");
  useEffect(() => { setTestoNota(nota?.testo || ""); }, [nota?.testo]);
  const settimanaInizio = fmtDataIso(giorni[0]);

  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: isMobile ? 6 : 18, marginBottom: isMobile ? 14 : 26 }}>
      {giorni.map((d) => {
        const ds = fmtDataIso(d);
        const vociGiorno = voci.filter((v) => v.data === ds).slice().sort((a, b) => {
          if (!a.orario && !b.orario) return 0;
          if (!a.orario) return 1;
          if (!b.orario) return -1;
          return a.orario.localeCompare(b.orario);
        });
        const corsiDelGiorno = corsiGiorno(ds);
        const isOggi = ds === oggiStr;
        const idxLunedi = (d.getDay() + 6) % 7; // lunedì=0, come GIORNI_ABBR_LUNGHI
        const intestazione = `${GIORNI_ABBR_LUNGHI[idxLunedi]} ${d.getDate()} ${MESI[d.getMonth()]} ${d.getFullYear()}`;
        const dueColonne = vociGiorno.length > 5;
        return (
          <CartaAgendaQuaderno
            key={ds} evidenziata={isOggi} palette={paletteMese(d.getFullYear(), d.getMonth())}
            onClick={() => onClickGiorno(ds)} onNuovo={() => onNuovoEvento(ds)}
            intestazione={intestazione}
          >
            {corsiDelGiorno.map((c) => (
              <div
                key={c.id}
                title={`${c.corsoNome} · ${c.locNome}${c.giorniTotali > 1 ? ` · ${c.indice}/${c.giorniTotali}` : ""}`}
                style={{ ...fontBody, fontSize: isMobile ? 10 : 12.5, fontWeight: 700, color: NAVY, background: coloreTenue(c.colore || NAVY, 0.35), borderRadius: 5, padding: isMobile ? "2px 4px" : "3px 8px", marginBottom: 4, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}
              >
                🎓 {c.corsoNome}{!isMobile && ` · ${c.sigla}`}{c.giorniTotali > 1 && ` ${c.indice}/${c.giorniTotali}`}
              </div>
            ))}
            {/* eventi personali: testo semplice "orario titolo" sulla riga
            (niente più pillola colorata, riservata solo ai corsi), su due
            colonne quando sono tanti — sempre sotto le barre dei corsi */}
            <div style={{ display: dueColonne ? "grid" : "block", gridTemplateColumns: dueColonne ? "1fr 1fr" : undefined, columnGap: 10 }}>
              {vociGiorno.map((v) => (
                <div
                  key={v.id}
                  onClick={(e) => { e.stopPropagation(); onClickVoce(v); }}
                  style={{ ...fontBody, fontSize: isMobile ? 9.5 : 12, fontWeight: 600, color: NAVY, cursor: "pointer", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", lineHeight: isMobile ? "16px" : "22px" }}
                >
                  {v.orario ? `${v.orario.slice(0, 5)} ` : ""}{v.titolo}
                </div>
              ))}
            </div>
          </CartaAgendaQuaderno>
        );
      })}
      <CartaAgendaQuaderno intestazione="Note" palette={paletteSettimanaNota(giorni)}>
        <textarea
          value={testoNota}
          onChange={(e) => setTestoNota(e.target.value)}
          onBlur={() => { if (testoNota !== (nota?.testo || "")) onSalvaNota(settimanaInizio, testoNota); }}
          placeholder="Appunti della settimana…"
          style={{ ...fontBody, fontSize: isMobile ? 10 : 12.5, color: NAVY, border: "none", background: "transparent", outline: "none", resize: "none", width: "100%", height: isMobile ? 140 : 270, lineHeight: isMobile ? "16px" : "22px", padding: 0 }}
        />
      </CartaAgendaQuaderno>
    </div>
  );
}
// griglia oraria della vista giorno espansa: mezz'ora per riga, dalle 8
// alle 20 (fascia oraria dei corsi/appuntamenti in accademia)
const ORE_GRIGLIA_GIORNO = (() => {
  const arr = [];
  for (let h = 8; h <= 20; h++) {
    arr.push(`${String(h).padStart(2, "0")}:00`);
    if (h < 20) arr.push(`${String(h).padStart(2, "0")}:30`);
  }
  return arr;
})();
function slotMezzoraDi(orario) {
  const [h, m] = orario.slice(0, 5).split(":").map(Number);
  return `${String(h).padStart(2, "0")}:${m < 30 ? "00" : "30"}`;
}
// vista dettagliata di un singolo giorno (si apre cliccando una carta
// dell'agenda): a sinistra la griglia oraria con gli appuntamenti
// personali del giorno, a destra i corsi già programmati. Cliccare un
// orario della griglia (o il "+" in basso a destra) apre subito
// l'inserimento di un nuovo appuntamento, con l'orario già precompilato
// quando si clicca una riga precisa
function VistaGiornoEspanso({ data, voci, corsiGiorno, onClickVoce, onNuovoEvento, onChiudi }) {
  const isMobile = useIsMobile();
  const d = new Date(`${data}T00:00:00`);
  const idxLunedi = (d.getDay() + 6) % 7;
  const titolo = `${GIORNI_ABBR_LUNGHI[idxLunedi]} ${d.getDate()} ${MESI[d.getMonth()]} ${d.getFullYear()}`;
  const corsiDelGiorno = corsiGiorno(data);
  const vociGiorno = voci.filter((v) => v.data === data);
  const vociConOrario = vociGiorno.filter((v) => v.orario);
  const vociSenzaOrario = vociGiorno.filter((v) => !v.orario);
  return (
    <Modal title={titolo} onClose={onChiudi} maxWidth={840}>
      <div style={{ display: "flex", gap: 18, flexDirection: isMobile ? "column" : "row" }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          {ORE_GRIGLIA_GIORNO.map((ora) => {
            const eventiSlot = vociConOrario.filter((v) => slotMezzoraDi(v.orario) === ora);
            const oraPiena = ora.endsWith(":00");
            return (
              // l'etichetta dell'ora sta appoggiata esattamente sulla riga
              // (a cavallo del bordo, come in un'agenda vera), non sospesa
              // a metà di uno spazio vuoto; le ore intere hanno una riga
              // più marcata delle mezzore, per orientarsi scorrendo veloce.
              // Cliccare la riga apre un nuovo appuntamento già con
              // quell'orario precompilato
              <div
                key={ora} onClick={() => onNuovoEvento(data, ora)} title={`Nuovo appuntamento alle ${ora}`}
                style={{ position: "relative", borderTop: oraPiena ? `1.5px solid #C9C2AE` : `1px solid ${CREAM_BORDER}`, minHeight: 30, cursor: "pointer" }}
              >
                <div style={{ position: "absolute", top: 0, left: 0, transform: "translateY(-50%)", background: "#fff", paddingRight: 6, ...fontBody, fontSize: 11, fontWeight: oraPiena ? 700 : 400, color: MUTED }}>
                  {ora}
                </div>
                <div style={{ paddingLeft: 46, paddingTop: 7, paddingBottom: 4, display: "flex", flexDirection: "column", gap: 3 }}>
                  {eventiSlot.map((v) => (
                    <div key={v.id} onClick={(e) => { e.stopPropagation(); onClickVoce(v); }} style={{ ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, cursor: "pointer" }}>
                      {v.titolo}
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
          {vociSenzaOrario.length > 0 && (
            <div style={{ marginTop: 14 }}>
              <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>Senza orario</div>
              {vociSenzaOrario.map((v) => (
                <div key={v.id} onClick={() => onClickVoce(v)} style={{ ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, cursor: "pointer", marginBottom: 4 }}>
                  {v.titolo}
                </div>
              ))}
            </div>
          )}
        </div>
        <div style={{ width: isMobile ? "100%" : 190, flexShrink: 0, display: "flex", flexDirection: isMobile ? "row" : "column", flexWrap: "wrap", gap: 8 }}>
          {corsiDelGiorno.length === 0 ? (
            <div style={{ ...fontBody, fontSize: 12, color: MUTED }}>Nessun corso</div>
          ) : corsiDelGiorno.map((c) => (
            <div key={c.id} title={`${c.corsoNome} · ${c.locNome}${c.giorniTotali > 1 ? ` · ${c.indice}/${c.giorniTotali}` : ""}`} style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, background: coloreTenue(c.colore || NAVY, 0.35), borderRadius: 8, padding: "10px 10px", textAlign: "center" }}>
              🎓 {c.corsoNome}<br />{c.locNome}{c.giorniTotali > 1 && ` · ${c.indice}/${c.giorniTotali}`}
            </div>
          ))}
        </div>
      </div>
    </Modal>
  );
}
// pagina "Agenda": chi ha una sola agenda tra i propri permessi (utente
// nominale o master) la trova già aperta, senza scegliere nulla (stesso
// spirito di Dashboard master). Chi ne ha più di una vede prima un elenco
// di tasti fra cui scegliere quale aprire. Solo il Programmatore può
// crearne/eliminarle (e vede sempre tutte); chiunque acceda a un'agenda
// può aggiungere/togliere le sue voci
function PaginaAgenda({ agende, agendaVoci, agendaNoteSettimanali, corsi, location, corsiDate, ruoloUtente, utenteLoggato, ricarica, onBack, titolo = "Agenda" }) {
  const isMobile = useIsMobile();
  const isProgrammatore = ruoloUtente === "programmatore";
  const isStaff = ruoloUtente === "programmatore" || ruoloUtente === "amministratore";
  const mieId = (utenteLoggato?.permessi || []).filter((p) => p.startsWith("agenda_")).map((p) => p.slice(7));
  const agendeVisibili = isStaff ? agende : agende.filter((a) => mieId.includes(a.id));
  const [agendaApertaId, setAgendaApertaId] = useState(agendeVisibili.length === 1 ? agendeVisibili[0].id : null);
  const agendaAperta = agende.find((a) => a.id === agendaApertaId) || null;
  const [popupNuovo, setPopupNuovo] = useState(null); // { data, orario } della voce da creare, o null
  const [popupVoce, setPopupVoce] = useState(null); // voce cliccata, o null
  const [giornoEspanso, setGiornoEspanso] = useState(null); // data "yyyy-mm-dd" della vista dettagliata, o null
  const [ricercaNote, setRicercaNote] = useState("");

  async function eliminaAgenda(a) {
    if (!window.confirm(`Eliminare l'agenda "${a.nome}"? Elimina anche tutti i suoi appuntamenti.`)) return;
    const { error } = await supabase.from("agende").delete().eq("id", a.id);
    if (error) { window.alert("Errore: " + error.message); return; }
    if (agendaApertaId === a.id) setAgendaApertaId(null);
    ricarica(["agende"]);
  }
  async function salvaNuovaVoce(campi) {
    const { error } = await supabase.from("agenda_voci").insert({ agenda_id: agendaAperta.id, data: popupNuovo.data, ...campi });
    if (error) { window.alert("Errore: " + error.message); return; }
    setPopupNuovo(null);
    ricarica(["agenda_voci"]);
  }
  async function salvaModificaVoce(campi) {
    const { error } = await supabase.from("agenda_voci").update(campi).eq("id", popupVoce.id);
    if (error) { window.alert("Errore: " + error.message); return; }
    setPopupVoce(null);
    ricarica(["agenda_voci"]);
  }
  async function eliminaVoce() {
    if (!window.confirm("Eliminare questo appuntamento?")) return;
    const { error } = await supabase.from("agenda_voci").delete().eq("id", popupVoce.id);
    if (error) { window.alert("Errore: " + error.message); return; }
    setPopupVoce(null);
    ricarica(["agenda_voci"]);
  }
  // ottava carta della settimana: upsert su (agenda_id, settimana_inizio),
  // così il testo resta legato alla settimana anche dopo un refresh
  async function salvaNotaSettimana(settimanaInizio, testo) {
    const { error } = await supabase
      .from("agenda_note_settimanali")
      .upsert({ agenda_id: agendaAperta.id, settimana_inizio: settimanaInizio, testo }, { onConflict: "agenda_id,settimana_inizio" });
    if (error) { window.alert("Errore: " + error.message); return; }
    ricarica(["agenda_note_settimanali"]);
  }

  // vista a calendario, identica nello spirito al Calendario corsi: elenco
  // continuo di settimane (da 6 mesi fa a 12 avanti) su cui scorrere invece
  // di usare frecce avanti/indietro. Le settimane sono continue (sempre da
  // lunedì a domenica, mai spezzate a un confine di mese: una settimana a
  // cavallo tra due mesi resta una riga sola), più un selettore per saltare
  // a un mese preciso e un tasto per tornare subito a oggi
  const oggi = new Date();
  const oggiStr = dataOggiStr();
  const mesi = useMemo(() => {
    const arr = [];
    for (let i = -6; i <= 12; i++) {
      const d = new Date(oggi.getFullYear(), oggi.getMonth() + i, 1);
      arr.push({ anno: d.getFullYear(), mese: d.getMonth() });
    }
    return arr;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const settimane = useMemo(() => {
    const inizioRange = new Date(oggi.getFullYear(), oggi.getMonth() - 6, 1);
    const fineRange = new Date(oggi.getFullYear(), oggi.getMonth() + 13, 0);
    const primoLunedi = new Date(inizioRange);
    primoLunedi.setDate(primoLunedi.getDate() - ((primoLunedi.getDay() + 6) % 7));
    const arr = [];
    const cursore = new Date(primoLunedi);
    while (cursore <= fineRange) {
      const giorni = [];
      for (let i = 0; i < 7; i++) giorni.push(new Date(cursore.getFullYear(), cursore.getMonth(), cursore.getDate() + i));
      arr.push(giorni);
      cursore.setDate(cursore.getDate() + 7);
    }
    return arr;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const refPerSettimana = useRef({});
  function vaiASettimanaDi(trova, comportamento = "smooth") {
    const sett = settimane.find(trova);
    if (sett) refPerSettimana.current[fmtDataIso(sett[0])]?.scrollIntoView({ block: "start", behavior: comportamento });
  }
  function vaiAMese(anno, mese) {
    vaiASettimanaDi((giorni) => giorni.some((d) => d.getFullYear() === anno && d.getMonth() === mese));
  }
  function vaiAOggi(comportamento) {
    vaiASettimanaDi((giorni) => giorni.some((d) => fmtDataIso(d) === oggiStr), comportamento);
  }
  useEffect(() => {
    if (!agendaAperta) return;
    // due frame di ritardo: assicura che la griglia (alta, con tutte le
    // settimane già montate) abbia finito il layout prima di scrollare,
    // altrimenti su dispositivi più lenti lo scroll può atterrare nel
    // posto sbagliato mentre il contenuto sta ancora assestandosi.
    // Niente scroll animato qui: aprendo l'agenda deve comparire subito
    // sulla settimana di oggi, non scorrere in vista partendo dall'alto
    requestAnimationFrame(() => requestAnimationFrame(() => { vaiAOggi("auto"); }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [agendaAperta?.id]);

  const vociAgendaAperta = agendaAperta ? agendaVoci.filter((v) => v.agenda_id === agendaAperta.id) : [];
  const noteBySettimana = useMemo(
    () => Object.fromEntries((agendaNoteSettimanali || []).filter((n) => n.agenda_id === agendaApertaId).map((n) => [n.settimana_inizio, n])),
    [agendaNoteSettimanali, agendaApertaId]
  );
  const corsoById = useMemo(() => Object.fromEntries((corsi || []).map((c) => [c.id, c])), [corsi]);
  const locById = useMemo(() => Object.fromEntries((location || []).map((l) => [l.id, l])), [location]);
  // stesso numero di frazione "giorno/totale" del Calendario corsi (es.
  // 1/2, 2/2): un corso di più giorni deve mostrarlo anche qui
  function corsiGiorno(ds) {
    return (corsiDate || [])
      .filter((cd) => cd.data_inizio <= ds && cd.data_fine >= ds)
      .map((cd) => ({
        id: cd.id,
        corsoNome: toTitleCase(corsoById[cd.corso_id]?.nome || "?"),
        locNome: toTitleCase(locById[cd.location_id]?.nome || "?"),
        sigla: siglaCitta(locById[cd.location_id]?.nome),
        colore: corsoById[cd.corso_id]?.colore,
        indice: differenzaGiorni(cd.data_inizio, ds) + 1,
        giorniTotali: differenzaGiorni(cd.data_inizio, cd.data_fine) + 1,
      }));
  }
  // ricerca testuale nelle note libere della settimana (l'ottava carta):
  // ogni risultato porta la data in cui è stata creata la nota (il campo
  // "ts", che l'upsert di salvaNotaSettimana non tocca più dopo la prima
  // volta, quindi resta la data di creazione anche dopo le modifiche)
  const risultatiRicercaNote = ricercaNote.trim()
    ? (agendaNoteSettimanali || [])
        .filter((n) => n.agenda_id === agendaApertaId && n.testo && n.testo.toLowerCase().includes(ricercaNote.trim().toLowerCase()))
        .sort((a, b) => b.settimana_inizio.localeCompare(a.settimana_inizio))
        .slice(0, 8)
    : [];

  return (
    <div style={{ background: "transparent", minHeight: "100vh", padding: isMobile ? "24px 16px 60px" : "32px 28px 60px" }}>
      <div style={{ maxWidth: agendaAperta ? 1320 : 720, margin: "0 auto" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginBottom: 10, flexWrap: "wrap" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
            <TastoLivelloPrecedente
              titolo={agendaAperta && agendeVisibili.length > 1 ? "Agenda" : "Home"}
              onClick={() => (agendaAperta && agendeVisibili.length > 1 ? setAgendaApertaId(null) : onBack())}
            />
            <div style={{ ...fontDisplay, fontSize: 24, fontWeight: 700, color: NAVY }}>{agendaAperta ? agendaAperta.nome : titolo}</div>
          </div>
          {agendaAperta && (
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              <select
                value=""
                onChange={(e) => { if (!e.target.value) return; const [a, m] = e.target.value.split("-").map(Number); vaiAMese(a, m); }}
                style={{ ...inputStyle, width: "auto" }}
              >
                <option value="">Vai al mese…</option>
                {mesi.map(({ anno, mese }) => <option key={`${anno}-${mese}`} value={`${anno}-${mese}`}>{MESI[mese]} {anno}</option>)}
              </select>
              <Button variant="ghost" onClick={vaiAOggi}>Oggi</Button>
            </div>
          )}
        </div>

        {agendaAperta && (
          <div style={{ position: "relative", marginBottom: 14 }}>
            <input
              type="text"
              value={ricercaNote}
              onChange={(e) => setRicercaNote(e.target.value)}
              placeholder="Cerca una parola nelle note delle settimane…"
              style={{ ...inputStyle, width: "100%" }}
            />
            {risultatiRicercaNote.length > 0 && (
              <div style={{ position: "absolute", top: "100%", left: 0, right: 0, marginTop: 4, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 10, boxShadow: "0 12px 24px -8px rgba(14,27,51,0.28)", zIndex: 50, overflow: "hidden" }}>
                {risultatiRicercaNote.map((n) => (
                  <div
                    key={n.id}
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={() => { vaiASettimanaDi((giorni) => fmtDataIso(giorni[0]) === n.settimana_inizio); setRicercaNote(""); }}
                    style={{ padding: "8px 14px", cursor: "pointer", borderBottom: `1px solid ${CREAM_BORDER}` }}
                  >
                    <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: MUTED }}>{fmtData(n.ts.slice(0, 10))}</div>
                    <div style={{ ...fontBody, fontSize: 13, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{n.testo}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {agendaAperta && (
          <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginBottom: 16 }}>
            Scorri verso il basso per vedere le altre settimane e i mesi successivi, la settimana riparte sempre da lunedì. Clicca una carta per aprire la vista dettagliata del giorno: da lì clicca un orario o il tasto + per aggiungere un appuntamento, clicca un appuntamento per modificarlo o eliminarlo. L'ottava carta di ogni settimana è per gli appunti liberi.
          </div>
        )}

        {!agendaAperta ? (
          <>
            {isProgrammatore && <div style={{ marginBottom: 18 }}><BottoneNuovaAgenda ricarica={ricarica} /></div>}
            {agendeVisibili.length === 0 ? (
              <div style={{ ...cardStyle, textAlign: "center", padding: 40, color: MUTED, ...fontBody, fontSize: 14 }}>Nessuna agenda assegnata.</div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {agendeVisibili.map((a) => (
                  <div key={a.id} style={{ display: "flex", gap: 8, alignItems: "center" }}>
                    <button
                      onClick={() => setAgendaApertaId(a.id)}
                      style={{ ...fontBody, fontSize: 15, fontWeight: 700, color: NAVY, background: "#fff", border: `1px solid ${CREAM_BORDER}`, borderRadius: 12, padding: "16px 18px", cursor: "pointer", flex: 1, textAlign: "left" }}
                    >
                      {a.nome}
                    </button>
                    {isProgrammatore && (
                      <button onClick={() => eliminaAgenda(a)} title="Elimina agenda" style={{ background: "transparent", border: "none", cursor: "pointer", color: "#C0392B", padding: 8, flexShrink: 0 }}>✕</button>
                    )}
                  </div>
                ))}
              </div>
            )}
          </>
        ) : (
          settimane.map((giorni) => {
            const chiave = fmtDataIso(giorni[0]);
            return (
              <div key={chiave} style={{ scrollMarginTop: 54 }} ref={(el) => { refPerSettimana.current[chiave] = el; }}>
                <SettimanaAgendaQuaderno
                  giorni={giorni} voci={vociAgendaAperta} corsiGiorno={corsiGiorno}
                  onClickGiorno={(ds) => setGiornoEspanso(ds)}
                  onClickVoce={(v) => setPopupVoce(v)}
                  onNuovoEvento={(ds) => setPopupNuovo({ data: ds, orario: null })}
                  nota={noteBySettimana[chiave]}
                  onSalvaNota={salvaNotaSettimana}
                />
              </div>
            );
          })
        )}
      </div>

      {giornoEspanso && (
        <VistaGiornoEspanso
          data={giornoEspanso} voci={vociAgendaAperta} corsiGiorno={corsiGiorno}
          onClickVoce={(v) => setPopupVoce(v)}
          onNuovoEvento={(ds, orario) => setPopupNuovo({ data: ds, orario })}
          onChiudi={() => setGiornoEspanso(null)}
        />
      )}
      {popupNuovo && (
        <PopupNuovaVoceAgenda dataClic={popupNuovo.data} orarioIniziale={popupNuovo.orario} onSalva={salvaNuovaVoce} onChiudi={() => setPopupNuovo(null)} />
      )}
      {popupVoce && (
        <PopupVoceAgenda voce={popupVoce} onSalva={salvaModificaVoce} onElimina={eliminaVoce} onChiudi={() => setPopupVoce(null)} />
      )}
    </div>
  );
}

// colore in continuo per il punteggio Performance, centrato su 100 (in
// linea con la media team): rosso sotto 85, transizione verso il navy
// intorno a 100, verde sopra 120 — niente fasce fisse alta/media/bassa
function interpolaColore(hex1, hex2, t) {
  const c1 = [1, 3, 5].map((i) => parseInt(hex1.slice(i, i + 2), 16));
  const c2 = [1, 3, 5].map((i) => parseInt(hex2.slice(i, i + 2), 16));
  const c = c1.map((v, i) => Math.round(v + (c2[i] - v) * t));
  return `#${c.map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}
function coloreScorePerformance(score) {
  const ROSSO = "#C0392B", VERDE = "#2E7D32";
  if (score <= 85) return ROSSO;
  if (score >= 120) return VERDE;
  if (score <= 100) return interpolaColore(ROSSO, NAVY, (score - 85) / 15);
  return interpolaColore(NAVY, VERDE, (score - 100) / 20);
}

// helper condivisi per le classifiche venditori (usati sia nella scheda
// personale del venditore sia nella pagina Statistiche > Statistica
// venditori): raggruppano un elenco di iscritti già filtrato per periodo
// in {venditore, corsi, valore, ticketMedio} e calcolano i due ranking
// (per numero di chiusure, per Performance) col confronto sul periodo
// immediatamente precedente
function statsVenditoriPerPeriodo(iscrittiInPeriodo, venditori) {
  const base = venditori.map((v) => ({ venditore: v, corsi: 0, valore: 0 }));
  const byId = Object.fromEntries(base.map((r) => [r.venditore.id, r]));
  iscrittiInPeriodo.forEach((i) => {
    const nomeNorm = (i.tutor || "").trim().toUpperCase();
    const v = venditori.find((vv) => vv.nome.trim().toUpperCase() === nomeNorm);
    if (!v || !byId[v.id]) return;
    byId[v.id].corsi += 1;
    byId[v.id].valore += i.totale_pattuito || 0;
  });
  return base.map((r) => ({ ...r, ticketMedio: r.corsi > 0 ? r.valore / r.corsi : 0 }));
}
function rankCorsiConTrend(corrente, precedente) {
  const posPrecById = Object.fromEntries(
    precedente.slice().sort((a, b) => b.corsi - a.corsi).map((r, i) => [r.venditore.id, i + 1])
  );
  return corrente.slice().sort((a, b) => b.corsi - a.corsi).map((r, i) => ({
    ...r,
    posizione: i + 1,
    trendPosizioni: r.corsi > 0 && posPrecById[r.venditore.id] ? posPrecById[r.venditore.id] - (i + 1) : null,
  }));
}
// Performance = ticket medio "corretto" per il volume di vendite
// (Bayesian shrinkage verso la media del team, così un campione di 2-3
// vendite di alto valore non scavalca chi ne ha chiuse molte di più)
// più un indice di volume, pesati 60/40
function calcolaPerformanceTeam(righeMese) {
  const attivi = righeMese.filter((r) => r.corsi > 0);
  const venditeTotali = attivi.reduce((s, r) => s + r.corsi, 0);
  const fatturatoTotale = attivi.reduce((s, r) => s + r.valore, 0);
  const numeroVenditoriAttivi = attivi.length;
  if (venditeTotali === 0 || numeroVenditoriAttivi === 0) return { righe: [], mediaPerformance: 0 };
  const ticketMedioTeam = fatturatoTotale / venditeTotali;
  const venditeMedieTeam = venditeTotali / numeroVenditoriAttivi;
  const righe = attivi.map((r) => {
    const n = r.corsi;
    const ticketMedioAggiustato = (n * r.ticketMedio + venditeMedieTeam * ticketMedioTeam) / (n + venditeMedieTeam);
    const indiceQualita = (ticketMedioAggiustato / ticketMedioTeam) * 100;
    const indiceVolume = (n / venditeMedieTeam) * 100;
    return { ...r, performance: indiceQualita * 0.6 + indiceVolume * 0.4 };
  });
  const mediaPerformance = righe.reduce((s, r) => s + r.performance, 0) / righe.length;
  return { righe, mediaPerformance };
}
function rankPerformanceConTrend(corrente, precedente) {
  const perfCorrente = calcolaPerformanceTeam(corrente);
  const perfPrecedente = calcolaPerformanceTeam(precedente);
  const posPrecById = Object.fromEntries(
    perfPrecedente.righe.slice().sort((a, b) => b.performance - a.performance).map((r, i) => [r.venditore.id, i + 1])
  );
  const righe = perfCorrente.righe.slice().sort((a, b) => b.performance - a.performance).map((r, i) => ({
    ...r,
    posizione: i + 1,
    trendPosizioni: posPrecById[r.venditore.id] ? posPrecById[r.venditore.id] - (i + 1) : null,
  }));
  return { righe, mediaPerformance: Math.round(perfCorrente.mediaPerformance) };
}

const COLORI_AVATAR_CLASSIFICA = ["#2E5C8A", "#8A6D1D", "#2E7D32", "#7B4B94", "#B0552F", "#456", "#1F6F78"];
function coloreAvatarClassifica(nome) {
  let h = 0;
  for (let i = 0; i < nome.length; i++) h = (h * 31 + nome.charCodeAt(i)) % COLORI_AVATAR_CLASSIFICA.length;
  return COLORI_AVATAR_CLASSIFICA[h];
}

// una colonna della classifica venditori (vedi PaginaDashboardVenditori):
// mostra i primi 5 per il valore scelto (chiusure o Performance), con
// il proprio venditore sempre visibile — aggiunto in coda se fuori dal
// primo 5 — e un confronto col mese precedente espresso come movimento
// in classifica (posizioni salite/scese)
function ColonnaClassifica({ titolo, sottotitolo, righe, chiaveValore, tipoTrend, etichettaMedia, formatValore, coloreValore, venditoreSelId, mostraTutti, onToggleMostraTutti }) {
  const proprioIdx = righe.findIndex((r) => r.venditore.id === venditoreSelId);
  const max = Math.max(1, ...righe.map((r) => r[chiaveValore]));
  let daMostrare = righe.slice(0, 5);
  let mostraSeparatore = false;
  if (mostraTutti) {
    daMostrare = righe;
  } else if (proprioIdx >= 5) {
    daMostrare = [...righe.slice(0, 5), righe[proprioIdx]];
    mostraSeparatore = true;
  }
  return (
    <div style={cardStyle}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10, marginBottom: 14 }}>
        <div>
          <div style={{ ...fontDisplay, fontSize: 16, fontWeight: 700, color: NAVY }}>{titolo}</div>
          <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>{sottotitolo}</div>
        </div>
        {proprioIdx >= 0 && (
          <div style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: "#8A6D1D", background: "#FBF3E4", border: `1px solid ${GOLD}`, borderRadius: 20, padding: "5px 10px", whiteSpace: "nowrap" }}>
            La tua posizione: {proprioIdx + 1}°
          </div>
        )}
      </div>
      {righe.length === 0 && <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>Nessun venditore da classificare.</div>}
      {daMostrare.map((r, i) => (
        <React.Fragment key={r.venditore.id}>
          {mostraSeparatore && i === 5 && <div style={{ ...fontBody, fontSize: 11, color: MUTED, textAlign: "center", padding: "4px 0" }}>⋯</div>}
          <RigaClassifica r={r} max={max} chiaveValore={chiaveValore} tipoTrend={tipoTrend} formatValore={formatValore} coloreValore={coloreValore} evidenzia={r.venditore.id === venditoreSelId} />
        </React.Fragment>
      ))}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12, paddingTop: 12, borderTop: `1px solid ${CREAM_BORDER}` }}>
        <div style={{ ...fontBody, fontSize: 12, color: MUTED }}>Media team: {etichettaMedia}</div>
        {righe.length > 5 && (
          <button onClick={onToggleMostraTutti} style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, background: "none", border: "none", cursor: "pointer", textDecoration: "underline" }}>
            {mostraTutti ? "Mostra solo i primi 5" : "Vedi classifica completa"}
          </button>
        )}
      </div>
    </div>
  );
}

function RigaClassifica({ r, max, chiaveValore, tipoTrend, formatValore, coloreValore, evidenzia }) {
  const iniziali = r.venditore.nome.trim().slice(0, 2).toUpperCase();
  const valore = r[chiaveValore];
  let trendTesto = "–", trendColore = MUTED;
  if (tipoTrend === "posizioni") {
    if (r.trendPosizioni) { trendTesto = r.trendPosizioni > 0 ? `+${r.trendPosizioni}` : String(r.trendPosizioni); trendColore = r.trendPosizioni > 0 ? "#2E7D32" : "#C0392B"; }
  } else if (tipoTrend === "percentuale") {
    if (r.trendPct) { trendTesto = r.trendPct > 0 ? `+${r.trendPct}%` : `${r.trendPct}%`; trendColore = r.trendPct > 0 ? "#2E7D32" : "#C0392B"; }
  }
  const coloreValoreFinale = coloreValore ? coloreValore(valore) : NAVY;
  return (
    <div style={{ padding: "8px 8px", marginBottom: 4, borderRadius: 10, background: evidenzia ? "#FBF3E4" : "transparent", border: evidenzia ? `1px solid ${GOLD}` : "1px solid transparent" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <div style={{ ...fontDisplay, fontSize: 13, fontWeight: 700, color: r.posizione === 1 ? GOLD : MUTED, width: 16, textAlign: "center", flexShrink: 0 }}>{r.posizione}</div>
        <div style={{ width: 30, height: 30, borderRadius: "50%", background: coloreAvatarClassifica(r.venditore.nome), color: "#fff", ...fontBody, fontSize: 12, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{iniziali}</div>
        <div style={{ flex: 1, minWidth: 0, display: "flex", alignItems: "center", gap: 6 }}>
          <span style={{ ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{toTitleCase(r.venditore.nome)}</span>
          {evidenzia && <span style={{ ...fontBody, fontSize: 10, fontWeight: 700, color: "#fff", background: GOLD, borderRadius: 8, padding: "1px 6px", flexShrink: 0 }}>TU</span>}
        </div>
        <div style={{ ...fontBody, fontSize: 13, fontWeight: 700, color: coloreValoreFinale, flexShrink: 0 }}>{formatValore(valore)}</div>
        <div style={{ ...fontBody, fontSize: 11.5, fontWeight: 700, color: trendColore, width: 34, textAlign: "right", flexShrink: 0 }}>{trendTesto}</div>
      </div>
      <div style={{ height: 5, background: BG, borderRadius: 3, overflow: "hidden", marginTop: 6, marginLeft: 40 }}>
        <div style={{ height: "100%", width: `${Math.min(100, (valore / max) * 100)}%`, background: evidenzia ? GOLD : coloreValoreFinale, borderRadius: 3 }} />
      </div>
    </div>
  );
}

// ---------- Dashboard modelle ----------
// calcola, per ogni edizione (corsi_date), l'elenco degli "slot modella"
// richiesti: uno per giorno con "Modella del Master" nel template
// corsi_giorni, più uno per ogni trattamento richiesto da ciascun allievo
// NOSTRA (richiede_modelle=true) nei giorni Allievi del template. Stessa
// logica esatta usata in "Assegna modelle" (SchedaData, vista "modelle"),
// solo estesa a tutte le edizioni invece che a una sola — uno slot è
// "assegnata" quando il suo nome_modella non è vuoto
function calcolaSlotModelle({ corsiDate, corsi, location, master, iscritti, corsiGiorni }) {
  const corsoById = Object.fromEntries(corsi.map((c) => [c.id, c]));
  const locById = Object.fromEntries(location.map((l) => [l.id, l]));
  const masterById = Object.fromEntries((master || []).map((m) => [m.id, m]));
  const giorniByCorso = {};
  (corsiGiorni || []).forEach((g) => {
    (giorniByCorso[g.corso_id] = giorniByCorso[g.corso_id] || []).push(g);
  });

  const slot = [];
  corsiDate.forEach((cd) => {
    const corso = corsoById[cd.corso_id];
    const loc = locById[cd.location_id];
    const masterRec = masterById[cd.master_id];
    const base = {
      corsoDataId: cd.id, corsoId: cd.corso_id, corsoNome: corso?.nome || "?", cittaNome: loc?.nome || "?",
      dataInizio: cd.data_inizio, dataFine: cd.data_fine, masterTrainerNome: masterRec?.nome || "",
    };
    const giorniCorso = (giorniByCorso[cd.corso_id] || []).slice().sort((a, b) => a.numero_giorno - b.numero_giorno);
    const giorniRilevanti = giorniCorso.filter((g) => g.richiede_modella_master || g.richiede_modelle_allievi);
    const giornoRipiego = giorniCorso.filter((g) => g.richiede_modelle_allievi)[0]?.numero_giorno ?? null;
    const iscrittiCd = iscritti.filter((i) => i.corso_data_id === cd.id);

    if (giorniRilevanti.length > 0) {
      giorniRilevanti.forEach((g) => {
        if (g.richiede_modella_master) {
          const modelleMaster = Array.isArray(cd.modelle_master) ? cd.modelle_master : [];
          const entry = modelleMaster.find((m) => m.numero_giorno === g.numero_giorno);
          if (entry?.cercare_per_master) slot.push({
            ...base, id: `${cd.id}-master-${g.numero_giorno}`, ruolo: "master", numeroGiorno: g.numero_giorno,
            tipo: g.tipo_modella_master || "Modella del Master", allievoNome: null,
            nomeModella: entry?.nome_modella || "", telefonoModella: entry?.telefono_modella || "",
            assegnata: modellaTrovata(entry),
          });
        }
        if (g.richiede_modelle_allievi) {
          iscrittiCd.forEach((i) => {
            if (!i.richiede_modelle) return; // SUA: se la porta l'allieva, non è un "fabbisogno" nostro
            (Array.isArray(i.tipi_modelle) ? i.tipi_modelle : []).forEach((m, idx) => {
              if ((m.giorno ?? giornoRipiego) !== g.numero_giorno) return;
              slot.push({
                ...base, id: `${cd.id}-allievo-${i.id}-${idx}`, ruolo: "allievo", numeroGiorno: g.numero_giorno,
                tipo: m.tipo || g.tipo_modella_allievi || "?", allievoNome: `${i.nome} ${i.cognome}`,
                iscrittoId: i.id, indexTipi: idx,
                nomeModella: m.nome_modella || "", telefonoModella: m.telefono_modella || "",
                assegnata: modellaTrovata(m),
              });
            });
          });
        }
      });
    } else {
      // corso senza template corsi_giorni: elenco piatto, come il ramo
      // legacy di "Assegna modelle" quando giorniRilevantiModelle è vuoto
      iscrittiCd.forEach((i) => {
        if (!i.richiede_modelle) return;
        (Array.isArray(i.tipi_modelle) ? i.tipi_modelle : []).forEach((m, idx) => {
          slot.push({
            ...base, id: `${cd.id}-allievo-${i.id}-${idx}`, ruolo: "allievo", numeroGiorno: null,
            tipo: m.tipo || "?", allievoNome: `${i.nome} ${i.cognome}`, iscrittoId: i.id, indexTipi: idx,
            nomeModella: m.nome_modella || "", telefonoModella: m.telefono_modella || "",
            assegnata: modellaTrovata(m),
          });
        });
      });
    }
  });
  return slot;
}

// scrive nome/telefono su un singolo slot (master o allievo), sulla
// tabella giusta (corsi_date.modelle_master o iscritti.tipi_modelle) —
// nome/telefono vuoti "liberano" lo slot (usato anche per "Elimina")
async function scriviSlotModella(slotDaScrivere, { corsiDate, iscritti }, nomeModella, telefonoModella) {
  if (slotDaScrivere.ruolo === "master") {
    // si rilegge dal database invece di usare la copia in pagina: due
    // scritture ravvicinate sullo stesso corso, partendo entrambe dalla
    // stessa copia vecchia, si cancellavano a vicenda
    const { data: cd } = await supabase.from("corsi_date").select("modelle_master").eq("id", slotDaScrivere.corsoDataId).maybeSingle();
    const attuale = Array.isArray(cd?.modelle_master) ? cd.modelle_master : [];
    const idx = attuale.findIndex((m) => m.numero_giorno === slotDaScrivere.numeroGiorno);
    const nuovo = idx >= 0
      ? attuale.map((m, i) => (i === idx ? { ...m, nome_modella: nomeModella, telefono_modella: telefonoModella } : m))
      : [...attuale, { numero_giorno: slotDaScrivere.numeroGiorno, mattina: false, pomeriggio: false, nome_modella: nomeModella, telefono_modella: telefonoModella }];
    const { error } = await supabase.from("corsi_date").update({ modelle_master: nuovo }).eq("id", slotDaScrivere.corsoDataId);
    return error;
  }
  const { data: iscritto } = await supabase.from("iscritti").select("tipi_modelle").eq("id", slotDaScrivere.iscrittoId).maybeSingle();
  const attuale = Array.isArray(iscritto?.tipi_modelle) ? iscritto.tipi_modelle : [];
  const nuovo = attuale.map((m, i) => (i === slotDaScrivere.indexTipi ? { ...m, nome_modella: nomeModella, telefono_modella: telefonoModella } : m));
  const { error } = await supabase.from("iscritti").update({ tipi_modelle: nuovo }).eq("id", slotDaScrivere.iscrittoId);
  return error;
}

// sposta una modella già assegnata da uno slot a un altro (libera lo slot
// di partenza, la scrive su quello di arrivo con lo stesso nome/telefono)
async function spostaModellaTraSlot(slotOrigine, slotDestinazione, ctx) {
  const err1 = await scriviSlotModella(slotOrigine, ctx, "", "");
  if (err1) return err1;
  const err2 = await scriviSlotModella(slotDestinazione, ctx, slotOrigine.nomeModella, slotOrigine.telefonoModella);
  return err2;
}

function etichettaSlot(s) {
  return `${fmtDataCompatta(s.dataInizio, s.dataFine)} · ${s.cittaNome} · ${toTitleCase(s.corsoNome)} · ${s.tipo}${s.allievoNome ? " · " + toTitleCase(s.allievoNome) : ""}`;
}

// card statistica in cima alla Dashboard modelle: cliccabile quando passa
// onClick (le due centrali aprono le liste di slot corrispondenti)
function CardStatisticaModelle({ etichetta, valore, sottotitolo, colore, sfondo, icona, onClick, compatto }) {
  return (
    <button
      onClick={onClick}
      disabled={!onClick}
      style={{
        ...fontBody, textAlign: compatto ? "center" : "left", flex: compatto ? "1 1 0" : "1 1 200px", minWidth: 0,
        display: "flex", flexDirection: compatto ? "column" : "row", alignItems: "center", gap: compatto ? 5 : 14,
        background: sfondo || "#fff", border: `1px solid ${sfondo ? "transparent" : CREAM_BORDER}`, borderRadius: 14,
        padding: compatto ? "12px 5px" : 18, cursor: onClick ? "pointer" : "default",
      }}
    >
      {icona && (
        <span style={{ width: compatto ? 32 : 42, height: compatto ? 32 : 42, borderRadius: "50%", background: colore ? `${colore}22` : "#F1ECDF", color: colore || NAVY, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          {icona}
        </span>
      )}
      <span style={{ minWidth: 0 }}>
        <div style={{ ...fontBody, fontSize: compatto ? 10 : 13, color: MUTED, marginBottom: 2, lineHeight: compatto ? 1.15 : undefined }}>{etichetta}</div>
        <div style={{ ...fontDisplay, fontSize: compatto ? 22 : 26, fontWeight: 700, color: colore || NAVY, lineHeight: 1 }}>{valore}</div>
        {sottotitolo && <div style={{ ...fontBody, fontSize: compatto ? 9.5 : 12, color: MUTED, marginTop: 3, lineHeight: compatto ? 1.1 : undefined }}>{sottotitolo}</div>}
      </span>
    </button>
  );
}

// banner di avviso scadenze modelle: rimane visibile finché non si preme
// "Visualizzato" — torna a comparire da capo se, alla riapertura della
// pagina, il numero di slot urgenti è cambiato rispetto a quando è stato
// chiuso l'ultima volta (altrimenti resterebbe muto per sempre su nuove
// urgenze comparse dopo la chiusura)
function AlertScadenzeModelle({ numeroSlot, numeroCorsi, giorni }) {
  const chiaveVisto = `edc_alert_modelle_${numeroSlot}_${numeroCorsi}_${giorni}`;
  const [chiuso, setChiuso] = useState(() => sessionStorage.getItem(chiaveVisto) === "1");
  if (chiuso || numeroSlot === 0) return null;
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 14, background: "#FDECEC", border: "1px solid #F5C6C0", borderRadius: 14, padding: "14px 18px", marginBottom: 18 }}>
      <span style={{ width: 34, height: 34, borderRadius: "50%", background: "#C0392B", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <path d="M12 9v4" /><path d="M12 17h.01" />
          <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
        </svg>
      </span>
      <div style={{ flex: 1, ...fontBody, fontSize: 14, color: "#7A2C1E" }}>
        <strong>{numeroSlot} modell{numeroSlot === 1 ? "a" : "e"} ancora da trovare</strong> per {numeroCorsi} corso{numeroCorsi === 1 ? "" : "i"} in partenza entro {giorni} giorni.
      </div>
      <Button variant="ghost" style={{ borderColor: "#C0392B", color: "#C0392B", flexShrink: 0 }} onClick={() => { sessionStorage.setItem(chiaveVisto, "1"); setChiuso(true); }}>
        Visualizzato
      </Button>
    </div>
  );
}

// ordine fisso dei trattamenti nelle colonne di "Modelle necessarie":
// sopracciglia sempre per prima, poi labbra, poi eyeliner — qualunque altro
// trattamento (needling, laminazione, microblading...) segue in ordine
// alfabetico. Basato su parola chiave, non sul testo esatto, perché il nome
// reale porta sempre una variante ("SOPRACCIGLIA OMBRETTO", "EYELINER
// BASE"...)
function prioritaTipoModella(tipo) {
  const t = String(tipo || "").toUpperCase();
  if (t.includes("SOPRACCIGLIA")) return 0;
  if (t.includes("LABBRA")) return 1;
  if (t.includes("EYELINER")) return 2;
  return 3;
}

// riga cliccabile della lista "Priorità": stessa card di CardDataMaster
// (bordo + spigoli arrotondati, riquadro data colorato, sezioni separate da
// una riga sottile) invece della semplice riga di lista di prima — stessa
// distribuzione di informazioni: data colorata → corso e sede → riepilogo
// richieste/assegnate/da trovare, sotto la lista di chi manca. Bordo e
// riquadro data nel colore proprio del corso (come CardDataMaster), non
// nel colore di urgenza — quello resta solo sul badge "TRA N GIORNI". Le
// icone dei trattamenti sono allineate in colonne fisse (sopracciglia,
// labbra, eyeliner, poi altri): così "sopracciglia" di un'allieva è sempre
// nella stessa colonna di "sopracciglia" delle altre, invece di scorrere
// dopo il nome (che ha lunghezze diverse) come accadeva prima.
function RigaPrioritaModelle({ edizione, onApri }) {
  const g = edizione.giorniAOggi;
  const coloreCorso = edizione.colore || NAVY;
  // sotto i 20 giorni (compreso oggi/in corso) il badge cresce e lampeggia
  // rosso: è la soglia oltre la quale bisogna davvero muoversi
  const urgente = g <= 20;
  const testoGiorni = g < 0 ? "IN CORSO" : g === 0 ? "OGGI" : g === 1 ? "DOMANI" : `TRA ${g} GIORNI`;
  const badgeGiorni = (
    <>
      {urgente && <style>{`@keyframes lampeggiaPrioritaModelle { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }`}</style>}
      <span style={{
        ...fontBody, fontWeight: 700, display: "inline-block", whiteSpace: "nowrap", borderRadius: 20,
        ...(urgente
          ? { fontSize: 13, color: "#fff", background: "#C0392B", padding: "6px 13px", animation: "lampeggiaPrioritaModelle 1.1s ease-in-out infinite" }
          : { fontSize: 11, color: NAVY, background: "#F1ECDF", padding: "4px 9px" }),
      }}>
        {testoGiorni}
      </span>
    </>
  );
  const { numero: numeroData, sotto: sottoData } = etichettaIntervalloGiorni(edizione.dataInizio, edizione.dataFine);
  const numero = (v, c, lab) => (
    <div style={{ textAlign: "center" }}>
      <div style={{ ...fontDisplay, fontSize: 20, fontWeight: 700, color: c }}>{v}</div>
      <div style={{ ...fontBody, fontSize: 11, color: MUTED }}>{lab}</div>
    </div>
  );

  const nomiAllievi = [];
  const trattamentiPerAllievo = new Map();
  edizione.slot.forEach((s) => {
    if (s.ruolo !== "allievo") return;
    if (!trattamentiPerAllievo.has(s.allievoNome)) { trattamentiPerAllievo.set(s.allievoNome, []); nomiAllievi.push(s.allievoNome); }
    const tipi = trattamentiPerAllievo.get(s.allievoNome);
    if (!tipi.includes(s.tipo)) tipi.push(s.tipo);
  });
  // colonne fisse per tipo di trattamento: sopracciglia, labbra, eyeliner,
  // poi il resto in ordine alfabetico
  const tipiPresenti = Array.from(new Set(edizione.slot.filter((s) => s.ruolo === "allievo").map((s) => s.tipo)))
    .sort((a, b) => prioritaTipoModella(a) - prioritaTipoModella(b) || String(a).localeCompare(String(b)));
  // le colonne dei trattamenti non possono avere larghezza "a contenuto"
  // (auto): con le schede ristrette, 3 trattamenti lunghi (es.
  // "SOPRACCIGLIA OMBRETTO") sforerebbero il bordo verso destra — restano
  // frazioni della larghezza disponibile, col testo troncato solo se
  // davvero non ci sta. Il nome invece non si tronca mai: se non basta lo
  // spazio va a capo su due righe, piuttosto che tagliare il nome
  // dell'allieva
  const anteprimaAllievi = nomiAllievi.length > 0 && (
    <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${CREAM_BORDER}` }}>
      <div style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 8 }}>Modelle necessarie</div>
      <div style={{
        display: "grid",
        gridTemplateColumns: `minmax(70px, 1.4fr) repeat(${tipiPresenti.length}, minmax(0, 1fr))`,
        columnGap: 6, rowGap: 8, alignItems: "center",
      }}>
        {nomiAllievi.map((nome) => (
          <React.Fragment key={nome}>
            <span style={{ ...fontBody, fontSize: 11, fontWeight: 700, color: NAVY, whiteSpace: "normal", wordBreak: "break-word" }}>{nome.toUpperCase()}</span>
            {tipiPresenti.map((t) => (
              <div key={t} style={{ minWidth: 0, textAlign: "center" }}>
                {trattamentiPerAllievo.get(nome).includes(t) && <PallinoTipoModellaCompatto tipo={t} />}
              </div>
            ))}
          </React.Fragment>
        ))}
      </div>
    </div>
  );

  return (
    <div onClick={onApri} style={{ border: `2px solid ${coloreCorso}`, borderLeftWidth: 6, borderRadius: 16, padding: 16, background: "#fff", cursor: "pointer" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginBottom: 10, flexWrap: "wrap" }}>
        {badgeGiorni}
        <span style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, textDecoration: "underline" }}>Clicca per assegnare modelle</span>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
        <div style={{ background: coloreCorso, borderRadius: 12, padding: "10px 14px", textAlign: "center", flexShrink: 0 }}>
          <div style={{ ...fontDisplay, fontSize: numeroData.length > 5 ? 14 : 20, fontWeight: 700, color: "#fff", whiteSpace: "nowrap" }}>{numeroData}</div>
          {sottoData && <div style={{ ...fontBody, fontSize: 10, fontWeight: 700, color: "#fff", textTransform: "uppercase" }}>{sottoData}</div>}
        </div>
        <div style={{ flex: "1 1 120px", minWidth: 0 }}>
          <div style={{ ...fontDisplay, fontSize: 17, fontWeight: 700, color: NAVY, lineHeight: 1.25 }}>{toTitleCase(edizione.corsoNome)}</div>
          <div style={{ ...fontDisplay, fontSize: 14, fontWeight: 700, color: NAVY, lineHeight: 1.25 }}>{toTitleCase(edizione.cittaNome)}</div>
          {edizione.masterTrainerNome && <div style={{ ...fontBody, fontSize: 11.5, color: MUTED, marginTop: 2 }}>Master: {toTitleCase(edizione.masterTrainerNome)}</div>}
        </div>
      </div>
      <div style={{ display: "flex", gap: 14, marginTop: 12 }}>
        {numero(edizione.richieste, NAVY, "richieste")}
        {numero(edizione.assegnate, "#2E7D32", "assegnate")}
        {numero(edizione.daTrovare, "#C0392B", "da trovare")}
      </div>
      {anteprimaAllievi}
    </div>
  );
}

// blocco per città nel pannello "Richieste totali per città": barra di
// avanzamento assegnate/richieste + tipologie principali
// riga cliccabile: si espande mostrando, corso per corso, ogni singolo
// slot che compone il totale (Modella del Master vs allievo, con nome
// dell'allievo e se è già assegnata) — serve a verificare da dove viene
// un numero, non solo a vederlo
function RigaCittaModelle({ dati, onApriEdizione }) {
  const [espanso, setEspanso] = useState(false);
  const pct = dati.richieste > 0 ? Math.round((dati.assegnate / dati.richieste) * 100) : 0;
  const tipologieOrdinate = Object.entries(dati.tipologie).sort((a, b) => b[1] - a[1]);
  const principali = tipologieOrdinate.slice(0, 3);
  const restoConteggio = tipologieOrdinate.slice(3).reduce((s, [, n]) => s + n, 0);
  return (
    <div style={{ padding: "14px 0", borderBottom: `1px solid ${CREAM_BORDER}` }}>
      <div onClick={() => setEspanso((v) => !v)} style={{ cursor: "pointer" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 4 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6, ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY }}>
            <IconaMarker size={14} /> {dati.citta.toUpperCase()}
            <span style={{ transform: espanso ? "rotate(90deg)" : "none", display: "flex", color: MUTED }}>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6" /></svg>
            </span>
          </div>
          <div style={{ ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY }}>{dati.richieste} modell{dati.richieste === 1 ? "a" : "e"}</div>
        </div>
        <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginBottom: 8 }}>
          {principali.map(([t, n], idx) => <span key={t}>{idx > 0 ? " · " : ""}{t} {n}</span>)}
          {restoConteggio > 0 && <span> · Altro {restoConteggio}</span>}
        </div>
        <div style={{ height: 6, borderRadius: 3, background: "#F1ECDF", overflow: "hidden", marginBottom: 6 }}>
          <div style={{ height: "100%", width: `${pct}%`, background: "#2E7D32", borderRadius: 3 }} />
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", ...fontBody, fontSize: 12 }}>
          <span style={{ color: "#2E7D32", fontWeight: 600 }}>{dati.assegnate} assegnate</span>
          <span style={{ color: "#C0392B", fontWeight: 600 }}>{dati.richieste - dati.assegnate} da trovare</span>
        </div>
      </div>
      {espanso && (
        <div style={{ marginTop: 10, background: "#F7F5EF", borderRadius: 10, padding: 10 }}>
          {dati.edizioni.map((e) => (
            <div key={e.corsoDataId} style={{ marginBottom: 10 }}>
              <div
                onClick={() => onApriEdizione?.(e)}
                style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", cursor: onApriEdizione ? "pointer" : "default", marginBottom: 4 }}
              >
                <span style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY }}>{fmtDataCompatta(e.dataInizio, e.dataFine)} · {toTitleCase(e.corsoNome)}</span>
                <span style={{ ...fontBody, fontSize: 11, color: MUTED }}>{e.richieste} slot</span>
              </div>
              {e.slot.map((s) => (
                <div key={s.id} style={{ display: "flex", justifyContent: "space-between", gap: 8, ...fontBody, fontSize: 12, padding: "3px 0", color: NAVY }}>
                  <span style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {s.ruolo === "master" ? "Modella del Master" : toTitleCase(s.allievoNome)} · {s.tipo}
                  </span>
                  <span style={{ flexShrink: 0, fontWeight: 600, color: s.assegnata ? "#2E7D32" : "#C0392B" }}>
                    {s.assegnata ? toTitleCase(s.nomeModella) : "da trovare"}
                  </span>
                </div>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
function IconaMarker({ size = 14, color = NAVY }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M21 10c0 6-9 12-9 12s-9-6-9-12a9 9 0 0 1 18 0z" /><circle cx="12" cy="10" r="3" />
    </svg>
  );
}

// modale "Ancora da trovare": elenco degli slot scoperti, ognuno apribile
// per inserire nome e telefono della modella trovata e salvare
function ModaleSlotDaTrovare({ slotList, ctx, ricarica, onClose }) {
  const [apertoId, setApertoId] = useState(null);
  const [nome, setNome] = useState("");
  const [telefono, setTelefono] = useState("");
  const [salvando, setSalvando] = useState(false);
  const [errore, setErrore] = useState("");

  function apri(s) { setApertoId(s.id); setNome(""); setTelefono(""); setErrore(""); }
  async function salva(s) {
    if (!nome.trim()) { setErrore("Scrivi almeno il nome della modella."); return; }
    setSalvando(true); setErrore("");
    const err = await scriviSlotModella(s, ctx, nome.trim(), telefono.trim());
    setSalvando(false);
    if (err) { setErrore("Errore: " + err.message); return; }
    setApertoId(null);
    await ricarica(["corsi_date", "iscritti"]);
  }

  return (
    <Modal title={`Modelle da trovare (${slotList.length})`} onClose={onClose} maxWidth={640}>
      {slotList.length === 0 ? (
        <div style={{ ...fontBody, fontSize: 14, color: MUTED, padding: "20px 0" }}>Nessuna modella ancora da trovare: tutti gli slot attivi sono assegnati.</div>
      ) : (
        slotList.map((s) => (
          <div key={s.id} style={{ borderBottom: `1px solid ${CREAM_BORDER}`, padding: "12px 0" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY }}>{fmtDataCompatta(s.dataInizio, s.dataFine)} · {s.cittaNome} · {toTitleCase(s.corsoNome)}</div>
                <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>
                  {s.ruolo === "master" ? "Modella del Master" : `Allieva: ${toTitleCase(s.allievoNome)}`} · {s.tipo}
                </div>
              </div>
              {apertoId !== s.id && <Button variant="ghost" style={{ flexShrink: 0 }} onClick={() => apri(s)}>Assegna</Button>}
            </div>
            {apertoId === s.id && (
              <div style={{ marginTop: 10, display: "flex", gap: 8, alignItems: "flex-end", flexWrap: "wrap" }}>
                <div style={{ flex: "1 1 160px" }}>
                  <Field label="Nome e cognome"><input style={inputStyle} value={nome} onChange={(e) => setNome(e.target.value)} autoFocus /></Field>
                </div>
                <div style={{ flex: "1 1 140px" }}>
                  <Field label="Telefono"><input style={inputStyle} value={telefono} onChange={(e) => setTelefono(e.target.value)} /></Field>
                </div>
                <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
                  <Button onClick={() => salva(s)} disabled={salvando}>{salvando ? "Salvo…" : "Salva"}</Button>
                  <Button variant="ghost" onClick={() => setApertoId(null)}>Annulla</Button>
                </div>
              </div>
            )}
            {apertoId === s.id && errore && <div style={{ ...fontBody, fontSize: 13, color: "#C0392B" }}>{errore}</div>}
          </div>
        ))
      )}
    </Modal>
  );
}

// modale "Già assegnate": elenco delle modelle assegnate, con azioni
// Modifica (rinomina nome/telefono), Sposta (su un altro slot scoperto),
// Elimina (libera lo slot)
function ModaleModelleAssegnate({ slotList, slotDaTrovare, ctx, ricarica, onClose }) {
  const [inModifica, setInModifica] = useState(null); // { id, modo: "modifica" | "sposta" }
  const [nome, setNome] = useState("");
  const [telefono, setTelefono] = useState("");
  const [destinazioneId, setDestinazioneId] = useState("");
  const [salvando, setSalvando] = useState(false);
  const [errore, setErrore] = useState("");

  function apriModifica(s) { setInModifica({ id: s.id, modo: "modifica" }); setNome(s.nomeModella); setTelefono(s.telefonoModella); setErrore(""); }
  function apriSposta(s) { setInModifica({ id: s.id, modo: "sposta" }); setDestinazioneId(""); setErrore(""); }
  async function salvaModifica(s) {
    if (!nome.trim()) { setErrore("Il nome non può essere vuoto (usa Elimina per liberare lo slot)."); return; }
    setSalvando(true); setErrore("");
    const err = await scriviSlotModella(s, ctx, nome.trim(), telefono.trim());
    setSalvando(false);
    if (err) { setErrore("Errore: " + err.message); return; }
    setInModifica(null);
    await ricarica(["corsi_date", "iscritti"]);
  }
  async function confermaSposta(s) {
    const dest = slotDaTrovare.find((d) => d.id === destinazioneId);
    if (!dest) { setErrore("Scegli lo slot di destinazione."); return; }
    setSalvando(true); setErrore("");
    const err = await spostaModellaTraSlot(s, dest, ctx);
    setSalvando(false);
    if (err) { setErrore("Errore: " + err.message); return; }
    setInModifica(null);
    await ricarica(["corsi_date", "iscritti"]);
  }
  async function elimina(s) {
    if (!window.confirm(`Rimuovere ${toTitleCase(s.nomeModella)} da questo slot? Tornerà "da trovare".`)) return;
    setSalvando(true);
    const err = await scriviSlotModella(s, ctx, "", "");
    setSalvando(false);
    if (err) { window.alert("Errore: " + err.message); return; }
    await ricarica(["corsi_date", "iscritti"]);
  }

  return (
    <Modal title={`Modelle assegnate (${slotList.length})`} onClose={onClose} maxWidth={680}>
      {slotList.length === 0 ? (
        <div style={{ ...fontBody, fontSize: 14, color: MUTED, padding: "20px 0" }}>Nessuna modella assegnata ancora.</div>
      ) : (
        slotList.map((s) => (
          <div key={s.id} style={{ borderBottom: `1px solid ${CREAM_BORDER}`, padding: "12px 0" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY }}>{toTitleCase(s.nomeModella)}{s.telefonoModella && <span style={{ fontWeight: 400, color: MUTED }}> · {s.telefonoModella}</span>}</div>
                <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>{etichettaSlot(s)}</div>
              </div>
              <div style={{ display: "flex", gap: 4, flexShrink: 0 }}>
                <button onClick={() => apriModifica(s)} title="Modifica" style={{ border: "none", background: "none", cursor: "pointer", color: NAVY, padding: 6, display: "flex" }}>
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" /><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" /></svg>
                </button>
                <button onClick={() => apriSposta(s)} title="Sposta su un altro corso" style={{ border: "none", background: "none", cursor: "pointer", color: NAVY, padding: 6, display: "flex" }}>
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17 3l4 4-4 4" /><path d="M3 11V9a4 4 0 0 1 4-4h14" /><path d="M7 21l-4-4 4-4" /><path d="M21 13v2a4 4 0 0 1-4 4H3" /></svg>
                </button>
                <button onClick={() => elimina(s)} disabled={salvando} title="Elimina" style={{ border: "none", background: "none", cursor: "pointer", color: "#C0392B", padding: 6, display: "flex" }}>
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6" /><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" /><path d="M10 11v6" /><path d="M14 11v6" /><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2" /></svg>
                </button>
              </div>
            </div>
            {inModifica?.id === s.id && inModifica.modo === "modifica" && (
              <div style={{ marginTop: 10, display: "flex", gap: 8, alignItems: "flex-end", flexWrap: "wrap" }}>
                <div style={{ flex: "1 1 160px" }}><Field label="Nome e cognome"><input style={inputStyle} value={nome} onChange={(e) => setNome(e.target.value)} autoFocus /></Field></div>
                <div style={{ flex: "1 1 140px" }}><Field label="Telefono"><input style={inputStyle} value={telefono} onChange={(e) => setTelefono(e.target.value)} /></Field></div>
                <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
                  <Button onClick={() => salvaModifica(s)} disabled={salvando}>{salvando ? "Salvo…" : "Salva"}</Button>
                  <Button variant="ghost" onClick={() => setInModifica(null)}>Annulla</Button>
                </div>
              </div>
            )}
            {inModifica?.id === s.id && inModifica.modo === "sposta" && (
              <div style={{ marginTop: 10, display: "flex", gap: 8, alignItems: "flex-end", flexWrap: "wrap" }}>
                <div style={{ flex: "1 1 320px" }}>
                  <Field label="Sposta su">
                    <select style={inputStyle} value={destinazioneId} onChange={(e) => setDestinazioneId(e.target.value)}>
                      <option value="">— scegli lo slot scoperto —</option>
                      {slotDaTrovare.map((d) => <option key={d.id} value={d.id}>{etichettaSlot(d)}</option>)}
                    </select>
                  </Field>
                </div>
                <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
                  <Button onClick={() => confermaSposta(s)} disabled={salvando || !destinazioneId}>{salvando ? "Sposto…" : "Conferma spostamento"}</Button>
                  <Button variant="ghost" onClick={() => setInModifica(null)}>Annulla</Button>
                </div>
              </div>
            )}
            {inModifica?.id === s.id && errore && <div style={{ ...fontBody, fontSize: 13, color: "#C0392B" }}>{errore}</div>}
          </div>
        ))
      )}
    </Modal>
  );
}

// dashboard "Fabbisogno, scadenze e assegnazioni": card riepilogo, filtri,
// priorità prossimi 15 giorni, riepilogo per città, tabella completa
function PaginaDashboardModelle({ corsi, location, corsiDate, iscritti, master, corsiGiorni, ricarica, apriDataModelle }) {
  // l'elenco resta diviso per mese: cliccando una colonna si riordina
  // dentro ogni mese, non fra mesi diversi — il calendario resta leggibile
  const { ordine: ordineTab, cambiaOrdine: cambiaOrdineTab, ordina: ordinaTab } = useOrdinamentoTabella();
  const valoriModelle = {
    citta: (e) => e.cittaNome || "",
    data: (e) => e.dataInizio || "",
    corso: (e) => e.corsoNome || "",
    richieste: (e) => e.richieste ?? null,
    daTrovare: (e) => e.daTrovare ?? null,
  };
  const isMobile = useIsMobile();
  const oggiStr = dataOggiStr();
  const [ricerca, setRicerca] = useState("");
  const [filtroCitta, setFiltroCitta] = useState("");
  const [filtroTipologia, setFiltroTipologia] = useState("");
  const [scadenzaGiorni, setScadenzaGiorni] = useState(15);
  const [ordine, setOrdine] = useState("urgenza"); // urgenza | richieste
  const [modaleDaTrovare, setModaleDaTrovare] = useState(false);
  const [modaleAssegnate, setModaleAssegnate] = useState(false);

  const ctx = { corsiDate, iscritti };

  const slotAttivi = useMemo(
    () => calcolaSlotModelle({ corsiDate, corsi, location, master, iscritti, corsiGiorni }).filter((s) => s.dataFine >= oggiStr),
    [corsiDate, corsi, location, master, iscritti, corsiGiorni, oggiStr]
  );

  const edizioni = useMemo(() => {
    const m = new Map();
    slotAttivi.forEach((s) => {
      if (!m.has(s.corsoDataId)) m.set(s.corsoDataId, { corsoDataId: s.corsoDataId, corsoId: s.corsoId, corsoNome: s.corsoNome, cittaNome: s.cittaNome, dataInizio: s.dataInizio, dataFine: s.dataFine, masterTrainerNome: s.masterTrainerNome, colore: (corsi || []).find((c) => c.id === s.corsoId)?.colore || null, slot: [] });
      m.get(s.corsoDataId).slot.push(s);
    });
    return Array.from(m.values()).map((e) => {
      const richieste = e.slot.length;
      const assegnate = e.slot.filter((s) => s.assegnata).length;
      const tipologie = {};
      e.slot.forEach((s) => { tipologie[s.tipo] = (tipologie[s.tipo] || 0) + 1; });
      const giorniAOggi = Math.round((new Date(e.dataInizio + "T00:00:00") - new Date(oggiStr + "T00:00:00")) / 86400000);
      return { ...e, richieste, assegnate, daTrovare: richieste - assegnate, tipologie, giorniAOggi };
    }).sort((a, b) => a.dataInizio.localeCompare(b.dataInizio));
  }, [slotAttivi, oggiStr]);

  const tipologiePresenti = useMemo(() => Array.from(new Set(slotAttivi.map((s) => s.tipo))).sort(), [slotAttivi]);
  const cittaPresenti = useMemo(() => Array.from(new Set(edizioni.map((e) => e.cittaNome))).sort(), [edizioni]);

  const edizioniFiltrate = useMemo(() => {
    let arr = edizioni.filter((e) => e.richieste > 0);
    if (filtroCitta) arr = arr.filter((e) => e.cittaNome === filtroCitta);
    if (filtroTipologia) arr = arr.filter((e) => Object.keys(e.tipologie).includes(filtroTipologia));
    const termini = ricerca.trim().toLowerCase().split(/\s+/).filter(Boolean);
    if (termini.length > 0) {
      arr = arr.filter((e) => {
        const testo = [e.corsoNome, e.cittaNome, e.masterTrainerNome, ...Object.keys(e.tipologie)].filter(Boolean).join(" ").toLowerCase();
        return termini.every((t) => testo.includes(t));
      });
    }
    return arr.slice().sort((a, b) => (ordine === "richieste" ? b.daTrovare - a.daTrovare : a.dataInizio.localeCompare(b.dataInizio)));
  }, [edizioni, filtroCitta, filtroTipologia, ricerca, ordine]);

  // tabella raggruppata per mese (come nei calendari): l'ordine scelto
  // nel filtro "Ordina" vale dentro ogni mese, i mesi restano sempre in
  // sequenza cronologica
  const edizioniPerMese = useMemo(() => {
    const gruppi = new Map();
    edizioniFiltrate.forEach((e) => {
      const chiave = e.dataInizio.slice(0, 7); // "YYYY-MM"
      if (!gruppi.has(chiave)) {
        const mese = parseInt(e.dataInizio.slice(5, 7), 10);
        gruppi.set(chiave, { chiave, etichetta: `${MESI[mese - 1]} ${e.dataInizio.slice(0, 4)}`, edizioni: [] });
      }
      gruppi.get(chiave).edizioni.push(e);
    });
    return Array.from(gruppi.values()).sort((a, b) => a.chiave.localeCompare(b.chiave));
  }, [edizioniFiltrate]);

  const edizioniPrioritarie = useMemo(
    () => edizioniFiltrate.filter((e) => e.daTrovare > 0 && e.giorniAOggi <= scadenzaGiorni),
    [edizioniFiltrate, scadenzaGiorni]
  );
  // vista fissa a 60 giorni, indipendente dal filtro "Entro N giorni" qui
  // sopra: dà sempre un colpo d'occhio più ampio accanto a quella corta
  const edizioniPrioritarie60 = useMemo(
    () => edizioniFiltrate.filter((e) => e.daTrovare > 0 && e.giorniAOggi <= 60),
    [edizioniFiltrate]
  );

  const perCitta = useMemo(() => {
    const m = new Map();
    edizioniFiltrate.forEach((e) => {
      if (!m.has(e.cittaNome)) m.set(e.cittaNome, { citta: e.cittaNome, richieste: 0, assegnate: 0, tipologie: {}, edizioni: [] });
      const c = m.get(e.cittaNome);
      c.richieste += e.richieste; c.assegnate += e.assegnate;
      Object.entries(e.tipologie).forEach(([t, n]) => { c.tipologie[t] = (c.tipologie[t] || 0) + n; });
      c.edizioni.push(e);
    });
    return Array.from(m.values()).sort((a, b) => b.richieste - a.richieste);
  }, [edizioniFiltrate]);

  const totaleRichieste = edizioni.reduce((s, e) => s + e.richieste, 0);
  const totaleAssegnate = edizioni.reduce((s, e) => s + e.assegnate, 0);
  const totaleDaTrovare = totaleRichieste - totaleAssegnate;
  const corsiDistinti = new Set(edizioni.filter((e) => e.richieste > 0).map((e) => e.corsoId)).size;

  const slotDaTrovare = useMemo(() => slotAttivi.filter((s) => !s.assegnata).sort((a, b) => a.dataInizio.localeCompare(b.dataInizio)), [slotAttivi]);
  const slotAssegnati = useMemo(() => slotAttivi.filter((s) => s.assegnata).sort((a, b) => a.dataInizio.localeCompare(b.dataInizio)), [slotAttivi]);

  function apriEdizione(e) {
    const cd = corsiDate.find((c) => c.id === e.corsoDataId);
    if (cd) apriDataModelle(cd);
  }

  async function ricaricaLocale() { await ricarica(["corsi_date", "iscritti"]); }

  return (
    <div>
      <AlertScadenzeModelle numeroSlot={edizioniPrioritarie.reduce((s, e) => s + e.daTrovare, 0)} numeroCorsi={edizioniPrioritarie.length} giorni={scadenzaGiorni} />

      <div style={{ display: "flex", gap: isMobile ? 6 : 14, flexWrap: isMobile ? "nowrap" : "wrap", marginBottom: 18 }}>
        <CardStatisticaModelle compatto={isMobile}
          etichetta="Modelle richieste" valore={totaleRichieste} sottotitolo={`su ${corsiDistinti} cors${corsiDistinti === 1 ? "o" : "i"}`}
          icona={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" /><circle cx="12" cy="7" r="4" /></svg>}
        />
        <CardStatisticaModelle compatto={isMobile}
          etichetta={`In scadenza entro ${scadenzaGiorni} gg`} valore={edizioniPrioritarie.reduce((s, e) => s + e.daTrovare, 0)}
          sottotitolo={`${edizioniPrioritarie.length} cors${edizioniPrioritarie.length === 1 ? "o prioritario" : "i prioritari"}`}
          colore="#C0392B" sfondo="#FDF3D9"
          icona={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10" /><polyline points="12 6 12 12 16 14" /></svg>}
        />
        <CardStatisticaModelle compatto={isMobile}
          etichetta="Già assegnate" valore={totaleAssegnate} colore="#2E7D32" onClick={() => setModaleAssegnate(true)}
          icona={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5" /></svg>}
        />
        <CardStatisticaModelle compatto={isMobile}
          etichetta="Ancora da trovare" valore={totaleDaTrovare} colore="#C0392B" onClick={() => setModaleDaTrovare(true)}
          icona={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8" /><path d="M21 21l-4.35-4.35" /></svg>}
        />
      </div>

      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 18 }}>
        <CampoRicerca value={ricerca} onChange={(e) => setRicerca(e.target.value)} placeholder="Cerca città, corso, master o tipologia…" style={{ flex: "2 1 260px" }} />
        <select style={{ ...inputStyle, flex: "1 1 150px" }} value={filtroCitta} onChange={(e) => setFiltroCitta(e.target.value)}>
          <option value="">Tutte le città</option>
          {cittaPresenti.map((c) => <option key={c} value={c}>{c.toUpperCase()}</option>)}
        </select>
        <select style={{ ...inputStyle, flex: "1 1 150px" }} value={filtroTipologia} onChange={(e) => setFiltroTipologia(e.target.value)}>
          <option value="">Tutte le tipologie</option>
          {tipologiePresenti.map((t) => <option key={t} value={t}>{t}</option>)}
        </select>
        <select style={{ ...inputStyle, flex: "1 1 150px" }} value={scadenzaGiorni} onChange={(e) => setScadenzaGiorni(Number(e.target.value))}>
          <option value={7}>Entro 7 giorni</option>
          <option value={15}>Entro 15 giorni</option>
          <option value={30}>Entro 30 giorni</option>
          <option value={90}>Entro 90 giorni</option>
        </select>
        <select style={{ ...inputStyle, flex: "1 1 150px" }} value={ordine} onChange={(e) => setOrdine(e.target.value)}>
          <option value="urgenza">Ordina: urgenza</option>
          <option value="richieste">Ordina: più da trovare</option>
        </select>
      </div>

      <div style={cardStyle}>
        <div style={{ marginBottom: 4 }}>
          <div style={{ ...hStyle, marginBottom: 0 }}>Priorità prossimi 60 giorni</div>
          <div style={subStyle}>In ordine di urgenza</div>
        </div>
        {edizioniPrioritarie60.length === 0 ? (
          <div style={{ ...fontBody, fontSize: 14, color: MUTED, padding: "20px 0" }}>Nessuna urgenza nei prossimi 60 giorni.</div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(2, 1fr)", gap: 14, marginTop: 10 }}>
            {edizioniPrioritarie60.map((e) => <RigaPrioritaModelle key={e.corsoDataId} edizione={e} onApri={() => apriEdizione(e)} />)}
          </div>
        )}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "2fr 1fr", gap: 18, alignItems: "start", marginTop: 18 }}>
        <div style={cardStyle}>
          <div style={{ ...hStyle, marginBottom: 0 }}>Tutti i corsi con modelle richieste</div>
          <div style={subStyle}>Solo corsi con fabbisogno attivo · ordinati per {ordine === "richieste" ? "quante ne mancano" : "urgenza"}</div>
          {isMobile ? (
            <div style={{ marginTop: 8 }}>
              {edizioniPerMese.map((gruppo) => (
                <div key={gruppo.chiave} style={{ marginBottom: 6 }}>
                  <div style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.5, background: BG, padding: "7px 10px", borderRadius: 6, marginBottom: 6 }}>{gruppo.etichetta}</div>
                  {gruppo.edizioni.map((e) => (
                    <div key={e.corsoDataId} onClick={() => apriEdizione(e)} style={{ cursor: "pointer", borderBottom: `1px solid ${CREAM_BORDER}`, padding: "10px 2px" }}>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8, marginBottom: 2 }}>
                        <span style={{ ...fontBody, fontSize: 14, fontWeight: 700, color: NAVY }}>{e.cittaNome.toUpperCase()}</span>
                        <span style={{ ...fontBody, fontSize: 12, color: MUTED, whiteSpace: "nowrap" }}>{fmtDataCompatta(e.dataInizio, e.dataFine).toUpperCase()}</span>
                      </div>
                      <div style={{ ...fontBody, fontSize: 14, color: NAVY, marginBottom: 6 }}>{toTitleCase(e.corsoNome)}</div>
                      <div style={{ display: "flex", gap: 5, flexWrap: "wrap", marginBottom: 8 }}>{Object.entries(e.tipologie).map(([t, n]) => <BadgeTipologia key={t} testo={t} conteggio={n} />)}</div>
                      <div style={{ display: "flex", gap: 20, ...fontBody, fontSize: 12 }}>
                        <span style={{ color: MUTED }}>Richieste <b style={{ color: NAVY, fontSize: 14 }}>{e.richieste}</b></span>
                        <span style={{ color: MUTED }}>Da trovare <b style={{ color: e.daTrovare > 0 ? "#C0392B" : "#2E7D32", fontSize: 14 }}>{e.daTrovare}</b></span>
                      </div>
                    </div>
                  ))}
                </div>
              ))}
              {edizioniFiltrate.length === 0 && <div style={{ ...fontBody, fontSize: 14, color: MUTED, padding: "20px 0" }}>Nessun corso trovato con questi filtri.</div>}
            </div>
          ) : (
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 560 }}>
              <thead>
                <tr style={{ ...fontBody, fontSize: 11, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, textAlign: "left" }}>
                  <ThOrdina campo="citta" ordine={ordineTab} onOrdina={cambiaOrdineTab} style={{ padding: "0 8px 8px 0" }}>Città</ThOrdina>
                  <ThOrdina campo="data" ordine={ordineTab} onOrdina={cambiaOrdineTab} style={{ padding: "0 8px 8px 0" }}>Data</ThOrdina>
                  <ThOrdina campo="corso" ordine={ordineTab} onOrdina={cambiaOrdineTab} style={{ padding: "0 8px 8px 0" }}>Corso</ThOrdina>
                  <th style={{ padding: "0 8px 8px 0" }}>Tipologie richieste</th>
                  <ThOrdina campo="richieste" ordine={ordineTab} onOrdina={cambiaOrdineTab} style={{ padding: "0 8px 8px 0", textAlign: "right" }}>Richieste</ThOrdina>
                  <ThOrdina campo="daTrovare" ordine={ordineTab} onOrdina={cambiaOrdineTab} style={{ padding: "0 0 8px 0", textAlign: "right" }}>Da trovare</ThOrdina>
                </tr>
              </thead>
              <tbody>
                {edizioniPerMese.map((gruppo) => (
                  <React.Fragment key={gruppo.chiave}>
                    <tr>
                      <td colSpan={6} style={{ ...fontBody, fontSize: 12, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.5, background: BG, padding: "7px 10px", borderRadius: 6 }}>
                        {gruppo.etichetta}
                      </td>
                    </tr>
                    {ordinaTab(gruppo.edizioni, valoriModelle).map((e) => (
                      <tr key={e.corsoDataId} onClick={() => apriEdizione(e)} style={{ cursor: "pointer", borderTop: `1px solid ${CREAM_BORDER}` }}>
                        <td style={{ padding: "10px 8px 10px 0", ...fontBody, fontSize: 13, fontWeight: 700, color: NAVY, whiteSpace: "nowrap" }}>{e.cittaNome.toUpperCase()}</td>
                        <td style={{ padding: "10px 8px", ...fontBody, fontSize: 13, color: NAVY, whiteSpace: "nowrap" }}>{fmtDataCompatta(e.dataInizio, e.dataFine).toUpperCase()}</td>
                        <td style={{ padding: "10px 8px", ...fontBody, fontSize: 13, color: NAVY }}>{toTitleCase(e.corsoNome)}</td>
                        <td style={{ padding: "10px 8px" }}><div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>{Object.entries(e.tipologie).map(([t, n]) => <BadgeTipologia key={t} testo={t} conteggio={n} />)}</div></td>
                        <td style={{ padding: "10px 8px", ...fontBody, fontSize: 13, fontWeight: 600, color: NAVY, textAlign: "right" }}>{e.richieste}</td>
                        <td style={{ padding: "10px 0", ...fontBody, fontSize: 13, fontWeight: 700, textAlign: "right", color: e.daTrovare > 0 ? "#C0392B" : "#2E7D32" }}>{e.daTrovare}</td>
                      </tr>
                    ))}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
            {edizioniFiltrate.length === 0 && <div style={{ ...fontBody, fontSize: 14, color: MUTED, padding: "20px 0" }}>Nessun corso trovato con questi filtri.</div>}
          </div>
          )}
        </div>

        <div style={cardStyle}>
          <div style={{ ...hStyle, marginBottom: 12 }}>Richieste totali per città</div>
          {perCitta.length === 0 ? (
            <div style={{ ...fontBody, fontSize: 14, color: MUTED }}>Nessuna richiesta attiva.</div>
          ) : (
            perCitta.map((c) => <RigaCittaModelle key={c.citta} dati={c} onApriEdizione={apriEdizione} />)
          )}
        </div>
      </div>

      {modaleDaTrovare && <ModaleSlotDaTrovare slotList={slotDaTrovare} ctx={ctx} ricarica={ricaricaLocale} onClose={() => setModaleDaTrovare(false)} />}
      {modaleAssegnate && <ModaleModelleAssegnate slotList={slotAssegnati} slotDaTrovare={slotDaTrovare} ctx={ctx} ricarica={ricaricaLocale} onClose={() => setModaleAssegnate(false)} />}
    </div>
  );
}

// pagina "Gestione modelle": Dashboard (fabbisogno/scadenze/assegnazioni)
// più le stesse modalità di "Date corsi" già usate in Dashboard
// venditori/Gestione corsi — qui pilotate da tab in alto invece che dalle
// pillole interne di SezioneDateCorsi, per restare fedeli al mockup
// ---------- CRM modelle ----------
// Tutte le modelle che hanno davvero fatto da modella, una riga per volta
// che l'hanno fatto: nome, numero, trattamento, corso, città e data.
//
// Si legge dai due posti in cui una modella viene registrata — la modella
// del Master (corsi_date.modelle_master) e quelle degli allievi
// (iscritti.tipi_modelle) — e si tengono solo quelle con NOME e NUMERO:
// senza il numero non è una rubrica, è un elenco di nomi.
//
// Ci sono anche le modelle portate dalle allieve ("SUA"): in dashboard non
// contano, perché non sono un fabbisogno nostro, ma qui sì — hanno fatto
// da modella a un nostro corso come le altre.
function raccogliModelleStoriche({ corsiDate, corsi, location, iscritti }) {
  const corsoById = Object.fromEntries((corsi || []).map((c) => [c.id, c]));
  const locById = Object.fromEntries((location || []).map((l) => [l.id, l]));
  const righe = [];
  (corsiDate || []).forEach((cd) => {
    const corso = corsoById[cd.corso_id];
    const loc = locById[cd.location_id];
    const base = {
      corsoDataId: cd.id,
      corsoNome: corso?.nome || "—",
      citta: loc?.nome ? toTitleCase(loc.nome) : "—",
      data: cd.data_inizio,
    };
    (Array.isArray(cd.modelle_master) ? cd.modelle_master : []).forEach((m, i) => {
      if (!modellaTrovata(m)) return;
      righe.push({
        ...base, chiave: `m-${cd.id}-${i}`,
        nome: String(m.nome_modella).trim(), telefono: String(m.telefono_modella).trim(),
        tipo: m.tipo || "Modella del Master", per: "Master",
      });
    });
    (iscritti || []).filter((i) => i.corso_data_id === cd.id).forEach((isc) => {
      (Array.isArray(isc.tipi_modelle) ? isc.tipi_modelle : []).forEach((m, i) => {
        if (!modellaTrovata(m)) return;
        righe.push({
          ...base, chiave: `a-${isc.id}-${i}`,
          nome: String(m.nome_modella).trim(), telefono: String(m.telefono_modella).trim(),
          tipo: m.tipo || "—", per: `${isc.nome || ""} ${isc.cognome || ""}`.trim(),
        });
      });
    });
  });
  return righe.sort((a, b) =>
    a.nome.localeCompare(b.nome, "it", { sensitivity: "base" }) || String(b.data).localeCompare(String(a.data))
  );
}

// ---------- Modelle da sistemare ----------
// Non "modelle ancora da trovare" — quello e' il lavoro normale, e sta
// nella Dashboard. Qui finisce solo cio' che e' STORTO: una richiesta che
// non dice quale trattamento, un trattamento che non corrisponde a nessun
// giorno del corso, un numero di modelle pagate diverso dai posti in
// elenco, una modella con il nome ma senza numero. Sono i casi in cui chi
// assegna le modelle si ferma e non sa cosa fare — e finora doveva
// accorgersene da solo, classe per classe.
function raccogliModelleDaSistemare({ corsiDate, corsi, location, iscritti, corsiGiorni }) {
  const oggi = dataOggiStr();
  const righe = [];
  (corsiDate || [])
    .filter((cd) => (cd.data_inizio || "") >= oggi)
    .sort((a, b) => String(a.data_inizio).localeCompare(String(b.data_inizio)))
    .forEach((cd) => {
      const corso = (corsi || []).find((c) => c.id === cd.corso_id);
      const citta = (location || []).find((l) => l.id === cd.location_id)?.nome || "";
      const giorniAllievi = (corsiGiorni || []).filter((g) => g.corso_id === cd.corso_id && g.richiede_modelle_allievi);
      (iscritti || []).filter((i) => i.corso_data_id === cd.id).forEach((i) => {
        const posti = Array.isArray(i.tipi_modelle) ? i.tipi_modelle : [];
        const motivi = [];
        const pagate = i.numero_modelle == null ? null : Number(i.numero_modelle);

        if (i.richiede_modelle && (pagate || 0) > 0 && posti.length === 0) {
          motivi.push({ gravita: "alta", testo: `Ha ${pagate} modelle da noi, ma nessun trattamento in elenco: non c'e' niente da assegnare.` });
        }
        if (i.richiede_modelle && posti.length > 0 && pagate != null && pagate !== posti.length) {
          motivi.push({ gravita: "alta", testo: `Modelle pagate ${pagate}, trattamenti in elenco ${posti.length}: uno dei due numeri e' sbagliato.` });
        }

        posti.forEach((m, idx) => {
          const tipo = normalizzaTipoModella(m.tipo);
          const etichettaPosto = m.tipo ? `"${m.tipo}"` : `${idx + 1}° posto`;
          if (!tipo) {
            motivi.push({ gravita: "alta", testo: `Il ${idx + 1}° posto non dice quale trattamento: sceglilo, o resta in un giorno a caso.` });
          } else if (m.giorno == null && giorniAllievi.length > 0 && !giorniAllievi.some((g) => normalizzaTipoModella(g.tipo_modella_allievi) === tipo)) {
            motivi.push({ gravita: "media", testo: `${etichettaPosto} non corrisponde a nessun giorno del corso: finisce nel primo giorno utile.` });
          }
          const nomeM = String(m.nome_modella || "").trim();
          const telM = String(m.telefono_modella || "").trim();
          if (nomeM && !telM) motivi.push({ gravita: "media", testo: `${etichettaPosto}: c'e' il nome "${nomeM}" ma manca il numero, quindi il posto non risulta coperto.` });
          if (!nomeM && telM) motivi.push({ gravita: "media", testo: `${etichettaPosto}: c'e' il numero ma manca il nome.` });
        });

        if (motivi.length > 0) {
          righe.push({
            iscrittoId: i.id,
            nome: `${i.nome || ""} ${i.cognome || ""}`.trim() || "senza nome",
            corsoDataId: cd.id, corsoData: cd,
            corsoNome: corso?.nome || "corso", citta, data: cd.data_inizio,
            nostra: !!i.richiede_modelle,
            motivi,
          });
        }
      });
    });
  return righe;
}

function PaginaModelleDaSistemare({ corsi, location, corsiDate, iscritti, corsiGiorni, onApriIscritto, onApriData }) {
  const righe = useMemo(
    () => raccogliModelleDaSistemare({ corsiDate, corsi, location, iscritti, corsiGiorni }),
    [corsiDate, corsi, location, iscritti, corsiGiorni]
  );
  // una scheda per edizione: chi assegna le modelle ragiona per classe,
  // non per allievo sparso
  const perEdizione = [];
  righe.forEach((r) => {
    const ultimo = perEdizione[perEdizione.length - 1];
    if (ultimo && ultimo.corsoDataId === r.corsoDataId) ultimo.righe.push(r);
    else perEdizione.push({ corsoDataId: r.corsoDataId, corsoData: r.corsoData, corsoNome: r.corsoNome, citta: r.citta, data: r.data, righe: [r] });
  });

  if (righe.length === 0) {
    return (
      <div style={{ ...cardStyle, padding: 20, ...fontBody, fontSize: 13.5, color: MUTED }}>
        Nessun problema: in tutte le classi in programma le richieste di modelle sono complete e coerenti.
      </div>
    );
  }

  return (
    <div>
      <div style={{ ...fontBody, fontSize: 13, color: MUTED, marginBottom: 14, lineHeight: 1.5 }}>
        {righe.length} alliev{righe.length === 1 ? "o" : "i"} con qualcosa da sistemare nelle modelle. Clicca il nome per aprire la sua scheda:
        il trattamento, il numero di modelle e il giorno si correggono da lì.
      </div>
      {perEdizione.map((ed) => (
        <div key={ed.corsoDataId} style={{ ...cardStyle, padding: 16, marginBottom: 12 }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, flexWrap: "wrap", marginBottom: 10 }}>
            <div>
              <div style={{ ...fontDisplay, fontSize: 15, fontWeight: 700, color: NAVY }}>
                {ed.corsoNome}{ed.citta ? ` · ${toTitleCase(ed.citta)}` : ""}
              </div>
              <div style={{ ...fontBody, fontSize: 12, color: MUTED, marginTop: 2 }}>{fmtData(ed.data)} — {ed.righe.length} da sistemare</div>
            </div>
            {onApriData && (
              <Button variant="ghost" onClick={() => onApriData(ed.corsoData)}>Assegna modelle ›</Button>
            )}
          </div>
          {ed.righe.map((r) => (
            <div key={r.iscrittoId} style={{ borderTop: `1px solid ${CREAM_BORDER}`, padding: "10px 0" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <span style={{ width: 30, height: 30, borderRadius: "50%", background: "#FDF8EC", border: `1px solid ${CREAM_BORDER}`, display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0, ...fontBody, fontSize: 11, fontWeight: 700, color: GOLD }}>
                  {inizialiNome(r.nome)}
                </span>
                <button
                  onClick={() => onApriIscritto && onApriIscritto(r.iscrittoId)}
                  title="Apri la scheda dell'allievo"
                  style={{ ...fontBody, fontSize: 13.5, fontWeight: 700, color: NAVY, textTransform: "uppercase", letterSpacing: 0.3, background: "none", border: "none", padding: 0, cursor: "pointer", textDecoration: "underline", textDecorationColor: CREAM_BORDER, textUnderlineOffset: 3 }}
                >
                  {r.nome}
                </button>
                <span style={{ ...fontBody, fontSize: 10.5, fontWeight: 700, padding: "2px 8px", borderRadius: 10, background: r.nostra ? "#F7EDDB" : "#FDECEC", color: r.nostra ? "#8A6D1D" : "#C0392B" }}>
                  {r.nostra ? "NOSTRA" : "HA LA SUA MODELLA"}
                </span>
              </div>
              <div style={{ marginTop: 4, marginLeft: 38 }}>
                {r.motivi.map((m, iM) => (
                  <div key={iM} style={{ ...fontBody, fontSize: 12.5, color: m.gravita === "alta" ? "#C0392B" : MUTED, lineHeight: 1.45 }}>• {m.testo}</div>
                ))}
              </div>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

function PaginaCrmModelle({ corsi, location, corsiDate, iscritti }) {
  const isMobile = useIsMobile();
  const [ricerca, setRicerca] = useState("");
  const righe = useMemo(
    () => raccogliModelleStoriche({ corsiDate, corsi, location, iscritti }),
    [corsiDate, corsi, location, iscritti]
  );
  const filtrate = ricerca.trim()
    ? righe.filter((r) => {
        const q = ricerca.trim().toLowerCase();
        return [r.nome, r.telefono, r.tipo, r.corsoNome, r.citta, r.per].some((v) => String(v || "").toLowerCase().includes(q));
      })
    : righe;
  // quante persone, non quante volte: la stessa modella tornata tre volte
  // resta una modella sola, e il numero di telefono è ciò che la identifica
  const quantePersone = new Set(filtrate.map((r) => r.telefono.replace(/\s+/g, ""))).size;

  const thStyle = { ...fontBody, fontSize: 10.5, fontWeight: 700, color: MUTED, textTransform: "uppercase", letterSpacing: 0.5, padding: "10px 12px", textAlign: "left", whiteSpace: "nowrap" };
  const tdStyle = { padding: "10px 12px", borderTop: `1px solid ${CREAM_BORDER}`, ...fontBody, fontSize: 13, color: NAVY, verticalAlign: "top" };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 14 }}>
        <div style={{ ...fontBody, fontSize: 13, color: MUTED }}>
          <b style={{ color: NAVY }}>{quantePersone}</b> modell{quantePersone === 1 ? "a" : "e"} · {filtrate.length} partecipazion{filtrate.length === 1 ? "e" : "i"} ai corsi
        </div>
        <div style={{ flex: "1 1 260px", maxWidth: 360 }}>
          <CampoRicerca value={ricerca} onChange={(e) => setRicerca(e.target.value)} placeholder="Cerca nome, numero, trattamento, città…" />
        </div>
      </div>

      {filtrate.length === 0 ? (
        <div style={{ ...cardStyle, padding: 20, ...fontBody, fontSize: 13.5, color: MUTED }}>
          {righe.length === 0
            ? "Nessuna modella registrata: compaiono qui appena vengono confermate con nome e numero nella scheda di un corso."
            : "Nessuna modella trovata con questa ricerca."}
        </div>
      ) : isMobile ? (
        // da telefono la tabella non ci sta: una scheda per riga
        <div>
          {filtrate.map((r) => (
            <div key={r.chiave} style={{ ...cardStyle, padding: 14, marginBottom: 8 }}>
              <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "baseline", flexWrap: "wrap" }}>
                <span style={{ ...fontBody, fontSize: 15, fontWeight: 700, color: NAVY, textTransform: "uppercase" }}>{r.nome}</span>
                <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}>
                  <a href={`tel:${r.telefono.replace(/\s+/g, "")}`} style={{ ...fontBody, fontSize: 13, color: NAVY, textDecoration: "underline" }}>{r.telefono}</a>
                  <a href={`https://wa.me/${numeroWhatsapp(r.telefono)}`} target="_blank" rel="noopener noreferrer" title="WhatsApp" style={{ display: "flex" }}>
                    <IconaWhatsapp size={20} />
                  </a>
                </span>
              </div>
              <div style={{ ...fontBody, fontSize: 12.5, color: MUTED, marginTop: 3, lineHeight: 1.5 }}>
                {r.tipo} · {r.citta} · {fmtData(r.data)}
                <span style={{ display: "block" }}>{r.corsoNome} — per {toTitleCase(r.per)}</span>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div style={{ ...cardStyle, padding: 0, overflow: "hidden" }}>
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 820 }}>
              <thead>
                <tr style={{ background: BG }}>
                  <th style={thStyle}>Modella</th>
                  <th style={thStyle}>Cellulare</th>
                  <th style={thStyle}>Trattamento</th>
                  <th style={thStyle}>Città</th>
                  <th style={thStyle}>Data</th>
                  <th style={thStyle}>Corso</th>
                  <th style={thStyle}>Per</th>
                </tr>
              </thead>
              <tbody>
                {filtrate.map((r) => (
                  <tr key={r.chiave}>
                    <td style={{ ...tdStyle, fontWeight: 700, textTransform: "uppercase" }}>{r.nome}</td>
                    <td style={tdStyle}>
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 8, whiteSpace: "nowrap" }}>
                        <a href={`tel:${r.telefono.replace(/\s+/g, "")}`} style={{ color: NAVY, textDecoration: "underline" }}>{r.telefono}</a>
                        <a href={`https://wa.me/${numeroWhatsapp(r.telefono)}`} target="_blank" rel="noopener noreferrer" title="WhatsApp" style={{ display: "flex" }}>
                          <IconaWhatsapp size={18} />
                        </a>
                      </span>
                    </td>
                    <td style={tdStyle}>{r.tipo}</td>
                    <td style={tdStyle}>{r.citta}</td>
                    <td style={{ ...tdStyle, whiteSpace: "nowrap" }}>{fmtData(r.data)}</td>
                    <td style={{ ...tdStyle, color: MUTED }}>{r.corsoNome}</td>
                    <td style={{ ...tdStyle, color: MUTED }}>{toTitleCase(r.per)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

// (Dashboard | Calendario corsi | Archivio corsi | CRM modelle). Cliccando una
